class _BrowserPageState extends State<BrowserPage>
    with AutomaticKeepAliveClientMixin, WidgetsBindingObserver, RouteAware {
  /// 将相对 URL 解析为绝对 URL（使用当前页面地址作为基准）
  String _toAbsoluteUrl(String url) {
    if (url.isEmpty) return url;
    final trimmed = url.trim();
    if (trimmed.startsWith('http://') ||
        trimmed.startsWith('https://') ||
        trimmed.startsWith('data:') ||
        trimmed.startsWith('blob:')) {
      return trimmed;
    }
    String base = _urlController.text.trim();
    if (base.isEmpty) base = _currentUrl;
    if (base.isEmpty) base = 'https://www.baidu.com';
    final baseUri = Uri.tryParse(base);
    if (baseUri == null || !baseUri.hasAuthority) return trimmed;
    if (trimmed.startsWith('//')) return 'https:$trimmed';
    return baseUri.resolve(trimmed).toString();
  }

  /// 是否为 API 接口（返回 JSON 而非图片），应跳过下载
  bool _isApiEndpointUrl(String url) {
    if (url.startsWith('blob:') || url.startsWith('data:')) return false;
    final lower = url.toLowerCase();
    if (RegExp(
      r'\.(jpg|jpeg|png|gif|webp|mp4|webm|mov|m3u8|ts|mp3|m4a)(\?|$)',
      caseSensitive: false,
    ).hasMatch(url))
      return false;
    final videoHosts = [
      'tik.',
      'porn',
      'xvideos',
      'xhamster',
      'pornhub',
      'redtube',
      'cdn.',
      'stream',
      'video.',
      'media.',
    ];
    try {
      final host = Uri.parse(url).host.toLowerCase();
      if (videoHosts.any((h) => host.contains(h))) return false;
    } catch (_) {}
    const apiPatterns = [
      'detailrecommend',
      'wisesearchsetpic',
      'wisejson',
      'getrelatedvideos',
      'getuserbyslug',
      '/graphql',
      '/v1/',
      '/v2/',
      '/v3/',
      '/models',
      '/model/',
      '/slug',
      '/users/',
      '/search?',
      '/query',
      '/json',
      '/rest/',
      '/endpoint',
      '/service',
      'getuser',
      'getpost',
      'relatedvideos',
      'userbyslug',
      'byslug',
    ];
    if (apiPatterns.any((p) => lower.contains(p))) return true;
    return RegExp(
      r'/(get|post|api|graphql|rest|v1|v2|models|user|slug)/',
    ).hasMatch(url);
  }

  Future<String> _resolveFinalUrl(
    String url, {
    Map<String, String>? headers,
  }) async {
    final absoluteUrl = _toAbsoluteUrl(url);
    try {
      final networkService = NetworkService();
      await networkService.initialize();
      final cookie = await _browserCookieHeaderForUrl(absoluteUrl);
      final resp = await networkService.dio.head(
        absoluteUrl,
        options: Options(
          method: 'HEAD',
          headers: {
            'User-Agent': _kBrowserMediaUserAgent,
            ...?headers,
            if (cookie.isNotEmpty && !(headers?.containsKey('Cookie') ?? false))
              'Cookie': cookie,
          },
        ),
      );
      final finalUrl = resp.realUri.toString();
      return finalUrl.isNotEmpty ? finalUrl : absoluteUrl;
    } catch (_) {
      return absoluteUrl;
    }
  }

  Future<String> _browserCookieHeaderForUrl(String url) async {
    try {
      final absolute = _toAbsoluteUrl(url);
      final uri = Uri.tryParse(absolute);
      if (uri == null ||
          !(uri.scheme == 'http' || uri.scheme == 'https') ||
          uri.host.isEmpty) {
        return '';
      }
      final byName = <String, String>{};
      Future<void> collectFrom(String cookieUrl) async {
        try {
          final cookies = await CookieManager.instance().getCookies(
            url: WebUri(cookieUrl),
          );
          for (final c in cookies) {
            final name = c.name.trim();
            if (name.isEmpty) continue;
            byName[name] = c.value.trim();
          }
        } catch (_) {}
      }

      await collectFrom(absolute);
      // fbcdn is a separate host; progressive media often still needs the
      // facebook.com session cookies from the logged-in WebView.
      if (_isFacebookCdnUrl(absolute) || _isFacebookPlatformPage(absolute)) {
        await collectFrom('https://www.facebook.com');
        await collectFrom('https://www.facebook.com/');
        await collectFrom('https://m.facebook.com');
        await collectFrom('https://m.facebook.com/');
      }
      if (byName.isEmpty) return '';
      return byName.entries.map((e) => '${e.key}=${e.value}').join('; ');
    } catch (e) {
      debugPrint('读取 WebView Cookie 失败: $e');
      return '';
    }
  }

  Future<void> _flushBrowserCookies() async {
    // Android: CookieManager.flush() 把内存 cookie 落盘，避免杀进程后丢失登录态。
    // iOS WKWebView 默认 data store 会自行持久化；这里仍走通道以便统一调用点。
    try {
      if (Platform.isAndroid) {
        await const MethodChannel(
          'browser_cookies',
        ).invokeMethod<bool>('flushCookies');
      }
    } catch (e) {
      debugPrint('Failed to persist browser cookies: $e');
    }
  }

  Future<Map<String, String>> _browserLikeMediaHeaders(
    String mediaUrl, {
    required String referer,
    String accept = '*/*',
    bool includeOrigin = false,
  }) async {
    final headers = <String, String>{
      'User-Agent': _kBrowserMediaUserAgent,
      'Referer': referer,
      'Accept': accept,
      'Accept-Language': 'zh-CN,zh;q=0.9,en;q=0.8',
      'Connection': 'keep-alive',
      if (includeOrigin && referer.startsWith('http'))
        'Origin': Uri.tryParse(referer)?.origin ?? referer,
    };
    final cookie = await _browserCookieHeaderForUrl(mediaUrl);
    if (cookie.isNotEmpty) {
      headers['Cookie'] = cookie;
    }
    return headers;
  }

  @override
  bool get wantKeepAlive => true;

  InAppWebViewController? _controller;
  final LinkedHashMap<String, _CapturedWebResource> _capturedWebResources =
      LinkedHashMap<String, _CapturedWebResource>();
  final LinkedHashMap<String, DateTime> _trustedMediaCandidateUrls =
      LinkedHashMap<String, DateTime>();
  final TextEditingController _urlController = TextEditingController();
  bool _isLoading = false;
  double _loadingProgress = 0.0;
  String _currentUrl = 'https://www.baidu.com';
  late final DatabaseService _databaseService;
  List<Map<String, String>> _bookmarks = [];
  final GlobalKey<ScaffoldState> _scaffoldKey = GlobalKey<ScaffoldState>();

  bool _showHomePage = true;
  bool _isBrowsingWebPage = false;

  void _recordLoadedWebResource(LoadedResource resource) {
    final rawUrl = resource.url?.toString().trim() ?? '';
    final uri = Uri.tryParse(rawUrl);
    if (uri == null ||
        !(uri.scheme == 'http' || uri.scheme == 'https') ||
        uri.host.isEmpty ||
        _isLikelyAdUrl(rawUrl)) {
      return;
    }
    final initiator = (resource.initiatorType ?? '').trim().toLowerCase();
    const ignoredInitiators = <String>{
      'css',
      'script',
      'link',
      'font',
      'beacon',
    };
    if (ignoredInitiators.contains(initiator)) return;

    _capturedWebResources.remove(rawUrl);
    _capturedWebResources[rawUrl] = _CapturedWebResource(
      url: rawUrl,
      initiatorType: initiator,
      pageUrl: _currentUrl,
      capturedAt: DateTime.now(),
    );
    final captured = _capturedWebResources[rawUrl]!;
    if (_capturedResourceMatchesType(captured, MediaType.video) ||
        _capturedResourceMatchesType(captured, MediaType.image)) {
      _trustMediaCandidate(rawUrl);
    }
    while (_capturedWebResources.length > _kMaxCapturedWebResources) {
      _capturedWebResources.remove(_capturedWebResources.keys.first);
    }
  }

  bool _urlLooksLikeImageResource(String url) {
    final lower = url.toLowerCase();
    if (RegExp(
      r'\.(jpe?g|png|gif|webp|bmp|svg|ico|tiff?|avif|heic|heif|jxl)(\?|#|$)',
      caseSensitive: false,
    ).hasMatch(lower)) {
      return true;
    }
    // Facebook photo CDN often omits a clear extension in some variants.
    if ((lower.contains('scontent.') || lower.contains('fbcdn.net')) &&
        !lower.contains('.mp4') &&
        !lower.contains('video.') &&
        !RegExp(r'(^|[./])video\.[a-z0-9.-]*fbcdn').hasMatch(lower) &&
        (lower.contains('/t39.') ||
            lower.contains('/t15.') ||
            lower.contains('/t51.') ||
            lower.contains('/t45.') ||
            lower.contains('/v/t') ||
            lower.contains('_n.jpg') ||
            lower.contains('_o.jpg') ||
            lower.contains('_s.jpg') ||
            lower.contains('stp=') ||
            lower.contains('p1080x1080') ||
            lower.contains('p960x960') ||
            lower.contains('scontent'))) {
      return true;
    }
    return false;
  }

  bool _capturedResourceMatchesType(
    _CapturedWebResource resource,
    MediaType mediaType,
  ) {
    final initiator = resource.initiatorType;
    if (mediaType == MediaType.image) {
      return initiator == 'img' ||
          initiator == 'image' ||
          _urlLooksLikeImageResource(resource.url);
    }
    if (mediaType == MediaType.video) {
      if (_looksLikeMediaFragmentUrl(resource.url)) return false;
      return initiator == 'video' ||
          initiator == 'media' ||
          (_isLikelyDirectMediaUrl(resource.url) &&
              !_looksLikeMediaFragmentUrl(resource.url));
    }
    return initiator == 'audio';
  }

  List<String> _recentCapturedMediaCandidates(
    MediaType mediaType, {
    String? pageUrl,
    DateTime? notBefore,
    int limit = 24,
  }) {
    final now = DateTime.now();
    final requestedPage = Uri.tryParse((pageUrl ?? _currentUrl).trim());
    final scored = <(_CapturedWebResource resource, int score)>[];
    for (final resource in _capturedWebResources.values) {
      if (notBefore != null && resource.capturedAt.isBefore(notBefore))
        continue;
      final age = now.difference(resource.capturedAt);
      if (age > const Duration(minutes: 30) ||
          !_capturedResourceMatchesType(resource, mediaType)) {
        continue;
      }
      final capturedPage = Uri.tryParse(resource.pageUrl);
      if (requestedPage != null &&
          capturedPage != null &&
          requestedPage.host.isNotEmpty &&
          capturedPage.host.isNotEmpty &&
          requestedPage.host != capturedPage.host) {
        continue;
      }
      var score = max(0, 1800 - age.inSeconds);
      if (resource.initiatorType == 'video' ||
          resource.initiatorType == 'img' ||
          resource.initiatorType == 'image') {
        score += 3000;
      }
      if (mediaType == MediaType.video) {
        score += _scoreFavoriteVideoUrl(resource.url);
      } else if (_urlLooksLikeImageResource(resource.url)) {
        score += 1200;
        if (_isFacebookCdnUrl(resource.url)) {
          score += _scoreFacebookImageCandidate(resource.url);
        }
      }
      scored.add((resource, score));
    }
    scored.sort((a, b) {
      final scoreOrder = b.$2.compareTo(a.$2);
      if (scoreOrder != 0) return scoreOrder;
      // 同一秒内可能连续加载多个信息流视频；分数相同时必须优先最新资源。
      return b.$1.capturedAt.compareTo(a.$1.capturedAt);
    });
    return scored.take(limit).map((entry) => entry.$1.url).toList();
  }

  bool _isXPlatformPage(String? url) {
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    return host == 'x.com' ||
        host.endsWith('.x.com') ||
        host == 'twitter.com' ||
        host.endsWith('.twitter.com');
  }

  bool _isFacebookPlatformPage(String? url) {
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    if (host.isEmpty) return false;
    return host == 'facebook.com' ||
        host.endsWith('.facebook.com') ||
        host == 'fb.com' ||
        host.endsWith('.fb.com') ||
        host == 'fb.watch' ||
        host.endsWith('.fb.watch') ||
        host == 'messenger.com' ||
        host.endsWith('.messenger.com');
  }

  /// Profile media tab grids (3-column thumbnails). Excludes full-screen Reels feed.
  bool _isFacebookProfileGridPage(String? url) {
    if (!_isFacebookPlatformPage(url)) return false;
    final trimmed = (url ?? '').trim();
    if (trimmed.isEmpty) return false;
    if (trimmed.toLowerCase().contains('/reel/')) return false;
    final uri = Uri.tryParse(trimmed);
    if (uri == null) return false;
    final path = uri.path.toLowerCase();
    if (path.contains('/watch')) return false;
    if (path.contains('profile.php') || path.contains('/people/')) return true;
    if (RegExp(r'/photos').hasMatch(path)) return true;
    final segments = uri.pathSegments.where((part) => part.isNotEmpty).toList();
    if (segments.isEmpty) return false;
    const excludedRoots = <String>{
      'reels',
      'watch',
      'marketplace',
      'groups',
      'gaming',
      'events',
      'pages',
      'help',
      'login',
      'recover',
      'share',
      'sharer',
      'dialog',
      'plugins',
      'stories',
      'hashtag',
      'l.php',
    };
    // Global reels feed (/reels) is vertical swipe, not profile grid.
    if (segments.length == 1 && segments.first == 'reels') return false;
    if (excludedRoots.contains(segments.first)) return false;
    // Profile Reels tab is vertical swipe; media grid lives under photos/media tabs.
    if (segments.length >= 2 &&
        const {'reels', 'videos', 'live'}.contains(segments.last)) {
      return false;
    }
    // /username, /username/photos, etc.
    return segments.length <= 2;
  }

  bool _isFacebookCdnUrl(String url) {
    final lower = url.toLowerCase();
    if (lower.contains('cdninstagram.com')) return false;
    return lower.contains('fbcdn.net') ||
        lower.contains('fbcdn.com') ||
        lower.contains('scontent.') ||
        RegExp(r'(^|[./])video\.[a-z0-9.-]*fbcdn').hasMatch(lower);
  }

  bool _isInstagramPlatformPage(String? url) {
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    return host == 'instagram.com' || host.endsWith('.instagram.com');
  }

  bool _isInstagramCdnUrl(String url) {
    final host = Uri.tryParse(url.trim())?.host.toLowerCase() ?? '';
    return host == 'cdninstagram.com' || host.endsWith('.cdninstagram.com');
  }

  int _scoreInstagramVideoCandidate(String url) {
    final metadata = facebookMediaMetadata(url);
    if (metadata?.isAudioOnly == true) return -100000;
    var score = _scoreFavoriteVideoUrl(url);
    if (_isInstagramCdnUrl(url)) score += 5000;
    if (metadata?.isVideoTrack == true) {
      score += 10000;
      score += ((metadata!.bitrate ?? 0) ~/ 1000).clamp(0, 10000);
    }
    return score;
  }

  List<String> _selectInstagramBoundTrackCandidates(
    Iterable<String> fragmentUrls, {
    Iterable<String> fallbackUrls = const <String>[],
    double targetDurationSeconds = 0,
    Set<String> excludedAssetIds = const <String>{},
  }) {
    final tracksByAsset = <String, List<String>>{};
    final seen = <String>{};
    void collect(String raw) {
      final whole = recoverWholeMediaUrlFromFragment(raw) ?? raw.trim();
      if (whole.isEmpty || !seen.add(whole) || !_isInstagramCdnUrl(whole)) {
        return;
      }
      final metadata = facebookMediaMetadata(whole);
      if (metadata == null || metadata.videoId.isEmpty) return;
      if (!metadata.isVideoTrack && !metadata.isAudioOnly) return;
      tracksByAsset.putIfAbsent(metadata.videoId, () => <String>[]).add(whole);
    }

    for (final raw in fragmentUrls) {
      collect(raw);
    }
    final boundGroupSummary = tracksByAsset.entries
        .map((entry) {
          final metadata =
              entry.value
                  .map(facebookMediaMetadata)
                  .whereType<FacebookMediaMetadata>()
                  .toList();
          final durations = metadata
              .map((value) => value.durationSeconds)
              .whereType<int>()
              .toSet()
              .join('/');
          final videoCount =
              metadata.where((value) => value.isVideoTrack).length;
          final audioCount =
              metadata.where((value) => value.isAudioOnly).length;
          return '${entry.key}(d=$durations,v=$videoCount,a=$audioCount)';
        })
        .join(',');
    debugPrint(
      '[IG_GROUPS] targetDuration=${targetDurationSeconds.toStringAsFixed(3)} '
      'bound=[$boundGroupSummary]',
    );

    String? selectedAssetId;
    var selectedScore = -0x7fffffff;
    double? selectedDurationDelta;
    for (final entry in tracksByAsset.entries) {
      if (excludedAssetIds.contains(entry.key)) {
        debugPrint('[IG_BOUND_SKIP_HANDLED] asset=${entry.key}');
        continue;
      }
      final metadata =
          entry.value
              .map(facebookMediaMetadata)
              .whereType<FacebookMediaMetadata>()
              .toList();
      if (metadata.isEmpty) continue;
      final videos =
          entry.value
              .where((url) => facebookMediaMetadata(url)?.isVideoTrack == true)
              .toList();
      final hasAudio = entry.value.any(
        (url) => facebookMediaMetadata(url)?.isAudioOnly == true,
      );
      var score =
          videos.isEmpty
              ? 0
              : videos
                  .map(_scoreInstagramVideoCandidate)
                  .reduce((left, right) => max(left, right));
      if (hasAudio) score += 2000;
      if (metadata.any(
        (value) => value.encodeTag.toLowerCase().contains('.ad.'),
      )) {
        score -= 50000;
      }
      double? durationDelta;
      if (targetDurationSeconds > 0) {
        final durations =
            metadata
                .map((value) => value.durationSeconds)
                .whereType<num>()
                .map((duration) => duration.toDouble())
                .where((duration) => duration > 0)
                .toList();
        if (durations.isNotEmpty) {
          durationDelta = durations
              .map((duration) => (duration - targetDurationSeconds).abs())
              .reduce(min);
          score += max(0, 200000 - (durationDelta * 50000).round());
        }
      }
      if (score > selectedScore) {
        selectedScore = score;
        selectedAssetId = entry.key;
        selectedDurationDelta = durationDelta;
      }
    }
    if (selectedAssetId == null) return const <String>[];
    if (targetDurationSeconds > 0) {
      // The DASH metadata duration is integral while the DOM duration has
      // fractions, so the same asset can be about one second apart. A wider
      // tolerance is unsafe in Instagram's reused feed player: the next/previous
      // Reel's tracks remain bound and a 7-second Reel can otherwise select a
      // nearby 9-second asset. Prefer a retry over downloading the wrong post.
      const allowedDelta = 1.25;
      if (selectedDurationDelta == null ||
          selectedDurationDelta! > allowedDelta) {
        debugPrint(
          '[IG_BOUND_REJECT] asset=$selectedAssetId '
          'targetDuration=${targetDurationSeconds.toStringAsFixed(3)} '
          'delta=${selectedDurationDelta?.toStringAsFixed(3) ?? 'unknown'} '
          'allowed=${allowedDelta.toStringAsFixed(3)}',
        );
        return const <String>[];
      }
    }

    // The exact MediaSource may only expose the audio half when Instagram
    // buffered video before the sniffer was installed. Once the bound element
    // has selected an asset identity, supplement only that same asset.
    for (final raw in fallbackUrls) {
      final whole = recoverWholeMediaUrlFromFragment(raw) ?? raw.trim();
      if (facebookMediaMetadata(whole)?.videoId == selectedAssetId) {
        collect(raw);
      }
    }
    final selectedTracks = tracksByAsset[selectedAssetId]!;
    final videos =
        selectedTracks
            .where((url) => facebookMediaMetadata(url)?.isVideoTrack == true)
            .toList()
          ..sort(
            (left, right) => _scoreInstagramVideoCandidate(
              right,
            ).compareTo(_scoreInstagramVideoCandidate(left)),
          );
    final audios =
        selectedTracks
            .where((url) => facebookMediaMetadata(url)?.isAudioOnly == true)
            .toList();
    debugPrint(
      '[IG_BOUND] asset=$selectedAssetId '
      'videoTracks=${videos.length} audioTracks=${audios.length} '
      'boundAssets=${tracksByAsset.length}',
    );
    return <String>[...videos, ...audios];
  }

  /// Facebook media strategy (dedicated site profile, parallel to X/91):
  /// - Capture: WebView LoadedResource + JS XHR/fetch/performance sniff
  ///   (fbcdn / scontent / video.*.fbcdn).
  /// - Prefer progressive MP4 (`*.mp4` with `oe=`/`oh=` signatures) over
  ///   blob:/MSE stubs. Range fragments (`bytestart`/`byteend`) are recovered
  ///   to the whole URL via [recoverWholeMediaUrlFromFragment], never saved as
  ///   tiny stubs. Auth: facebook.com cookies + Referer www/m.facebook.com.
  /// - Bind current reel via [facebookMediaIdentity] + active bytestart keys
  ///   (not the next-reel prefetch).
  /// - After download: reject files under [kFacebookMinVideoBytes] and
  ///   init-only MP4 stubs ([looksLikeIncompleteMp4Stub]); retry next candidate.
  /// - Images: scontent CDN (`/t39.` `/t15.` `_n.jpg`/`_o.jpg` / srcset).
  /// - Hard limit: DRM / SAMPLE-AES / live MediaStream cannot be saved as a
  ///   standalone playable file; surface a clear user message instead.
  bool _isFacebookProgressiveMp4Url(String url) {
    final lower = url.trim().toLowerCase();
    if (lower.isEmpty || lower.startsWith('blob:') || isMediaFragmentUrl(url)) {
      return false;
    }
    if (!_isFacebookCdnUrl(url) && !lower.contains('facebook.com')) {
      return false;
    }
    if (lower.contains('.m3u8') || lower.contains('.mpd')) return false;
    if (lower.contains('.mp4')) return true;
    // Newer FBCDN progressive stems often omit ".mp4" in the path segment.
    return lower.contains('/v/t') ||
        lower.contains('/v/s') ||
        lower.contains('video.') ||
        lower.contains('efg=');
  }

  String? _normalizeFacebookMediaCandidate(String raw, {required bool video}) {
    var value = raw.trim();
    if (value.isEmpty ||
        value.startsWith('blob:') ||
        value.startsWith('data:')) {
      return null;
    }
    if (isMediaFragmentUrl(value)) {
      final recovered = recoverWholeMediaUrlFromFragment(value);
      if (recovered == null || recovered.trim().isEmpty) return null;
      value = recovered.trim();
    }
    if (isMediaFragmentUrl(value)) return null;
    final facebookMetadata = facebookMediaMetadata(value);
    if (video && facebookMetadata?.isAudioOnly == true) {
      debugPrint(
        'FB pipeline: ignored audio-only DASH track '
        'videoId=${facebookMetadata!.videoId} '
        'tag=${facebookMetadata.encodeTag}',
      );
      return null;
    }
    final lower = value.toLowerCase();
    if (_isFacebookCdnUrl(value)) {
      if (video) {
        if (lower.contains('.mp4') ||
            lower.contains('.m3u8') ||
            lower.contains('.mpd') ||
            lower.contains('video.') ||
            lower.contains('/v/t') ||
            lower.contains('/v/s')) {
          return value;
        }
        return null;
      }
      if (_urlLooksLikeImageResource(value) ||
          lower.contains('scontent.') ||
          RegExp(
            r'\.(jpe?g|png|gif|webp)(\?|#|$)',
            caseSensitive: false,
          ).hasMatch(lower)) {
        return value;
      }
      return null;
    }
    if (video) {
      return _isLikelyDirectMediaUrl(value) ? value : null;
    }
    return _urlLooksLikeImageResource(value) ? value : null;
  }

  int _scoreFacebookVideoCandidate(
    String url, {
    String expectedVideoKey = '',
    bool isReels = false,
    DateTime? captureTime,
    DateTime? playbackStartedAt,
    Set<String> activelyStreamedKeys = const <String>{},
  }) {
    final lower = url.toLowerCase();
    var score = _scoreFavoriteVideoUrl(url);
    final facebookMetadata = facebookMediaMetadata(url);
    if (facebookMetadata?.isAudioOnly == true) return -100000;
    if (isMediaFragmentUrl(url)) return -100000;
    if (!_isFacebookCdnUrl(url) && !lower.contains('facebook.com')) {
      return score - 400;
    }
    if (lower.contains('bytestart') || lower.contains('byteend')) {
      score -= 50000;
    }
    // Progressive CDN MP4 with FB edge signatures (oe=/oh=) is the golden path.
    if (lower.contains('.mp4')) score += 8000;
    if (lower.contains('oe=') || lower.contains('oh=')) score += 3500;
    if (lower.contains('_nc_') || lower.contains('efg=')) score += 800;
    if (lower.contains('video.') && lower.contains('fbcdn')) score += 5000;
    if (lower.contains('scontent.') && lower.contains('.mp4')) score += 4500;
    // Adaptive playlists are fallback only; prefer progressive when present.
    if (lower.contains('.m3u8') || lower.contains('mpegurl')) score += 1200;
    if (lower.contains('.mpd')) score += 900;
    if (lower.contains('_hd') ||
        lower.contains('hd_src') ||
        lower.contains('quality=hd') ||
        lower.contains('oe_hd')) {
      score += 1500;
    }
    if (lower.contains('_sd') || lower.contains('sd_src')) score += 400;
    if (lower.contains('audio') || lower.contains('/aud/')) score -= 20000;
    if (facebookMetadata?.isVideoTrack == true) {
      score += 30000;
      // Same video_id may expose 144p..1080p DASH renditions. Keep identity
      // binding dominant, then prefer the highest resolution/bitrate.
      score += (facebookMetadata!.qualityScore ~/ 1000).clamp(0, 2000000);
    }
    if (_looksLikePreviewClipUrl(lower)) score -= 8000;

    final identity = facebookMediaIdentity(url);
    final expected = expectedVideoKey.trim();
    if (expected.isNotEmpty && identity.isNotEmpty) {
      if (facebookIdentitiesMatch(identity, expected)) {
        // Bound to the pressed / currently playing reel — beat any neighbor
        // prefetch that only wins on "newest capture".
        score += 250000;
      } else {
        score -= isReels ? 180000 : 40000;
      }
    }
    if (identity.isNotEmpty &&
        activelyStreamedKeys.any(
          (key) => facebookIdentitiesMatch(identity, key),
        )) {
      // Range activity while watching marks the current item; full-file
      // prefetch of the next reel usually has little/no bytestart traffic.
      score += isReels ? 90000 : 25000;
    }
    if (isReels && captureTime != null && playbackStartedAt != null) {
      final deltaMs = captureTime.difference(playbackStartedAt).inMilliseconds;
      // Prefetch of the *next* reel often arrives late during playback.
      // Prefer media that appeared near session start / early playback.
      if (deltaMs >= -2000 && deltaMs <= 8000) {
        score += 20000;
      } else if (deltaMs > 20000) {
        score -= 35000;
      }
      // Pressed reel already playing for a while + brand-new capture ⇒ neighbor.
      final playedMs =
          DateTime.now().difference(playbackStartedAt).inMilliseconds;
      final captureAgeMs =
          DateTime.now().difference(captureTime).inMilliseconds;
      if (playedMs > 3000 && captureAgeMs < 2500) {
        score -= 90000;
      }
    }
    return score;
  }

  int _scoreFacebookImageCandidate(String url) {
    final lower = url.toLowerCase();
    var score = 0;
    if (!_isFacebookCdnUrl(url)) return score - 200;
    if (lower.contains('scontent.')) score += 2000;
    if (lower.contains('_o.') || lower.contains('_o.jpg')) score += 1800;
    if (lower.contains('_n.') || lower.contains('_n.jpg')) score += 900;
    if (lower.contains('p1080x1080') || lower.contains('p960x960')) {
      score += 1200;
    }
    if (lower.contains('p720x720') || lower.contains('s720x720')) score += 600;
    if (lower.contains('/t39.') ||
        lower.contains('/t15.') ||
        lower.contains('/t51.') ||
        lower.contains('/t45.')) {
      score += 700;
    }
    if (RegExp(
      r'(avatar|profile|emoji|sprite|sticker|icon|safe_image)',
    ).hasMatch(lower)) {
      score -= 5000;
    }
    if (lower.contains('.mp4') || lower.contains('video.')) score -= 8000;
    return score;
  }

  String _facebookUnsupportedMediaMessage({required bool forVideo}) {
    if (forVideo) {
      return 'Facebook 未能绑定当前长按的视频身份（邻条预加载会被拒绝）。'
          '请对准正在播放的视频再试；若仍失败请继续播放几秒后再长按。';
    }
    return 'Facebook 当前未捕获到可用图片地址（叠层/懒加载）。请对准图片本体再长按';
  }

  Set<String> _facebookActivelyStreamedVideoKeys({
    String? pageUrl,
    DateTime? notBefore,
  }) {
    final keys = <String>{};
    final now = DateTime.now();
    final requestedPage = Uri.tryParse((pageUrl ?? _currentUrl).trim());
    for (final resource in _capturedWebResources.values) {
      if (notBefore != null && resource.capturedAt.isBefore(notBefore)) {
        continue;
      }
      if (now.difference(resource.capturedAt) > const Duration(minutes: 10)) {
        continue;
      }
      final lower = resource.url.toLowerCase();
      final isRange =
          lower.contains('bytestart') ||
          lower.contains('byteend') ||
          isMediaFragmentUrl(resource.url);
      if (!isRange || !_isFacebookCdnUrl(resource.url)) continue;
      final capturedPage = Uri.tryParse(resource.pageUrl);
      if (requestedPage != null &&
          capturedPage != null &&
          requestedPage.host.isNotEmpty &&
          capturedPage.host.isNotEmpty &&
          requestedPage.host != capturedPage.host) {
        continue;
      }
      final whole =
          recoverWholeMediaUrlFromFragment(resource.url) ?? resource.url;
      final identity = facebookMediaIdentity(whole);
      if (identity.isNotEmpty) keys.add(identity);
    }
    return keys;
  }

  DateTime? _facebookCaptureTimeForUrl(String url) {
    final absolute = _toAbsoluteUrl(url);
    final direct = _capturedWebResources[absolute]?.capturedAt;
    if (direct != null) return direct;
    final identity = facebookMediaIdentity(absolute);
    if (identity.isEmpty) return _trustedMediaCandidateUrls[absolute];
    DateTime? best;
    for (final entry in _capturedWebResources.entries) {
      final key = facebookMediaIdentity(entry.key);
      if (key.isEmpty || !facebookIdentitiesMatch(key, identity)) continue;
      final at = entry.value.capturedAt;
      if (best == null || at.isAfter(best)) best = at;
    }
    return best ?? _trustedMediaCandidateUrls[absolute];
  }

  String? _findFacebookPairedAudioUrl({
    required String videoId,
    required Iterable<String> explicitCandidates,
    String pageUrl = '',
  }) {
    final wanted = videoId.trim();
    if (wanted.isEmpty) return null;
    final pageHost = Uri.tryParse(pageUrl)?.host.toLowerCase() ?? '';
    final ranked = <(String, int, DateTime)>[];
    final seen = <String>{};

    void consider(
      String raw, {
      DateTime? capturedAt,
      String capturedPage = '',
    }) {
      if (!seen.add(raw)) return;
      final metadata = facebookMediaMetadata(raw);
      if (metadata?.isAudioOnly != true || metadata!.videoId != wanted) return;
      final capturedHost = Uri.tryParse(capturedPage)?.host.toLowerCase() ?? '';
      if (pageHost.isNotEmpty &&
          capturedHost.isNotEmpty &&
          pageHost != capturedHost) {
        return;
      }
      final whole = recoverWholeMediaUrlFromFragment(raw) ?? raw;
      if (isMediaFragmentUrl(whole)) return;
      ranked.add((
        whole,
        metadata.bitrate ?? 0,
        capturedAt ?? DateTime.fromMillisecondsSinceEpoch(0),
      ));
    }

    for (final candidate in explicitCandidates) {
      consider(candidate);
    }
    for (final entry in _capturedWebResources.entries) {
      consider(
        entry.key,
        capturedAt: entry.value.capturedAt,
        capturedPage: entry.value.pageUrl,
      );
    }
    for (final entry in _trustedMediaCandidateUrls.entries) {
      consider(entry.key, capturedAt: entry.value);
    }
    ranked.sort((left, right) {
      final bitrateOrder = right.$2.compareTo(left.$2);
      if (bitrateOrder != 0) return bitrateOrder;
      return right.$3.compareTo(left.$3);
    });
    final selected = ranked.isEmpty ? null : ranked.first.$1;
    debugPrint(
      'FB audio pair: videoId=$wanted candidates=${ranked.length} '
      'selected=${selected != null}',
    );
    return selected;
  }

  /// Keep only URLs that share [boundKey].
  /// `reel:N` may match `fbvideo:N` when Facebook reuses the numeric id.
  List<String> _facebookCandidatesMatchingBound(
    Iterable<String> urls,
    String boundKey,
  ) {
    final key = boundKey.trim();
    if (key.isEmpty) return const <String>[];
    return urls
        .where((url) {
          final id = facebookMediaIdentity(url);
          return id.isNotEmpty && facebookIdentitiesMatch(id, key);
        })
        .toList(growable: false);
  }

  /// Recover downloadable whole-file URLs for a bound identity from captures,
  /// including bytestart/byteend fragments (stripped to full progressive MP4).
  ///
  /// `_recentCapturedMediaCandidates` intentionally skips fragments — that
  /// left us with a correct `fbvideo:` bind but zero progressive candidates
  /// (FB_DL: resolve exhausted after strongSolo bind).
  List<String> _facebookHarvestUrlsForBoundKey(
    String boundKey, {
    DateTime? notBefore,
    bool includeOlder = true,
  }) {
    final key = boundKey.trim();
    if (key.isEmpty) return const <String>[];
    final keys = <String>{key};
    if (key.startsWith('reel:')) {
      final bare = key.substring('reel:'.length);
      if (RegExp(r'^\d{6,}$').hasMatch(bare)) {
        keys.add('fbvideo:$bare');
      }
    } else if (key.startsWith('fbvideo:')) {
      final bare = key.substring('fbvideo:'.length);
      if (RegExp(r'^\d{6,}$').hasMatch(bare)) {
        keys.add('reel:$bare');
      }
    }
    bool idMatches(String id) =>
        keys.any((k) => facebookIdentitiesMatch(id, k));

    final out = <String>[];
    final seen = <String>{};
    void consider(String raw, DateTime? at) {
      if (notBefore != null &&
          !includeOlder &&
          at != null &&
          at.isBefore(notBefore)) {
        return;
      }
      final whole = recoverWholeMediaUrlFromFragment(raw) ?? raw;
      final id = facebookMediaIdentity(whole);
      if (id.isEmpty || !idMatches(id)) return;
      final normalized = _normalizeFacebookMediaCandidate(whole, video: true);
      if (normalized == null || !seen.add(normalized)) return;
      out.add(normalized);
    }

    for (final entry in _capturedWebResources.entries) {
      consider(entry.key, entry.value.capturedAt);
    }
    for (final entry in _trustedMediaCandidateUrls.entries) {
      consider(entry.key, entry.value);
    }
    return out;
  }

  bool _isFacebookCdnIdentity(String key) {
    final k = key.trim();
    if (k.isEmpty || k.startsWith('reel:')) return false;
    return k.startsWith('fbvideo:') ||
        RegExp(r'^\d').hasMatch(k) ||
        k.contains('_');
  }

  /// Prefer a CDN stem identity over reel:page-id (which cannot match captures).
  /// X-like rule: never invent a bind from "lone active prefetch" or arbitrary
  /// input candidates — only from expected key, finger post-prime streams, or
  /// the pressed element's own progressive URL.
  String _facebookUpgradeBoundKey({
    required String expectedVideoKey,
    required String primaryUrl,
    required List<String> inputCandidates,
    required Set<String> activeKeys,
    required String pageUrl,

    /// Keys that streamed *because* we primed the finger video — strongest
    /// CDN bind, like X's mediaId from the pressed tweet.
    Map<String, int> postPrimeCounts = const {},
    bool fingerUnderVideo = false,
  }) {
    var boundKey = expectedVideoKey.trim();
    void consider(String key) {
      final k = key.trim();
      if (_isFacebookCdnIdentity(k)) boundKey = k;
    }

    // Silence unused: callers still pass pre-prime activeKeys for API symmetry.
    // Never promote activeKeys — neighbor prefetch often owns the lone stream.
    // ignore: unused_local_variable
    final _ = activeKeys;

    // Keep a stable fbvideo: bind from JS/long-press if already known.
    if (_isFacebookCdnIdentity(boundKey)) {
      return boundKey;
    }

    // Post-prime range traffic from the *finger* video.
    // NEVER accept a lone identity (buffered current emits no ranges; next
    // prefetch often owns the only bytestart stream). Require dominance.
    if (postPrimeCounts.isNotEmpty &&
        (fingerUnderVideo || boundKey.startsWith('reel:'))) {
      final ranked =
          postPrimeCounts.entries.toList()
            ..sort((a, b) => b.value.compareTo(a.value));
      final top = ranked.first;
      final second = ranked.length > 1 ? ranked[1].value : 0;
      final dominates =
          ranked.length >= 2 && top.value >= 3 && top.value >= second * 2;
      // After a real finger prime+seek, a single streaming identity is the
      // current reel — require fewer hits than the old ">=5" guard (which was
      // meant for the broken async-prime={} path).
      final strongSolo =
          ranked.length == 1 &&
          (top.value >= 5 || (fingerUnderVideo && top.value >= 1));
      if (dominates || strongSolo) {
        consider(top.key);
        debugPrint(
          'FB_DL upgrade postPrime top=${top.key} count=${top.value} '
          'second=$second dominates=$dominates strongSolo=$strongSolo '
          'finger=$fingerUnderVideo',
        );
      } else {
        debugPrint(
          'FB_DL upgrade postPrime AMBIGUOUS counts=$postPrimeCounts '
          '(refuse lone/weak prefetch bind)',
        );
      }
    }

    // Soft reel: MUST NOT promote primaryUrl / interceptor candidates.
    // But Facebook often reuses reel numeric id as efg.video_id — try that.
    if (boundKey.startsWith('reel:')) {
      final bare = boundKey.substring('reel:'.length);
      if (RegExp(r'^\d{6,}$').hasMatch(bare)) {
        final sameId = 'fbvideo:$bare';
        final harvested = _facebookHarvestUrlsForBoundKey(sameId);
        if (harvested.isNotEmpty) {
          debugPrint(
            'FB_DL upgrade softReel→sameId $boundKey → $sameId '
            'urls=${harvested.length}',
          );
          return sameId;
        }
      }
      debugPrint(
        'FB_DL upgrade keep softReel=$boundKey '
        '(refuse primary/candidate CDN guess; harvest empty)',
      );
      return boundKey;
    }
    // Pressed element's own progressive URL (never browse-history candidates).
    if (!_isFacebookCdnIdentity(boundKey)) {
      consider(facebookMediaIdentity(primaryUrl));
    }
    // Explicit long-press candidates only when they already share expected key.
    if (!_isFacebookCdnIdentity(boundKey)) {
      for (final candidate in inputCandidates) {
        final key = facebookMediaIdentity(candidate);
        if (_isFacebookCdnIdentity(key) &&
            (expectedVideoKey.isEmpty ||
                facebookIdentitiesMatch(key, expectedVideoKey))) {
          boundKey = key;
          break;
        }
      }
    }
    if (!_isFacebookCdnIdentity(boundKey)) {
      final pageKey = facebookMediaIdentity(pageUrl);
      if (_isFacebookCdnIdentity(pageKey)) boundKey = pageKey;
    }
    return boundKey;
  }

  /// Drop stale FB progressive captures that belong to other reels so later
  /// resolves cannot drain browse history before the current item.
  void _pruneStaleFacebookProgressiveCaptures(String boundKey) {
    final key = boundKey.trim();
    if (key.isEmpty || key.startsWith('reel:')) return;
    final staleUrls = <String>[];
    for (final entry in _capturedWebResources.entries) {
      if (!_isFacebookProgressiveMp4Url(entry.key)) continue;
      final id = facebookMediaIdentity(entry.key);
      if (id.isEmpty) continue;
      if (!facebookIdentitiesMatch(id, key)) {
        staleUrls.add(entry.key);
      }
    }
    for (final url in staleUrls) {
      _capturedWebResources.remove(url);
    }
    final staleTrusted = <String>[];
    for (final entry in _trustedMediaCandidateUrls.entries) {
      if (!_isFacebookProgressiveMp4Url(entry.key)) continue;
      final id = facebookMediaIdentity(entry.key);
      if (id.isEmpty) continue;
      if (!facebookIdentitiesMatch(id, key)) {
        staleTrusted.add(entry.key);
      }
    }
    for (final url in staleTrusted) {
      _trustedMediaCandidateUrls.remove(url);
    }
    if (staleUrls.isNotEmpty || staleTrusted.isNotEmpty) {
      debugPrint(
        'FB bind: pruned stale progressive '
        'captures=${staleUrls.length} trusted=${staleTrusted.length} '
        'boundKey=$key',
      );
    }
  }

  /// Cancel in-flight *smart/action-recipe* FB downloads that are not the
  /// current bound reel. Never touches user manual downloads.
  void _cancelStaleSmartFacebookDownloads(String boundKey) {
    final key = boundKey.trim();
    if (key.isEmpty || key.startsWith('reel:')) return;
    final staleIds = <String>[];
    for (final row in _downloadTasks) {
      if (row['isSmartBatchMedia'] != true) continue;
      if (row['status'] != 'downloading') continue;
      final url = (row['url'] ?? '').toString();
      if (url.startsWith('action-recipe://')) continue;
      if (!_isFacebookCdnUrl(url) &&
          !url.toLowerCase().contains('facebook.com')) {
        continue;
      }
      final id = facebookMediaIdentity(url);
      if (id.isEmpty) continue;
      if (facebookIdentitiesMatch(id, key)) continue;
      final idStr = (row['id'] ?? '').toString();
      if (idStr.isNotEmpty) staleIds.add(idStr);
    }
    for (final id in staleIds) {
      final idx = _downloadTasks.indexWhere((row) => row['id'] == id);
      if (idx < 0) continue;
      final token = _downloadTasks[idx]['cancelToken'];
      if (token is CancelToken && !token.isCancelled) {
        token.cancel('stale_fb_smart_candidate');
      }
      _downloadingUrls.remove((_downloadTasks[idx]['url'] ?? '').toString());
      _removeDownloadTask(id);
    }
    if (staleIds.isNotEmpty) {
      debugPrint(
        'FB bind: cancelled ${staleIds.length} stale smart FB downloads '
        'boundKey=$key',
      );
    }
  }

  /// Facebook 常只在真正播放后才请求当前视频的 progressive/DASH/range 资源。
  /// 必须只 play/seek **手指下/正在播的那条**，绝不能挑「最大可见」——
  /// 否则会把预加载的下一条当成当前条（与 X 按推文 mediaId 绑定同理）。
  Future<Map<String, dynamic>?> _primeFacebookCurrentVideoForDownload() async {
    try {
      // MUST be sync IIFE. InAppWebView does not await async evaluateJavascript
      // promises — async version returned {} and skipped post-prime bind, then
      // Dart upgraded from a neighbor CDN URL (wrong reel + false duplicates).
      final raw = await _controller?.evaluateJavascript(
        source: r'''
(() => {
  const videos = Array.from(document.querySelectorAll('video'));
  const vw = window.innerWidth || 1;
  const vh = window.innerHeight || 1;
  const tx = (typeof window._lastTouchX === 'number') ? window._lastTouchX : (vw / 2);
  const ty = (typeof window._lastTouchY === 'number') ? window._lastTouchY : (vh / 2);
  const scored = videos
    .map((video) => {
      const r = video.getBoundingClientRect();
      const visibleW = Math.max(0, Math.min(r.right, vw) - Math.max(r.left, 0));
      const visibleH = Math.max(0, Math.min(r.bottom, vh) - Math.max(r.top, 0));
      const area = visibleW * visibleH;
      const contains = tx >= r.left && tx <= r.right && ty >= r.top && ty <= r.bottom;
      const cx = r.left + r.width / 2;
      const cy = r.top + r.height / 2;
      const distance = Math.hypot(cx - tx, cy - ty);
      let score = area - distance * 200;
      if (contains) score += 1e12;
      if (!video.paused && !video.ended) score += 1e11;
      if (Number(video.currentTime || 0) > 0.2) score += 1e9;
      return {video, r, area, score, contains};
    })
    .filter((x) => x.area > 4096 && x.r.width > 80 && x.r.height > 80)
    .sort((a, b) => b.score - a.score);
  const picked = scored[0];
  if (!picked) return {ok:false, reason:'no_visible_video'};
  const video = picked.video;
  const before = {
    paused: !!video.paused,
    currentTime: Number(video.currentTime || 0),
    readyState: Number(video.readyState || 0),
    src: String(video.currentSrc || video.src || ''),
    finger: !!picked.contains
  };
  try {
    try { video.muted = false; } catch (_) {}
    try { video.play(); } catch (_) {}
    // Tiny seek forces MSE to expose *this* reel's ranges — not a neighbor.
    const duration = Number(video.duration);
    const current = Number(video.currentTime || 0);
    if (Number.isFinite(duration) && duration > 1) {
      const target = Math.min(Math.max(0, current + 0.45), duration - 0.1);
      if (Math.abs(target - current) > 0.05) video.currentTime = target;
    } else if (Number.isFinite(current)) {
      video.currentTime = Math.max(0, current + 0.25);
    }
  } catch (e) {
    return Object.assign({}, before, {ok:false, reason:'play_rejected', error:String(e)});
  }
  let reelId = '';
  try {
    const link = video.closest && video.closest('a[href*="/reel/"], a[href*="/reels/"], a[href*="/videos/"]');
    if (link && link.href) {
      const m = String(link.href).match(/\/(?:reel|reels|videos)\/(\d{6,})/i);
      if (m) reelId = m[1];
    }
  } catch (_) {}
  if (!reelId) {
    try {
      let node = video;
      for (let depth = 0; !reelId && node && depth < 10; depth++, node = node.parentElement) {
        const attr = node.getAttribute && (
          node.getAttribute('data-video-id') ||
          node.getAttribute('data-id') ||
          node.getAttribute('data-reel-id')
        );
        if (attr && /^\d{6,}$/.test(String(attr))) {
          reelId = String(attr);
          break;
        }
      }
    } catch (_) {}
  }
  if (!reelId) {
    try {
      const m = String(location.href || '').match(/\/(?:reel|reels|videos)\/(\d{6,})/i);
      if (m) reelId = m[1];
    } catch (_) {}
  }
  let videoId = '';
  try {
    const src = String(video.currentSrc || video.src || '');
    const efgMatch = src.match(/[?&]efg=([^&]+)/i);
    if (efgMatch) {
      const normalized = decodeURIComponent(efgMatch[1])
        .replace(/-/g, '+').replace(/_/g, '/');
      const padded = normalized + '='.repeat((4 - normalized.length % 4) % 4);
      const metadata = JSON.parse(atob(padded));
      videoId = String(metadata.video_id || '').trim();
    }
  } catch (_) {}
  return {
    ok:true,
    paused: !!video.paused,
    currentTime: Number(video.currentTime || 0),
    readyState: Number(video.readyState || 0),
    duration: Number.isFinite(video.duration) ? Number(video.duration) : null,
    src: String(video.currentSrc || video.src || ''),
    finger: !!picked.contains,
    reelId: reelId,
    videoId: videoId
  };
})()
''',
      );
      final result = _coerceJsMap(raw);
      debugPrint('FB_DL prime rawType=${raw.runtimeType} result=$result');
      return result;
    } catch (e) {
      debugPrint('FB current-video prime failed: $e');
      return null;
    }
  }

  /// Count byte-range activity per identity in a time window (for post-prime bind).
  Map<String, int> _facebookActiveStreamCounts({
    String? pageUrl,
    DateTime? notBefore,
  }) {
    final counts = <String, int>{};
    final now = DateTime.now();
    final requestedPage = Uri.tryParse((pageUrl ?? _currentUrl).trim());
    for (final resource in _capturedWebResources.values) {
      if (notBefore != null && resource.capturedAt.isBefore(notBefore)) {
        continue;
      }
      if (now.difference(resource.capturedAt) > const Duration(minutes: 10)) {
        continue;
      }
      final lower = resource.url.toLowerCase();
      final isRange =
          lower.contains('bytestart') ||
          lower.contains('byteend') ||
          isMediaFragmentUrl(resource.url);
      if (!isRange || !_isFacebookCdnUrl(resource.url)) continue;
      final capturedPage = Uri.tryParse(resource.pageUrl);
      if (requestedPage != null &&
          capturedPage != null &&
          requestedPage.host.isNotEmpty &&
          capturedPage.host.isNotEmpty &&
          requestedPage.host != capturedPage.host) {
        continue;
      }
      final whole =
          recoverWholeMediaUrlFromFragment(resource.url) ?? resource.url;
      final identity = facebookMediaIdentity(whole);
      if (identity.isEmpty) continue;
      counts[identity] = (counts[identity] ?? 0) + 1;
    }
    return counts;
  }

  Future<List<String>> _resolveFacebookLongPressVideoCandidates({
    required String primaryUrl,
    required List<String> candidates,
    required String pageUrl,
    DateTime? notBefore,
    String expectedVideoKey = '',
    bool isReels = false,
  }) async {
    final onFacebook =
        _isFacebookPlatformPage(pageUrl) ||
        _isFacebookPlatformPage(_currentUrl) ||
        _isFacebookCdnUrl(primaryUrl) ||
        candidates.any(_isFacebookCdnUrl);
    if (!onFacebook) {
      return <String>[
        primaryUrl,
        ...candidates,
      ].where((url) => url.trim().isNotEmpty).toSet().toList();
    }
    final reelsContext =
        isReels ||
        isFacebookReelsPageUrl(pageUrl) ||
        isFacebookReelsPageUrl(_currentUrl);
    // Explicit long-press / gesture inputs only — never treat page history as
    // the seed list when identity binding is still unresolved.
    // (Trusted primary is decided after soft-reel discard below.)

    var effectiveNotBefore = notBefore;
    var activeKeys = _facebookActivelyStreamedVideoKeys(
      pageUrl: pageUrl,
      notBefore: effectiveNotBefore,
    );
    var postPrimeCounts = <String, int>{};
    var fingerUnderVideo = false;
    var softReelKey = '';
    // Seed soft reel identity from JS/page before priming upgrades to fbvideo:.
    final expectedSeed = expectedVideoKey.trim();
    if (expectedSeed.startsWith('reel:')) {
      softReelKey = expectedSeed;
    } else if (expectedSeed.isEmpty) {
      final pageId = facebookMediaIdentity(pageUrl);
      if (pageId.startsWith('reel:')) softReelKey = pageId;
    }
    // 无论手动还是智能长按，都先确保**手指下**的视频真正开始播放。Facebook
    // 往往在此后才暴露当前条目的完整 progressive/DASH/range 地址。
    final primeStartedAt = DateTime.now().subtract(
      const Duration(milliseconds: 400),
    );
    final primed = await _primeFacebookCurrentVideoForDownload();
    final primedOk = primed?['ok'] == true;
    if (primedOk) {
      fingerUnderVideo = primed?['finger'] == true;
      final primedReel = (primed?['reelId'] ?? '').toString().trim();
      if (primedReel.isNotEmpty) {
        softReelKey = 'reel:$primedReel';
      }
    }
    // Always wait after prime attempt when we only have soft reel identity —
    // need bytestart ranges from *this* video. Previously async prime returned
    // {} so this wait never ran and we bound a neighbor CDN URL instead.
    if (primedOk || softReelKey.isNotEmpty || reelsContext) {
      // Paused / readyState<2 often needs longer for MSE range requests.
      final paused = primed?['paused'] == true;
      final ready = (primed?['readyState'] as num?)?.toInt() ?? 0;
      final waitMs = (paused || ready < 2) ? 3200 : 2200;
      await Future<void>.delayed(Duration(milliseconds: waitMs));
      effectiveNotBefore = primeStartedAt;
      activeKeys = _facebookActivelyStreamedVideoKeys(
        pageUrl: pageUrl,
        notBefore: effectiveNotBefore,
      );
      postPrimeCounts = _facebookActiveStreamCounts(
        pageUrl: pageUrl,
        notBefore: primeStartedAt,
      );
      debugPrint(
        'FB_DL post-prime counts=$postPrimeCounts '
        'finger=$fingerUnderVideo softReel=$softReelKey '
        'videoId=${primed?['videoId']} ok=$primedOk '
        'waitMs=$waitMs paused=$paused ready=$ready',
      );
    }
    // JS may still ship a neighbor progressive as primary when blob has no
    // CDN bind. Never trust it for identity while we only know soft reel.
    var trustedPrimary = primaryUrl;
    if (softReelKey.isNotEmpty) {
      final primaryId = facebookMediaIdentity(primaryUrl);
      if (_isFacebookCdnIdentity(primaryId)) {
        debugPrint(
          'FB_DL discard untrusted JS primary id=$primaryId '
          'soft=$softReelKey',
        );
        trustedPrimary = '';
      }
    }
    final inputTrusted = <String>[
      trustedPrimary,
      ...candidates,
    ].where((url) => url.trim().isNotEmpty).toList(growable: false);
    final primedVideoIdForBind =
        primedOk ? (primed?['videoId'] ?? '').toString().trim() : '';
    var boundKey = _facebookUpgradeBoundKey(
      expectedVideoKey:
          primedVideoIdForBind.isNotEmpty
              ? 'fbvideo:${primedVideoIdForBind.toLowerCase()}'
              : (_isFacebookCdnIdentity(expectedSeed)
                  ? expectedSeed
                  : (softReelKey.isNotEmpty ? softReelKey : expectedSeed)),
      primaryUrl: trustedPrimary,
      inputCandidates: inputTrusted,
      activeKeys: activeKeys,
      pageUrl: pageUrl,
      postPrimeCounts: postPrimeCounts,
      fingerUnderVideo: fingerUnderVideo,
    );
    if (_isFacebookCdnIdentity(boundKey)) {
      _pruneStaleFacebookProgressiveCaptures(boundKey);
      _cancelStaleSmartFacebookDownloads(boundKey);
    }

    int scoreOf(String url) => _scoreFacebookVideoCandidate(
      url,
      expectedVideoKey: boundKey,
      isReels: reelsContext,
      captureTime: _facebookCaptureTimeForUrl(url),
      playbackStartedAt: effectiveNotBefore,
      activelyStreamedKeys: activeKeys,
    );

    List<String> normalizeAll(Iterable<String> raw) {
      final out = <String>[];
      final seen = <String>{};
      for (final value in raw) {
        final normalized = _normalizeFacebookMediaCandidate(value, video: true);
        if (normalized == null || !seen.add(normalized)) continue;
        out.add(normalized);
      }
      return out;
    }

    /// Same-identity progressive variants only — never a multi-reel drain list.
    List<String> bindOnlyCurrent(List<String> ranked) {
      final progressive = ranked
          .where(_isFacebookProgressiveMp4Url)
          .toList(growable: false);
      if (progressive.isEmpty) {
        return ranked;
      }
      final top = progressive.first;
      final topKey = facebookMediaIdentity(top);
      final sameIdentity =
          topKey.isEmpty
              ? <String>[top]
              : progressive
                  .where(
                    (url) => facebookIdentitiesMatch(
                      facebookMediaIdentity(url),
                      topKey,
                    ),
                  )
                  .toList(growable: false);
      final playlists = ranked
          .where((url) {
            final lower = url.toLowerCase();
            if (!lower.contains('.m3u8') && !lower.contains('.mpd')) {
              return false;
            }
            if (topKey.isEmpty) return true;
            final id = facebookMediaIdentity(url);
            return id.isEmpty || facebookIdentitiesMatch(id, topKey);
          })
          .toList(growable: false);
      return <String>[...sameIdentity, ...playlists];
    }

    var merged = List<String>.from(inputTrusted);
    for (var attempt = 0; attempt < 12; attempt++) {
      // Captures may include neighbor/history progressive MP4s. Only merge
      // them as *sources to score*; output is always same-identity only.
      merged = <String>[
        ...merged,
        ..._recentCapturedMediaCandidates(
          MediaType.video,
          pageUrl: pageUrl,
          notBefore: effectiveNotBefore,
          limit: reelsContext ? 32 : 48,
        ),
      ];
      for (final entry in _trustedMediaCandidateUrls.entries) {
        if (!_isFacebookCdnUrl(entry.key)) continue;
        if (DateTime.now().difference(entry.value) >
            const Duration(minutes: 30)) {
          continue;
        }
        merged.add(entry.key);
      }
      // CRITICAL: recover whole MP4 from bytestart captures for the bound id.
      // Recent-candidate scan skips fragments, which left correct binds with
      // zero downloadable URLs (user saw「未能绑定」snackbar).
      final harvestKey =
          _isFacebookCdnIdentity(boundKey)
              ? boundKey
              : (softReelKey.isNotEmpty ? softReelKey : boundKey);
      if (harvestKey.isNotEmpty) {
        final harvested = _facebookHarvestUrlsForBoundKey(
          harvestKey,
          notBefore: effectiveNotBefore,
          includeOlder: true,
        );
        if (harvested.isNotEmpty) {
          merged.addAll(harvested);
          if (attempt == 0 || attempt == 3 || attempt == 7) {
            debugPrint(
              'FB_DL harvest key=$harvestKey n=${harvested.length} '
              'sample=${harvested.first.length > 100 ? harvested.first.substring(0, 100) : harvested.first}',
            );
          }
        } else if (attempt == 0 || attempt == 6) {
          debugPrint('FB_DL harvest EMPTY key=$harvestKey');
        }
      }
      // Refresh post-prime counts each attempt — ranges may arrive late.
      if (attempt > 0 && attempt % 3 == 0) {
        postPrimeCounts = _facebookActiveStreamCounts(
          pageUrl: pageUrl,
          notBefore: primeStartedAt,
        );
      }
      // Re-upgrade bound key once captures arrive (primary may have been blob).
      boundKey = _facebookUpgradeBoundKey(
        expectedVideoKey:
            _isFacebookCdnIdentity(boundKey)
                ? boundKey
                : (softReelKey.isNotEmpty
                    ? softReelKey
                    : (boundKey.isNotEmpty ? boundKey : expectedVideoKey)),
        primaryUrl: trustedPrimary,
        inputCandidates: normalizeAll(inputTrusted),
        activeKeys: _facebookActivelyStreamedVideoKeys(
          pageUrl: pageUrl,
          notBefore: effectiveNotBefore,
        ),
        pageUrl: pageUrl,
        postPrimeCounts: postPrimeCounts,
        fingerUnderVideo: fingerUnderVideo,
      );

      final usable = normalizeAll(merged);
      usable.sort((left, right) => scoreOf(right).compareTo(scoreOf(left)));

      List<String> scoped = const <String>[];
      final hasCdnBound = _isFacebookCdnIdentity(boundKey);
      if (hasCdnBound || boundKey.startsWith('reel:')) {
        final matched = _facebookCandidatesMatchingBound(usable, boundKey);
        if (matched.isNotEmpty) {
          scoped = matched;
        } else {
          // Direct harvest bypasses usable scoring gaps.
          scoped = _facebookHarvestUrlsForBoundKey(
            boundKey,
            includeOlder: true,
          );
        }
      } else if (postPrimeCounts.isNotEmpty &&
          (fingerUnderVideo || softReelKey.isNotEmpty)) {
        // Same dominance rule as upgrade — never lone prefetch.
        final ranked =
            postPrimeCounts.entries.toList()
              ..sort((a, b) => b.value.compareTo(a.value));
        final top = ranked.first;
        final second = ranked.length > 1 ? ranked[1].value : 0;
        final dominates =
            ranked.length >= 2 && top.value >= 3 && top.value >= second * 2;
        final strongSolo =
            ranked.length == 1 &&
            (top.value >= 5 || (fingerUnderVideo && top.value >= 1));
        if (_isFacebookCdnIdentity(top.key) && (dominates || strongSolo)) {
          final matched = _facebookCandidatesMatchingBound(usable, top.key);
          if (matched.isNotEmpty) {
            scoped = matched;
            boundKey = top.key;
          } else {
            final harvested = _facebookHarvestUrlsForBoundKey(top.key);
            if (harvested.isNotEmpty) {
              scoped = harvested;
              boundKey = top.key;
            }
          }
        }
      }
      // No CDN identity → do not download anything. Fail clearly (X-style).

      final progressive = scoped
          .where(_isFacebookProgressiveMp4Url)
          .toList(growable: false);
      final hasPlaylist = scoped.any((url) {
        final lower = url.toLowerCase();
        return lower.contains('.m3u8') || lower.contains('.mpd');
      });
      if (progressive.isNotEmpty) {
        final boundOnly = bindOnlyCurrent(scoped);
        final top = boundOnly.first;
        final topKey = facebookMediaIdentity(top);
        // Refuse to return a progressive that does not match the bind.
        if (_isFacebookCdnIdentity(boundKey) &&
            topKey.isNotEmpty &&
            !facebookIdentitiesMatch(topKey, boundKey)) {
          debugPrint(
            'FB media strategy: refuse mismatched top=$topKey '
            'bound=$boundKey (neighbor guard)',
          );
          await Future<void>.delayed(const Duration(milliseconds: 250));
          continue;
        }
        final reason =
            hasCdnBound && facebookIdentitiesMatch(topKey, boundKey)
                ? 'bound_current'
                : (activeKeys.any((key) => facebookIdentitiesMatch(topKey, key))
                    ? 'active_stream'
                    : (reelsContext ? 'reels_bound' : 'quality'));
        final skippedNeighbor = usable
            .where(_isFacebookProgressiveMp4Url)
            .where(
              (url) =>
                  topKey.isNotEmpty &&
                  !facebookIdentitiesMatch(facebookMediaIdentity(url), topKey),
            )
            .take(1)
            .toList(growable: false);
        debugPrint(
          'FB media strategy: reason=$reason reels=$reelsContext '
          'boundKey=${boundKey.isEmpty ? "(none)" : boundKey} '
          'topKey=${topKey.isEmpty ? "(none)" : topKey} '
          'softReel=${softReelKey.isEmpty ? "(none)" : softReelKey} '
          'activeKeys=${activeKeys.length} '
          'progressive=${boundOnly.where(_isFacebookProgressiveMp4Url).length} '
          'playlist=$hasPlaylist '
          'total=${usable.length} bindOnly=${boundOnly.length} top=$top'
          '${skippedNeighbor.isEmpty ? "" : " skippedNeighbor=${skippedNeighbor.first}"}',
        );
        if (_isFacebookCdnIdentity(topKey)) {
          _pruneStaleFacebookProgressiveCaptures(topKey);
          _cancelStaleSmartFacebookDownloads(topKey);
        }
        return boundOnly;
      }
      if (hasPlaylist) {
        final playlists = bindOnlyCurrent(scoped);
        debugPrint(
          'FB media strategy: no progressive MP4; falling back to '
          'HLS/DASH candidates (${playlists.length}) boundKey=$boundKey',
        );
        return playlists;
      }
      await Future<void>.delayed(const Duration(milliseconds: 250));
    }
    // Exhausted: fail closed. Returning a scored neighbor is how wrong Reels
    // get saved; callers must surface "cannot bind" instead.
    debugPrint(
      'FB media strategy: resolve exhausted WITHOUT safe bind; '
      'boundKey=$boundKey softReel=$softReelKey finger=$fingerUnderVideo '
      'reels=$reelsContext — refusing neighbor fallback',
    );
    return const <String>[];
  }

  /// Google / X 等登录后需要尽快把 cookie 落盘的站点。
  bool _shouldPersistCookiesForUrl(String? url) {
    if (_isXPlatformPage(url) || _isFacebookPlatformPage(url)) return true;
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    if (host.isEmpty) return false;
    return host == 'google.com' ||
        host.endsWith('.google.com') ||
        host == 'google.cn' ||
        host.endsWith('.google.cn') ||
        host == 'googleapis.com' ||
        host.endsWith('.googleapis.com') ||
        host == 'gstatic.com' ||
        host.endsWith('.gstatic.com') ||
        host == 'youtube.com' ||
        host.endsWith('.youtube.com') ||
        host == 'youtu.be';
  }

  bool _isXMediaViewerPage(String? url) {
    final uri = Uri.tryParse((url ?? '').trim());
    if (uri == null || !_isXPlatformPage(url)) return false;
    final path = uri.path.toLowerCase();
    return path.contains('/mediaviewer') ||
        uri.queryParameters.containsKey('currentTweet');
  }

  bool _isXStatusDetailPage(String? url) {
    final uri = Uri.tryParse((url ?? '').trim());
    if (uri == null || !_isXPlatformPage(url)) return false;
    final segments = uri.pathSegments.where((part) => part.isNotEmpty).toList();
    final statusIndex = segments.indexWhere(
      (part) => part.toLowerCase() == 'status',
    );
    return statusIndex >= 0 &&
        statusIndex + 1 < segments.length &&
        RegExp(r'^\d+$').hasMatch(segments[statusIndex + 1]);
  }

  bool _isSameXSmartReturnPage(String expected, String actual) {
    if (_isSameLoadedDocument(expected, actual)) return true;
    final expectedUri = Uri.tryParse(expected);
    final actualUri = Uri.tryParse(actual);
    if (expectedUri == null ||
        actualUri == null ||
        !_isXPlatformPage(expected) ||
        !_isXPlatformPage(actual) ||
        _isXStatusDetailPage(actual) ||
        _isXMediaViewerPage(actual)) {
      return false;
    }
    final expectedPath =
        expectedUri.path.isEmpty ? '/' : expectedUri.path.toLowerCase();
    final actualPath =
        actualUri.path.isEmpty ? '/' : actualUri.path.toLowerCase();
    return (expectedPath == '/' && actualPath == '/home') ||
        (expectedPath == '/home' && actualPath == '/');
  }

  String _xMediaIdentity(String url) {
    final match = RegExp(
      r'/(?:amplify_video|ext_tw_video|tweet_video)/(\d+)/',
      caseSensitive: false,
    ).firstMatch(url);
    return match?.group(1) ?? '';
  }

  int _scoreXVideoCandidate(String url) {
    final lower = url.toLowerCase();
    var score = _scoreFavoriteVideoUrl(url);
    if (!lower.contains('video.twimg.com/')) return score;
    if (RegExp(r'/pl/[^/]+\.m3u8(?:\?|$)').hasMatch(lower)) score += 10000;
    if (lower.contains('/pl/avc1/')) score += 4000;
    if (lower.contains('/vid/avc1/')) score += 3000;
    if (lower.contains('/pl/mp4a/') || lower.contains('/aud/mp4a/')) {
      score -= 20000;
    }
    return score;
  }

  Future<List<String>> _resolveXLongPressVideoCandidates({
    required String primaryUrl,
    required List<String> candidates,
    required String pageUrl,
    String expectedMediaId = '',
    DateTime? notBefore,
  }) async {
    if (!_isXPlatformPage(pageUrl) && !_isXPlatformPage(_currentUrl)) {
      return <String>[
        primaryUrl,
        ...candidates,
      ].where((url) => url.trim().isNotEmpty).toSet().toList();
    }
    final mediaId =
        expectedMediaId.trim().isNotEmpty
            ? expectedMediaId.trim()
            : _xMediaIdentity(primaryUrl);
    var merged = <String>[primaryUrl, ...candidates];
    for (var attempt = 0; attempt < 20; attempt++) {
      merged = <String>[
        ...merged,
        ..._recentCapturedMediaCandidates(
          MediaType.video,
          pageUrl: pageUrl,
          // X often loads the master before playback. The media-ID filter
          // below prevents this wider capture window from crossing posts.
          notBefore: mediaId.isEmpty ? notBefore : null,
          limit: 48,
        ),
      ];
      final sameMedia =
          merged
              .where((url) {
                if (url.trim().isEmpty) return false;
                return mediaId.isEmpty || _xMediaIdentity(url) == mediaId;
              })
              .toSet()
              .toList()
            ..sort(
              (left, right) => _scoreXVideoCandidate(
                right,
              ).compareTo(_scoreXVideoCandidate(left)),
            );
      final hasUsableVideo = sameMedia.any(
        (url) =>
            _scoreXVideoCandidate(url) > 0 &&
            !url.toLowerCase().contains('/mp4a/') &&
            !url.toLowerCase().contains('/aud/'),
      );
      if (hasUsableVideo) return sameMedia;
      await Future<void>.delayed(const Duration(milliseconds: 300));
    }
    final fallback =
        merged
            .where((url) {
              if (url.trim().isEmpty) return false;
              return mediaId.isEmpty || _xMediaIdentity(url) == mediaId;
            })
            .toSet()
            .toList()
          ..sort(
            (left, right) => _scoreXVideoCandidate(
              right,
            ).compareTo(_scoreXVideoCandidate(left)),
          );
    return fallback;
  }

  List<String> _recentActiveDashManifestCandidates({
    String? pageUrl,
    DateTime? notBefore,
    int limit = 4,
  }) {
    final now = DateTime.now();
    final requestedPage = Uri.tryParse((pageUrl ?? _currentUrl).trim());
    final activity = <String, ({int count, DateTime latest})>{};
    for (final resource in _capturedWebResources.values) {
      if (notBefore != null && resource.capturedAt.isBefore(notBefore))
        continue;
      if (now.difference(resource.capturedAt) > const Duration(minutes: 10) ||
          !_looksLikeMediaFragmentUrl(resource.url)) {
        continue;
      }
      final lowerUrl = resource.url.toLowerCase();
      if (lowerUrl.contains('dash-init') ||
          lowerUrl.contains('dash_init') ||
          lowerUrl.contains('/init.')) {
        // 下一条视频通常会预加载初始化分片，但这不代表用户正在观看它。
        continue;
      }
      final capturedPage = Uri.tryParse(resource.pageUrl);
      if (requestedPage != null &&
          capturedPage != null &&
          requestedPage.host.isNotEmpty &&
          capturedPage.host.isNotEmpty &&
          requestedPage.host != capturedPage.host) {
        continue;
      }
      final manifest = recoverWholeMediaUrlFromFragment(resource.url);
      if (manifest == null ||
          !(Uri.tryParse(manifest)?.path.toLowerCase().endsWith('.mpd') ??
              false)) {
        continue;
      }
      final previous = activity[manifest];
      activity[manifest] = (
        count: (previous?.count ?? 0) + 1,
        latest:
            previous == null || resource.capturedAt.isAfter(previous.latest)
                ? resource.capturedAt
                : previous.latest,
      );
    }
    final ranked =
        activity.entries.toList()..sort((a, b) {
          final timeOrder = b.value.latest.compareTo(a.value.latest);
          if (timeOrder != 0) return timeOrder;
          return b.value.count.compareTo(a.value.count);
        });
    return ranked.take(limit).map((entry) => entry.key).toList();
  }

  double? _extractDashManifestDurationSeconds(String xml) {
    String durationFromTag(String tag) {
      final match = RegExp(
        '<$tag\\b([^>]*)>',
        caseSensitive: false,
      ).firstMatch(xml);
      return _dashAttributes(match?.group(1) ?? '')['duration'] ?? '';
    }

    final mpd = RegExp(r'<MPD\b([^>]*)>', caseSensitive: false).firstMatch(xml);
    final mpdDuration = _parseDashDurationSeconds(
      _dashAttributes(mpd?.group(1) ?? '')['mediaPresentationDuration'] ?? '',
    );
    if (mpdDuration != null && mpdDuration > 0) return mpdDuration;
    final periodDuration = _parseDashDurationSeconds(durationFromTag('Period'));
    if (periodDuration != null && periodDuration > 0) return periodDuration;

    for (final template in RegExp(
      r'<SegmentTemplate\b([^>]*)>([\s\S]*?)</SegmentTemplate>',
      caseSensitive: false,
    ).allMatches(xml)) {
      final attrs = _dashAttributes(template.group(1) ?? '');
      final timescale = int.tryParse(attrs['timescale'] ?? '') ?? 1;
      if (timescale <= 0) continue;
      var timelineUnits = 0;
      for (final segment in RegExp(
        r'<S\b([^>]*)/?>',
        caseSensitive: false,
      ).allMatches(template.group(2) ?? '')) {
        final segmentAttrs = _dashAttributes(segment.group(1) ?? '');
        final duration = int.tryParse(segmentAttrs['d'] ?? '');
        final repeat = int.tryParse(segmentAttrs['r'] ?? '') ?? 0;
        if (duration == null || duration <= 0 || repeat < 0) continue;
        timelineUnits += duration * (repeat + 1);
      }
      if (timelineUnits > 0) return timelineUnits / timescale;
    }
    return null;
  }

  Future<String?> _selectDashManifestForLongPress(
    List<String> candidates, {
    required double targetDurationSeconds,
  }) async {
    if (candidates.isEmpty) return null;
    if (targetDurationSeconds <= 0) {
      return candidates.first;
    }
    final networkService = NetworkService();
    await networkService.initialize();
    final checks = candidates.take(4).map((candidate) async {
      try {
        final headers = await _browserLikeMediaHeaders(
          candidate,
          referer: _getMediaReferer(candidate),
          accept: 'application/dash+xml,application/xml,text/xml,*/*',
        );
        final response = await networkService.dio.get<String>(
          candidate,
          options: Options(
            responseType: ResponseType.plain,
            headers: headers,
            sendTimeout: const Duration(seconds: 3),
            receiveTimeout: const Duration(seconds: 3),
          ),
        );
        final duration = _extractDashManifestDurationSeconds(
          response.data ?? '',
        );
        return duration == null ? null : (url: candidate, duration: duration);
      } catch (_) {
        return null;
      }
    });
    final matches =
        (await Future.wait(
          checks,
        )).whereType<({String url, double duration})>();
    ({String url, double duration})? best;
    var bestDifference = double.infinity;
    for (final match in matches) {
      final difference = (match.duration - targetDurationSeconds).abs();
      if (difference < bestDifference) {
        best = match;
        bestDifference = difference;
      }
    }
    // 清单预检可能受临时鉴权限制；完全无法解析时保留上一版的活跃分片选择结果。
    if (best == null) return candidates.first;
    // Player duration and MPD duration may use different timelines or rounding.
    // Prefer the closest manifest, but do not turn an uncertain match into a
    // guaranteed download failure. The caller can retain the other manifests
    // as fallbacks when this candidate cannot be downloaded.
    return best.url;
  }

  bool _isCapturedVideoCandidate(String url) {
    final resource = _capturedWebResources[url];
    if (resource == null) return false;
    return DateTime.now().difference(resource.capturedAt) <=
            const Duration(minutes: 30) &&
        _capturedResourceMatchesType(resource, MediaType.video);
  }

  void _trustMediaCandidate(String url) {
    final absolute = _toAbsoluteUrl(url);
    final uri = Uri.tryParse(absolute);
    if (uri == null ||
        !(uri.scheme == 'http' || uri.scheme == 'https') ||
        _isLikelyAdUrl(absolute) ||
        _looksLikeMediaFragmentUrl(absolute)) {
      return;
    }
    _trustedMediaCandidateUrls.remove(absolute);
    _trustedMediaCandidateUrls[absolute] = DateTime.now();
    while (_trustedMediaCandidateUrls.length > 300) {
      _trustedMediaCandidateUrls.remove(_trustedMediaCandidateUrls.keys.first);
    }
  }

  bool _isTrustedMediaCandidate(String url) {
    final capturedAt = _trustedMediaCandidateUrls[_toAbsoluteUrl(url)];
    return capturedAt != null &&
        DateTime.now().difference(capturedAt) <= const Duration(minutes: 30);
  }

