    _mediaDownloadFailHintTimer = null;
  }

  /// 与网页端 [markMediaUrlProcessing] 配对：一次下载流程结束后允许同一 URL 再次长按保存。
  void _releaseJsProcessedUrl(String url) {
    final c = _controller;
    if (c == null || url.isEmpty) return;
    final encoded = jsonEncode(url);
    unawaited(
      c.evaluateJavascript(
        source:
            'try{window.__appReleaseProcessedMediaUrl&&window.__appReleaseProcessedMediaUrl($encoded);'
            'window.processedMediaUrls&&window.processedMediaUrls.delete($encoded);}catch(e){}',
      ),
    );
  }

  void _clearJsProcessedMediaUrls() {
    final c = _controller;
    if (c == null) return;
    unawaited(
      c.evaluateJavascript(
        source:
            'try{window.__appClearProcessedMediaUrls&&window.__appClearProcessedMediaUrls();'
            'window.processedMediaUrls&&window.processedMediaUrls.clear();}catch(e){}',
      ),
    );
  }

  /// 登记本次将要处理的 HTTP(S) 媒体 URL。若短期内重复则返回 false（需提示用户）；超时自动视为可重试。
  bool _tryRegisterMediaUrlForProcessing(String url) {
    final now = DateTime.now();
    final prev = _processedMediaUrlsSince[url];
    if (prev != null) {
      if (now.difference(prev) > _kMediaUrlInFlightTtl) {
        _processedMediaUrlsSince.remove(url);
      } else {
        return false;
      }
    }
    _processedMediaUrlsSince[url] = now;
    return true;
  }

  /// 常见「拉活 / 应用商店 / 站内 App」协议：拦截即可，不尝试唤起、也不弹「无法打开」。
  bool _isNoisyExternalAppScheme(String lowerUrl) {
    return lowerUrl.startsWith('baiduboxlite://') ||
        lowerUrl.startsWith('baiduboxapp://') ||
        lowerUrl.startsWith('baidu://') ||
        lowerUrl.startsWith('bdapp://') ||
        lowerUrl.startsWith('baiduhaokan://') ||
        lowerUrl.startsWith('tbopen://') ||
        lowerUrl.startsWith('snssdk://') ||
        lowerUrl.startsWith('sinaweibo://') ||
        lowerUrl.startsWith('weixin://') ||
        lowerUrl.startsWith('alipays://') ||
        lowerUrl.startsWith('intent://') ||
        lowerUrl.startsWith('samsungapps://') ||
        lowerUrl.startsWith('market://') ||
        lowerUrl.startsWith('hap://');
  }

  /// 从 App 深链（如 baiduboxlite://…?url=）或 intent:// 提取可在 WebView 打开的 http(s) URL。
  String? _extractHttpUrlFromAppDeepLink(String rawUrl) {
    final trimmed = rawUrl.trim();
    if (trimmed.isEmpty) return null;
    final lower = trimmed.toLowerCase();

    String? asHttp(String? value) {
      if (value == null || value.isEmpty) return null;
      var candidate = value.trim();
      try {
        candidate = Uri.decodeFull(candidate);
      } catch (_) {}
      if (candidate.startsWith('http://') || candidate.startsWith('https://')) {
        return candidate;
      }
      try {
        final again = Uri.decodeFull(candidate);
        if (again.startsWith('http://') || again.startsWith('https://')) {
          return again;
        }
      } catch (_) {}
      return null;
    }

    if (lower.startsWith('intent://')) {
      final fallback = RegExp(
        r'S\.browser_fallback_url=([^;]+)',
        caseSensitive: false,
      ).firstMatch(trimmed);
      final fromFallback = asHttp(fallback?.group(1));
      if (fromFallback != null) return fromFallback;

      final schemeMatch = RegExp(
        r';scheme=([a-zA-Z][a-zA-Z0-9+.-]*)',
      ).firstMatch(trimmed);
      final scheme = (schemeMatch?.group(1) ?? '').toLowerCase();
      if (scheme == 'http' || scheme == 'https') {
        final pathPart = trimmed.substring('intent://'.length).split('#').first;
        if (pathPart.isNotEmpty) return '$scheme://$pathPart';
      }
      return null;
    }

    final uri = Uri.tryParse(trimmed);
    if (uri == null) return null;
    for (final key in const ['url', 'target', 'link', 'u', 'weburl', 'src']) {
      final hit = asHttp(uri.queryParameters[key]);
      if (hit != null) return hit;
    }
    return null;
  }

  /// 非 http(s) 导航：优先解开深链到网页；否则静默取消（避免「无法打开」页）。
  Future<NavigationActionPolicy> _handleNonHttpNavigation(
    InAppWebViewController ctrl,
    String url,
  ) async {
    if (url.startsWith('data:') || url.startsWith('blob:')) {
      return NavigationActionPolicy.ALLOW;
    }
    final extracted = _extractHttpUrlFromAppDeepLink(url);
    if (extracted != null) {
      debugPrint('深链转 WebView 打开: $extracted <- $url');
      await ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(extracted)));
      return NavigationActionPolicy.CANCEL;
    }
    final lower = url.toLowerCase();
    if (_isNoisyExternalAppScheme(lower)) {
      debugPrint('已拦截 App 协议导航: $url');
      return NavigationActionPolicy.CANCEL;
    }
    debugPrint('检测到自定义URL协议: $url');
    _launchExternalApp(url);
    return NavigationActionPolicy.CANCEL;
  }

  Future<void> _launchExternalApp(String url) async {
    debugPrint('尝试启动外部应用: $url');
    try {
      final Uri? uri = Uri.tryParse(url);
      if (uri != null && await canLaunchUrl(uri)) {
        await launchUrl(uri, mode: LaunchMode.externalApplication);
        debugPrint('成功启动外部应用');
      } else {
        debugPrint('无法启动外部应用: $url');
        final lower = url.toLowerCase();
        final isAppScheme = _isNoisyExternalAppScheme(lower);
        if (!isAppScheme && mounted) {
          ScaffoldMessenger.of(
            context,
          ).showSnackBar(SnackBar(content: Text('无法打开: $url')));
        }
      }
    } catch (e) {
      debugPrint('启动外部应用时出错: $e');
      final lower = url.toLowerCase();
      final isAppScheme = _isNoisyExternalAppScheme(lower);
      if (!isAppScheme && mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('打开链接时出错: $e')));
      }
    }
  }

