  void _openFavoriteInBrowser(Map<String, dynamic> item) {
    final pageUrl = (item['pageUrl'] ?? '').toString().trim();
    final videoUrl = (item['videoUrl'] ?? '').toString().trim();
    final target =
        pageUrl.isNotEmpty ? pageUrl : (videoUrl.isNotEmpty ? videoUrl : '');
    if (target.isEmpty) return;
    _loadUrl(target);
  }

  Future<void> _openDownloadedFavorite(
    Map<String, dynamic> item, {
    required bool locate,
  }) async {
    final existing = await _findExistingMediaForItem(item);
    if (!mounted) return;
    if (existing == null) {
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('未在媒体库中找到该视频，可尝试重新下载')));
      return;
    }
    if (locate) {
      await _openMediaLibraryAt(existing);
      return;
    }
    final mediaItem = MediaItem.fromMap(Map<String, dynamic>.from(existing));
    await Navigator.of(context).push(
      MaterialPageRoute(
        builder:
            (_) => MediaPreviewPage(mediaItems: [mediaItem], initialIndex: 0),
      ),
    );
  }

  Future<bool> _redownloadFavorite(Map<String, dynamic> item) async {
    final retryItem = Map<String, dynamic>.from(item)
      ..['allowSourceUrlReuse'] = true;
    return _downloadOneFavorite(item: retryItem, showResultHint: true);
  }

  bool _isLikelyDirectMediaUrl(String url) {
    final u = url.trim().toLowerCase();
    if (u.isEmpty) return false;
    if (!(u.startsWith('http://') || u.startsWith('https://'))) return false;
    if (u.startsWith('blob:') || u.startsWith('data:')) return false;
    if (_isFacebookCdnUrl(url) &&
        (u.contains('.mp4') ||
            u.contains('.m3u8') ||
            u.contains('.mpd') ||
            u.contains('video.') ||
            u.contains('/v/'))) {
      return !isMediaFragmentUrl(url);
    }
    return u.contains('.m3u8') ||
        u.contains('.mpd') ||
        u.contains('.mp4') ||
        u.contains('.webm') ||
        u.contains('.mov') ||
        u.contains('/hls/') ||
        u.contains('/manifest') ||
        u.contains('/stream');
  }

  Future<String?> _resolveFavoriteDownloadUrl({
    required String pageUrl,
    required String videoUrl,
  }) async {
    if (_isLikelyDirectMediaUrl(videoUrl) ||
        _isTrustedMediaCandidate(videoUrl)) {
      return videoUrl;
    }
    if (_isLikelyDirectMediaUrl(pageUrl) || _isTrustedMediaCandidate(pageUrl)) {
      return pageUrl;
    }
    if (pageUrl.isEmpty ||
        !(pageUrl.startsWith('http://') || pageUrl.startsWith('https://'))) {
      return null;
    }
    try {
      final networkService = NetworkService();
      await networkService.initialize();
      final pageHeaders = await _browserLikeMediaHeaders(
        pageUrl,
        referer: pageUrl,
        accept:
            'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      );
      final resp = await networkService.dio.get<String>(
        pageUrl,
        options: Options(
          responseType: ResponseType.plain,
          headers: pageHeaders,
          sendTimeout: const Duration(seconds: 8),
          receiveTimeout: const Duration(seconds: 8),
        ),
      );
      final html = (resp.data ?? '')
          .replaceAll(r'\/', '/')
          .replaceAll(r'\u002F', '/')
          .replaceAll(r'\u002f', '/')
          .replaceAll('&amp;', '&');
      if (html.isEmpty) return null;
      final baseUri = Uri.tryParse(pageUrl);
      if (baseUri == null) return null;
      final candidates = <String>{};
      final re = RegExp(
        r"""https?:\/\/[^"'\s<>]+?(?:\.m3u8|\.mp4|\.webm|\.mov)(?:\?[^"'\s<>]*)?""",
        caseSensitive: false,
      );
      for (final m in re.allMatches(html)) {
        final v = m.group(0)?.trim();
        if (v != null && v.isNotEmpty && _isLikelyDirectMediaUrl(v)) {
          candidates.add(v);
        }
      }
      final relRe = RegExp(
        r"""["']([^"']+?(?:\.m3u8|\.mp4|\.webm|\.mov)(?:\?[^"']*)?)["']""",
        caseSensitive: false,
      );
      for (final m in relRe.allMatches(html)) {
        final rel = m.group(1)?.trim();
        if (rel == null || rel.isEmpty) continue;
        final abs = baseUri.resolve(rel).toString();
        if (_isLikelyDirectMediaUrl(abs)) {
          candidates.add(abs);
        }
      }
      final scriptRe = RegExp(
        r"""setVideoUrl(?:High|Low|HLS)\(['"]([^'"]+)['"]\)""",
        caseSensitive: false,
      );
      for (final m in scriptRe.allMatches(html)) {
        final v = m.group(1)?.trim();
        if (v != null && v.isNotEmpty) {
          final abs = baseUri.resolve(v).toString();
          if (_isLikelyDirectMediaUrl(abs)) {
            candidates.add(abs);
          }
        }
      }
      if (candidates.isEmpty) return null;
      final primary = videoUrl.isNotEmpty ? videoUrl : pageUrl;
      return _chooseBestFavoriteVideoUrl(primary, candidates.toList());
    } catch (_) {
      return null;
    }
  }

  bool _isXVideoLikeHost(String url) {
    final s = url.toLowerCase();
    return s.contains('xvideos.') ||
        s.contains('xvideos-cdn') ||
        s.contains('xv-vod') ||
        s.contains('xhcdn');
  }

  bool _isTikPornPage(String? url) {
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    return host == 'tik.porn' || host.endsWith('.tik.porn');
  }

  /// 91 风格详情页路径：`/archives/{数字}/`（不绑定域名，供跨站沿用 91 套路）。
  bool _is91StyleArchivePage(String? url) {
    final uri = Uri.tryParse((url ?? '').trim());
    if (uri == null) return false;
    final segments = uri.pathSegments.where((e) => e.isNotEmpty).toList();
    return segments.length >= 2 &&
        segments.first.toLowerCase() == 'archives' &&
        RegExp(r'^\d+$').hasMatch(segments[1]);
  }

  /// 原生 91 站详情页（域名 + archives 路径）。跨站借用请用 [_is91StyleArchivePage]。
  bool _is91ContentPage(String? url) {
    final uri = Uri.tryParse((url ?? '').trim());
    if (uri == null) return false;
    final host = uri.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    if (host != '91cg1.com' && !host.endsWith('.91cg1.com')) return false;
    return _is91StyleArchivePage(url);
  }

  String _smartStablePageKey(String pageUrl) {
    if (!_is91ContentPage(pageUrl)) return '';
    final uri = Uri.tryParse(pageUrl.trim());
    if (uri == null) return '';
    final host = uri.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    final segments = uri.pathSegments.where((e) => e.isNotEmpty).toList();
    return '$host/archives/${segments[1]}';
  }

  bool _isSame91TaskPage(String left, String right) {
    final leftKey = _smartStablePageKey(left);
    final rightKey = _smartStablePageKey(right);
    if (leftKey.isNotEmpty || rightKey.isNotEmpty) {
      return leftKey.isNotEmpty && leftKey == rightKey;
    }
    // 搜索列表页：www / 尾斜杠差异不能判成不同页，否则 91 点卡片深挖整段被跳过。
    final leftUri = Uri.tryParse(left.trim());
    final rightUri = Uri.tryParse(right.trim());
    if (leftUri == null || rightUri == null) {
      return _isSameLoadedDocument(left, right);
    }
    String normHost(Uri uri) =>
        uri.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    String normPath(Uri uri) {
      var path = uri.path;
      if (path.length > 1 && path.endsWith('/')) {
        path = path.substring(0, path.length - 1);
      }
      return path;
    }

    if (normHost(leftUri) != normHost(rightUri)) return false;
    if (normPath(leftUri) != normPath(rightUri)) return false;
    final isSearch =
        leftUri.pathSegments.any((s) => s.toLowerCase() == 'search') ||
        rightUri.pathSegments.any((s) => s.toLowerCase() == 'search');
    if (isSearch) return true;
    return leftUri.query == rightUri.query;
  }

  bool _isElementBoundFeedPage(String? url) {
    final host = Uri.tryParse((url ?? '').trim())?.host.toLowerCase() ?? '';
    return host == 'tik.porn' ||
        host.endsWith('.tik.porn') ||
        host == 'pin.porn' ||
        host.endsWith('.pin.porn') ||
        host == 'x.com' ||
        host.endsWith('.x.com') ||
        host == 'twitter.com' ||
        host.endsWith('.twitter.com') ||
        host == 'facebook.com' ||
        host.endsWith('.facebook.com') ||
        host == 'fb.com' ||
        host.endsWith('.fb.com') ||
        host == 'fb.watch' ||
        host.endsWith('.fb.watch') ||
        host == 'instagram.com' ||
        host.endsWith('.instagram.com');
  }

  bool _looksLikePreviewClipUrl(String u) {
    final s = u.toLowerCase();
    const hints = [
      'preview',
      'sample',
      'trailer',
      'teaser',
      'thumb',
      'poster',
      'storyboard',
      'sprite',
      'clip',
      'snippet',
      'init.',
      '/init',
      '.m4s',
      '/seg',
      '/chunk',
      '/fragment',
    ];
    return hints.any(s.contains);
  }

  bool _looksLikeMediaFragmentUrl(String url) {
    return isMediaFragmentUrl(url);
  }

  int _scoreFavoriteVideoUrl(String url) {
    final s = url.toLowerCase();
    var score = 0;
    if (_isLikelyAdUrl(s)) score -= 5000;
    if (s.contains('.m3u8') || s.contains('.m3u')) score += 1800;
    if (s.contains('.mpd')) score += 1700;
    if (s.contains('mpegurl') ||
        s.contains('/hls/') ||
        s.contains('/playlist')) {
      score += 1200;
    }
    if (s.contains('.mp4')) score += 900;
    if (s.contains('.webm')) score += 450;
    if (_isXVideoLikeHost(s)) score += 500;
    if (_isFacebookCdnUrl(s)) score += 600;
    if (_isInstagramCdnUrl(s)) {
      final metadata = facebookMediaMetadata(url);
      if (metadata?.isAudioOnly == true) return -100000;
      score += metadata?.isVideoTrack == true ? 2400 : 500;
      score += ((metadata?.bitrate ?? 0) ~/ 1000).clamp(0, 5000);
    }
    if (s.contains('setvideourlhigh') || s.contains('high')) score += 220;
    if (_looksLikePreviewClipUrl(s)) score -= 1200;
    return score;
  }

  List<String> _buildFavoriteAttempts(
    String primary,
    List<String> candidates, {
    bool preservePrimary = false,
  }) {
    final merged = <String>[];
    final seen = <String>{};
    void push(String? u) {
      if (u == null) return;
      final s = u.trim();
      if (s.isEmpty) return;
      final abs = _toAbsoluteUrl(s);
      if (abs.isEmpty ||
          seen.contains(abs) ||
          _isLikelyAdUrl(abs) ||
          _looksLikeMediaFragmentUrl(abs)) {
        return;
      }
      seen.add(abs);
      merged.add(abs);
    }

    push(primary);
    for (final c in candidates) {
      push(c);
    }
    final insertionOrder = <String, int>{
      for (var i = 0; i < merged.length; i++) merged[i]: i,
    };
    int compareCandidates(String a, String b) {
      final aScore =
          _xMediaIdentity(a).isNotEmpty
              ? _scoreXVideoCandidate(a)
              : (_isFacebookCdnUrl(a)
                  ? _scoreFacebookVideoCandidate(a)
                  : (_isInstagramCdnUrl(a)
                      ? _scoreInstagramVideoCandidate(a)
                      : _scoreFavoriteVideoUrl(a)));
      final bScore =
          _xMediaIdentity(b).isNotEmpty
              ? _scoreXVideoCandidate(b)
              : (_isFacebookCdnUrl(b)
                  ? _scoreFacebookVideoCandidate(b)
                  : (_isInstagramCdnUrl(b)
                      ? _scoreInstagramVideoCandidate(b)
                      : _scoreFavoriteVideoUrl(b)));
      final scoreOrder = bScore.compareTo(aScore);
      if (scoreOrder != 0) return scoreOrder;
      return insertionOrder[a]!.compareTo(insertionOrder[b]!);
    }

    if (preservePrimary && merged.length > 1) {
      final primaryUrl = merged.first;
      final fallbacks = merged.sublist(1)..sort(compareCandidates);
      return <String>[primaryUrl, ...fallbacks];
    }
    merged.sort(compareCandidates);
    return merged;
  }

  String _chooseBestFavoriteVideoUrl(String primary, List<String> candidates) {
    final attempts = _buildFavoriteAttempts(primary, candidates);
    return attempts.isEmpty ? primary : attempts.first;
  }

  Future<List<String>> _resniffFavoriteCandidatesFromSourcePage(
    String pageUrl,
  ) async {
    if (pageUrl.isEmpty ||
        !(pageUrl.startsWith('http://') || pageUrl.startsWith('https://'))) {
      return const <String>[];
    }
    try {
      final networkService = NetworkService();
      await networkService.initialize();
      final pageHeaders = await _browserLikeMediaHeaders(
        pageUrl,
        referer: pageUrl,
        accept:
            'text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8',
      );
      final resp = await networkService.dio.get<String>(
        pageUrl,
        options: Options(
          responseType: ResponseType.plain,
          headers: pageHeaders,
        ),
      );
      final html = (resp.data ?? '')
          .replaceAll(r'\/', '/')
          .replaceAll(r'\u002F', '/')
          .replaceAll(r'\u002f', '/')
          .replaceAll('&amp;', '&');
      if (html.isEmpty) return const <String>[];
      final baseUri = Uri.tryParse(pageUrl);
      if (baseUri == null) return const <String>[];
      final out = <String>{};
      void addCandidate(String? raw) {
        if (raw == null) return;
        final s = raw.trim();
        if (s.isEmpty) return;
        final abs = baseUri.resolve(s).toString();
        if (_isLikelyDirectMediaUrl(abs)) out.add(abs);
      }

      final genericDirect = RegExp(
        r"""https?:\/\/[^"'\s<>]+?(?:\.m3u8|\.mp4|\.webm|\.mov)(?:\?[^"'\s<>]*)?""",
        caseSensitive: false,
      );
      for (final m in genericDirect.allMatches(html)) {
        addCandidate(m.group(0));
      }

      final xvideoJs = RegExp(
        r"""setVideoUrl(?:High|Low|HLS)\(['"]([^'"]+)['"]\)""",
        caseSensitive: false,
      );
      for (final m in xvideoJs.allMatches(html)) {
        addCandidate(m.group(1));
      }

      final schemaVideo = RegExp(
        r'''"contentUrl"\s*:\s*"([^"]+)"''',
        caseSensitive: false,
      );
      for (final m in schemaVideo.allMatches(html)) {
        addCandidate(m.group(1));
      }

      final playerConfigUrl = RegExp(
        r'''["'](?:url|file|src|source|videoUrl|playUrl|hls|manifest)["']\s*:\s*["']([^"']+)["']''',
        caseSensitive: false,
      );
      for (final m in playerConfigUrl.allMatches(html)) {
        addCandidate(m.group(1));
      }

      final dataSrc = RegExp(
        r'''(?:data-src|src)\s*=\s*["']([^"']+\.(?:m3u8|mp4|webm|mov)(?:\?[^"']*)?)["']''',
        caseSensitive: false,
      );
      for (final m in dataSrc.allMatches(html)) {
        addCandidate(m.group(1));
      }
      return out.toList();
    } catch (_) {
      return const <String>[];
    }
  }

  Future<bool> _downloadOneFavorite({
    required Map<String, dynamic> item,
    bool showResultHint = false,
    bool showModalDialog = false,
    void Function(String failureType)? onFailureType,
  }) async {
    return _downloadMediaRobustly(
      item: item,
      showResultHint: showResultHint,
      showModalDialog: showModalDialog, // 允许外部控制是否显示弹窗
      onFailureType: onFailureType,
    );
  }

  /// 稳健下载媒体：具备多候选重试、自动嗅探补偿和全局进度对话框。
  /// 用于收藏栏下载和网页长按下载，解决 XVideo 等站点直接下载 Blob 导致的断流或文件残缺问题。
  Future<bool> _downloadMediaRobustly({
    required Map<String, dynamic> item,
    bool showResultHint = false,
    bool showModalDialog = false, // 是否显示全局阻塞式进度弹窗
    void Function(String failureType)? onFailureType,
    int? minFileBytes,
    int? maxFileBytes,
  }) async {
    final isLongPress = item['downloadOrigin'] == 'long_press';
    final isSmartBatch = item['downloadOrigin'] == 'smart_batch';
    final isSmartGesture = item['isSmartGesture'] == true;
    final isSmartDownload = isSmartBatch || isSmartGesture;
    final smartTask =
        item['smartTask'] is Map<String, dynamic>
            ? item['smartTask'] as Map<String, dynamic>
            : null;
    if (isSmartGesture) smartTask?.remove('lastGestureFailureType');
    final forceNoPreSkip = _smartForceDownloadNoPreSkip(smartTask);
    final pageUrlEarly = (item['pageUrl'] ?? '').toString().trim();
    final videoUrlEarly = (item['videoUrl'] ?? '').toString().trim();
    final looksFacebookEarly =
        item['facebookPipeline'] == true ||
        smartTask?['facebookPipeline'] == true ||
        _smartUsesFacebookPipeline(
          (smartTask?['siteProfile'] ?? '').toString(),
        ) ||
        _isFacebookPlatformPage(pageUrlEarly) ||
        _isFacebookPlatformPage(_currentUrl) ||
        _isFacebookCdnUrl(videoUrlEarly);
    // 智能/动作编排：下载前禁止按 URL/src/磁盘路径宣称「库内已有」。
    // Facebook 手动长按同样禁止：邻条 CDN 误绑后会弹「疑似重复」，但当前条未入库。
    // 仅入库后内容哈希匹配（或 24h 备案带 fileHash 且库内哈希仍在）才可跳过。
    final existingMedia = await _findExistingMediaForItem(item);
    if (existingMedia != null && item['allowSourceUrlReuse'] != true) {
      if (isSmartDownload || looksFacebookEarly) {
        debugPrint(
          'FB_DL ignore robust URL pre-skip '
          'smart=$isSmartDownload fb=$looksFacebookEarly '
          'row=${existingMedia['id']}',
        );
      } else {
        final downloadAnyway = await _confirmSourceUrlDuplicateBeforeDownload(
          existingMedia,
        );
        if (!downloadAnyway) {
          await _markFavoriteDownloaded(item, downloaded: true);
          onFailureType?.call('already_in_library');
          return true;
        }
      }
      // URL matches are only hints. The downloaded content hash remains the
      // authoritative duplicate check for dynamic and signed media URLs.
    }
    if (forceNoPreSkip) {
      debugPrint(
        'Smart download: forceNoPreSkip on '
        '(URL/disk pre-skip disabled; hash-only duplicate gate)',
      );
    }
    final pageUrl = (item['pageUrl'] ?? '').toString().trim();
    final videoUrl = (item['videoUrl'] ?? '').toString().trim();
    final candidateRaw = item['candidateUrls'];
    final candidateUrls = <String>[];
    if (candidateRaw is List) {
      for (final e in candidateRaw) {
        if (e is String && e.trim().isNotEmpty) {
          candidateUrls.add(e.trim());
        }
      }
    }
    final looksFacebookItem =
        item['facebookPipeline'] == true ||
        smartTask?['facebookPipeline'] == true ||
        _smartUsesFacebookPipeline(
          (smartTask?['siteProfile'] ?? '').toString(),
        ) ||
        _isFacebookPlatformPage(pageUrl) ||
        _isFacebookPlatformPage(_currentUrl) ||
        _isFacebookCdnUrl(videoUrl) ||
        candidateUrls.any(_isFacebookCdnUrl);
    final looksInstagramItem =
        _isInstagramPlatformPage(pageUrl) ||
        _isInstagramPlatformPage(_currentUrl) ||
        _isInstagramCdnUrl(videoUrl) ||
        candidateUrls.any(_isInstagramCdnUrl);
    // Facebook / Reels: never re-inject page-wide capture history here —
    // that drains previously browsed progressives before the bound current.
    if (!isLongPress && !looksFacebookItem && !looksInstagramItem) {
      candidateUrls.addAll(
        _recentCapturedMediaCandidates(MediaType.video, pageUrl: pageUrl),
      );
    }
    var downloadUrl =
        isLongPress
            ? videoUrl
            : await _resolveFavoriteDownloadUrl(
              pageUrl: pageUrl,
              videoUrl: videoUrl,
            );
    if ((downloadUrl == null || downloadUrl.isEmpty) &&
        candidateUrls.isNotEmpty) {
      final directCandidates =
          candidateUrls
              .where(
                (url) =>
                    _isLikelyDirectMediaUrl(url) ||
                    _isCapturedVideoCandidate(url) ||
                    _isTrustedMediaCandidate(url),
              )
              .toList();
      if (directCandidates.isNotEmpty) {
        downloadUrl = _chooseBestFavoriteVideoUrl(
          videoUrl.isNotEmpty ? videoUrl : directCandidates.first,
          directCandidates,
        );
      }
    }
    if (downloadUrl == null || downloadUrl.isEmpty) {
      if (isSmartGesture) {
        smartTask?['lastGestureFailureType'] = 'no_direct_url';
      }
      onFailureType?.call('no_direct_url');
      if (showResultHint && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('该媒体缺少可下载的直链，请先在网页播放后再尝试'),
            duration: Duration(milliseconds: 1500),
          ),
        );
      }
      return false;
    }
    final isFacebookPipeline =
        looksFacebookItem ||
        _isFacebookCdnUrl(downloadUrl) ||
        candidateUrls.any(_isFacebookCdnUrl);
    final isInstagramPipeline =
        looksInstagramItem ||
        _isInstagramCdnUrl(downloadUrl) ||
        candidateUrls.any(_isInstagramCdnUrl);
    // Facebook 视频必须保留最小体积闸门，避免把 init/stub 黑色视频占位保存入库。
    final effectiveMinFileBytes =
        isFacebookPipeline
            ? max(minFileBytes ?? 0, _kMinFacebookSavedVideoBytes)
            : minFileBytes;
    final effectiveMaxFileBytes = maxFileBytes;
    final progress = ValueNotifier<double?>(null);
    final detailNotifier = ValueNotifier<String>('准备下载...');
    var shownDialog = false;
    if (showModalDialog && mounted) {
      shownDialog = true;
      final mediaName = item['title'] ?? item['name'] ?? '未知媒体';
      showGeneralDialog<void>(
        context: context,
        barrierDismissible: false,
        barrierLabel: 'robust_media_download',
        barrierColor: Colors.black.withValues(alpha: 0.15),
        transitionDuration: const Duration(milliseconds: 120),
        pageBuilder:
            (_, __, ___) => Center(
              child: Container(
                width: 240,
                padding: const EdgeInsets.symmetric(
                  horizontal: 14,
                  vertical: 14,
                ),
                decoration: BoxDecoration(
                  color: Colors.black.withValues(alpha: 0.72),
                  borderRadius: BorderRadius.circular(14),
                ),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    ValueListenableBuilder<double?>(
                      valueListenable: progress,
                      builder: (_, p, __) {
                        if (p == null) {
                          return const SizedBox(
                            width: 28,
                            height: 28,
                            child: CircularProgressIndicator(
                              strokeWidth: 3,
                              valueColor: AlwaysStoppedAnimation<Color>(
                                Colors.greenAccent,
                              ),
                              backgroundColor: Colors.white24,
                            ),
                          );
                        }
                        return SizedBox(
                          width: 30,
                          height: 30,
                          child: CircularProgressIndicator(
                            value: p.clamp(0.0, 1.0),
                            strokeWidth: 3,
                            valueColor: const AlwaysStoppedAnimation<Color>(
                              Colors.greenAccent,
                            ),
                            backgroundColor: Colors.white24,
                          ),
                        );
                      },
                    ),
                    const SizedBox(height: 10),
                    Text(
                      '正在下载：$mediaName',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                        color: Colors.white,
                        fontSize: 13,
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                    const SizedBox(height: 6),
                    ValueListenableBuilder<String>(
                      valueListenable: detailNotifier,
                      builder:
                          (_, t, __) => Text(
                            t,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: Colors.white70,
                              fontSize: 11,
                            ),
                          ),
                    ),
                  ],
                ),
              ),
            ),
      );
    }
    final taskLenBefore = _downloadTasks.length;
    final attempts = _buildFavoriteAttempts(
      downloadUrl,
      candidateUrls
          .where(
            (url) =>
                _isLikelyDirectMediaUrl(url) ||
                _isCapturedVideoCandidate(url) ||
                _isTrustedMediaCandidate(url),
          )
          .toList(),
      // Once smart selection has bound a concrete media URL, keep it first
      // just like a long press. Fallback candidates are tried only on failure.
      preservePrimary:
          (isLongPress && !isInstagramPipeline) ||
          isFacebookPipeline ||
          (isSmartBatch &&
              (downloadUrl.startsWith('http://') ||
                  downloadUrl.startsWith('https://'))),
    );
    String? pairedDashAudioUrl;
    var requireFacebookAudioMux = false;
    var missingFacebookAudioTrack = false;
    var facebookDashVideoId = '';
    if (isInstagramPipeline) {
      final targetDurationSeconds =
          (item['durationSec'] as num?)?.toDouble() ?? 0.0;
      FacebookMediaMetadata? selectedVideoMetadata;
      final instagramVideoMetadata =
          attempts
              .map(facebookMediaMetadata)
              .whereType<FacebookMediaMetadata>()
              .where(
                (metadata) =>
                    metadata.isVideoTrack && metadata.videoId.isNotEmpty,
              )
              .toList()
            ..sort((left, right) {
              if (targetDurationSeconds > 0) {
                final leftDelta =
                    ((left.durationSeconds ?? 0) - targetDurationSeconds).abs();
                final rightDelta =
                    ((right.durationSeconds ?? 0) - targetDurationSeconds)
                        .abs();
                final durationOrder = leftDelta.compareTo(rightDelta);
                if (durationOrder != 0) return durationOrder;
              }
              return right.qualityScore.compareTo(left.qualityScore);
            });
      if (instagramVideoMetadata.isNotEmpty) {
        selectedVideoMetadata = instagramVideoMetadata.first;
        final selectedAssetId = selectedVideoMetadata.videoId;
        attempts.removeWhere((candidate) {
          final metadata = facebookMediaMetadata(candidate);
          return metadata != null &&
              metadata.videoId.isNotEmpty &&
              metadata.videoId != selectedAssetId;
        });
      }
      if (selectedVideoMetadata != null) {
        for (final candidate in <String>[
          videoUrl,
          downloadUrl,
          ...candidateUrls,
          ...attempts,
        ]) {
          final metadata = facebookMediaMetadata(candidate);
          if (metadata?.isAudioOnly == true &&
              metadata!.videoId == selectedVideoMetadata.videoId) {
            pairedDashAudioUrl =
                recoverWholeMediaUrlFromFragment(candidate) ?? candidate;
            break;
          }
        }
      }
      final beforeAudioFilter = attempts.length;
      attempts.removeWhere(
        (url) => facebookMediaMetadata(url)?.isAudioOnly == true,
      );
      attempts.sort(
        (left, right) => _scoreInstagramVideoCandidate(
          right,
        ).compareTo(_scoreInstagramVideoCandidate(left)),
      );
      debugPrint(
        'Instagram pipeline: video candidates=${attempts.length}, '
        'removedAudio=${beforeAudioFilter - attempts.length}, '
        'pairedAudio=${pairedDashAudioUrl != null}',
      );
      if (attempts.isEmpty) {
        onFailureType?.call('instagram_video_track_not_captured');
        if (isSmartGesture) {
          smartTask?['lastGestureFailureType'] =
              'instagram_video_track_not_captured';
        }
        if (shownDialog && mounted) {
          final nav = Navigator.of(context, rootNavigator: true);
          if (nav.canPop()) nav.pop();
        }
        progress.dispose();
        detailNotifier.dispose();
        return false;
      }
    }
    // X exposes a master playlist together with separate audio/video streams.
    // Keep one media ID per smart-download step and prefer the complete master.
    final smartXMediaId =
        isSmartBatch
            ? <String>[downloadUrl, videoUrl, ...attempts]
                .map(_xMediaIdentity)
                .firstWhere((id) => id.isNotEmpty, orElse: () => '')
            : '';
    Map<String, String>? smartVideoStates;
    if (smartTask != null && smartXMediaId.isNotEmpty) {
      final existingStates = smartTask['videoMediaStates'];
      smartVideoStates =
          existingStates is Map<String, String>
              ? existingStates
              : <String, String>{};
      smartTask['videoMediaStates'] = smartVideoStates;
      if (smartVideoStates.containsKey(smartXMediaId)) {
        final prev = (smartVideoStates[smartXMediaId] ?? '').toString();
        final activelyDownloading =
            prev == 'downloading' && _hasActiveSmartBatchDownload();
        if (activelyDownloading) {
          if (isSmartGesture) {
            smartTask?['lastGestureFailureType'] = 'already_in_smart_task';
          }
          onFailureType?.call('already_in_smart_task');
          return false;
        }
        // 动作编排：忽略 completed/会话态预跳过，清掉软状态后强制再下
        if (forceNoPreSkip) {
          smartVideoStates.remove(smartXMediaId);
          debugPrint(
            'Smart download: action_recipe ignore videoMediaState '
            'id=$smartXMediaId prev=$prev (force download)',
          );
        } else {
          // completed/failed/stale：会话态 / URL 映射绝不能当「库内已有」；
          // 清掉后强制再下，由入库内容哈希判定真实重复。
          smartVideoStates.remove(smartXMediaId);
          debugPrint(
            'Smart download: cleared videoMediaState '
            'id=$smartXMediaId prev=$prev (hash-only duplicate gate)',
          );
        }
      }
      attempts.removeWhere((url) {
        final id = _xMediaIdentity(url);
        return id.isNotEmpty && id != smartXMediaId;
      });
      attempts.sort(
        (left, right) =>
            _scoreXVideoCandidate(right).compareTo(_scoreXVideoCandidate(left)),
      );
      smartVideoStates[smartXMediaId] = 'downloading';
    }
    // Facebook: bind-only-current — quality/stub fallbacks must share the same
    // CDN identity as the primary. Never drain previously browsed reels.
    if (isFacebookPipeline) {
      final expectedFbKey =
          (item['expectedFbVideoKey'] ?? smartTask?['expectedFbVideoKey'] ?? '')
              .toString()
              .trim();
      var boundFbKey =
          expectedFbKey.isNotEmpty && !expectedFbKey.startsWith('reel:')
              ? expectedFbKey
              : facebookMediaIdentity(downloadUrl);
      if (boundFbKey.startsWith('reel:') || boundFbKey.isEmpty) {
        boundFbKey = facebookMediaIdentity(downloadUrl);
      }
      // Identity-based anti-duplicate (session + library). Hash-only cannot
      // catch the same reel across re-signed / multi-quality CDN URLs.
      final identityForSkip =
          _isFacebookCdnIdentity(boundFbKey)
              ? boundFbKey
              : (expectedFbKey.isNotEmpty
                  ? expectedFbKey
                  : facebookMediaIdentity(downloadUrl));
      if (identityForSkip.isNotEmpty && isSmartDownload) {
        if (_sessionHasHandledFacebookIdentity(smartTask, identityForSkip)) {
          debugPrint(
            'FB_DL session identity skip $identityForSkip '
            'url=${downloadUrl.length > 100 ? downloadUrl.substring(0, 100) : downloadUrl}',
          );
          if (smartTask != null) {
            smartTask['expectedFbVideoKey'] = identityForSkip;
          }
          if (isSmartGesture) {
            smartTask?['lastGestureFailureType'] = 'already_in_library';
          }
          onFailureType?.call('already_in_library');
          if (shownDialog && mounted) {
            final nav = Navigator.of(context, rootNavigator: true);
            if (nav.canPop()) nav.pop();
          }
          progress.dispose();
          detailNotifier.dispose();
          return false;
        }
        if (await _libraryConfirmsFacebookIdentity(identityForSkip)) {
          debugPrint(
            'FB_DL library identity skip $identityForSkip '
            'url=${downloadUrl.length > 100 ? downloadUrl.substring(0, 100) : downloadUrl}',
          );
          _rememberHandledFacebookIdentity(
            smartTask,
            identityForSkip,
            softReelKey:
                expectedFbKey.startsWith('reel:') ? expectedFbKey : null,
          );
          if (smartTask != null) {
            smartTask['expectedFbVideoKey'] = identityForSkip;
          }
          if (isSmartGesture) {
            smartTask?['lastGestureFailureType'] = 'already_in_library';
          }
          onFailureType?.call('already_in_library');
          if (shownDialog && mounted) {
            final nav = Navigator.of(context, rootNavigator: true);
            if (nav.canPop()) nav.pop();
          }
          progress.dispose();
          detailNotifier.dispose();
          return false;
        }
      }
      if (boundFbKey.isNotEmpty && !boundFbKey.startsWith('reel:')) {
        final before = attempts.length;
        attempts.removeWhere((url) {
          final id = facebookMediaIdentity(url);
          return id.isNotEmpty && !facebookIdentitiesMatch(id, boundFbKey);
        });
        if (before != attempts.length) {
          debugPrint(
            'FB pipeline: filtered attempts $before→${attempts.length} '
            'boundKey=$boundFbKey',
          );
        }
        _cancelStaleSmartFacebookDownloads(boundFbKey);
        if (smartTask != null) {
          smartTask['expectedFbVideoKey'] = boundFbKey;
        }
      } else if (attempts.isNotEmpty) {
        // 无稳定 CDN 身份时：手动/智能都只允许本次长按首选地址，
        // 禁止混入页面历史捕获（否则会下到预加载的下一条）。
        // Prefer abort when identity is still reel:/empty after resolve —
        // downloading an unbound primary is how neighbors get saved.
        if (expectedFbKey.startsWith('reel:') || expectedFbKey.isEmpty) {
          debugPrint(
            'FB pipeline: abort — no CDN identity for pressed item '
            '(expected=$expectedFbKey primary=$downloadUrl)',
          );
          if (isSmartGesture) {
            smartTask?['lastGestureFailureType'] = 'fb_identity_unbound';
          }
          onFailureType?.call('fb_identity_unbound');
          if (shownDialog && mounted) {
            final nav = Navigator.of(context, rootNavigator: true);
            if (nav.canPop()) nav.pop();
          }
          progress.dispose();
          detailNotifier.dispose();
          if (showResultHint && mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(_facebookUnsupportedMediaMessage(forVideo: true)),
                duration: const Duration(seconds: 3),
              ),
            );
          }
          return false;
        }
        final primary =
            downloadUrl.trim().isNotEmpty ? downloadUrl : attempts.first;
        attempts
          ..clear()
          ..add(primary);
        debugPrint(
          'FB pipeline: no stable current-media identity; '
          'restricted to the long-press primary candidate',
        );
      }
      attempts.sort(
        (left, right) => _scoreFacebookVideoCandidate(
          right,
          expectedVideoKey: boundFbKey,
          isReels: isFacebookReelsPageUrl(pageUrl),
        ).compareTo(
          _scoreFacebookVideoCandidate(
            left,
            expectedVideoKey: boundFbKey,
            isReels: isFacebookReelsPageUrl(pageUrl),
          ),
        ),
      );
      FacebookMediaMetadata? selectedVideoMetadata;
      for (final candidate in attempts) {
        final metadata = facebookMediaMetadata(candidate);
        if (metadata?.isVideoTrack == true && metadata!.videoId.isNotEmpty) {
          selectedVideoMetadata = metadata;
          break;
        }
      }
      if (selectedVideoMetadata != null) {
        pairedDashAudioUrl = _findFacebookPairedAudioUrl(
          videoId: selectedVideoMetadata.videoId,
          explicitCandidates: <String>[
            videoUrl,
            downloadUrl,
            ...candidateUrls,
            ...attempts,
          ],
          pageUrl: pageUrl,
        );
        if (pairedDashAudioUrl == null) {
          // Audio requests often follow the first video range slightly later.
          // Hold the current reel instead of switching/accepting silence.
          for (
            var audioWait = 0;
            audioWait < 6 && pairedDashAudioUrl == null;
            audioWait++
          ) {
            await Future<void>.delayed(const Duration(milliseconds: 300));
            pairedDashAudioUrl = _findFacebookPairedAudioUrl(
              videoId: selectedVideoMetadata.videoId,
              explicitCandidates: <String>[
                videoUrl,
                downloadUrl,
                ...candidateUrls,
                ...attempts,
              ],
              pageUrl: pageUrl,
            );
          }
        }
        requireFacebookAudioMux = pairedDashAudioUrl != null;
        if (requireFacebookAudioMux) {
          facebookDashVideoId = selectedVideoMetadata.videoId;
        }
        if (pairedDashAudioUrl == null) {
          // Do not save a known DASH video-only representation as a silent
          // success. Prefer a progressive candidate whose metadata does not
          // explicitly identify it as a separate video track.
          final progressiveWithEmbeddedAudio =
              attempts.where((candidate) {
                final metadata = facebookMediaMetadata(candidate);
                return metadata == null &&
                    _isFacebookProgressiveMp4Url(candidate);
              }).toList();
          if (progressiveWithEmbeddedAudio.isNotEmpty) {
            attempts
              ..clear()
              ..addAll(progressiveWithEmbeddedAudio);
            selectedVideoMetadata = null;
          } else {
            missingFacebookAudioTrack = true;
            debugPrint(
              'FB pipeline: matching audio track not captured for '
              'videoId=${selectedVideoMetadata.videoId} after bounded wait; '
              'preserve the bound video track as a partial success',
            );
          }
        }
      }
      final beforeAudioFilter = attempts.length;
      attempts.removeWhere(
        (url) => facebookMediaMetadata(url)?.isAudioOnly == true,
      );
      if (beforeAudioFilter != attempts.length) {
        debugPrint(
          'FB pipeline: removed ${beforeAudioFilter - attempts.length} '
          'audio-only fallback candidate(s) before download',
        );
      }
      if (attempts.isEmpty) {
        final failureType =
            missingFacebookAudioTrack
                ? 'fb_audio_track_not_captured'
                : 'fb_video_track_not_captured';
        if (isSmartGesture) {
          smartTask?['lastGestureFailureType'] = failureType;
        }
        onFailureType?.call(failureType);
        debugPrint(
          missingFacebookAudioTrack
              ? 'FB pipeline: abort known video-only DASH download because '
                  'its matching audio track was not captured'
              : 'FB pipeline: abort download because only an audio DASH track '
                  'was captured; wait for the matching video track instead',
        );
        if (shownDialog && mounted) {
          final nav = Navigator.of(context, rootNavigator: true);
          if (nav.canPop()) nav.pop();
        }
        progress.dispose();
        detailNotifier.dispose();
        return false;
      }
      if (missingFacebookAudioTrack) {
        debugPrint(
          '[SMART_PARTIAL] Facebook audio track unavailable; '
          'continue with the verified video track only',
        );
      }
    }
    if (isLongPress && attempts.length > (isFacebookPipeline ? 8 : 3)) {
      // Facebook: keep more progressive candidates so stub/size rejects can
      // fall through to the next URL instead of saving a black placeholder.
      attempts.removeRange(isFacebookPipeline ? 8 : 3, attempts.length);
    } else if (isSmartBatch && attempts.length > (isFacebookPipeline ? 8 : 3)) {
      // 智能批量任务应快速换媒体，不能在同一候选上无限消耗时间。
      attempts.removeRange(isFacebookPipeline ? 8 : 3, attempts.length);
    }
    if (isFacebookPipeline) {
      debugPrint(
        'FB pipeline: robust download candidates=${attempts.length} '
        'minBytes=$effectiveMinFileBytes primary=$downloadUrl',
      );
    }
    detailNotifier.value = '已获取下载地址，准备开始...';
    if (_favoriteDownloadDiagnosticsEnabled) {
      Logger.log(
        '[稳健下载诊断] 开始: 候选总数=${attempts.length}, pageUrl=${pageUrl.isEmpty ? "-" : pageUrl}, videoUrl=${videoUrl.isEmpty ? "-" : videoUrl}',
      );
    }
    var ok = false;
    int successIndex = -1;
    var lastFailureType = 'unknown';
    for (int i = 0; i < attempts.length; i++) {
      final sw = Stopwatch()..start();
      var failureType = 'unknown';
      final facebookMetadata = facebookMediaMetadata(attempts[i]);
      final attemptRequiresFacebookAudio =
          requireFacebookAudioMux &&
          facebookMetadata?.isVideoTrack == true &&
          facebookMetadata!.videoId == facebookDashVideoId;
      final attemptMinFileBytes =
          (isFacebookPipeline || isInstagramPipeline) &&
                  facebookMetadata?.isVideoTrack == true
              ? facebookVideoMinimumBytes(attempts[i])
              : effectiveMinFileBytes;
      progress.value = null;
      detailNotifier.value = '候选 ${i + 1}/${attempts.length}：正在连接...';
      if (smartTask != null &&
          !await _reserveSmartMediaName(
            smartTask,
            attempts[i],
            title: (item['title'] ?? '').toString(),
            pageUrl: pageUrl,
          )) {
        // 预约拦截仅在「24h 备案 fileHash 且库内哈希仍在」时发生；
        // URL/标题软预约在 forceNoPreSkip 下已放行，不会误杀
        failureType =
            (smartTask['lastSmartReserveBlockReason'] ?? 'already_in_library')
                .toString();
        if (failureType.isEmpty) failureType = 'already_in_library';
        lastFailureType = failureType;
        detailNotifier.value = '媒体库已有相同内容（哈希），正在换下一个';
        if (_favoriteDownloadDiagnosticsEnabled) {
          Logger.log(
            '[稳健下载诊断] 尝试#${i + 1}/${attempts.length}: 跳过 | failureType=$failureType | url=${attempts[i]}',
          );
        }
        // A hash-confirmed library duplicate is terminal for this media item.
        // Trying a lower rendition as if it were another item can turn a
        // correct duplicate skip into a size failure and make the grid retry.
        if (failureType == 'already_in_library') break;
        continue;
      }
      ok = await _performBackgroundDownload(
        attempts[i],
        MediaType.video,
        skipFailurePrompt: i < attempts.length - 1,
        onFailureType: (t) => failureType = t,
        inactivityTimeout:
            isSmartDownload
                ? const Duration(minutes: 2)
                : isLongPress
                ? const Duration(minutes: 2)
                : const Duration(minutes: 3),
        maxRequestAttempts:
            isSmartDownload
                ? 4
                : isLongPress
                ? 4
                : null,
        showSuccessPrompt: false,
        showDuplicatePrompt: !isSmartDownload,
        validateSmartMedia:
            isSmartDownload || isFacebookPipeline || isInstagramPipeline,
        isSmartBatchMedia: isSmartDownload,
        smartTask: smartTask,
        smartMediaTitle: (item['title'] ?? '').toString(),
        smartPageUrl: pageUrl,
        minFileBytes: attemptMinFileBytes,
        maxFileBytes: effectiveMaxFileBytes,
        rejectIncompleteMp4Stub: isFacebookPipeline || isInstagramPipeline,
        rejectAudioOnlyMp4: isInstagramPipeline,
        pairedAudioUrl:
            ((isFacebookPipeline && attemptRequiresFacebookAudio) ||
                        isInstagramPipeline) &&
                    facebookIdentitiesMatch(
                      facebookMediaIdentity(attempts[i]),
                      facebookMediaIdentity(pairedDashAudioUrl ?? ''),
                    )
                ? pairedDashAudioUrl
                : null,
        requirePairedAudio: attemptRequiresFacebookAudio,
        expectedMediaIdentity:
            isFacebookPipeline
                ? (item['expectedFbVideoKey'] ??
                        smartTask?['expectedFbVideoKey'] ??
                        '')
                    .toString()
                    .trim()
                : '',
        onProgress: (fraction, {String? detail}) {
          progress.value = fraction.clamp(0.0, 1.0);
          if (detail != null && detail.trim().isNotEmpty) {
            detailNotifier.value = '候选 ${i + 1}/${attempts.length}：$detail';
          }
        },
      );
      sw.stop();
      lastFailureType = failureType;
      if (!ok && smartTask != null && failureType != 'already_in_library') {
        _releaseSmartMediaName(
          smartTask,
          attempts[i],
          title: (item['title'] ?? '').toString(),
          pageUrl: pageUrl,
        );
      }
      if (_favoriteDownloadDiagnosticsEnabled) {
        Logger.log(
          '[稳健下载诊断] 尝试#${i + 1}/${attempts.length}: ${ok ? "成功" : "失败"} | failureType=${ok ? "none" : failureType} | elapsedMs=${sw.elapsedMilliseconds} | url=${attempts[i]}',
        );
      }
      if (ok) {
        successIndex = i + 1;
        break;
      }
      if (failureType == 'library_save_failed' ||
          failureType == 'already_in_library' ||
          (failureType == 'outside_requested_size_range' &&
              item['downloadOrigin'] != 'smart_batch' &&
              !isFacebookPipeline) ||
          failureType == 'cancelled') {
        break;
      }
      if (isFacebookPipeline &&
          (failureType == 'outside_requested_size_range' ||
              failureType == 'invalid_smart_media_content' ||
              failureType == 'fb_stub_rejected')) {
        detailNotifier.value = '候选 ${i + 1} 为 stub/过小，正在换下一个…';
        debugPrint(
          'FB pipeline: reject candidate #${i + 1} failure=$failureType, '
          'trying next',
        );
        continue;
      }
      if (smartXMediaId.isNotEmpty &&
          failureType == 'invalid_smart_media_content') {
        // Remaining X candidates are normally lower renditions of the same
        // media ID. Re-downloading them wastes time without finding a new item.
        break;
      }
    }
    if (!ok &&
        !isLongPress &&
        !isSmartBatch &&
        lastFailureType != 'library_save_failed' &&
        lastFailureType != 'already_in_library' &&
        lastFailureType != 'cancelled' &&
        pageUrl.startsWith('http')) {
      detailNotifier.value = '第3步：重新打开源页并二次嗅探...';
      final resniffCandidates = await _resniffFavoriteCandidatesFromSourcePage(
        pageUrl,
      );
      if (resniffCandidates.isNotEmpty) {
        final tried = attempts.toSet();
        final secondAttempts =
            _buildFavoriteAttempts(downloadUrl, [
              ...candidateUrls,
              ...resniffCandidates,
            ]).where((u) => !tried.contains(u)).toList();
        for (int i = 0; i < secondAttempts.length; i++) {
          final sw = Stopwatch()..start();
          var failureType = 'unknown';
          progress.value = null;
          detailNotifier.value =
              '二次嗅探候选 ${i + 1}/${secondAttempts.length}：正在连接...';
          ok = await _performBackgroundDownload(
            secondAttempts[i],
            MediaType.video,
            skipFailurePrompt: i < secondAttempts.length - 1,
            onFailureType: (t) => failureType = t,
            inactivityTimeout: const Duration(minutes: 3),
            showSuccessPrompt: false,
            showDuplicatePrompt: !isSmartDownload,
            validateSmartMedia: isSmartDownload,
            isSmartBatchMedia: isSmartDownload,
            smartTask: smartTask,
            smartMediaTitle: (item['title'] ?? '').toString(),
            smartPageUrl: pageUrl,
            minFileBytes: minFileBytes,
            maxFileBytes: maxFileBytes,
            onProgress: (fraction, {String? detail}) {
              progress.value = fraction.clamp(0.0, 1.0);
              if (detail != null && detail.trim().isNotEmpty) {
                detailNotifier.value =
                    '二次嗅探候选 ${i + 1}/${secondAttempts.length}：$detail';
              }
            },
          );
          sw.stop();
          lastFailureType = failureType;
          if (_favoriteDownloadDiagnosticsEnabled) {
            Logger.log(
              '[稳健下载诊断] 二次嗅探尝试#${i + 1}/${secondAttempts.length}: ${ok ? "成功" : "失败"} | failureType=${ok ? "none" : failureType} | elapsedMs=${sw.elapsedMilliseconds} | url=${secondAttempts[i]}',
            );
          }
          if (ok) {
            break;
          }
          if (failureType == 'library_save_failed' ||
              failureType == 'already_in_library' ||
              (failureType == 'outside_requested_size_range' &&
                  item['downloadOrigin'] != 'smart_batch') ||
              failureType == 'cancelled') {
            break;
          }
        }
      } else {
        lastFailureType = 'resniff_no_candidate';
      }
    }
    if (_favoriteDownloadDiagnosticsEnabled) {
      Logger.log(
        '[稳健下载诊断] 结束: ${ok ? "成功" : "失败"} | 命中候选=${ok ? successIndex : 0}',
      );
    }
    if (smartVideoStates != null && smartXMediaId.isNotEmpty) {
      smartVideoStates[smartXMediaId] = ok ? 'completed' : 'failed';
    }
    if (_downloadTasks.length > taskLenBefore) {
      final last = _downloadTasks.first;
      final p = (last['progress'] as num?)?.toDouble();
      progress.value = p == null ? null : p.clamp(0.0, 1.0);
      final d = (last['progressDetail'] ?? '').toString();
      detailNotifier.value = d.isNotEmpty ? d : (ok ? '下载完成，正在入库...' : '下载失败');
    }
    progress.value = 1.0;
    detailNotifier.value = ok ? '已保存到媒体库' : '下载失败';
    await Future<void>.delayed(const Duration(milliseconds: 180));
    if (shownDialog && mounted) {
      final nav = Navigator.of(context, rootNavigator: true);
      if (nav.canPop()) nav.pop();
    }
    progress.dispose();
    detailNotifier.dispose();
    if (!ok) {
      if (isSmartGesture) {
        smartTask?['lastGestureFailureType'] = lastFailureType;
      }
      onFailureType?.call(lastFailureType);
    }
    if (ok && lastFailureType != 'already_downloading') {
      await _markFavoriteDownloaded(item, downloaded: true);
    }
    if (showResultHint && mounted && lastFailureType != 'already_in_library') {
      final canView = ok || lastFailureType == 'already_in_library';
      final fbStubFail =
          isFacebookPipeline &&
          !ok &&
          (lastFailureType == 'outside_requested_size_range' ||
              lastFailureType == 'fb_stub_rejected' ||
              lastFailureType == 'invalid_smart_media_content');
      final fbAudioFail =
          isFacebookPipeline &&
          !ok &&
          (lastFailureType == 'fb_audio_track_not_captured' ||
              lastFailureType == 'fb_audio_mux_failed');
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            ok
                ? (isLongPress ? '已保存当前长按的媒体' : '已加入下载：$downloadUrl')
                : (lastFailureType == 'library_save_failed'
                    ? '文件已下载，但写入媒体库失败；已停止重复下载'
                    : lastFailureType == 'already_in_library'
                    ? '媒体库中已存在相同文件，未重复保存'
                    : fbStubFail
                    ? 'Facebook 当前播放窗口未捕获到完整可播放视频（仅收到初始化分片或请求受限）'
                    : fbAudioFail
                    ? 'Facebook 已捕获视频轨，但尚未捕获或合并对应音轨；请继续播放几秒后再长按'
                    : (isLongPress ? '当前长按的媒体保存失败，已停止尝试' : '下载失败，请稍后重试')),
          ),
          duration: Duration(
            seconds: canView ? 3 : ((fbStubFail || fbAudioFail) ? 4 : 2),
          ),
          action:
              canView
                  ? SnackBarAction(label: '查看', onPressed: _openMediaLibrary)
                  : null,
        ),
      );
    }
    return ok;
  }

  bool _isRetryableFavoriteFailure(String failureType) {
    return failureType == 'timeout' ||
        failureType == 'connection_error' ||
        failureType == 'dio_error' ||
        failureType == 'http_5xx';
  }

  Future<void> _downloadFavoritesBatch(
    List<Map<String, dynamic>> items, {
    bool forceRedownload = false,
  }) async {
    if (items.isEmpty || !mounted) return;
    final batchTaskId = const Uuid().v4();
    final batchCancelToken = CancelToken();
    var success = 0;
    var failed = 0;
    var skipped = 0;
    var retried = 0;
    var processed = 0;
    final retryQueue = <Map<String, dynamic>>[];
    _addDownloadTask(
      batchTaskId,
      'favorite-batch://$batchTaskId',
      MediaType.video,
      batchCancelToken,
      displayName:
          forceRedownload
              ? '收藏批量重新下载（${items.length}）'
              : '收藏批量下载（${items.length}）',
      isFavoriteBatch: true,
    );

    void updateBatchProgress(String currentName, {bool retrying = false}) {
      final baseProgress = processed / items.length;
      _updateDownloadTask(
        batchTaskId,
        progress: (retrying ? 0.75 + baseProgress * 0.24 : baseProgress * 0.75)
            .clamp(0.0, 0.99),
        progressDetail:
            '${retrying ? "正在重试" : "已处理"} $processed/${items.length} · '
            '成功 $success · 跳过 $skipped · 当前：$currentName',
      );
    }

    try {
      for (int i = 0; i < items.length; i++) {
        if (batchCancelToken.isCancelled) break;
        final currentItem = items[i];
        final currentName =
            (currentItem['title'] ?? currentItem['name'] ?? '未知媒体').toString();
        updateBatchProgress(currentName);

        if (!forceRedownload && _isFavoriteLikelyDownloaded(currentItem)) {
          skipped++;
          processed++;
          updateBatchProgress(currentName);
          continue;
        }
        final downloadItem = Map<String, dynamic>.from(currentItem);
        if (forceRedownload) {
          downloadItem['allowSourceUrlReuse'] = true;
        }
        var failureType = 'unknown';
        final ok = await _downloadOneFavorite(
          item: downloadItem,
          showResultHint: false,
          showModalDialog: false, // 批量下载时，不显示单个文件的弹窗
          onFailureType: (t) => failureType = t,
        );
        if (ok) {
          success++;
        } else {
          failed++;
          if (_isRetryableFavoriteFailure(failureType)) {
            retryQueue.add(Map<String, dynamic>.from(currentItem));
          }
        }
        processed++;
        updateBatchProgress(currentName);
      }
      if (retryQueue.isNotEmpty && !batchCancelToken.isCancelled) {
        for (int j = 0; j < retryQueue.length; j++) {
          if (batchCancelToken.isCancelled) break;
          final currentItem = retryQueue[j];
          final currentName =
              (currentItem['title'] ?? currentItem['name'] ?? '未知媒体')
                  .toString();
          updateBatchProgress(currentName, retrying: true);

          retried++;
          await Future<void>.delayed(const Duration(milliseconds: 320));
          final ok = await _downloadOneFavorite(
            item: Map<String, dynamic>.from(currentItem)
              ..['allowSourceUrlReuse'] = forceRedownload,
            showResultHint: false,
            showModalDialog: false, // 重试时同样不显示单个文件弹窗
          );
          if (ok) {
            success++;
            failed--;
          }
          _updateDownloadTask(
            batchTaskId,
            progress: (0.75 + ((j + 1) / retryQueue.length) * 0.24).clamp(
              0.0,
              0.99,
            ),
            progressDetail:
                '重试 ${j + 1}/${retryQueue.length} · 成功 $success · 跳过 $skipped · 当前：$currentName',
          );
        }
      }
    } finally {
      final cancelled = batchCancelToken.isCancelled;
      _updateDownloadTask(
        batchTaskId,
        status: cancelled ? 'cancelled' : 'completed',
        progress: cancelled ? (processed / items.length).clamp(0.0, 1.0) : 1.0,
        progressDetail:
            cancelled
                ? '已停止：成功 $success，失败 $failed，跳过 $skipped'
                : '完成：成功 $success，失败 $failed，跳过 $skipped',
      );
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(
              cancelled
                  ? '批量下载已停止：成功 $success 条，失败 $failed 条，跳过 $skipped 条'
                  : '${forceRedownload ? "批量重新下载" : "批量下载"}完成：成功 $success 条，失败 $failed 条，跳过 $skipped 条',
            ),
            duration: const Duration(milliseconds: 1500),
          ),
        );
        if (retried > 0 && !cancelled) {
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text('二轮重试已执行：$retried 条（仅超时/网络类失败）'),
              duration: const Duration(milliseconds: 1300),
            ),
          );
        }
      }
    }
  }

  Future<void> _saveVideoSourceUrlMap() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
        _kVideoSourceUrlMapPrefsKey,
        jsonEncode(_videoSourceUrlToMediaId),
      );
    } catch (e) {
      debugPrint('保存视频来源映射失败: $e');
    }
  }

  String _normalizeVideoSourceUrl(String url) {
    final uri = Uri.tryParse(_toAbsoluteUrl(url));
    if (uri == null) return url;
    const ignoredParams = <String>{
      'token',
      'sig',
      'signature',
      'expires',
      'expire',
      'exp',
      'auth',
      'auth_key',
      'x-amz-signature',
      'x-amz-date',
      'x-amz-credential',
      'x-amz-security-token',
      'x-amz-algorithm',
      'x-amz-expires',
      'x-signature',
    };
    final keptEntries = <MapEntry<String, String>>[];
    for (final e in uri.queryParametersAll.entries) {
      final key = e.key.toLowerCase();
      if (ignoredParams.contains(key)) continue;
      for (final value in e.value) {
        keptEntries.add(MapEntry(e.key, value));
      }
    }
    keptEntries.sort((a, b) {
      final c = a.key.compareTo(b.key);
      if (c != 0) return c;
      return a.value.compareTo(b.value);
    });
    final query = keptEntries
        .map(
          (e) =>
              '${Uri.encodeQueryComponent(e.key)}=${Uri.encodeQueryComponent(e.value)}',
        )
        .join('&');
    return uri.replace(query: query, fragment: '').toString();
  }

  Future<String> _resolveMediaLocationLabel(
    Map<String, dynamic> mediaRow,
  ) async {
    final dir = mediaRow['directory']?.toString() ?? '';
    if (dir.isEmpty || dir == 'root') return '根目录';
    if (dir == 'favorites') return '收藏夹';
    if (dir == 'recycle_bin') return '回收站';
    final parent = await _databaseService.getMediaItemById(dir);
    final name = parent?['name']?.toString();
    if (name != null && name.isNotEmpty) return name;
    return dir;
  }

  Future<Map<String, dynamic>?> _findExistingVideoBySourceUrl(
    String url,
  ) async {
    final normalized = _normalizeVideoSourceUrl(url);
    final mediaId = _videoSourceUrlToMediaId[normalized];
    if (mediaId == null || mediaId.isEmpty) return null;
    final row = await _databaseService.getMediaItemById(mediaId);
    if (row == null) {
      _videoSourceUrlToMediaId.remove(normalized);
      await _saveVideoSourceUrlMap();
      return null;
    }
    final type = DatabaseService.mediaTypeIndex(row);
    if (type != MediaType.video.index) return null;
    final directory = row['directory']?.toString() ?? '';
    // 仅将「当前媒体库可见/可用」的视频视为已存在；回收站中的旧记录不阻止再次下载。
    if (directory == 'recycle_bin') {
      _videoSourceUrlToMediaId.remove(normalized);
      await _saveVideoSourceUrlMap();
      return null;
    }
    final path = row['path']?.toString() ?? '';
    if (path.isEmpty || !await File(path).exists()) {
      _videoSourceUrlToMediaId.remove(normalized);
      await _saveVideoSourceUrlMap();
      return null;
    }
    return row;
  }

  Future<Map<String, dynamic>?> _findExistingVideoBeforeDownload(
    String url,
  ) async {
    return _findExistingVideoBySourceUrl(url);
  }

  void _openMediaLibrary() {
