  void _openDirectoryPage() {
    if (!mounted) return;
    Logger.log('[BrowserPage] 目录页按钮被点击');
    // 进入目录前绑定会话，供文档编辑器「当前的浏览页面」预览使用。
    _rememberLastBrowsingUrl(_currentUrl);
    _syncBrowserSessionPreview(bindForDirectory: true);
    // 进入目录后不再被浏览器下载成功提示打扰。
    ScaffoldMessenger.of(context).clearSnackBars();
    Navigator.of(context).push(
      MaterialPageRoute(
        builder:
            (context) => DirectoryPage(
              showRouteBackButton: true,
              onDocumentOpen: (documentName) {
                Navigator.of(context).push(
                  MaterialPageRoute(
                    builder:
                        (_) => DocumentEditorPage(
                          documentName: documentName,
                          onSave: (_) {},
                        ),
                  ),
                );
              },
            ),
      ),
    );
  }

