  void _setupWebViewController(InAppWebViewController ctrl) {
    _controller = ctrl;
    ctrl.addJavaScriptHandler(
      handlerName: 'Flutter',
      callback: (args) {
        if (args.isNotEmpty && args[0] != null) {
          debugPrint('来自JavaScript的消息: ${args[0]}');
          _handleJavaScriptMessage(args[0].toString());
        }
      },
    );
    ctrl.addJavaScriptHandler(
      handlerName: 'TelegramStreamChunk',
      callback: (args) async {
        if (args.isEmpty || args.first is! Map) {
          return <String, dynamic>{'ok': false, 'reason': 'invalid_message'};
        }
        return _handleTelegramStreamChunk(
          Map<String, dynamic>.from(args.first as Map),
        );
      },
    );
    _syncBrowserSessionPreview();
    // Remount after GlobalKey loan/return: native surface starts at about:blank.
    if (_isBrowsingWebPage) {
      unawaited(_recoverBrowsingSurfaceIfBlank(reason: 'webview_created'));
    }
  }

  Future<Map<String, dynamic>> _handleTelegramStreamChunk(
    Map<String, dynamic> message,
  ) async {
    final phase = (message['phase'] ?? '').toString();
    final transferId = (message['transferId'] ?? '').toString();
    try {
      if (phase == 'start') {
        if (_telegramStreamSink != null) {
          await _telegramStreamSink!.close();
        }
        final appDir = await getApplicationDocumentsDirectory();
        final mediaDir = Directory('${appDir.path}/media');
        if (!await mediaDir.exists()) await mediaDir.create(recursive: true);
        final file = File('${mediaDir.path}/${const Uuid().v4()}.mp4');
        _telegramStreamFile = file;
        _telegramStreamSink = file.openWrite();
        _telegramStreamTransferId = transferId;
        _telegramStreamBytes = 0;
        _telegramStreamExpectedBytes =
            (message['expectedBytes'] as num?)?.toInt() ?? 0;
        debugPrint(
          '[TG_STREAM] start id=$transferId '
          'expected=${message['expectedBytes']} path=${file.path}',
        );
        return <String, dynamic>{'ok': true};
      }
      if (transferId.isEmpty ||
          transferId != _telegramStreamTransferId ||
          _telegramStreamSink == null) {
        return <String, dynamic>{'ok': false, 'reason': 'unknown_transfer'};
      }
      if (phase == 'chunk') {
        final encoded = (message['data'] ?? '').toString();
        final bytes = base64Decode(encoded);
        _telegramStreamSink!.add(bytes);
        _telegramStreamBytes += bytes.length;
        if (_telegramStreamBytes % (4 * 1024 * 1024) < bytes.length) {
          await _telegramStreamSink!.flush();
          debugPrint(
            '[TG_STREAM] progress id=$transferId bytes=$_telegramStreamBytes',
          );
        }
        return <String, dynamic>{
          'ok': true,
          'receivedBytes': _telegramStreamBytes,
        };
      }
      if (phase == 'end') {
        final sink = _telegramStreamSink!;
        final file = _telegramStreamFile!;
        _telegramStreamSink = null;
        _telegramStreamFile = null;
        _telegramStreamTransferId = '';
        await sink.flush();
        await sink.close();
        final actualBytes = await file.length();
        final expectedBytes = _telegramStreamExpectedBytes;
        _telegramStreamExpectedBytes = 0;
        debugPrint(
          '[TG_STREAM] end id=$transferId bytes=$actualBytes '
          'expected=$expectedBytes',
        );
        if ((expectedBytes > 0 && actualBytes != expectedBytes) ||
            actualBytes < _kMinBase64VideoBytes ||
            _detectVideoExtension(
                  await file
                      .openRead(0, min(actualBytes, 64 * 1024))
                      .fold<List<int>>(
                        <int>[],
                        (all, part) => all..addAll(part),
                      ),
                ) ==
                null) {
          await file.delete();
          throw const FormatException('Telegram stream is not a valid video');
        }
        await _saveToMediaLibrary(
          file,
          MediaType.video,
          allowDuplicate: false,
          relaxValidation: false,
        );
        _notifyMediaDownloadSaved();
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('Telegram 视频已保存到媒体库'),
              duration: _kMediaSaveSnackDuration,
            ),
          );
        }
        return <String, dynamic>{'ok': true, 'savedBytes': actualBytes};
      }
      if (phase == 'error') {
        final sink = _telegramStreamSink;
        final file = _telegramStreamFile;
        _telegramStreamSink = null;
        _telegramStreamFile = null;
        _telegramStreamTransferId = '';
        await sink?.close();
        if (file != null && await file.exists()) await file.delete();
        debugPrint('[TG_STREAM] web error: ${message['error']}');
        return <String, dynamic>{'ok': true};
      }
      return <String, dynamic>{'ok': false, 'reason': 'unknown_phase'};
    } catch (e, st) {
      debugPrint('[TG_STREAM] phase=$phase failed: $e\n$st');
      final sink = _telegramStreamSink;
      final file = _telegramStreamFile;
      _telegramStreamSink = null;
      _telegramStreamFile = null;
      _telegramStreamTransferId = '';
      _telegramStreamExpectedBytes = 0;
      try {
        await sink?.close();
        if (file != null && await file.exists()) await file.delete();
      } catch (_) {}
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('Telegram 视频保存失败：$e'),
            duration: _kMediaSaveSnackDuration,
          ),
        );
      }
      return <String, dynamic>{'ok': false, 'reason': e.toString()};
    }
  }

  /// Same [InAppWebView] instance (via GlobalKey) for BrowserPage or document loan host.
  Widget _buildLiveSessionWebView() {
    // If PlatformView State is recreated after loan, prefer last real URL over about:blank.
    final restoreUrl = _isBrowsingWebPage ? _resolvedLastBrowsingUrl() : null;
    final initialUrl =
        (restoreUrl != null && BrowserSessionPreview.isHttpUrl(restoreUrl))
            ? restoreUrl
            : 'about:blank';
    final instagramBottomInset =
        _isInstagramPlatformPage(_currentUrl)
            ? max(MediaQuery.viewPaddingOf(context).bottom, 32.0)
            : 0.0;
    final webView = InAppWebView(
      key: BrowserSessionPreview.instance.webViewKey,
      initialUrlRequest: URLRequest(url: WebUri(initialUrl)),
      initialSettings: InAppWebViewSettings(
        javaScriptEnabled: true,
        useHybridComposition: true,
        useOnLoadResource: true,
        useShouldOverrideUrlLoading: true,
        allowFileAccess: true,
        domStorageEnabled: true,
        databaseEnabled: true,
        cacheEnabled: true,
        // 正常浏览：持久 cookie / 本地存储；勿用无痕，否则退出即丢登录
        incognito: false,
        clearCache: false,
        clearSessionCache: false,
        thirdPartyCookiesEnabled: true,
        // iOS：与系统 HTTPCookieStorage 共享，利于跨次冷启动保持登录
        sharedCookiesEnabled: true,
        saveFormData: true,
        javaScriptCanOpenWindowsAutomatically: true,
        supportMultipleWindows: true,
        mixedContentMode: MixedContentMode.MIXED_CONTENT_ALWAYS_ALLOW,
      ),
      initialUserScripts: UnmodifiableListView([
        UserScript(
          source: _kEarlyMediaSnifferScript,
          injectionTime: UserScriptInjectionTime.AT_DOCUMENT_START,
        ),
      ]),
      onWebViewCreated: (ctrl) => _setupWebViewController(ctrl),
      shouldAllowDeprecatedTLS: (ctrl, challenge) async {
        return ShouldAllowDeprecatedTLSAction.ALLOW;
      },
      // 注意：PROCEED 会跳过证书校验，存在中间人攻击风险。
      // 若需更高安全性，可改为 DENY 或实现白名单校验。
      onReceivedServerTrustAuthRequest: (ctrl, challenge) async {
        return ServerTrustAuthResponse(
          action: ServerTrustAuthResponseAction.PROCEED,
        );
      },
      onLoadStart: (ctrl, url) {
        if (url != null) {
          final urlStr = url.toString();
          // 自定义协议若仍进到 onLoadStart：解开深链或立刻停住，避免「无法打开」页。
          if (!urlStr.startsWith('http://') &&
              !urlStr.startsWith('https://') &&
              !urlStr.startsWith('about:') &&
              !urlStr.startsWith('data:') &&
              !urlStr.startsWith('blob:')) {
            final extracted = _extractHttpUrlFromAppDeepLink(urlStr);
            if (extracted != null) {
              unawaited(
                ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(extracted))),
              );
            } else {
              unawaited(ctrl.stopLoading());
            }
            return;
          }
          // Google 若仍跳到失效 /m，立刻拉回可用首页。
          final googleFixed = _rewriteDeadGoogleMobileNavigation(urlStr);
          if (googleFixed != null) {
            unawaited(
              ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(googleFixed))),
            );
            return;
          }
        }
        if (url != null) {
          final urlStr = url.toString();
          // Remount / loan return often emits about:blank — do not clobber chrome.
          if (_isBlankHistoryUrl(urlStr)) {
            setState(() => _isLoading = true);
            if (_isBrowsingWebPage) {
              final saved = _resolvedLastBrowsingUrl();
              if (saved != null &&
                  (_isBlankHistoryUrl(_currentUrl) ||
                      _isBlankHistoryUrl(_urlController.text))) {
                setState(() {
                  _currentUrl = saved;
                  _urlController.text = saved;
                });
              }
              unawaited(
                _recoverBrowsingSurfaceIfBlank(reason: 'load_start_blank'),
              );
            }
            return;
          }
          if (urlStr.startsWith('http://') || urlStr.startsWith('https://')) {
            // 尽早记入干净后退栈，避免陷阱页抢在 onLoadStop 前冲掉搜索结果。
            _noteMeaningfulWebNavigation(urlStr);
            _rememberLastBrowsingUrl(urlStr);
          }
        }
        setState(() {
          _isLoading = true;
          if (url != null) {
            final urlStr = url.toString();
            _currentUrl = urlStr;
            _urlController.text = _currentUrl;
            // 仅当加载真实网页时切换到 WebView，about:blank 不切换（保持主界面）
            if (urlStr.startsWith('http://') || urlStr.startsWith('https://')) {
              _showHomePage = false;
              _isBrowsingWebPage = true;
              widget.onBrowserHomePageChanged?.call(false);
            }
          }
        });
        _syncBrowserSessionPreview();
      },
      onProgressChanged: (ctrl, progress) {
        setState(() {
          _loadingProgress = progress / 100;
          _isLoading = _loadingProgress < 1.0;
        });
      },
      onLoadStop: (ctrl, url) {
        if (url != null) _onPageFinished(url.toString());
      },
      onUpdateVisitedHistory: (ctrl, url, isReload) {
        if (url == null) return;
        final urlStr = url.toString();
        if (_isBlankHistoryUrl(urlStr)) return;
        if (!urlStr.startsWith('http://') && !urlStr.startsWith('https://')) {
          return;
        }
        _noteMeaningfulWebNavigation(urlStr, fromHistoryUpdate: true);
        _rememberLastBrowsingUrl(urlStr);
        if (!mounted) return;
        setState(() {
          _currentUrl = urlStr;
          _urlController.text = urlStr;
        });
      },
      onLoadResource: (ctrl, resource) {
        _recordLoadedWebResource(resource);
      },
      onCreateWindow: (ctrl, action) async {
        final popupUrl = action.request.url?.toString();
        if (popupUrl == null || popupUrl.isEmpty) {
          debugPrint('网页请求打开新窗口，但没有提供目标地址');
          return false;
        }
        if (!popupUrl.startsWith('http://') &&
            !popupUrl.startsWith('https://')) {
          await _handleNonHttpNavigation(ctrl, popupUrl);
          return false;
        }
        final googleFixed = _rewriteDeadGoogleMobileNavigation(popupUrl);
        if (googleFixed != null) {
          await ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(googleFixed)));
          return false;
        }
        if (_smartDownloadTask != null &&
            !_isWithinSmartDownloadSite(popupUrl)) {
          debugPrint('智能下载已阻止跨站弹窗: $popupUrl');
          _showSmartOperation('已阻止外部网站弹窗');
          return false;
        }
        debugPrint('接管网页新窗口并在当前页打开: $popupUrl');
        await ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(popupUrl)));
        return false;
      },
      onReceivedError:
          (ctrl, req, err) => debugPrint('WebView错误: ${err?.description}'),
      shouldOverrideUrlLoading: (ctrl, nav) async {
        final url = nav.request.url?.toString() ?? '';
        debugPrint('导航请求: $url');
        if (_isDownloadableLink(url) || _isYouTubeLink(url)) {
          debugPrint('检测到可能的下载链接: $url');
          _handleDownload(url, '', _guessMimeType(url));
          return NavigationActionPolicy.CANCEL;
        }
        if (!url.startsWith('http://') && !url.startsWith('https://')) {
          return _handleNonHttpNavigation(ctrl, url);
        }
        final googleFixed = _rewriteDeadGoogleMobileNavigation(url);
        if (googleFixed != null) {
          debugPrint('拦截失效 Google /m 导航: $url -> $googleFixed');
          await ctrl.loadUrl(urlRequest: URLRequest(url: WebUri(googleFixed)));
          return NavigationActionPolicy.CANCEL;
        }
        if (_smartDownloadTask != null && !_isWithinSmartDownloadSite(url)) {
          debugPrint('智能下载已阻止跳出当前网站: $url');
          final task = _smartDownloadTask!;
          final id = (task['discoveryTaskId'] ?? '').toString();
          if (id.isNotEmpty) {
            _updateDownloadTask(
              id,
              progressDetail:
                  '已阻止外部网站跳转，继续在当前网站内寻找 · 已保存 ${task['success']}/${task['target']}',
            );
          }
          return NavigationActionPolicy.CANCEL;
        }
        return NavigationActionPolicy.ALLOW;
      },
    );
    if (instagramBottomInset <= 0) return webView;
    return Padding(
      padding: EdgeInsets.only(bottom: instagramBottomInset),
      child: webView,
    );
  }

