              const r = video.getBoundingClientRect();
              return r.width >= 100 && r.height >= 80 &&
                r.bottom > 0 && r.top < h;
            })
            .map(video => {
              const r = video.getBoundingClientRect();
              const covers = r.left <= cx && r.right >= cx &&
                r.top <= cy && r.bottom >= cy;
              const visibleArea =
                Math.max(0, Math.min(r.right, w) - Math.max(r.left, 0)) *
                Math.max(0, Math.min(r.bottom, h) - Math.max(r.top, 0));
              return {
                video,
                score: (covers ? 1e12 : 0) +
                  (!video.paused && !video.ended ? 1e11 : 0) + visibleArea
              };
            })
            .sort((a, b) => b.score - a.score);
          const video = videos.length ? videos[0].video : null;
          if (!video) return {ok:false, reason:'no_visible_video'};
          const r = video.getBoundingClientRect();
          const x = Math.max(8, Math.min(w - 8, r.left + r.width / 2));
          const y = Math.max(8, Math.min(h - 8, r.top + r.height / 2));
          let seeked = false;
          try {
            if (Number.isFinite(video.duration) && video.duration > 3) {
              const target = Math.min(
                Math.max(0.75, video.duration * 0.12),
                video.duration - 0.5
              );
              video.currentTime = target;
              seeked = true;
            }
            const promise = video.play();
            if (promise && promise.catch) promise.catch(() => {});
          } catch (_) {}
          setTimeout(function() {
            try {
              video.removeAttribute('data-app-smart-gesture');
              video.setAttribute('data-app-smart-current', '1');
              pressedElement = video;
              const fakeEvent = {
                preventDefault: function() {},
                stopPropagation: function() {},
                target: video,
                touches: [{clientX:x, clientY:y}],
                changedTouches: [{clientX:x,clientY:y}]
              };
              handleMediaDownload(video, fakeEvent);
            } catch (_) {}
          }, 900);
          return {
            ok:true,
            seeked:seeked,
            duration:Number(video.duration || 0),
            src:String(video.currentSrc || video.src || '').slice(-48)
          };
        } catch (err) {
          return {ok:false, reason:String(err && err.message || err || 'error')};
        }
      };

      function tryCanvasCaptureFallback() {
        const target = window._lastMediaTargetForFallback;
        window._lastMediaTargetForFallback = null;
        if (!target) return;
        const tag = target.tagName ? target.tagName.toLowerCase() : '';
        let w = target.naturalWidth || target.videoWidth || target.width || target.offsetWidth;
        let h = target.naturalHeight || target.videoHeight || target.height || target.offsetHeight;
        if (w <= 0 || h <= 0) { w = target.offsetWidth || 200; h = target.offsetHeight || 200; }
        const canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext('2d');
        if (!ctx) return;
        function postBase64(base64) {
          if (base64) Flutter.postMessage(JSON.stringify({ type: 'media', mediaType: 'image', url: base64, isBase64: true, action: 'download' }));
        }
        function tryFetchImageAsBase64(src, onFail) {
          if (!src) { if (onFail) onFail(); return; }
          fetch(src, { mode: 'cors', credentials: 'omit', cache: 'no-store' })
            .then(function(r) {
              if (!r || !r.ok) throw new Error('fetch not ok');
              return r.blob();
            })
            .then(function(blob) {
              const fr = new FileReader();
              fr.onload = function() {
                const b64 = extractBase64FromDataUrl(fr.result);
                if (b64) postBase64(b64);
                else if (onFail) onFail();
              };
              fr.onerror = function() { if (onFail) onFail(); };
              fr.readAsDataURL(blob);
            })
            .catch(function() {
              fetch(src, { mode: 'cors', credentials: 'include', cache: 'no-store' })
                .then(function(r) { if (!r || !r.ok) throw new Error('fetch2 not ok'); return r.blob(); })
                .then(function(blob) {
                  const fr = new FileReader();
                  fr.onload = function() {
                    const b64 = extractBase64FromDataUrl(fr.result);
                    if (b64) postBase64(b64);
                    else if (onFail) onFail();
                  };
                  fr.onerror = function() { if (onFail) onFail(); };
                  fr.readAsDataURL(blob);
                })
                .catch(function() { if (onFail) onFail(); });
            });
        }
        function postCanvas(srcForFetch) {
          try {
            const dataUrl = canvas.toDataURL('image/png');
            if (dataUrl && dataUrl.startsWith('data:image/')) {
              Flutter.postMessage(JSON.stringify({ type: 'media', mediaType: 'image', url: extractBase64FromDataUrl(dataUrl), isBase64: true, action: 'download' }));
              return;
            }
          } catch (e) { console.log('toDataURL failed:', e); }
          if (srcForFetch) tryFetchImageAsBase64(srcForFetch, null);
        }
        function tryDrawImg(src) {
          const img = new Image();
          img.crossOrigin = 'anonymous';
          img.onload = function() {
            try { ctx.drawImage(img, 0, 0, w, h); postCanvas(src); } catch (e) {
              try { ctx.drawImage(target, 0, 0, w, h); postCanvas(src); } catch (e2) { tryFetchImageAsBase64(src, null); }
            }
          };
          img.onerror = function() {
            try { ctx.drawImage(target, 0, 0, w, h); postCanvas(src); } catch (e) { tryFetchImageAsBase64(src, null); }
          };
          img.src = src;
        }
        if (tag === 'img') {
          const src = target.currentSrc || target.src;
          if (src) {
            tryFetchImageAsBase64(src, function() { tryDrawImg(src); });
          }
        } else if (tag === 'video') {
          try {
            ctx.drawImage(target, 0, 0, w, h);
            postCanvas(null);
          } catch (e) {
            console.log('video canvas fallback failed:', e);
          }
        } else if (tag === 'canvas') {
          try {
            ctx.drawImage(target, 0, 0, w, h);
            postCanvas(null);
          } catch (e) { console.log('canvas fallback failed:', e); }
        } else if (target.style && target.style.backgroundImage) {
          const m = target.style.backgroundImage.match(/url\(['"]?([^'")]+)['"]?\)/);
          if (m && m[1]) {
            const u = m[1];
            tryFetchImageAsBase64(u, function() { tryDrawImg(u); });
          }
        }
      }

      // 启动动态内容监听
      const dynamicObserver = observeDynamicContent();
      
      // 初始扫描页面媒体元素
      setTimeout(() => {
        const initialMediaElements = deepScanForMediaElements();
        initialMediaElements.forEach(element => {
          window.MediaInterceptor.mediaElements.add(element);
        });
        console.log('初始扫描完成，找到', initialMediaElements.length, '个媒体元素');
      }, 1000);
      window.updateFeedbackStatus = updateFeedbackStatus;
      window.tryCanvasCaptureFallback = tryCanvasCaptureFallback;
      window.__appMediaDownloadHandlersVersion = handlerVersion;
      return true;
      })()
    ''',
      );
      final ready = await controller.evaluateJavascript(
        source:
            "window.__appMediaDownloadHandlersVersion === 'media-download-v33'",
      );
      if (ready == true || ready.toString().toLowerCase() == 'true') {
        if (_lastMediaHandlerFailureUrl == injectionUrl) {
          _lastMediaHandlerFailureUrl = '';
          _lastMediaHandlerFailureAt = null;
        }
        return true;
      }
    } catch (e, st) {
      debugPrint('网页媒体长按处理程序安装失败: $e\n$st');
    }
    final currentUrl = (await controller.getUrl())?.toString() ?? _currentUrl;
    if (!_isSameLoadedDocument(injectionUrl, currentUrl)) {
      debugPrint('媒体处理程序注入期间页面已切换，忽略旧页面失败: $injectionUrl -> $currentUrl');
      return false;
    }
    if (allowRetry && mounted && identical(controller, _controller)) {
      await Future<void>.delayed(const Duration(milliseconds: 250));
      return _injectDownloadHandlers(
        allowRetry: false,
        expectedUrl: injectionUrl,
      );
    }
    if (mounted) {
      final now = DateTime.now();
      final recentlyNotified =
          _lastMediaHandlerFailureUrl == injectionUrl &&
          _lastMediaHandlerFailureAt != null &&
          now.difference(_lastMediaHandlerFailureAt!) <
              const Duration(seconds: 30);
      if (!recentlyNotified) {
        _lastMediaHandlerFailureUrl = injectionUrl;
        _lastMediaHandlerFailureAt = now;
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('媒体监听初始化失败，已自动改用兼容模式继续尝试'),
            duration: Duration(seconds: 2),
          ),
        );
      }
    }
    return false;
  }

  Future<void> _handleJavaScriptMessage(String message) async {
    try {
      final data = jsonDecode(message);
      if (data is! Map || !data.containsKey('type')) return;
      if (data['type'] == 'ig_debug') {
        debugPrint(
          '[IG_DOM] phase=${data['phase'] ?? ''} '
          'touch=${data['touch'] ?? ''} '
          'initial=${data['initial'] ?? ''} '
          'selected=${data['selected'] ?? ''} '
          'post=${data['post'] ?? ''} '
          'postIndex=${data['postIndex'] ?? ''} '
          'videoIndex=${data['videoIndex'] ?? ''} '
          'videos=${data['videos'] ?? ''}',
        );
        return;
      }
      if (data['type'] == 'fb_debug' || data['type'] == 'FB_DL') {
        String clip(dynamic v, int n) {
          final s = (v ?? '').toString();
          if (s.length <= n) return s;
          return s.substring(0, n);
        }

        debugPrint(
          'FB_DL js phase=${data['phase'] ?? ''} '
          'reason=${data['reason'] ?? ''} '
          'key=${data['key'] ?? ''} '
          'softReel=${data['softReel'] ?? ''} '
          'url=${clip(data['url'], 140)} '
          'playing=${clip(data['playing'], 80)} '
          'activeKeys=${data['activeKeys'] ?? ''} '
          't=${data['currentTime'] ?? ''} '
          'extra=${data['extra'] ?? ''}',
        );
        return;
      }
      if (data['type'] == 'long_press_status') {
        if (mounted && data['isSmartGesture'] != true) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('已识别长按，正在解析当前媒体…'),
              duration: Duration(milliseconds: 900),
            ),
          );
        }
        debugPrint(
          'media long press acknowledged: '
          'target=${data['target'] ?? 'unknown'}',
        );
        return;
      }

      final dynamic urlValue = data['url'];
      final bool isBase64 = data['isBase64'] ?? false;
      final bool isStreamReference = data['isStreamReference'] == true;
      final bool isSmartGesture =
          data['isSmartGesture'] == true || _isSmartDemoLearningActive();
      final String? action = data['action'];
      final dynamic candidateValue = data['candidates'];
      final String mediaType =
          data['mediaType'] ??
          (_guessMimeType(
                urlValue is String ? urlValue : '',
              ).startsWith('image/')
              ? 'image'
              : (_guessMimeType(
                    urlValue is String ? urlValue : '',
                  ).startsWith('video/')
                  ? 'video'
                  : 'audio'));
      final String sourceMimeType =
          (data['mimeType'] ?? data['mime'] ?? '').toString();
      final messageDurationSeconds =
          (data['durationSec'] as num?)?.toDouble() ?? 0.0;
      final mediaSessionId = (data['sessionId'] ?? '').toString().trim();
      final playbackStartedAtMs =
          (data['playbackStartedAtMs'] as num?)?.toInt() ?? 0;
      final sessionNotBefore =
          playbackStartedAtMs > 0
              ? DateTime.fromMillisecondsSinceEpoch(
                playbackStartedAtMs,
              ).subtract(const Duration(seconds: 2))
              : null;
      final rawDownloadCandidateUrls = <String>[];
      if (candidateValue is List) {
        for (final e in candidateValue) {
          if (e is String && e.trim().isNotEmpty) {
            rawDownloadCandidateUrls.add(_toAbsoluteUrl(e.trim()));
          }
        }
      }
      final messagePageUrl = (data['pageUrl'] ?? _currentUrl).toString().trim();
      // Media events can originate from a cross-origin player iframe/CDN even
      // when the visible top-level page is TikPORN. Check both contexts so all
      // long-press download paths apply the same site-specific policy.
      final isElementBoundFeedDownloadContext =
          _isElementBoundFeedPage(messagePageUrl) ||
          _isElementBoundFeedPage(_currentUrl);
      final requestedMediaType =
          mediaType == 'video'
              ? MediaType.video
              : mediaType == 'audio'
              ? MediaType.audio
              : MediaType.image;
      final activeSmartTask = _smartDownloadTask;
      final instagramMessagePath =
          Uri.tryParse(messagePageUrl)?.path.toLowerCase() ?? '';
      final instagramCurrentPath =
          Uri.tryParse(_currentUrl)?.path.toLowerCase() ?? '';
      final isInstagramReelVideoMessage =
          requestedMediaType == MediaType.video &&
          (_isInstagramPlatformPage(messagePageUrl) ||
              _isInstagramPlatformPage(_currentUrl)) &&
          (instagramMessagePath.contains('/reel') ||
              instagramCurrentPath.contains('/reel'));
      // Instagram's visible Reel is frequently covered by an IMG poster. The
      // center probe can therefore initialize an automatic task as "image"
      // even though the long-press hook correctly resolves the underlying
      // VIDEO. Promote that proven Reel video instead of rejecting it and
      // waiting for the library gate to time out.
      if (isSmartGesture &&
          activeSmartTask != null &&
          activeSmartTask['mediaType'] == MediaType.image &&
          isInstagramReelVideoMessage) {
        debugPrint(
          '[SMART_MEDIA_GATE] promote Instagram poster task image->video '
          'page=$messagePageUrl',
        );
        activeSmartTask['mediaType'] = MediaType.video;
      }
      final rejectsUnexpectedSmartMedia =
          isSmartGesture &&
          activeSmartTask != null &&
          activeSmartTask['allowMixedMedia'] != true &&
          activeSmartTask['mediaType'] is MediaType &&
          activeSmartTask['mediaType'] != requestedMediaType;
      if (action == 'download' && rejectsUnexpectedSmartMedia) {
        final expected = activeSmartTask['mediaType'] as MediaType;
        activeSmartTask['lastGestureFailureType'] =
            'unexpected_smart_media_type';
        debugPrint(
          '[SMART_MEDIA_GATE] rejected unexpected media '
          'expected=${expected.name} actual=${requestedMediaType.name} '
          'url=$urlValue page=$messagePageUrl',
        );
        // Keep the library gate closed. A thumbnail must never complete a
        // video-only item or release the recipe to slide to the next item.
        return;
      }
      if (action == 'favorite' && requestedMediaType == MediaType.video) {
        rawDownloadCandidateUrls.addAll(
          _recentCapturedMediaCandidates(
            requestedMediaType,
            pageUrl: messagePageUrl,
          ),
        );
      }
      final downloadCandidateUrls = normalizeMediaCandidateUrls(
        rawDownloadCandidateUrls,
        video: requestedMediaType == MediaType.video,
        maxCandidates:
            action == 'download'
                ? (_isFacebookPlatformPage(messagePageUrl) ||
                        _isFacebookPlatformPage(_currentUrl)
                    ? 12
                    : 4)
                : 12,
      );
      for (final candidate in downloadCandidateUrls) {
        _trustMediaCandidate(candidate);
      }
      if (urlValue is String && !isBase64) {
        _trustMediaCandidate(urlValue);
      }

      if (urlValue is! String) return;
      if (action == 'favorite') {
        final pageUrl = (data['pageUrl'] ?? '').toString().trim();
        final title = (data['title'] ?? '').toString().trim();
        final positionSec = (data['positionSec'] as num?)?.toDouble() ?? 0.0;
        final durationSec = (data['durationSec'] as num?)?.toDouble() ?? 0.0;
        final candidateUrls = List<String>.from(downloadCandidateUrls);
        final normalizedVideoUrl = _toAbsoluteUrl(urlValue);
        if (normalizedVideoUrl.isNotEmpty &&
            (_isLikelyAdUrl(normalizedVideoUrl) ||
                _looksLikePreviewClipUrl(normalizedVideoUrl))) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('检测到广告/预览片段，未加入收藏'),
                duration: Duration(milliseconds: 1200),
              ),
            );
          }
          return;
        }
        final pageKey = _normalizeUrlForKey(
          (pageUrl.isNotEmpty ? pageUrl : _currentUrl).trim(),
        );
        final videoKey =
            normalizedVideoUrl.isEmpty
                ? ''
                : _normalizeUrlForKey(normalizedVideoUrl);
        final exists = (await _loadSharedFavoriteVideos()).any((row) {
          final pk =
              (row['pageKey'] ?? '').toString().trim().isNotEmpty
                  ? (row['pageKey'] ?? '').toString().trim()
                  : _normalizeUrlForKey((row['pageUrl'] ?? '').toString());
          final vk =
              (row['videoKey'] ?? '').toString().trim().isNotEmpty
                  ? (row['videoKey'] ?? '').toString().trim()
                  : _normalizeUrlForKey((row['videoUrl'] ?? '').toString());
          if (videoKey.isNotEmpty && vk == videoKey) return true;
          if (pageKey.isNotEmpty && pk == pageKey) return true;
          return false;
        });
        if (exists) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('请勿重复收藏'),
                duration: Duration(milliseconds: 1000),
              ),
            );
          }
          final ctrl = _controller;
          if (ctrl != null) {
            unawaited(
              ctrl.evaluateJavascript(
                source:
                    "typeof updateFeedbackStatus === 'function' && updateFeedbackStatus('请勿重复收藏', false);",
              ),
            );
          }
          return;
        }
        await _addSharedFavoriteFromBrowser(
          pageUrl: pageUrl.isNotEmpty ? pageUrl : _currentUrl,
          videoUrl: normalizedVideoUrl,
          title: title,
          positionSec: positionSec,
          durationSec: durationSec,
          candidateUrls: candidateUrls,
        );
        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(
            const SnackBar(
              content: Text('已收藏当前视频'),
              duration: Duration(milliseconds: 1200),
            ),
          );
        }
        return;
      }
      if (action != 'download') return;

      // 如果是视频下载，且不是 Base64（Base64 通常是 Canvas/Recorder 生成的小文件），
      // 则强制使用稳健下载逻辑，以解决 Blob 断流或残缺问题。
      if (mediaType == 'video' && !isBase64 && !isStreamReference) {
        if (_longPressVideoDownloadInProgress) {
          if (isSmartGesture) {
            // 同一次智能长按常会连发多条 media 消息；绝不能因此清掉 pending，
            // 否则会一边下载一边继续空滚，91 详情页尤其明显。
            debugPrint(
              'Smart gesture: ignore duplicate media while download in progress',
            );
            return;
          } else if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('当前长按的视频正在保存，请勿重复长按'),
                duration: Duration(milliseconds: 1600),
              ),
            );
          }
          return;
        }
        _longPressVideoDownloadInProgress = true;
        var downloaded = false;
        var primaryVideoUrl = '';
        var candidateUrls = <String>[];
        var isFacebookDownload = false;
        try {
          final pageUrl = (data['pageUrl'] ?? '').toString().trim();
          final sourcePageUrl = (data['sourcePageUrl'] ?? '').toString().trim();
          final title = (data['title'] ?? '').toString().trim();
          candidateUrls = List<String>.from(downloadCandidateUrls);
          final normalizedPrimary = normalizeMediaCandidateUrls(
            <String>[_toAbsoluteUrl(urlValue)],
            video: true,
            maxCandidates: 1,
          );
          primaryVideoUrl =
              normalizedPrimary.isEmpty ? '' : normalizedPrimary.first;
          final isXDownload =
              _isXPlatformPage(pageUrl) || _isXPlatformPage(_currentUrl);
          isFacebookDownload =
              _isFacebookPlatformPage(pageUrl) ||
              _isFacebookPlatformPage(_currentUrl) ||
              _isFacebookCdnUrl(primaryVideoUrl);
          final expectedXMediaId =
              (data['expectedXMediaId'] ?? '').toString().trim();

          final xCandidates = await _resolveXLongPressVideoCandidates(
            primaryUrl: primaryVideoUrl,
            candidates: candidateUrls,
            pageUrl: pageUrl.isNotEmpty ? pageUrl : _currentUrl,
            expectedMediaId: expectedXMediaId,
            notBefore: sessionNotBefore,
          );
          if (isXDownload && xCandidates.isNotEmpty) {
            primaryVideoUrl = xCandidates.first;
            candidateUrls = xCandidates.skip(1).toList();
          } else if (isXDownload && expectedXMediaId.isNotEmpty) {
            primaryVideoUrl = '';
            candidateUrls = <String>[];
          } else if (isFacebookDownload) {
            final expectedFbVideoKey =
                (data['expectedFbVideoKey'] ?? data['siteMediaId'] ?? '')
                    .toString()
                    .trim();
            final isFbReels =
                data['isFacebookReels'] == true ||
                isFacebookReelsPageUrl(
                  pageUrl.isNotEmpty ? pageUrl : _currentUrl,
                ) ||
                isFacebookReelsPageUrl(sourcePageUrl);
            debugPrint(
              'FB_DL dart_recv expectedKey=$expectedFbVideoKey '
              'reels=$isFbReels primary=${primaryVideoUrl.length > 100 ? primaryVideoUrl.substring(0, 100) : primaryVideoUrl} '
              'cands=${candidateUrls.length} smart=$isSmartGesture',
            );
            final fbCandidates = await _resolveFacebookLongPressVideoCandidates(
              primaryUrl: primaryVideoUrl,
              candidates: candidateUrls,
              pageUrl: pageUrl.isNotEmpty ? pageUrl : _currentUrl,
              notBefore: sessionNotBefore,
              expectedVideoKey: expectedFbVideoKey,
              isReels: isFbReels,
            );
            if (fbCandidates.isNotEmpty) {
              primaryVideoUrl = fbCandidates.first;
              candidateUrls = fbCandidates.skip(1).toList();
            } else {
              primaryVideoUrl = '';
              candidateUrls = <String>[];
            }
            final boundKey =
                facebookMediaIdentity(primaryVideoUrl).isNotEmpty
                    ? facebookMediaIdentity(primaryVideoUrl)
                    : expectedFbVideoKey;
            debugPrint(
              'FB_DL dart_resolved boundKey=$boundKey '
              'primary=${primaryVideoUrl.length > 120 ? primaryVideoUrl.substring(0, 120) : primaryVideoUrl} '
              'n=${fbCandidates.length}',
            );
            if (boundKey.isNotEmpty && !boundKey.startsWith('reel:')) {
              final task = _smartDownloadTask;
              if (task != null &&
                  (isSmartGesture || _isSmartDemoLearningActive())) {
                task['expectedFbVideoKey'] = boundKey;
              }
            }
          }

          if (primaryVideoUrl.isEmpty && candidateUrls.isEmpty) {
            if (isSmartGesture) {
              final task = _smartDownloadTask;
              if (task != null) {
                task['lastGestureFailureType'] = 'no_direct_url';
              }
              await _completeSmartGestureDownload(false);
            } else if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(
                    isFacebookDownload
                        ? _facebookUnsupportedMediaMessage(forVideo: true)
                        : '当前仅检测到无法单独保存的视频分片，请继续播放后再长按重试',
                  ),
                  duration: Duration(seconds: isFacebookDownload ? 4 : 2),
                ),
              );
            }
            return;
          }

          final itemMap = {
            'pageUrl':
                sourcePageUrl.isNotEmpty
                    ? sourcePageUrl
                    : (pageUrl.isNotEmpty ? pageUrl : _currentUrl),
            'videoUrl': primaryVideoUrl,
            'title': title,
            'candidateUrls': candidateUrls,
            'downloadOrigin': 'long_press',
            'facebookPipeline': isFacebookDownload,
            'expectedFbVideoKey':
                facebookMediaIdentity(primaryVideoUrl).isNotEmpty
                    ? facebookMediaIdentity(primaryVideoUrl)
                    : (data['expectedFbVideoKey'] ?? data['siteMediaId'] ?? '')
                        .toString()
                        .trim(),
            'isSmartGesture': isSmartGesture || _isSmartDemoLearningActive(),
            'smartTask':
                (isSmartGesture || _isSmartDemoLearningActive())
                    ? _smartDownloadTask
                    : null,
            'sessionId': mediaSessionId,
            'durationSec': messageDurationSeconds,
          };

          downloaded = await _downloadMediaRobustly(
            item: itemMap,
            showResultHint: !isSmartGesture,
            minFileBytes:
                isFacebookDownload ? _kMinFacebookSavedVideoBytes : null,
          );
          if (isSmartGesture) {
            await _completeSmartGestureDownload(downloaded);
          }
          return;
        } finally {
          _longPressVideoDownloadInProgress = false;
          _releaseJsProcessedUrl(urlValue);
          if (primaryVideoUrl.isNotEmpty && primaryVideoUrl != urlValue) {
            _releaseJsProcessedUrl(primaryVideoUrl);
            _processedMediaUrlsSince.remove(primaryVideoUrl);
          }
          // Failed / stub saves must not soft-block a correct Reels retry.
          if (!downloaded && isFacebookDownload) {
            _clearJsProcessedMediaUrls();
            _processedMediaUrlsSince.remove(urlValue);
            for (final candidate in candidateUrls) {
              _processedMediaUrlsSince.remove(candidate);
            }
          }
        }
      }

      // Base64 不参与去重；HTTP(S) URL 带 TTL，避免 finally 未执行时永久无法重下同一链接。
      var didRegisterMediaUrl = false;
      if (!isBase64 && !isStreamReference) {
        if (!_tryRegisterMediaUrlForProcessing(urlValue)) {
          if (isSmartGesture) {
            // 同一次长按常连发多条 media；在等待入库确认时绝不能 complete，
            // 否则 Completer 提前结束 → 套路会边下边切条。
            final task = _smartDownloadTask;
            final awaitingSave =
                task != null &&
                (task['actionAwaitingLibrarySave'] == true ||
                    task['gestureDownloadPending'] == true ||
                    _hasActiveSmartBatchDownload());
            if (awaitingSave) {
              debugPrint(
                'Smart gesture: ignore duplicate media while awaiting library save',
              );
              return;
            }
            if (task != null) {
              task['lastGestureFailureType'] = 'already_downloading';
            }
            await _completeSmartGestureDownload(false);
          } else if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('该链接正在保存中，请稍候再试'),
                duration: _kMediaSaveSnackDuration,
              ),
            );
          }
          return;
        }
        didRegisterMediaUrl = true;
      }

      try {
        debugPrint(
          'Received URL from JavaScript with download action: $urlValue, type: $mediaType, isBase64: $isBase64',
        );

        if (isBase64 || isStreamReference) {
          if (isBase64 && _awaitingCanvasFallbackResult) {
            _canvasFallbackSucceeded = true;
            _canvasFallbackCompleter?.complete(true);
          }
          if (mediaType == 'video') {
            final useElementBoundDisambiguation =
                isElementBoundFeedDownloadContext;
            if (isStreamReference &&
                (_isXPlatformPage(messagePageUrl) ||
                    _isXPlatformPage(_currentUrl))) {
              final directXUrls =
                  downloadCandidateUrls
                      .where((url) => _xMediaIdentity(url).isNotEmpty)
                      .toList();
              if (directXUrls.isNotEmpty) {
                final xCandidates = await _resolveXLongPressVideoCandidates(
                  primaryUrl: directXUrls.first,
                  candidates: directXUrls.skip(1).toList(),
                  pageUrl: messagePageUrl,
                  expectedMediaId:
                      (data['expectedXMediaId'] ?? '').toString().trim(),
                  notBefore: sessionNotBefore,
                );
                if (xCandidates.isNotEmpty) {
                  final sourcePageUrl =
                      (data['sourcePageUrl'] ?? messagePageUrl)
                          .toString()
                          .trim();
                  final downloaded = await _downloadMediaRobustly(
                    item: <String, dynamic>{
                      'pageUrl':
                          sourcePageUrl.isNotEmpty
                              ? sourcePageUrl
                              : messagePageUrl,
                      'videoUrl': xCandidates.first,
                      'candidateUrls': xCandidates.skip(1).toList(),
                      'title': (data['title'] ?? '').toString(),
                      'downloadOrigin': 'long_press',
                      'isSmartGesture':
                          isSmartGesture || _isSmartDemoLearningActive(),
                      'smartTask':
                          (isSmartGesture || _isSmartDemoLearningActive())
                              ? _smartDownloadTask
                              : null,
                      'sessionId': mediaSessionId,
                      'durationSec': messageDurationSeconds,
                    },
                    showResultHint: !isSmartGesture,
                  );
                  if (isSmartGesture) {
                    await _completeSmartGestureDownload(downloaded);
                  }
                  return;
                }
              }
            }
            if (isStreamReference &&
                (_isFacebookPlatformPage(messagePageUrl) ||
                    _isFacebookPlatformPage(_currentUrl) ||
                    downloadCandidateUrls.any(_isFacebookCdnUrl))) {
              final expectedFbVideoKey =
                  (data['expectedFbVideoKey'] ?? data['siteMediaId'] ?? '')
                      .toString()
                      .trim();
              final isFbReels =
                  data['isFacebookReels'] == true ||
                  isFacebookReelsPageUrl(messagePageUrl) ||
                  isFacebookReelsPageUrl(_currentUrl);
              final fbCandidates =
                  await _resolveFacebookLongPressVideoCandidates(
                    primaryUrl:
                        downloadCandidateUrls.isNotEmpty
                            ? downloadCandidateUrls.first
                            : '',
                    candidates: downloadCandidateUrls,
                    pageUrl:
                        messagePageUrl.isNotEmpty
                            ? messagePageUrl
                            : _currentUrl,
                    notBefore: sessionNotBefore,
                    expectedVideoKey: expectedFbVideoKey,
                    isReels: isFbReels,
                  );
              if (fbCandidates.isNotEmpty) {
                final sourcePageUrl =
                    (data['sourcePageUrl'] ?? messagePageUrl).toString().trim();
                final boundKey = facebookMediaIdentity(fbCandidates.first);
                if (boundKey.isNotEmpty &&
                    !boundKey.startsWith('reel:') &&
                    (isSmartGesture || _isSmartDemoLearningActive())) {
                  _smartDownloadTask?['expectedFbVideoKey'] = boundKey;
                }
                final downloaded = await _downloadMediaRobustly(
                  item: <String, dynamic>{
                    'pageUrl':
                        sourcePageUrl.isNotEmpty
                            ? sourcePageUrl
                            : messagePageUrl,
                    'videoUrl': fbCandidates.first,
                    'candidateUrls': fbCandidates.skip(1).toList(),
                    'title': (data['title'] ?? '').toString(),
                    'downloadOrigin': 'long_press',
                    'facebookPipeline': true,
                    'expectedFbVideoKey':
                        boundKey.isNotEmpty ? boundKey : expectedFbVideoKey,
                    'isSmartGesture':
                        isSmartGesture || _isSmartDemoLearningActive(),
                    'smartTask':
                        (isSmartGesture || _isSmartDemoLearningActive())
                            ? _smartDownloadTask
                            : null,
                    'sessionId': mediaSessionId,
                    'durationSec': messageDurationSeconds,
                  },
                  showResultHint: !isSmartGesture,
                );
                if (isSmartGesture) {
                  await _completeSmartGestureDownload(downloaded);
                }
                return;
              }
              // Blob/MSE only — no recoverable progressive/playlist URL.
              if (isSmartGesture) {
                final task = _smartDownloadTask;
                if (task != null) {
                  task['lastGestureFailureType'] = 'no_direct_url';
                }
                await _completeSmartGestureDownload(false);
              } else if (mounted) {
                ScaffoldMessenger.of(context).showSnackBar(
                  SnackBar(
                    content: Text(
                      _facebookUnsupportedMediaMessage(forVideo: true),
                    ),
                    duration: const Duration(seconds: 4),
                  ),
                );
              }
              return;
            }
            final boundFragmentValue = data['boundFragments'];
            final boundFragmentUrls = <String>[];
            if (useElementBoundDisambiguation && boundFragmentValue is List) {
              for (final value in boundFragmentValue) {
                if (value is String && value.trim().isNotEmpty) {
                  boundFragmentUrls.add(value.trim());
                }
              }
            }
            if (isStreamReference &&
                (_isInstagramPlatformPage(messagePageUrl) ||
                    _isInstagramPlatformPage(_currentUrl))) {
              final instagramHandledAssetIds =
                  (_smartDownloadTask?['instagramHandledAssetIds']
                      as Set<String>?) ??
                  <String>{};
              if (_smartDownloadTask != null) {
                _smartDownloadTask!['instagramHandledAssetIds'] =
                    instagramHandledAssetIds;
              }
              final boundInstagramTracks = _selectInstagramBoundTrackCandidates(
                boundFragmentUrls,
                fallbackUrls: <String>[
                  ...downloadCandidateUrls,
                  ..._recentCapturedMediaCandidates(
                    MediaType.video,
                    pageUrl: messagePageUrl,
                    notBefore: sessionNotBefore,
                  ),
                  // Instagram can preload/cache the video half before the
                  // current long-press session, then request only audio while
                  // we observe playback. Once boundFragments identifies the
                  // exact xpv_asset_id, older requests are safe to use only as
                  // a same-asset rescue source.
                  ..._recentCapturedMediaCandidates(
                    MediaType.video,
                    pageUrl: messagePageUrl,
                    limit: 160,
                  ),
                ],
                targetDurationSeconds: messageDurationSeconds,
                excludedAssetIds:
                    isSmartGesture
                        ? instagramHandledAssetIds
                        : const <String>{},
              );
              if (boundInstagramTracks.any(
                (url) => facebookMediaMetadata(url)?.isVideoTrack == true,
              )) {
                final selectedInstagramAssetId =
                    boundInstagramTracks
                        .map(facebookMediaMetadata)
                        .whereType<FacebookMediaMetadata>()
                        .firstWhere(
                          (metadata) =>
                              metadata.isVideoTrack &&
                              metadata.videoId.isNotEmpty,
                        )
                        .videoId;
                if (_smartDownloadTask != null) {
                  _smartDownloadTask!['instagramTrackCaptureFailures'] = 0;
                }
                final downloaded = await _downloadMediaRobustly(
                  item: <String, dynamic>{
                    'pageUrl':
                        messagePageUrl.isNotEmpty
                            ? messagePageUrl
                            : _currentUrl,
                    'videoUrl': boundInstagramTracks.first,
                    // Keep the matching audio track in this list. The Instagram
                    // pipeline removes it from video attempts only after binding
                    // it to the selected video asset for muxing.
                    'candidateUrls': boundInstagramTracks,
                    'title': (data['title'] ?? '').toString(),
                    'downloadOrigin': 'long_press',
                    'isSmartGesture':
                        isSmartGesture || _isSmartDemoLearningActive(),
                    'smartTask':
                        (isSmartGesture || _isSmartDemoLearningActive())
                            ? _smartDownloadTask
                            : null,
                    'sessionId': mediaSessionId,
                    'durationSec': messageDurationSeconds,
                  },
                  showResultHint: !isSmartGesture,
                );
                if (downloaded &&
                    isSmartGesture &&
                    selectedInstagramAssetId.isNotEmpty) {
                  instagramHandledAssetIds.add(selectedInstagramAssetId);
                  debugPrint(
                    '[IG_ASSET_HANDLED] asset=$selectedInstagramAssetId '
                    'count=${instagramHandledAssetIds.length}',
                  );
                }
                if (isSmartGesture) {
                  await _completeSmartGestureDownload(downloaded);
                }
                return;
              }
              debugPrint(
                '[IG_BOUND] current asset has no recoverable video track; '
                'refusing unrelated fallback',
              );
              if (mounted && !isSmartGesture) {
                if (!_instagramManualTrackRecoveryInProgress) {
                  _instagramManualTrackRecoveryInProgress = true;
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('正在加速获取当前视频轨，并自动重试下载…'),
                      duration: Duration(seconds: 2),
                    ),
                  );
                  unawaited(() async {
                    // Let the failed blob message finish and release its
                    // processing key before the automatic manual retry.
                    await Future<void>.delayed(
                      const Duration(milliseconds: 180),
                    );
                    try {
                      final raw = await _controller?.evaluateJavascript(
                        source:
                            'window.__appRecoverInstagramManualVideoTrack'
                            ' ? window.__appRecoverInstagramManualVideoTrack()'
                            " : ({ok:false,reason:'hook_missing'})",
                      );
                      debugPrint('[IG_MANUAL_TRACK_RECOVERY] $raw');
                    } catch (e) {
                      debugPrint('[IG_MANUAL_TRACK_RECOVERY] failed: $e');
                    }
                    // Keep the guard closed while the delayed JS retry posts
                    // its result, preventing an automatic retry loop.
                    await Future<void>.delayed(const Duration(seconds: 4));
                    _instagramManualTrackRecoveryInProgress = false;
                  }());
                } else {
                  ScaffoldMessenger.of(context).showSnackBar(
                    const SnackBar(
                      content: Text('视频轨仍在获取中，请稍候再长按一次'),
                      duration: Duration(seconds: 3),
                    ),
                  );
                }
              }
              if (isSmartGesture) {
                final smartTask = _smartDownloadTask;
                if (smartTask != null) {
                  final captureFailures =
                      ((smartTask['instagramTrackCaptureFailures'] as int?) ??
                          0) +
                      1;
                  smartTask['instagramTrackCaptureFailures'] = captureFailures;
                  smartTask['lastGestureFailureType'] =
                      'instagram_current_track_not_captured';
                  _showSmartOperation(
                    '当前视频轨尚未捕获，继续播放后重试（$captureFailures/8）',
                    point: const Offset(0.5, 0.46),
                  );
                }
                await _completeSmartGestureDownload(false);
              }
              return;
            }
            final boundStreamCandidates =
                normalizeMediaCandidateUrls(
                  boundFragmentUrls,
                  video: true,
                  maxCandidates: 8,
                ).where((candidate) {
                  return !_looksLikeMediaFragmentUrl(candidate) &&
                      _isLikelyDirectMediaUrl(candidate);
                }).toList();
            if (boundStreamCandidates.isNotEmpty) {
              // These URLs were consumed by the exact MediaSource attached to
              // the long-pressed video, so they outrank every page-level sniff.
              final selectedManifest = boundStreamCandidates.first;
              final downloaded = await _downloadMediaRobustly(
                item: <String, dynamic>{
                  'pageUrl': _currentUrl,
                  'videoUrl': selectedManifest,
                  'candidateUrls': boundStreamCandidates,
                  'title': (data['title'] ?? '').toString(),
                  'downloadOrigin': 'long_press',
                  'isSmartGesture':
                      isSmartGesture || _isSmartDemoLearningActive(),
                  'smartTask':
                      (isSmartGesture || _isSmartDemoLearningActive())
                          ? _smartDownloadTask
                          : null,
                  'sessionId': mediaSessionId,
                  'durationSec': messageDurationSeconds,
                },
                showResultHint: !isSmartGesture,
              );
              if (isSmartGesture) {
                await _completeSmartGestureDownload(downloaded);
              }
              return;
            }
            final boundDashCandidates =
                normalizeMediaCandidateUrls(
                  boundFragmentUrls,
                  video: true,
                  maxCandidates: 8,
                ).where((candidate) {
                  return Uri.tryParse(
                        candidate,
                      )?.path.toLowerCase().endsWith('.mpd') ??
                      false;
                }).toList();
            final activeDashCandidates =
                useElementBoundDisambiguation
                    ? _recentActiveDashManifestCandidates(
                      pageUrl: messagePageUrl,
                      notBefore: sessionNotBefore,
                    )
                    : const <String>[];
            final capturedDashCandidates =
                _recentCapturedMediaCandidates(
                  MediaType.video,
                  pageUrl: messagePageUrl,
                  notBefore: sessionNotBefore,
                ).where((candidate) {
                  final path =
                      Uri.tryParse(candidate)?.path.toLowerCase() ?? '';
                  return path.endsWith('.mpd');
                }).toList();
            final dashCandidates = <String>[
              ...boundDashCandidates,
              ...activeDashCandidates.where(
                (candidate) => !boundDashCandidates.contains(candidate),
              ),
              ...capturedDashCandidates.where(
                (candidate) =>
                    !boundDashCandidates.contains(candidate) &&
                    !activeDashCandidates.contains(candidate),
              ),
            ];
            if (dashCandidates.isNotEmpty) {
              // 当前播放会持续产生分片请求；下一条通常仅预加载 MPD/少量分片。
              final selectedManifest =
                  boundDashCandidates.isNotEmpty
                      ? boundDashCandidates.first
                      : useElementBoundDisambiguation
                      ? await _selectDashManifestForLongPress(
                        dashCandidates,
                        targetDurationSeconds: messageDurationSeconds,
                      )
                      : dashCandidates.first;
              if (selectedManifest == null) {
                if (isSmartGesture) {
                  final task = _smartDownloadTask;
                  if (task != null) {
                    task['lastGestureFailureType'] = 'no_direct_url';
                  }
                  await _completeSmartGestureDownload(false);
                }
                return;
              }
              final downloaded = await _downloadMediaRobustly(
                item: <String, dynamic>{
                  'pageUrl': _currentUrl,
                  'videoUrl': selectedManifest,
                  'candidateUrls': <String>[
                    selectedManifest,
                    ...dashCandidates.where(
                      (candidate) => candidate != selectedManifest,
                    ),
                  ],
                  'title': (data['title'] ?? '').toString(),
                  'downloadOrigin': 'long_press',
                  'isSmartGesture':
                      isSmartGesture || _isSmartDemoLearningActive(),
                  'smartTask':
                      (isSmartGesture || _isSmartDemoLearningActive())
                          ? _smartDownloadTask
                          : null,
                  'sessionId': mediaSessionId,
                  'durationSec': messageDurationSeconds,
                },
                showResultHint: !isSmartGesture,
              );
              if (isSmartGesture) {
                await _completeSmartGestureDownload(downloaded);
              }
              return;
            }
          }
          if (isStreamReference) {
            if (isSmartGesture) {
              final task = _smartDownloadTask;
              // 流引用只是「还没抓到完整地址」：入库闸门打开时绝不能 complete，
              // 否则 Completer 提前结束 → waitDownload 只剩文案 → findNext 抢跑切条。
              final awaitingSave =
                  task != null &&
                  (task['actionAwaitingLibrarySave'] == true ||
                      task['actionLongPressNeedsConfirm'] == true ||
                      task['gestureDownloadPending'] == true);
              if (awaitingSave) {
                debugPrint(
                  'Smart gesture: ignore stream reference while awaiting library save',
                );
                return;
              }
              task?['lastGestureFailureType'] = 'no_direct_url';
              await _completeSmartGestureDownload(false);
            }
            if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(
                  content: Text('尚未捕获当前视频的完整下载地址，请继续播放几秒后重试'),
                  duration: Duration(seconds: 2),
                ),
              );
            }
            return;
          }
          if (isSmartGesture) {
            _mediaDownloadSaveResolved = false;
          }
          await _handleBlobUrl(
            urlValue,
            mediaType,
            sourceMimeType: sourceMimeType,
          );
          if (isSmartGesture) {
            final task = _smartDownloadTask;
            if (task != null &&
                !_mediaDownloadSaveResolved &&
                (task['lastGestureFailureType'] ?? '').toString().isEmpty) {
              // blob/base64 路径未写入 failureType 时，空 failure 会被
              // suppressEarlyComplete 当成噪声压制，导致入库闸门永不关闭。
              task['lastGestureFailureType'] = 'download_failed_retryable';
            }
            await _completeSmartGestureDownload(_mediaDownloadSaveResolved);
          }
          return;
        }

        _mediaDownloadFailHintTimer?.cancel();
        _mediaDownloadSaveResolved = false;

        final absoluteUrl = _toAbsoluteUrl(urlValue);
        final referer = _getMediaReferer(absoluteUrl);
        final resolvedUrl = await _resolveFinalUrl(
          urlValue,
          headers: {
            'Referer': referer,
            'User-Agent':
                'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Mobile Safari/537.36',
            'Accept': '*/*',
          },
        );
        _trustMediaCandidate(resolvedUrl);
        final mimeType = _guessMimeType(resolvedUrl);
        MediaType selectedType = _determineMediaType(mimeType);
        if (mimeType == 'application/octet-stream') {
          selectedType = requestedMediaType;
        }
        if (selectedType == MediaType.image &&
            _urlLooksLikeVideoStream(resolvedUrl)) {
          selectedType = MediaType.video;
        }
        if (selectedType == MediaType.video) {
          // 智能手势/动作编排/Facebook：禁止 URL+磁盘预跳过（签名 URL 易误绑邻条后
          // 再弹「重复」，而当前条其实未入库）。仅入库后内容哈希可 already_in_library。
          final existing = await _findExistingVideoBeforeDownload(resolvedUrl);
          if (existing != null) {
            final onFacebook =
                _isFacebookPlatformPage(_currentUrl) ||
                _isFacebookCdnUrl(resolvedUrl) ||
                _isFacebookPlatformPage(
                  (data['pageUrl'] ?? data['sourcePageUrl'] ?? '').toString(),
                );
            if (isSmartGesture || onFacebook) {
              debugPrint(
                'FB_DL ignore source-map pre-skip '
                'smart=$isSmartGesture fb=$onFacebook '
                'url=${resolvedUrl.length > 100 ? resolvedUrl.substring(0, 100) : resolvedUrl}',
              );
            } else if (!await _confirmSourceUrlDuplicateBeforeDownload(
              existing,
            )) {
              return;
            }
          }
        }
        final canCanvasFallback = selectedType == MediaType.image;
        final attempts = <String>[];
        final seenAttempts = <String>{};
        void pushAttempt(String? candidate) {
          if (candidate == null) return;
          final absolute = _toAbsoluteUrl(candidate.trim());
          if (absolute.isEmpty ||
              seenAttempts.contains(absolute) ||
              (_isApiEndpointUrl(absolute) &&
                  !_isTrustedMediaCandidate(absolute)) ||
              absolute.startsWith('blob:') ||
              absolute.startsWith('data:')) {
            return;
          }
          if (selectedType == MediaType.image &&
              _urlLooksLikeVideoStream(absolute)) {
            return;
          }
          seenAttempts.add(absolute);
          attempts.add(absolute);
        }

        pushAttempt(resolvedUrl);
        for (final candidate in downloadCandidateUrls) {
          pushAttempt(candidate);
        }
        if (selectedType == MediaType.image &&
            (_isFacebookPlatformPage(messagePageUrl) ||
                _isFacebookPlatformPage(_currentUrl) ||
                _isFacebookCdnUrl(resolvedUrl))) {
          final fbImageAttempts = <String>[];
          final fbSeen = <String>{};
          void pushFbImage(String? raw) {
            final normalized = _normalizeFacebookMediaCandidate(
              raw ?? '',
              video: false,
            );
            if (normalized == null || !fbSeen.add(normalized)) return;
            fbImageAttempts.add(normalized);
          }

          pushFbImage(resolvedUrl);
          for (final candidate in downloadCandidateUrls) {
            pushFbImage(candidate);
          }
          for (final candidate in _recentCapturedMediaCandidates(
            MediaType.image,
            pageUrl: messagePageUrl,
            notBefore: sessionNotBefore,
            limit: 24,
          )) {
            if (_isFacebookCdnUrl(candidate) ||
                candidate.toLowerCase().contains('scontent')) {
              pushFbImage(candidate);
            }
          }
          fbImageAttempts.sort(
            (a, b) => _scoreFacebookImageCandidate(
              b,
            ).compareTo(_scoreFacebookImageCandidate(a)),
          );
          attempts
            ..clear()
            ..addAll(fbImageAttempts);
          seenAttempts
            ..clear()
            ..addAll(fbImageAttempts);
        }
        final maxImageAttempts =
            selectedType == MediaType.image &&
                    (_isFacebookPlatformPage(messagePageUrl) ||
                        _isFacebookPlatformPage(_currentUrl))
                ? 8
                : 3;
        if (attempts.length > maxImageAttempts) {
          attempts.removeRange(maxImageAttempts, attempts.length);
        }
        if (selectedType == MediaType.image &&
            attempts.isEmpty &&
            (_isFacebookPlatformPage(messagePageUrl) ||
                _isFacebookPlatformPage(_currentUrl) ||
                _isFacebookCdnUrl(resolvedUrl))) {
          if (isSmartGesture) {
            final task = _smartDownloadTask;
            if (task != null) {
              task['lastGestureFailureType'] = 'no_direct_url';
            }
            await _completeSmartGestureDownload(false);
          } else if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              SnackBar(
                content: Text(
                  _facebookUnsupportedMediaMessage(forVideo: false),
                ),
                duration: const Duration(seconds: 3),
              ),
            );
          }
          return;
        }
        var success = false;
        var lastFailureType = 'unknown';
        for (var i = 0; i < attempts.length; i++) {
          var failureType = 'unknown';
          success = await _performBackgroundDownload(
            attempts[i],
            selectedType,
            skipFailurePrompt: canCanvasFallback || i < attempts.length - 1,
            inactivityTimeout:
                selectedType == MediaType.image
                    ? const Duration(seconds: 45)
                    : const Duration(minutes: 2),
            maxRequestAttempts: 4,
            showSuccessPrompt: !isSmartGesture,
            showDuplicatePrompt: !isSmartGesture,
            validateSmartMedia: isSmartGesture,
            isSmartBatchMedia: isSmartGesture,
            smartTask: isSmartGesture ? _smartDownloadTask : null,
            smartMediaTitle: (data['title'] ?? '').toString(),
            smartPageUrl: messagePageUrl,
            onFailureType: (type) => failureType = type,
          );
          lastFailureType = failureType;
          if (success) break;
          if (failureType == 'library_save_failed' ||
              failureType == 'already_in_library' ||
              failureType == 'cancelled') {
            break;
          }
        }
        if (success) {
          _notifyMediaDownloadSaved();
          if (isSmartGesture) {
            await _completeSmartGestureDownload(true);
          }
        } else if (!success &&
            canCanvasFallback &&
            lastFailureType != 'already_in_library' &&
            lastFailureType != 'cancelled' &&
            mounted) {
          try {
            final ctrl = _controller;
            if (ctrl != null) {
              _awaitingCanvasFallbackResult = true;
              _canvasFallbackSucceeded = false;
              _canvasFallbackCompleter = Completer<bool>();
              await ctrl.evaluateJavascript(
                source:
                    'typeof tryCanvasCaptureFallback === "function" && tryCanvasCaptureFallback();',
              );
              final canvasSucceeded = await _canvasFallbackCompleter!.future
                  .timeout(
                    const Duration(seconds: 5),
                    onTimeout: () {
                      if (!_canvasFallbackCompleter!.isCompleted) {
                        _canvasFallbackCompleter!.complete(false);
                      }
                      return false;
                    },
                  );
              var recovered = canvasSucceeded;
              if (!canvasSucceeded && selectedType == MediaType.image) {
                recovered = await _tryScreenshotFallback(ctrl) || recovered;
              }
              _awaitingCanvasFallbackResult = false;
              _canvasFallbackCompleter = null;
              // canvas 成功仅表示已取得像素/base64，真正落盘在 _handleBlobUrl；此处不 _notify，避免与失败提示打架
              // 极晚到的 base64 仍可能随后触发 _handleBlobUrl 并成功，故用短延迟再提示失败，避免与成功条打架。
              if (!recovered &&
                  canCanvasFallback &&
                  !_mediaDownloadSaveResolved &&
                  mounted) {
                if (!isSmartGesture) {
                  _mediaDownloadFailHintTimer?.cancel();
                  _mediaDownloadFailHintTimer = Timer(
                    const Duration(seconds: 2),
                    () {
                      if (!mounted || _mediaDownloadSaveResolved) return;
                      ScaffoldMessenger.of(context).showSnackBar(
                        SnackBar(
                          content: Text(
                            _downloadErrorForUser(
                              Exception('[下载失败] 无法保存该媒体，请稍后重试或长按图片本身'),
                            ),
                          ),
                          duration: _kMediaSaveSnackDuration,
                        ),
                      );
                    },
                  );
                }
              }
              if (isSmartGesture) {
                final task = _smartDownloadTask;
                if (task != null &&
                    !_mediaDownloadSaveResolved &&
                    (task['lastGestureFailureType'] ?? '').toString().isEmpty) {
                  task['lastGestureFailureType'] = 'download_failed_retryable';
                }
                await _completeSmartGestureDownload(_mediaDownloadSaveResolved);
              }
            }
          } catch (_) {
            _awaitingCanvasFallbackResult = false;
            _canvasFallbackCompleter = null;
            if (canCanvasFallback && !_mediaDownloadSaveResolved && mounted) {
              if (isSmartGesture) {
                final task = _smartDownloadTask;
                if (task != null) {
                  task['lastGestureFailureType'] = lastFailureType;
                }
                await _completeSmartGestureDownload(false);
              } else {
                _mediaDownloadFailHintTimer?.cancel();
                _mediaDownloadFailHintTimer = Timer(
                  const Duration(seconds: 2),
                  () {
                    if (!mounted || _mediaDownloadSaveResolved) return;
                    ScaffoldMessenger.of(context).showSnackBar(
                      SnackBar(
                        content: Text(
                          _downloadErrorForUser(Exception('[下载失败] 无法保存该媒体')),
                        ),
                        duration: _kMediaSaveSnackDuration,
                      ),
                    );
                  },
                );
              }
            }
          }
        } else if (isSmartGesture) {
          final task = _smartDownloadTask;
          if (task != null) {
            task['lastGestureFailureType'] = lastFailureType;
          }
          await _completeSmartGestureDownload(false);
        }
      } finally {
        if (didRegisterMediaUrl || isStreamReference) {
          _processedMediaUrlsSince.remove(urlValue);
          _releaseJsProcessedUrl(urlValue);
        }
      }
    } catch (e, stackTrace) {
      debugPrint('Error handling JavaScript message: $e');
      debugPrint('Trace: $stackTrace');
      final task = _smartDownloadTask;
      if (task != null && task['gestureDownloadPending'] == true) {
        task['lastGestureFailureType'] = 'handler_exception';
        await _completeSmartGestureDownload(false);
      }
    }
  }

  Future<void> _handleBlobUrl(
    String base64Data,
    String mediaType, {
    String? sourceMimeType,
  }) async {
    File? outputFile;
    try {
      debugPrint('处理Base64数据以直接保存: $mediaType');
      String raw = base64Data.trim();
      String dataUrlMime = '';
      if (raw.startsWith('data:')) {
        final base64Idx = raw.indexOf(';base64,');
        if (base64Idx >= 0) {
          dataUrlMime = raw.substring(5, base64Idx).split(';').first.trim();
          raw = raw.substring(base64Idx + 8);
        } else {
          final commaIdx = raw.indexOf(',');
          if (commaIdx < 0 || commaIdx >= raw.length - 1) {
            if (mounted)
              ScaffoldMessenger.of(context).showSnackBar(
                const SnackBar(content: Text('Base64数据格式错误：data URL缺少有效内容')),
              );
            return;
          }
          dataUrlMime = raw.substring(5, commaIdx).split(';').first.trim();
          raw = raw.substring(commaIdx + 1);
        }
      }
      raw = raw.replaceAll(RegExp(r'[\s\r\n]'), '');
      if (raw.isEmpty || raw.length < 10) {
        if (mounted)
          ScaffoldMessenger.of(
            context,
          ).showSnackBar(const SnackBar(content: Text('Base64数据为空或过短')));
        return;
      }
      List<int> bytes;
      try {
        bytes = base64Decode(raw);
      } catch (_) {
        try {
          bytes = base64Url.decode(raw);
        } catch (e2) {
          if (mounted)
            ScaffoldMessenger.of(
              context,
            ).showSnackBar(SnackBar(content: Text('Base64解码失败: $e2')));
          return;
        }
      }
      final effectiveMime =
          (sourceMimeType != null && sourceMimeType.trim().isNotEmpty)
              ? sourceMimeType.trim()
              : dataUrlMime;
      final normalizedMediaType = mediaType.toLowerCase().trim();
      String? detectedExtension;
      if (normalizedMediaType == 'video') {
        if (bytes.length < _kMinBase64VideoBytes) {
          final smartTask = _smartDownloadTask;
          if (smartTask != null &&
              (smartTask['gestureDownloadPending'] == true ||
                  smartTask['actionAwaitingLibrarySave'] == true ||
                  smartTask['actionLongPressNeedsConfirm'] == true)) {
            smartTask['lastGestureFailureType'] = 'invalid_smart_media_content';
          }
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('视频数据不完整，未保存到媒体库'),
                duration: _kMediaSaveSnackDuration,
              ),
            );
          }
          return;
        }
        detectedExtension = _detectVideoExtension(bytes);
        if (detectedExtension == null) {
          final smartTask = _smartDownloadTask;
          if (smartTask != null &&
              (smartTask['gestureDownloadPending'] == true ||
                  smartTask['actionAwaitingLibrarySave'] == true ||
                  smartTask['actionLongPressNeedsConfirm'] == true)) {
            smartTask['lastGestureFailureType'] = 'invalid_smart_media_content';
          }
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('保存的内容不是有效视频，未保存到媒体库'),
                duration: _kMediaSaveSnackDuration,
              ),
            );
          }
          return;
        }
      } else if (normalizedMediaType == 'image') {
        detectedExtension = _detectImageExtension(bytes);
        if (detectedExtension == null) {
          final smartTask = _smartDownloadTask;
          if (smartTask != null &&
              (smartTask['gestureDownloadPending'] == true ||
                  smartTask['actionAwaitingLibrarySave'] == true ||
                  smartTask['actionLongPressNeedsConfirm'] == true)) {
            smartTask['lastGestureFailureType'] = 'invalid_smart_media_content';
          }
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('保存的内容不是有效图片，未保存到媒体库'),
                duration: _kMediaSaveSnackDuration,
              ),
            );
          }
          return;
        }
      }
      final appDir = await getApplicationDocumentsDirectory();
      final mediaDir = Directory('${appDir.path}/media');
      if (!await mediaDir.exists()) await mediaDir.create(recursive: true);
      final uuid = const Uuid().v4();
      String extension = _extensionForBase64Media(
        normalizedMediaType,
        effectiveMime,
      );
      extension = detectedExtension ?? extension;
      final filePath = '${mediaDir.path}/$uuid$extension';
      final file = File(filePath);
      outputFile = file;
      await file.writeAsBytes(bytes);
      debugPrint('已从Base64保存文件: $filePath');
      if (normalizedMediaType == 'video') {
        final durationMs = await _probeNativeVideoDurationMs(file);
        if (durationMs != null && durationMs <= 0) {
          await file.delete();
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(
                content: Text('网页录制的视频缺少有效时长，已放弃保存；请播放视频后重新长按下载'),
                duration: Duration(seconds: 3),
              ),
            );
          }
          return;
        }
      }
      await _saveToMediaLibrary(
        file,
        normalizedMediaType == 'image'
            ? MediaType.image
            : (normalizedMediaType == 'audio'
                ? MediaType.audio
                : MediaType.video),
        allowDuplicate: false,
        relaxValidation: false,
      );
      _notifyMediaDownloadSaved();
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('已保存到媒体库：${file.path.split('/').last}'),
            duration: _kMediaSaveSnackDuration,
            action: SnackBarAction(
              label: '查看',
              onPressed:
                  () => Navigator.of(context).push(
                    MaterialPageRoute(
                      builder:
                          (context) =>
                              const MediaManagerPage(showRouteBackButton: true),
                    ),
                  ),
            ),
          ),
        );
      }
    } on _ExistingMediaDuplicateException catch (e) {
      try {
        if (outputFile != null && await outputFile.exists()) {
          await outputFile.delete();
        }
      } catch (_) {}
      await _showMediaDuplicateDialog(e.existingRow);
    } catch (e, stackTrace) {
      debugPrint('处理Base64数据时出错: $e');
      debugPrint('错误堆栈: $stackTrace');
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('下载失败: $e'),
            duration: _kMediaSaveSnackDuration,
          ),
        );
      }
    }
  }

  /// If navigation hits dead Google `/m`, return replacement URL; else null.
  String? _rewriteDeadGoogleMobileNavigation(String url) {
    if (!BrowserService.isDeadGoogleMobileUrl(url)) return null;
    final fixed = BrowserService.normalizeCommonWebsiteUrl(url);
    if (fixed.isEmpty || fixed == url) {
      return BrowserService.kGoogleHomeUrl;
    }
    return fixed;
  }

  void _loadUrl(String url) {
    // Only fix known dead Google /m shortcuts; never rewrite user .hk / query URLs.
    final processedUrl = BrowserService.prepareUrlForLoad(url);
    // 智能下载期间禁止任何跨站页面跳转（含程序主动 _loadUrl，不只靠 WebView 拦截）。
    if (_smartDownloadTask != null &&
        !_isWithinSmartDownloadSite(processedUrl)) {
      debugPrint('智能下载禁止跨站导航: $processedUrl');
      final task = _smartDownloadTask!;
      task['matchStage'] = '已阻止跨站跳转';
      _showSmartOperation('已阻止跳出当前网站，继续在本站内下载');
      final id = (task['discoveryTaskId'] ?? '').toString();
      if (id.isNotEmpty) {
        _updateDownloadTask(
          id,
          progressDetail:
              '已阻止外部网站跳转，继续在当前网站内寻找 · 已保存 ${task['success']}/${task['target']}',
        );
      }
      return;
    }
    final uri = Uri.tryParse(processedUrl);
    if (uri != null) {
      _controller?.loadUrl(urlRequest: URLRequest(url: WebUri(processedUrl)));
    } else {
      if (mounted) {
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text('无效的URL: $processedUrl')));
      }
      return;
    }
    setState(() {
      _showHomePage = false;
      _currentUrl = processedUrl;
      _urlController.text = processedUrl;
      _isBrowsingWebPage = true;
      _shouldKeepWebPageState = true;
      _lastBrowsedUrl = processedUrl;
    });
    _rememberLastBrowsingUrl(processedUrl);
    widget.onBrowserHomePageChanged?.call(_showHomePage);
    _syncBrowserSessionPreview();
  }

  bool _isWithinSmartDownloadSite(String url) {
    final task = _smartDownloadTask;
    if (task == null) return true;
    final uri = Uri.tryParse(url);
    if (uri == null || !(uri.scheme == 'http' || uri.scheme == 'https')) {
      // about:blank / data / blob 等非网页导航不视为跨站。
      return true;
    }
    final targetHost = uri.host.toLowerCase().replaceFirst(
      RegExp(r'^www\.'),
      '',
    );
    final siteHost = (task['host'] ?? '').toString().toLowerCase().replaceFirst(
      RegExp(r'^www\.'),
      '',
    );
    if (targetHost.isEmpty || siteHost.isEmpty) return false;
    // 用站点根域判断，避免 www/m 子域误伤；同时禁止完全不同的外站。
    return _sameSmartSite(targetHost, siteHost);
  }

  /// 智能下载中若已落到外站，强制拉回本站入口。
  Future<bool> _recoverSmartDownloadIfOffsite(
    Map<String, dynamic> task,
    String actualLoadedUrl, {
    String reason = '检测到已离开当前网站',
  }) async {
    final taskHost = (task['host'] ?? '').toString();
    final actualHost =
        Uri.tryParse(
          actualLoadedUrl,
        )?.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '') ??
        '';
    if (actualHost.isEmpty ||
        taskHost.isEmpty ||
        _sameSmartSite(actualHost, taskHost)) {
      return false;
    }
    final siteUrl = (task['siteUrl'] ?? '').toString();
    final originUrl = (task['originUrl'] ?? '').toString();
    final strict91 = (task['strict91SearchUrl'] ?? '').toString();
    final strictX = (task['strictXSearchUrl'] ?? '').toString();
    final strictBaidu = (task['strictBaiduSearchUrl'] ?? '').toString();
    var recovery = '';
    if (strict91.isNotEmpty) {
      recovery = strict91;
    } else if (strictX.isNotEmpty) {
      recovery = strictX;
    } else if (strictBaidu.isNotEmpty) {
      recovery = strictBaidu;
    } else if (originUrl.startsWith('http') &&
        _isWithinSmartDownloadSite(originUrl)) {
      recovery = originUrl;
    } else if (siteUrl.startsWith('http')) {
      recovery = siteUrl;
    }
    task['matchStage'] = reason;
    _showSmartOperation('$reason，已拉回本站继续');
    debugPrint('Smart offsite recovery: from=$actualLoadedUrl to=$recovery');
    if (recovery.isNotEmpty) {
      // 临时清任务拦截会导致递归；recovery 已保证同站，直接 load。
      final processed =
          recovery.startsWith('http') ? recovery : 'https://$recovery';
      _controller?.loadUrl(urlRequest: URLRequest(url: WebUri(processed)));
      if (mounted) {
        setState(() {
          _currentUrl = processed;
          _urlController.text = processed;
        });
      }
    }
    return true;
  }

  Future<void> _goToHomePage() async {
    if (!_showHomePage) {
      // Only persist after first successful load — never write defaults over
      // user-stored .hk / query bookmarks during the startup race.
      if (_commonWebsitesLoaded) {
        await _saveCommonWebsites();
      }
      await _loadBookmarks();

      // 确保常用网站列表被正确加载（缺省数据只在 load 内写入，不在此处塞默认 Google）
      await _loadCommonWebsites();

      // 回主页不销毁 WebView，但后退栈从「主页再出发」更干净。
      _clearWebBackStack();
      setState(() => _showHomePage = true);
      widget.onBrowserHomePageChanged?.call(_showHomePage);
      _syncBrowserSessionPreview();
    }
  }

  bool _isBlankHistoryUrl(String? u) {
    if (u == null || u.trim().isEmpty) return true;
    final s = u.trim().toLowerCase();
    return s == 'about:blank' ||
        s.startsWith('about:blank#') ||
        s == 'about://blank' ||
        s.startsWith('about:srcdoc');
  }

  /// 用于后退栈 / 劫持判断：去掉 fragment，保留 host/path/query。
  String _navIdentityKey(String url) {
    final trimmed = url.trim();
    if (trimmed.isEmpty) return '';
    final uri = Uri.tryParse(trimmed);
    if (uri == null) return trimmed.split('#').first;
    return uri.replace(fragment: '').toString();
  }

  String _navHostPathKey(String url) {
    final uri = Uri.tryParse(url.trim());
    if (uri == null) return _navIdentityKey(url);
    final host = uri.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    return '$host${uri.path}';
  }

  void _clearWebBackStack() {
    _webBackStack.clear();
    _webBackStackCurrent = null;
    _historyLikelyHijacked = false;
    _navSpamPathKey = null;
    _navSpamWindowStart = null;
    _navSpamCount = 0;
  }

  void _observeUrlForHistorySpam(String url) {
    if (!url.startsWith('http://') && !url.startsWith('https://')) return;
    final pathKey = _navHostPathKey(url);
    if (pathKey.isEmpty) return;
    final now = DateTime.now();
    if (_navSpamPathKey == pathKey &&
        _navSpamWindowStart != null &&
        now.difference(_navSpamWindowStart!) < const Duration(seconds: 2)) {
      _navSpamCount++;
      if (_navSpamCount >= 4) {
        _historyLikelyHijacked = true;
      }
    } else {
      _navSpamPathKey = pathKey;
      _navSpamWindowStart = now;
      _navSpamCount = 1;
    }
  }

  /// 记录有意义的页面（忽略 hash / 重复 URL），供 WebView history 被污染时逃生。
  /// [fromHistoryUpdate] 为 true 时：同 host+path 的 query 刷屏只用于劫持检测，不入栈。
  void _noteMeaningfulWebNavigation(
    String url, {
    bool fromHistoryUpdate = false,
  }) {
    if (_webBackNavigating) return;
    if (_isBlankHistoryUrl(url)) return;
    if (!url.startsWith('http://') && !url.startsWith('https://')) return;
    final key = _navIdentityKey(url);
    if (key.isEmpty) return;
    _observeUrlForHistorySpam(url);
    if (_webBackStackCurrent == null) {
      _webBackStackCurrent = key;
      return;
    }
    if (_webBackStackCurrent == key) return;
    final sameShell =
        _navHostPathKey(_webBackStackCurrent!) == _navHostPathKey(key);
    // pushState / 同壳 query 垃圾：不污染干净后退栈。
    if (sameShell && (fromHistoryUpdate || _historyLikelyHijacked)) {
      if (!fromHistoryUpdate) {
        _webBackStackCurrent = key;
      }
      return;
    }
    _webBackStack.add(_webBackStackCurrent!);
    if (_webBackStack.length > _kWebBackStackMax) {
      _webBackStack.removeAt(0);
    }
    _webBackStackCurrent = key;
  }

  void _syncWebBackStackAfterEscape(String landedUrl) {
    final key = _navIdentityKey(landedUrl);
    if (key.isEmpty || _isBlankHistoryUrl(landedUrl)) return;
    _webBackStackCurrent = key;
    while (_webBackStack.isNotEmpty &&
        _navIdentityKey(_webBackStack.last) == key) {
      _webBackStack.removeLast();
    }
    if (_navHostPathKey(landedUrl) != _navSpamPathKey) {
      _historyLikelyHijacked = false;
      _navSpamCount = 0;
    }
  }

  bool _isStillOnTrappedPage(String beforeUrl, String afterUrl) {
    if (_isBlankHistoryUrl(afterUrl)) return true;
    final beforeId = _navIdentityKey(beforeUrl);
    final afterId = _navIdentityKey(afterUrl);
    if (beforeId.isNotEmpty && beforeId == afterId) return true;
    // 劫持场景：goBack 只在同壳页面的 query/hash 垃圾项之间挪动。
    if (_historyLikelyHijacked &&
        _navHostPathKey(beforeUrl) == _navHostPathKey(afterUrl)) {
      return true;
    }
    return false;
  }

  bool _isUsableBackTarget(String candidate, String stuckUrl) {
    if (candidate.isEmpty || _isBlankHistoryUrl(candidate)) return false;
    if (!candidate.startsWith('http://') && !candidate.startsWith('https://')) {
      return false;
    }
    final stuckKey = _navIdentityKey(stuckUrl);
    final stuckPath = _navHostPathKey(stuckUrl);
    if (stuckKey.isNotEmpty && _navIdentityKey(candidate) == stuckKey) {
      return false;
    }
    // 劫持时跳过与困页同壳的垃圾项，保留搜索结果等真正上一页。
    if (_historyLikelyHijacked &&
        stuckPath.isNotEmpty &&
        _navHostPathKey(candidate) == stuckPath) {
      return false;
    }
    return true;
  }

  Future<String?> _popWebBackStackTarget(String stuckUrl) async {
    while (_webBackStack.isNotEmpty) {
      final candidate = _webBackStack.removeLast();
      if (!_isUsableBackTarget(candidate, stuckUrl)) continue;
      _webBackStackCurrent = candidate;
      return candidate;
    }
    _webBackStackCurrent = null;
    return null;
  }

  /// 栈被清空或未记上时，用本会话浏览轨迹找回上一有意义页（如百度搜索结果）。
  String? _fallbackPreviousFromSessionTrail(String stuckUrl) {
    final stuckKey = _navIdentityKey(stuckUrl);
    for (final row in _sessionPageTrail) {
      final u = (row['url'] ?? '').toString().trim();
      if (!_isUsableBackTarget(u, stuckUrl)) continue;
      // 轨迹最新在前：第一条常是当前困页，已在 usable 检查里跳过。
      if (stuckKey.isNotEmpty && _navIdentityKey(u) == stuckKey) continue;
      return _navIdentityKey(u);
    }
    return null;
  }

  Future<String?> _resolveWebBackEscapeTarget(String stuckUrl) async {
    final fromStack = await _popWebBackStackTarget(stuckUrl);
    if (fromStack != null && fromStack.isNotEmpty) return fromStack;
    final fromTrail = _fallbackPreviousFromSessionTrail(stuckUrl);
    if (fromTrail != null && fromTrail.isNotEmpty) {
      _webBackStackCurrent = fromTrail;
      return fromTrail;
    }
    return null;
  }

  Future<void> _loadWebBackEscapeUrl(
    InAppWebViewController c,
    String url,
  ) async {
    if (_isBlankHistoryUrl(url)) return;
    _webBackNavigating = true;
    try {
      // loadUrl 会清掉 forward 栈，避免前进落到 about:blank。
      await c.loadUrl(urlRequest: URLRequest(url: WebUri(url)));
      _syncWebBackStackAfterEscape(url);
      if (mounted) {
        setState(() {
          _currentUrl = url;
          _urlController.text = url;
        });
      } else {
        _currentUrl = url;
        _urlController.text = url;
      }
    } finally {
      Future<void>.delayed(const Duration(milliseconds: 500), () {
        _webBackNavigating = false;
      });
    }
  }

  /// 跳过历史里的 about:blank；若只剩空白则停止（绝不在此处回主页）。
  /// 返回当前 URL；仍为空白时由调用方改走应用栈 / 主页兜底。
  Future<String> _goBackSkippingBlanks(
    InAppWebViewController c, {
    int maxSteps = 8,
  }) async {
    var u = (await c.getUrl())?.toString() ?? '';
    for (var i = 0; i < maxSteps; i++) {
      if (!_isBlankHistoryUrl(u)) return u;
      if (!await c.canGoBack()) return u;
      await c.goBack();
      await Future<void>.delayed(const Duration(milliseconds: 40));
      u = (await c.getUrl())?.toString() ?? '';
    }
    return u;
  }

  Future<void> _performWebGoBack() async {
    final c = _controller;
    if (c == null || _showHomePage) return;

    final before = (await c.getUrl())?.toString() ?? _currentUrl;

    // 历史已被劫持时：优先 loadUrl 到应用栈上一有意义页（搜索结果等），
    // 避免连续 goBack 越过目标页落到 about:blank / 主页。
    if (_historyLikelyHijacked) {
      final hijackTarget = await _resolveWebBackEscapeTarget(before);
      if (hijackTarget != null && hijackTarget.isNotEmpty) {
        debugPrint('劫持后退栈逃生: $before -> $hijackTarget');
        _historyLikelyHijacked = false;
        await _loadWebBackEscapeUrl(c, hijackTarget);
        return;
      }
    }

    var escaped = false;
    var after = '';

    if (await c.canGoBack()) {
      await c.goBack();
      await Future<void>.delayed(const Duration(milliseconds: 50));
      after = await _goBackSkippingBlanks(c);

      if (!_isStillOnTrappedPage(before, after) && !_isBlankHistoryUrl(after)) {
        escaped = true;
      } else if (_isBlankHistoryUrl(after)) {
        // 落到空白：不要继续 goBack（会冲过搜索结果），改走应用栈。
        escaped = false;
      } else {
        // 仍困在同壳：少量 goBack；一旦空白立刻停，防止越过上一真页。
        for (var i = 0; i < _kWebBackTrapBurstMax; i++) {
          if (!await c.canGoBack()) break;
          await c.goBack();
          await Future<void>.delayed(const Duration(milliseconds: 55));
          after = (await c.getUrl())?.toString() ?? '';
          if (_isBlankHistoryUrl(after)) {
            escaped = false;
            break;
          }
          if (!_isStillOnTrappedPage(before, after)) {
            escaped = true;
            break;
          }
        }
      }

      if (escaped) {
        _syncWebBackStackAfterEscape(after);
        return;
      }
    }

    // WebView 历史无效、落到 blank、或仍困同页：用干净栈 / 会话轨迹。
    final target = await _resolveWebBackEscapeTarget(before);
    if (target != null && target.isNotEmpty) {
      debugPrint('后退栈逃生: $before -> $target');
      _historyLikelyHijacked = false;
      await _loadWebBackEscapeUrl(c, target);
      return;
    }

    // 仅当确实没有上一有意义页时才回浏览器主页。
    await _goToHomePage();
  }

  Future<void> _performWebGoForward() async {
    final c = _controller;
    if (c == null || _showHomePage) return;
    if (!await c.canGoForward()) return;
    await c.goForward();
    await Future<void>.delayed(const Duration(milliseconds: 40));
    for (var i = 0; i < 28; i++) {
      final u = (await c.getUrl())?.toString() ?? '';
      if (!_isBlankHistoryUrl(u)) return;
      if (!await c.canGoForward()) {
        // 前进方向只剩 about:blank：退回，避免停在空白页。
        if (await c.canGoBack()) {
          await c.goBack();
        }
        return;
      }
      await c.goForward();
      await Future<void>.delayed(const Duration(milliseconds: 40));
    }
    final landed = (await c.getUrl())?.toString() ?? '';
    if (_isBlankHistoryUrl(landed) && await c.canGoBack()) {
      await c.goBack();
    }
  }

  void _restoreWebPage() {
    if (_showHomePage && _isBrowsingWebPage && _shouldKeepWebPageState) {
      setState(() => _showHomePage = false);
      widget.onBrowserHomePageChanged?.call(_showHomePage);
      _syncBrowserSessionPreview();
    }
  }

  void _exitWebPage() {
    _clearWebBackStack();
    _controller?.loadUrl(urlRequest: URLRequest(url: WebUri('about:blank')));
    setState(() {
      _showHomePage = true;
      _isBrowsingWebPage = false;
      _shouldKeepWebPageState = false;
      _lastBrowsedUrl = null;
      _currentUrl = 'https://www.baidu.com';
      _urlController.text = _currentUrl;
    });
    BrowserSessionPreview.instance.clearLastBrowsingUrl();
    widget.onBrowserHomePageChanged?.call(_showHomePage);
    _syncBrowserSessionPreview();
  }

  Widget _buildHomePage() {
    // 确保_commonWebsites不为空
    if (_commonWebsites.isEmpty) {
      debugPrint('构建主页时发现常用网站列表为空，加载默认网站');
      _loadCommonWebsites();
    }

    final bottomSafeInset = MediaQuery.of(context).padding.bottom;
    return ColoredBox(
      color: Colors.white,
      child: ReorderableGridView.builder(
        padding: EdgeInsets.fromLTRB(
          14.0,
          14.0,
          14.0,
          14.0 + bottomSafeInset + 8.0,
        ),
        gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: 5,
          childAspectRatio: 1.15,
          crossAxisSpacing: 10.0,
          mainAxisSpacing: 10.0,
        ),
        itemCount: _commonWebsites.length + 1, // +1 for the add button
        itemBuilder: (context, index) {
          if (index == _commonWebsites.length) {
            return _buildAddWebsiteCard();
          }
          return _buildWebsiteCard(_commonWebsites[index], index);
        },
        onReorder: _reorderWebsites,
        dragStartBehavior: DragStartBehavior.start,
      ),
    );
  }

