  Future<void> _loadSmartKeywordHistory() async {
    final prefs = await SharedPreferences.getInstance();
    final values = prefs.getStringList(_kSmartKeywordHistoryKey) ?? const [];
    _smartKeywordHistory
      ..clear()
      ..addAll(values.where((value) => value.trim().isNotEmpty).take(30));
  }

  Future<void> _rememberSmartKeyword(String keyword) async {
    final normalized = keyword.trim();
    if (normalized.isEmpty) return;
    _smartKeywordHistory.removeWhere(
      (value) => value.toLowerCase() == normalized.toLowerCase(),
    );
    _smartKeywordHistory.insert(0, normalized);
    if (_smartKeywordHistory.length > 30) {
      _smartKeywordHistory.removeRange(30, _smartKeywordHistory.length);
    }
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(_kSmartKeywordHistoryKey, _smartKeywordHistory);
  }

  Future<void> _removeSmartKeyword(String keyword) async {
    _smartKeywordHistory.removeWhere(
      (value) => value.toLowerCase() == keyword.trim().toLowerCase(),
    );
    final prefs = await SharedPreferences.getInstance();
    await prefs.setStringList(_kSmartKeywordHistoryKey, _smartKeywordHistory);
  }

  Future<void> _loadSmartDownload24hRegistry() async {
    if (_smartDownload24hRegistryLoaded) return;
    final pending = _smartDownloadRegistryLoadFuture;
    if (pending != null) return pending;
    final future = () async {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kSmartDownload24hRegistryKey);
      final cutoff = DateTime.now().subtract(const Duration(hours: 24));
      final rows = <Map<String, dynamic>>[];
      if (raw != null && raw.trim().isNotEmpty) {
        try {
          final decoded = jsonDecode(raw);
          if (decoded is List) {
            for (final value in decoded.whereType<Map>()) {
              final row = Map<String, dynamic>.from(value);
              final savedAt = DateTime.tryParse(
                (row['savedAt'] ?? '').toString(),
              );
              if (savedAt != null && savedAt.isAfter(cutoff)) rows.add(row);
            }
          }
        } catch (e) {
          debugPrint('加载智能下载 24 小时备案失败: $e');
        }
      }
      rows.sort(
        (a, b) => (b['savedAt'] ?? '').toString().compareTo(
          (a['savedAt'] ?? '').toString(),
        ),
      );
      _smartDownload24hRegistry
        ..clear()
        ..addAll(rows.take(3000));
      _smartDownload24hRegistryLoaded = true;
      await prefs.setString(
        _kSmartDownload24hRegistryKey,
        jsonEncode(_smartDownload24hRegistry),
      );
    }();
    _smartDownloadRegistryLoadFuture = future;
    await future;
  }

  Future<void> _recordSmartDownload24h({
    required Map<String, dynamic> task,
    required String mediaUrl,
    required String title,
    required String pageUrl,
    required String fileHash,
    required int fileSize,
  }) async {
    await _loadSmartDownload24hRegistry();
    final siteHost = (task['host'] ?? '').toString().toLowerCase();
    if (siteHost.isEmpty) return;
    final nameKey = _smartMediaNameKey(
      mediaUrl,
      title: title,
      pageUrl: pageUrl,
    );
    final titleKey = _smartMediaTitleKey(title);
    final sourceKey = _normalizeVideoSourceUrl(mediaUrl);
    final pageKey = _smartStablePageKey(pageUrl);
    final allowTitleIdentity = !_isElementBoundFeedPage(pageUrl);
    final now = DateTime.now();
    final cutoff = now.subtract(const Duration(hours: 24));
    _smartDownload24hRegistry.removeWhere((row) {
      final savedAt = DateTime.tryParse((row['savedAt'] ?? '').toString());
      return savedAt == null || savedAt.isBefore(cutoff);
    });
    _smartDownload24hRegistry.removeWhere(
      (row) =>
          (row['siteHost'] ?? '').toString() == siteHost &&
          ((nameKey.isNotEmpty &&
                  (row['nameKey'] ?? '').toString() == nameKey) ||
              (allowTitleIdentity &&
                  titleKey.isNotEmpty &&
                  (row['titleKey'] ?? '').toString() == titleKey) ||
              (sourceKey.isNotEmpty &&
                  (row['sourceKey'] ?? '').toString() == sourceKey) ||
              (pageKey.isNotEmpty &&
                  (row['pageKey'] ?? '').toString() == pageKey) ||
              (fileHash.isNotEmpty &&
                  (row['fileHash'] ?? '').toString() == fileHash)),
    );
    _smartDownload24hRegistry.insert(0, <String, dynamic>{
      'siteHost': siteHost,
      'nameKey': nameKey,
      'titleKey': titleKey,
      'sourceKey': sourceKey,
      'pageKey': pageKey,
      'fileHash': fileHash,
      'fileSize': fileSize,
      'savedAt': now.toIso8601String(),
    });
    if (_smartDownload24hRegistry.length > 3000) {
      _smartDownload24hRegistry.removeRange(
        3000,
        _smartDownload24hRegistry.length,
      );
    }
    final snapshot = jsonEncode(_smartDownload24hRegistry);
    _smartDownloadRegistryWrite = _smartDownloadRegistryWrite.then((_) async {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(_kSmartDownload24hRegistryKey, snapshot);
    });
    await _smartDownloadRegistryWrite;
  }

  Future<void> _loadSmartStrategyProfiles() async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(_kSmartStrategyProfilesKey);
    if (raw == null || raw.trim().isEmpty) return;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return;
      _smartStrategyProfiles
        ..clear()
        ..addAll(
          decoded.map(
            (key, value) => MapEntry(
              key.toString(),
              value is Map
                  ? Map<String, dynamic>.from(value)
                  : <String, dynamic>{},
            ),
          ),
        );
    } catch (e) {
      debugPrint('加载智能下载策略画像失败: $e');
    }
  }

  String _smartStrategyKey(Map<String, dynamic> task, String strategy) {
    return '${(task['host'] ?? '').toString().toLowerCase()}|$strategy';
  }

  bool _smartStrategyCircuitOpen(Map<String, dynamic> task, String strategy) {
    final taskStats = task['strategyStats'] as Map<String, dynamic>;
    final local = taskStats[strategy] as Map<String, dynamic>?;
    final localFailures = (local?['consecutiveFailures'] as int?) ?? 0;
    if (strategy == 'click_media_card') {
      final target = (task['target'] as int?) ?? 1;
      return localFailures >= max(12, target * 3);
    }
    if (strategy == 'exploratory_click') {
      return localFailures >= 8;
    }
    if (localFailures >= 3) return true;
    final global = _smartStrategyProfiles[_smartStrategyKey(task, strategy)];
    if (((global?['consecutiveFailures'] as int?) ?? 0) < 5) return false;
    final failedAt = DateTime.tryParse(
      (global?['lastFailureAt'] ?? '').toString(),
    );
    return failedAt != null &&
        DateTime.now().difference(failedAt) < const Duration(hours: 6);
  }

  void _recordSmartStrategyOutcome(
    Map<String, dynamic> task,
    String strategy, {
    required bool success,
    int elapsedMs = 0,
  }) {
    if (!identical(_smartDownloadTask, task)) return;
    final now = DateTime.now().toIso8601String();
    final taskStats = task['strategyStats'] as Map<String, dynamic>;
    final local = Map<String, dynamic>.from(
      taskStats[strategy] as Map? ?? const <String, dynamic>{},
    );
    final globalKey = _smartStrategyKey(task, strategy);
    final global = Map<String, dynamic>.from(
      _smartStrategyProfiles[globalKey] ?? const <String, dynamic>{},
    );
    for (final row in <Map<String, dynamic>>[local, global]) {
      row[success ? 'successes' : 'failures'] =
          ((row[success ? 'successes' : 'failures'] as int?) ?? 0) + 1;
      row['consecutiveFailures'] =
          success ? 0 : ((row['consecutiveFailures'] as int?) ?? 0) + 1;
      row[success ? 'lastSuccessAt' : 'lastFailureAt'] = now;
      if (elapsedMs > 0) {
        final previous = (row['averageElapsedMs'] as num?)?.toDouble() ?? 0;
        row['averageElapsedMs'] =
            previous <= 0
                ? elapsedMs
                : (previous * 0.7 + elapsedMs * 0.3).round();
      }
    }
    taskStats[strategy] = local;
    _smartStrategyProfiles[globalKey] = global;
    unawaited(() async {
      try {
        final prefs = await SharedPreferences.getInstance();
        await prefs.setString(
          _kSmartStrategyProfilesKey,
          jsonEncode(_smartStrategyProfiles),
        );
      } catch (e) {
        debugPrint('保存智能下载策略画像失败: $e');
      }
    }());
  }

  Future<void> _onBookmarkSmartLongPress() async {
    if (_smartDownloadTask != null) {
      await _promptStopOrResetSmartDownload();
      return;
    }
    await _showCurrentMediaSmartDownload();
  }

  /// 分页嗅探：软停止。扫描阶段保留已结果；下载阶段在当前条完成后停下。
  void _requestPaginatedSniffSoftStop() {
    final task = _smartDownloadTask;
    if (task == null || task['mode'] != 'paginated_sniff') return;
    final phase = (task['phase'] ?? '').toString();
    task['sniffAbortRequested'] = true;
    if (phase == 'paginated_sniff_downloading') {
      task['matchStage'] = '分页嗅探 · 即将停止下载…';
      _showSmartOperation(
        '当前文件完成后停止下载…',
        point: const Offset(0.5, 0.1),
        showFinger: false,
      );
    } else {
      task['matchStage'] = '分页嗅探 · 正在停止，整理已嗅探结果…';
      _showSmartOperation(
        '正在停止嗅探，稍后展示已收集结果…',
        point: const Offset(0.5, 0.1),
        showFinger: false,
      );
    }
    debugPrint('paginatedSniff: soft stop requested phase=$phase');
  }

  /// 智能下载进行中：停止，或停止后重新打开设置。
  Future<void> _promptStopOrResetSmartDownload() async {
    if (!mounted || _smartDownloadTask == null) return;
    final task = _smartDownloadTask!;
    final phase = (task['phase'] ?? '').toString();
    final isSniffMode = task['mode'] == 'paginated_sniff';
    final isSniffScan =
        isSniffMode &&
        <String>{
          'paginated_sniff_scanning',
          'paginated_sniff_discover',
        }.contains(phase);
    final isSniffDownload =
        isSniffMode && phase == 'paginated_sniff_downloading';
    final choice = await showDialog<String>(
      context: context,
      builder:
          (ctx) => AlertDialog(
            title: Text(
              isSniffScan
                  ? '停止分页嗅探？'
                  : (isSniffDownload ? '停止分页下载？' : '智能下载进行中'),
            ),
            content: Text(
              isSniffScan
                  ? '停止后将保留已经嗅探到的媒体，供你选择下载。'
                      '也可彻底退出本次任务。'
                  : (isSniffDownload
                      ? '将在当前文件下载完成后停止，已成功的文件会保留。'
                      : '可退出卡住的任务，或停止后重新设置数量/大小/动作编排。'),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx, 'cancel'),
                child: const Text('继续运行'),
              ),
              if (isSniffScan)
                FilledButton(
                  onPressed: () => Navigator.pop(ctx, 'soft_stop'),
                  child: const Text('停止并查看结果'),
                ),
              if (isSniffDownload)
                FilledButton(
                  onPressed: () => Navigator.pop(ctx, 'soft_stop'),
                  child: const Text('下完当前后停止'),
                ),
              TextButton(
                onPressed: () => Navigator.pop(ctx, 'stop'),
                child: Text((isSniffScan || isSniffDownload) ? '彻底退出' : '停止退出'),
              ),
              if (!isSniffMode)
                FilledButton(
                  onPressed: () => Navigator.pop(ctx, 'reset'),
                  child: const Text('停止并重设'),
                ),
            ],
          ),
    );
    if (!mounted) return;
    if (choice == 'soft_stop') {
      _requestPaginatedSniffSoftStop();
    } else if (choice == 'stop') {
      await _finishSmartDownload('用户已停止任务');
    } else if (choice == 'reset') {
      await _finishSmartDownload('用户已停止任务');
      if (mounted) await _showCurrentMediaSmartDownload();
    }
  }

  Future<void> _showCurrentMediaSmartDownload() async {
    if (_showHomePage || _controller == null) return;
    var mediaType = MediaType.video;
    var currentVideoUrls = <String>[];
    var currentVideoDuration = 0.0;
    var currentMediaPageUrl = _currentUrl;
    try {
      final result = await _controller!.evaluateJavascript(
        source: '''
          (() => {
            const visible = el => {
              const r = el.getBoundingClientRect();
              return r.width > 100 && r.height > 80 && r.bottom > 0 && r.top < innerHeight;
            };
            const videos = Array.from(document.querySelectorAll('video')).filter(visible);
            const images = Array.from(document.querySelectorAll('img')).filter(visible)
              .filter(img => (img.naturalWidth || img.width) >= 200 && (img.naturalHeight || img.height) >= 160);
            const centerDistance = el => {
              const r = el.getBoundingClientRect();
              const dx = (r.left + r.width / 2) - innerWidth / 2;
              const dy = (r.top + r.height / 2) - innerHeight / 2;
              return Math.abs(dy) + Math.abs(dx) * 0.25;
            };
            const nearestCenter = list => list.sort((a,b) =>
              centerDistance(a) - centerDistance(b))[0];
            const playingVideos = videos.filter(v => !v.paused && !v.ended && v.readyState >= 2);
            const rawHost = location.hostname.toLowerCase();
            const host = rawHost.startsWith('www.') ? rawHost.slice(4) : rawHost;
            const isXPlatform = host === 'x.com' || host.endsWith('.x.com') ||
              host === 'twitter.com' || host.endsWith('.twitter.com');
            const media = nearestCenter(playingVideos) ||
              (isXPlatform ? nearestCenter(videos) : nearestCenter(images)) ||
              (isXPlatform ? nearestCenter(images) : nearestCenter(videos));
            document.querySelectorAll(
              '[data-smart-seed-media], [data-smart-seed-scope], '
              + '[data-app-smart-x-active], [data-app-smart-x-visited]'
            )
              .forEach(el => {
                el.removeAttribute('data-smart-seed-media');
                el.removeAttribute('data-smart-seed-scope');
                el.removeAttribute('data-app-smart-x-active');
                el.removeAttribute('data-app-smart-x-visited');
              });
            if (media) {
              media.setAttribute('data-smart-seed-media', '1');
              let scope = isXPlatform
                ? (media.closest('article[data-testid="tweet"], article') || media.parentElement)
                : media.parentElement;
              while (!isXPlatform && scope && scope !== document.body) {
                const count = scope.querySelectorAll('video, img').length;
                const scopeHint = String(scope.id || '') + ' ' + String(scope.className || '');
                if (count >= 2 &&
                    /(user|profile|gallery|album|folder|category|channel|feed|list|grid|items|posts)/i.test(scopeHint)) break;
                scope = scope.parentElement;
              }
              if ((!isXPlatform && !scope) || scope === document.body) {
                scope = media.closest('main, section, article, [role="feed"]') || media.parentElement;
              }
              if (scope) scope.setAttribute('data-smart-seed-scope', '1');
              if (isXPlatform && scope) {
                scope.setAttribute('data-app-smart-x-active', '1');
              }
            }
            const type = media && media.tagName === 'IMG' ? 'image' : 'video';
            const mediaUrls = type === 'video' ? [
              media.currentSrc,
              media.src,
              ...Array.from(media.querySelectorAll('source')).map(source => source.src)
            ].filter(Boolean) : [];
            const nearby = media && media.closest('article, figure, [class*="card"], [class*="item"]');
            const statusUrl = isXPlatform && nearby
              ? (Array.from(nearby.querySelectorAll('a[href*="/status/"]'))
                  .map(link => link.href || '').find(href => String(href).includes('/status/')) || '')
              : '';
            const values = [
              media && (media.getAttribute('alt') || media.getAttribute('title') || media.getAttribute('aria-label')),
              media && media.parentElement && media.parentElement.getAttribute('title'),
              nearby && nearby.querySelector('figcaption, h1, h2, h3, [class*="title"], [class*="caption"], [class*="tag"]')?.textContent,
              nearby && nearby.innerText,
              document.querySelector('meta[property="og:title"]')?.content,
              document.querySelector('meta[property="og:description"]')?.content,
              document.title
            ];
            const stripUrls = value => {
              const parts = [];
              let token = '';
              const flush = () => {
                if (!token) return;
                const lower = token.toLowerCase();
                if (!lower.startsWith('http://') && !lower.startsWith('https://')) {
                  parts.push(token);
                }
                token = '';
              };
              for (const char of String(value || '')) {
                if (char.charCodeAt(0) <= 32) {
                  flush();
                } else {
                  token += char;
                }
              }
              flush();
              return parts.join(' ').trim();
            };
            const cleaned = values.map(stripUrls).filter(v => {
                const rawLower = v.toLowerCase();
                const lower = rawLower.startsWith('www.') ? rawLower.slice(4) : rawLower;
                return v.length >= 2 && lower !== host && lower !== location.hostname.toLowerCase();
              });
            return {
              type,
              keyword: (cleaned[0] || '').slice(0, 80),
              mediaUrls: Array.from(new Set(mediaUrls)),
              sourcePageUrl: statusUrl || location.href,
              duration: type === 'video' && Number.isFinite(media.duration)
                ? media.duration
                : 0
            };
          })()
        ''',
      );
      if (result is Map) {
        mediaType =
            result['type']?.toString() == 'image'
                ? MediaType.image
                : MediaType.video;
        final rawUrls = result['mediaUrls'];
        if (rawUrls is List) {
          currentVideoUrls = rawUrls.map((value) => value.toString()).toList();
        }
        currentVideoDuration = (result['duration'] as num?)?.toDouble() ?? 0.0;
        currentMediaPageUrl =
            (result['sourcePageUrl'] ?? _currentUrl).toString().trim();
      }
    } catch (e) {
      debugPrint('提取当前媒体关键词失败: $e');
    }
    await _showSmartDownloadDialog(
      <String, dynamic>{
        'name': '当前媒体',
        'url':
            currentMediaPageUrl.isNotEmpty ? currentMediaPageUrl : _currentUrl,
      },
      initialKeyword: '',
      initialMediaType: mediaType,
      startFromCurrentPage: true,
      initialVideoUrls: currentVideoUrls,
      initialVideoDuration: currentVideoDuration,
    );
  }

  Future<int?> _estimateSmartSeedVideoBytes(
    List<String> rawUrls,
    String pageUrl,
    double durationSec,
  ) async {
    final networkService = NetworkService();
    await networkService.initialize();
    for (final rawUrl in rawUrls) {
      final url = _toAbsoluteUrl(rawUrl.trim());
      final uri = Uri.tryParse(url);
      if (uri == null || !(uri.scheme == 'http' || uri.scheme == 'https')) {
        continue;
      }
      try {
        final cookie = await _browserCookieHeaderForUrl(url);
        final headers = <String, String>{
          'User-Agent': _kBrowserMediaUserAgent,
          'Referer': pageUrl,
          if (cookie.isNotEmpty) 'Cookie': cookie,
        };
        final path = uri.path.toLowerCase();
        if (path.endsWith('.m3u8') || path.endsWith('.mpd')) {
          final response = await networkService.dio.get<String>(
            url,
            options: Options(
              responseType: ResponseType.plain,
              followRedirects: true,
              maxRedirects: 5,
              sendTimeout: const Duration(seconds: 5),
              receiveTimeout: const Duration(seconds: 5),
              validateStatus:
                  (code) => code != null && code >= 200 && code < 400,
              headers: headers,
            ),
          );
          final manifest = response.data ?? '';
          final bandwidths = RegExp(
            r'''(?:BANDWIDTH|bandwidth)\s*=\s*["']?(\d+)''',
          ).allMatches(manifest).map((match) => int.parse(match.group(1)!));
          final maxBandwidth = bandwidths.fold<int>(0, max);
          var knownDuration = durationSec;
          if (knownDuration <= 0 && path.endsWith('.m3u8')) {
            knownDuration = RegExp(r'#EXTINF:([\d.]+)')
                .allMatches(manifest)
                .fold<double>(
                  0,
                  (sum, match) => sum + (double.tryParse(match.group(1)!) ?? 0),
                );
          }
          if (maxBandwidth > 0 && knownDuration > 0) {
            return (maxBandwidth * knownDuration / 8).round();
          }
          continue;
        }
        final head = await networkService.dio.head<dynamic>(
          url,
          options: Options(
            followRedirects: true,
            maxRedirects: 5,
            sendTimeout: const Duration(seconds: 5),
            receiveTimeout: const Duration(seconds: 5),
            validateStatus: (code) => code != null && code >= 200 && code < 400,
            headers: headers,
          ),
        );
        final contentLength = int.tryParse(
          (head.headers.value('content-length') ?? '').trim(),
        );
        if (contentLength != null && contentLength > 0) return contentLength;

        final range = await networkService.dio.get<List<int>>(
          url,
          options: Options(
            responseType: ResponseType.bytes,
            followRedirects: true,
            maxRedirects: 5,
            sendTimeout: const Duration(seconds: 5),
            receiveTimeout: const Duration(seconds: 5),
            validateStatus: (code) => code == 206,
            headers: {...headers, 'Range': 'bytes=0-0'},
          ),
        );
        final contentRange = range.headers.value('content-range') ?? '';
        final total = int.tryParse(contentRange.split('/').last.trim());
        if (total != null && total > 0) return total;
      } catch (e) {
        debugPrint('当前视频大小自动探测失败（尝试下一地址）: $e');
      }
    }
    return null;
  }

  void _showSmartOperation(
    String label, {
    Offset point = const Offset(0.5, 0.5),
    bool showFinger = true,
  }) {
    if (!mounted || _smartDownloadTask == null) return;
    final safePoint = Offset(
      point.dx.clamp(0.08, 0.92),
      point.dy.clamp(0.08, 0.92),
    );
    setState(() {
      _smartOperationPoint = safePoint;
      _smartOperationLabel = label;
      _smartOperationShowFinger = showFinger;
    });
    _smartDownloadTask!['visibleOperation'] = label;
  }

  Future<void> _refreshMixedSmartMediaType(Map<String, dynamic> task) async {
    if (task['allowMixedMedia'] != true ||
        !identical(_smartDownloadTask, task) ||
        _controller == null) {
      return;
    }
    // 91 专有套路不走「屏幕中心媒体」混合识别，避免冲掉详情页向下找视频逻辑。
    final siteProfile = (task['siteProfile'] ?? '').toString();
    if (siteProfile == '91' || task['strict91KeywordMode'] == true) {
      return;
    }
    try {
      final result = await _controller!.evaluateJavascript(
        source: '''
          (() => {
            const visible = el => {
              const r = el.getBoundingClientRect();
              if (r.width < 100 || r.height < 80 ||
                  r.bottom <= 0 || r.top >= innerHeight ||
                  r.right <= 0 || r.left >= innerWidth) return false;
              if (el.tagName !== 'IMG') return true;
              const src = String(el.currentSrc || el.src || '').toLowerCase();
              const width = Math.max(el.naturalWidth || 0, r.width);
              const height = Math.max(el.naturalHeight || 0, r.height);
              return width >= 200 && height >= 160 &&
                !/(avatar|emoji|icon|logo|profile_images|profile_banners)/.test(src);
            };
            const rows = Array.from(document.querySelectorAll('video, img'))
              .filter(visible)
              .map(el => {
                const r = el.getBoundingClientRect();
                const x = r.left + r.width / 2;
                const y = r.top + r.height / 2;
                const distance = Math.abs(y - innerHeight / 2) +
                  Math.abs(x - innerWidth / 2) * 0.25;
                return {el, x, y, distance};
              })
              .sort((a, b) => a.distance - b.distance);
            const selected = rows[0];
            if (!selected) return null;
            return {
              type: selected.el.tagName === 'IMG' ? 'image' : 'video',
              x: innerWidth > 0 ? selected.x / innerWidth : 0.5,
              y: innerHeight > 0 ? selected.y / innerHeight : 0.5
            };
          })()
        ''',
      );
      if (result is! Map || !identical(_smartDownloadTask, task)) return;
      final isImage = result['type']?.toString() == 'image';
      task['mediaType'] = isImage ? MediaType.image : MediaType.video;
      _showSmartOperation(
        isImage ? '已定位中心图片，准备下载' : '已定位中心视频，准备下载',
        point: Offset(
          (result['x'] as num?)?.toDouble() ?? 0.5,
          (result['y'] as num?)?.toDouble() ?? 0.5,
        ),
      );
    } catch (e) {
      debugPrint('智能下载判断中心媒体类型失败: $e');
    }
  }

  bool _isBaiduHost(String host) {
    final normalized = host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    return normalized == 'baidu.com' || normalized.endsWith('.baidu.com');
  }

  String _smartSiteRoot(String host) {
    final normalized = host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    final parts =
        normalized.split('.').where((part) => part.isNotEmpty).toList();
    if (parts.length <= 2) return normalized;
    const compoundSuffixes = <String>{
      'com.cn',
      'net.cn',
      'org.cn',
      'com.hk',
      'co.uk',
      'com.au',
      'co.jp',
    };
    final suffix2 = parts.sublist(parts.length - 2).join('.');
    final take = compoundSuffixes.contains(suffix2) ? 3 : 2;
    return parts.sublist(parts.length - take).join('.');
  }

  bool _sameSmartSite(String leftHost, String rightHost) {
    if (leftHost.isEmpty || rightHost.isEmpty) return false;
    return _smartSiteRoot(leftHost) == _smartSiteRoot(rightHost);
  }

  String _smartSiteProfile(String host) {
    final value = host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');
    if (value == 'x.com' ||
        value.endsWith('.x.com') ||
        value == 'twitter.com' ||
        value.endsWith('.twitter.com')) {
      return 'x';
    }
    if (value == '91cg1.com' || value.endsWith('.91cg1.com')) return '91';
    if (value == 'facebook.com' ||
        value.endsWith('.facebook.com') ||
        value == 'fb.com' ||
        value.endsWith('.fb.com') ||
        value == 'fb.watch' ||
        value.endsWith('.fb.watch') ||
        value == 'messenger.com' ||
        value.endsWith('.messenger.com')) {
      return 'facebook';
    }
    if (value == 'instagram.com' || value.endsWith('.instagram.com')) {
      return 'instagram';
    }
    if (value == 'tik.porn' || value.endsWith('.tik.porn')) return 'tikporn';
    if (value == 'pin.porn' || value.endsWith('.pin.porn')) return 'pinporn';
    if (value.contains('xvideos') ||
        value.contains('xfree') ||
        value.contains('freevideo')) {
      return 'xvideo';
    }
    if (_isBaiduHost(value)) return 'baidu';
    return 'generic';
  }

  /// X / 91 已验证的智能下载管线：保留扩大探索等既有行为，避免回归。
  /// 「沿用套路」面板：专有套路见 [_dedicatedSmartPatternIds]；通用见 id=`generic`。
  /// 91 专有套路以 a00c4bd（2026.7.23-6:47）已验证行为为准完整保留。
  bool _smartUsesLegacyPriorityPipeline(String siteProfile) =>
      siteProfile == 'x' || siteProfile == '91';

  /// Facebook / Reels：仅保留下载引擎侧质量策略（绑当前 reel、拒 stub）。
  /// 不再提供任何内置/专用下载套路，操作步骤完全由用户动作编排决定。
  bool _smartUsesFacebookPipeline(String siteProfile) =>
      siteProfile == 'facebook' ||
      siteProfile == 'facebook_image' ||
      siteProfile == 'facebook_grid';

  bool _smartUsesInstagramGridPipeline(String siteProfile) =>
      siteProfile == 'instagram' || siteProfile == 'instagram_grid';

  bool _smartUsesProfileGridPipeline(String siteProfile) =>
      _smartUsesInstagramGridPipeline(siteProfile) ||
      siteProfile == 'facebook_grid';

  /// 个人页网格 / 动作编排 / 通用实测：长按后须等媒体库确认再切条。
  bool _smartUsesLibraryGate(Map<String, dynamic> task) =>
      task['mode'] == 'action_recipe' ||
      task['mode'] == 'simple_generic' ||
      task['instagramGridMode'] == true;

  /// 已固化的「专有」站点套路（重要常用站逐个加入）。
  /// 默认只对本站自动选用；用户可在「沿用套路」里手动借用到其他站。
  /// Facebook 芯片启动的是个人页网格批量管线（facebook_grid）或动作编排（Reels 竖滑）。
  static const Set<String> _dedicatedSmartPatternIds = <String>{
    'x',
    '91',
    'instagram_grid',
    'facebook_grid',
  };

  /// 「沿用套路」可选列表：全部专有站 + 普适通用套路（不按当前 host 隐藏）。
  static const List<Map<String, String>> _confirmedSmartPatterns =
      <Map<String, String>>[
        {'id': 'x', 'label': 'X · 原智能（已验证）', 'kind': 'dedicated'},
        {'id': '91', 'label': '91 · 原智能（已验证）', 'kind': 'dedicated'},
        {
          'id': 'instagram_grid',
          'label': 'Instagram · 媒体网格专用',
          'kind': 'dedicated',
        },
        {
          'id': 'facebook_grid',
          'label': 'Facebook · Reels 网格专用',
          'kind': 'dedicated',
        },
        {'id': 'generic', 'label': '通用套路', 'kind': 'generic'},
      ];

  static final Set<String> _confirmedSmartPatternIds =
      _confirmedSmartPatterns.map((e) => e['id']!).toSet();

  /// 默认选用：有本站专有套路 → 专有；否则 → 通用。
  String _defaultConfirmedPatternIdForHost(
    String host, {
    MediaType mediaType = MediaType.video,
  }) {
    final profile = _smartSiteProfile(host);
    if (profile == 'instagram') return 'instagram_grid';
    if (profile == 'facebook') return 'facebook_grid';
    if (_dedicatedSmartPatternIds.contains(profile)) return profile;
    return 'generic';
  }

  bool _hostHasDedicatedSmartPattern(String host) {
    final profile = _smartSiteProfile(host);
    return profile == 'instagram' ||
        profile == 'facebook' ||
        _dedicatedSmartPatternIds.contains(profile);
  }

  /// 专有芯片对应的可编辑种子（内置管线仍保留；重新编排后可覆盖为本站默认）。
  SmartActionRecipe _dedicatedPatternEditableSeed(
    String patternId,
    String host,
  ) {
    final hostKey = host.isEmpty ? 'unknown' : host;
    switch (patternId) {
      case 'x':
        return SmartActionRecipe.xEditableSeedTemplate(hostKey);
      case '91':
        return SmartActionRecipe.ninetyOneEditableSeedTemplate(hostKey);
      default:
        return SmartActionRecipe.feedTemplate(hostKey);
    }
  }

  String _confirmedPatternLabel(String patternId) {
    for (final row in _confirmedSmartPatterns) {
      if (row['id'] == patternId) return row['label'] ?? patternId;
    }
    return patternId;
  }

  /// 91 关键词搜索分页 URL（第 1 页无页码后缀）。
  String _strict91SearchUrlForPage(String origin, String keyword, int page) {
    final encoded = Uri.encodeComponent(keyword.trim());
    if (page <= 1) return '$origin/search/$encoded/';
    return '$origin/search/$encoded/$page/';
  }

  /// 关键词模式：仅翻搜索结果页，禁止 broaden / 乱逛。
  bool _tryAdvance91KeywordSearchPage(Map<String, dynamic> task) {
    if (task['strict91KeywordMode'] != true) return false;
    final keyword = (task['keyword'] ?? '').toString().trim();
    if (keyword.isEmpty) return false;
    final siteUri = Uri.tryParse((task['siteUrl'] ?? '').toString());
    if (siteUri == null || siteUri.origin.isEmpty) return false;
    final page = ((task['strict91SearchPage'] as int?) ?? 1) + 1;
    if (page > 12) return false;
    task['strict91SearchPage'] = page;
    final nextUrl = _strict91SearchUrlForPage(siteUri.origin, keyword, page);
    task['strict91SearchUrl'] = nextUrl;
    task['phase'] = 'collecting_search_results';
    task['candidates'] = <Map<String, String>>[];
    task['index'] = 0;
    task['strict91QueueReady'] = false;
    task['strict91ActiveCardUrl'] = '';
    task['matchStage'] = '关键词搜索 · 第 $page 页';
    _showSmartOperation('当前页已试完，加载关键词第 $page 页');
    _loadUrl(nextUrl);
    return true;
  }

  /// 候选用尽时：X/91 继续扩大探索；91 关键词模式只翻搜索页。
  void _onSmartCandidatesExhausted(Map<String, dynamic> task, String reason) {
    if (task['strict91KeywordMode'] == true) {
      if (_tryAdvance91KeywordSearchPage(task)) return;
      unawaited(_finishSmartDownload('关键词搜索结果已尝试完毕（$reason）'));
      return;
    }
    if (task['allowBroadenDiscovery'] == true) {
      _broadenSmartDiscovery(task, reason);
      return;
    }
    unawaited(_finishSmartDownload('当前候选已尝试完毕，已停止扩大探索（$reason）'));
  }

  /// V1 通用站：优先用页面已暴露的媒体直链下载；成功则计入智能下载进度。
  /// X/91 不会调用本方法。

  Future<void> _loadSmartDemoRecipes() async {
    if (_smartDemoRecipesLoaded) return;
    try {
      final prefs = await SharedPreferences.getInstance();
      final raw = prefs.getString(_kSmartDemoRecipesKey);
      _smartDemoRecipes.clear();
      if (raw != null && raw.isNotEmpty) {
        final decoded = jsonDecode(raw);
        if (decoded is Map) {
          decoded.forEach((key, value) {
            if (value is Map) {
              final recipe = Map<String, dynamic>.from(value);
              if ((recipe['host'] ?? '').toString().isEmpty) {
                final parts = key.toString().split('|');
                if (parts.isNotEmpty) recipe['host'] = parts.first;
                if (parts.length > 1) recipe['pageType'] = parts[1];
              }
              _ensureSmartStrategyName(recipe);
              _smartDemoRecipes[key.toString()] = recipe;
            }
          });
        }
      }
    } catch (e) {
      debugPrint('加载智能下载示范记忆失败: $e');
    } finally {
      _smartDemoRecipesLoaded = true;
    }
  }

  Future<void> _saveSmartDemoRecipes() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString(
        _kSmartDemoRecipesKey,
        jsonEncode(_smartDemoRecipes),
      );
    } catch (e) {
      debugPrint('保存智能下载示范记忆失败: $e');
    }
  }

  String _smartDemoPageType({
    required String url,
    required String siteProfile,
    required String keyword,
    required String smartRunMode,
  }) {
    if (keyword.trim().isNotEmpty || smartRunMode == 'list') return 'search';
    final lower = url.toLowerCase();
    if (siteProfile == 'x' &&
        (_isXStatusDetailPage(url) || _isXMediaViewerPage(url))) {
      return 'detail';
    }
    if (RegExp(
      r'/video|/watch|/play|/v/|/status/',
      caseSensitive: false,
    ).hasMatch(lower)) {
      return 'detail';
    }
    return 'feed';
  }

  String _smartDemoRecipeKey({required String host, required String pageType}) {
    return '${host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '')}|$pageType';
  }

  String _normalizeSmartHost(String host) =>
      host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '');

  String _smartStrategyDisplaySite(String host) {
    final profile = _smartSiteProfile(host);
    if (profile == 'x') return 'X';
    if (profile == '91') return '91';
    if (profile == 'baidu') return '百度';
    if (profile == 'tikporn') return 'TikPorn';
    if (profile == 'pinporn') return 'PinPorn';
    final h = _normalizeSmartHost(host);
    final parts = h.split('.');
    if (parts.length >= 2) return parts[parts.length - 2];
    return h.isEmpty ? '站点' : h;
  }

  String _smartPageTypeLabel(String pageType) {
    switch (pageType) {
      case 'search':
        return '搜索';
      case 'detail':
        return '详情';
      default:
        return '信息流';
    }
  }

  String _smartAcquisitionLabel(String acquisition) {
    switch (acquisition) {
      case 'sniff':
        return '直链';
      case 'detail_longpress':
        return '详情长按';
      case 'legacy_x':
      case 'legacy_91':
        return '原智能';
      case 'legacy_facebook':
        return 'FB长按→上滑';
      case 'site_address':
        return '站内地址';
      case 'longpress_inplace':
      default:
        return '长按';
    }
  }

  String _autoSmartStrategyName(Map<String, dynamic> recipe) {
    final host = (recipe['host'] ?? '').toString();
    final pageType = (recipe['pageType'] ?? 'feed').toString();
    final acquisition =
        (recipe['acquisition'] ?? 'longpress_inplace').toString();
    return '${_smartStrategyDisplaySite(host)}·${_smartPageTypeLabel(pageType)}·${_smartAcquisitionLabel(acquisition)}';
  }

  void _ensureSmartStrategyName(Map<String, dynamic> recipe) {
    final custom = recipe['nameCustom'] == true;
    final name = (recipe['name'] ?? '').toString().trim();
    if (!custom || name.isEmpty) {
      recipe['name'] = _autoSmartStrategyName(recipe);
      recipe['nameCustom'] = false;
    }
  }

  String? _defaultSameHostStrategyKey({
    required String host,
    required String pageType,
  }) {
    final want = _normalizeSmartHost(host);
    MapEntry<String, Map<String, dynamic>>? bestExact;
    MapEntry<String, Map<String, dynamic>>? bestAny;
    int scoreOf(Map<String, dynamic> r) {
      final successes = (r['successes'] as int?) ?? 0;
      final updated = DateTime.tryParse((r['updatedAt'] ?? '').toString());
      final ageBoost =
          updated == null ? 0 : updated.millisecondsSinceEpoch ~/ 1000000;
      // 用户主动示范教出来的经验享有最高优先级。
      final demoBoost =
          (r['source'] == 'user_demo' || r['demoTaught'] == true)
              ? 500000000000
              : 0;
      return demoBoost + successes * 100000000 + ageBoost;
    }

    for (final entry in _smartDemoRecipes.entries) {
      final recipe = entry.value;
      if (_normalizeSmartHost((recipe['host'] ?? '').toString()) != want) {
        continue;
      }
      if ((recipe['pageType'] ?? '').toString() == pageType) {
        if (bestExact == null || scoreOf(recipe) > scoreOf(bestExact.value)) {
          bestExact = entry;
        }
      } else if (bestAny == null || scoreOf(recipe) > scoreOf(bestAny.value)) {
        bestAny = entry;
      }
    }
    if (bestExact != null) return bestExact.key;
    if (bestAny == null) return null;
    final anySuccess = (bestAny.value['successes'] as int?) ?? 0;
    // 跨页型回退要够强，避免信息流经验误伤搜索页。
    return anySuccess >= 3 ? bestAny.key : null;
  }

  List<MapEntry<String, Map<String, dynamic>>> _sortedSmartStrategies({
    String? preferHost,
  }) {
    final pref = preferHost == null ? '' : _normalizeSmartHost(preferHost);
    final entries = _smartDemoRecipes.entries.toList();
    entries.sort((a, b) {
      final ha = _normalizeSmartHost((a.value['host'] ?? '').toString());
      final hb = _normalizeSmartHost((b.value['host'] ?? '').toString());
      final aSame = pref.isNotEmpty && ha == pref;
      final bSame = pref.isNotEmpty && hb == pref;
      if (aSame != bSame) return aSame ? -1 : 1;
      final aDemo =
          a.value['source'] == 'user_demo' || a.value['demoTaught'] == true;
      final bDemo =
          b.value['source'] == 'user_demo' || b.value['demoTaught'] == true;
      if (aDemo != bDemo) return aDemo ? -1 : 1;
      final sa = (a.value['successes'] as int?) ?? 0;
      final sb = (b.value['successes'] as int?) ?? 0;
      if (sa != sb) return sb.compareTo(sa);
      final ta = DateTime.tryParse((a.value['updatedAt'] ?? '').toString());
      final tb = DateTime.tryParse((b.value['updatedAt'] ?? '').toString());
      if (ta != null && tb != null) return tb.compareTo(ta);
      return a.key.compareTo(b.key);
    });
    return entries;
  }

  void _onSmartBatchAcquireOutcome(
    Map<String, dynamic> task, {
    required bool ok,
    String? acquisition,
    String failureType = '',
  }) {
    if (!identical(_smartDownloadTask, task)) return;
    final duplicate = <String>{
      'already_in_library',
      'already_in_smart_task',
      'duplicate_name_in_smart_task',
      'already_downloading',
    }.contains(failureType);
    if (ok) {
      final profile = (task['siteProfile'] ?? '').toString();
      final resolved =
          (acquisition != null && acquisition.isNotEmpty)
              ? acquisition
              : _smartUsesLegacyPriorityPipeline(profile)
              ? (profile == 'x' ? 'legacy_x' : 'legacy_91')
              : _smartUsesFacebookPipeline(profile)
              ? 'legacy_facebook'
              : ((task['gestureMode'] == true)
                  ? 'longpress_inplace'
                  : 'site_address');
      _lockSmartTaskAcquisition(task, resolved);
      _noteSmartStrategyProgress(task, success: true);
      _touchSmartProgressMarker(task);
      return;
    }
    if (duplicate) {
      _touchSmartProgressMarker(task);
      return;
    }
    _noteSmartTaskAcquisitionFailure(task);
    _touchSmartProgressMarker(task);
  }

  String _normalizeSmartAcquisition(String acquisition) {
    switch (acquisition) {
      case 'sniff':
      case 'detail_longpress':
      case 'legacy_x':
      case 'legacy_91':
      case 'legacy_facebook':
      case 'site_address':
        return acquisition;
      case 'longpress':
      case 'longpress_inplace':
        return 'longpress_inplace';
      case '':
        return '';
      default:
        return acquisition;
    }
  }

  bool _isLongpressAcquisition(String acquisition) {
    final value = _normalizeSmartAcquisition(acquisition);
    return value == 'longpress_inplace' ||
        value == 'detail_longpress' ||
        value == 'legacy_facebook';
  }

  void _applyAcquisitionLockPrefs(
    Map<String, dynamic> task,
    String acquisition,
  ) {
    final value = _normalizeSmartAcquisition(acquisition);
    task['preferSniffFirst'] = value == 'sniff';
    task['skipSniffAcquire'] =
        _isLongpressAcquisition(value) ||
        value == 'legacy_x' ||
        value == 'legacy_91' ||
        value == 'site_address';
  }

  /// 本任务内：一旦某下载方式成功，就锁定沿用，直到连续失败才换。
  void _lockSmartTaskAcquisition(
    Map<String, dynamic> task,
    String acquisition, {
    bool announce = true,
  }) {
    if (!identical(_smartDownloadTask, task)) return;
    // 示范期只记步骤，不锁方式，避免与手动长按示范冲突。
    if (task['demoPhase'] == 'demo') return;
    var value = _normalizeSmartAcquisition(acquisition);
    if (value.isEmpty) return;
    final siteProfile = (task['siteProfile'] ?? '').toString();
    // X/91：默认保住原智能；仅在备用尝试或已学到直链/站内地址时允许锁定这些方式。
    if (_smartUsesLegacyPriorityPipeline(siteProfile) &&
        (value == 'sniff' || value == 'site_address')) {
      final preferred = (task['preferredAcquisition'] ?? '').toString();
      final allowAlt = task['allowLegacyAlternateAcquire'] == true;
      if (!allowAlt && preferred != 'sniff' && preferred != 'site_address') {
        value = siteProfile == 'x' ? 'legacy_x' : 'legacy_91';
      } else {
        task['allowLegacyAlternateAcquire'] = true;
      }
    }
    if (_smartUsesFacebookPipeline(siteProfile) &&
        (value == 'sniff' || value == 'site_address')) {
      final preferred = (task['preferredAcquisition'] ?? '').toString();
      final allowAlt = task['allowLegacyAlternateAcquire'] == true;
      if (!allowAlt && preferred != 'sniff' && preferred != 'site_address') {
        value = 'legacy_facebook';
      } else {
        task['allowLegacyAlternateAcquire'] = true;
      }
    }
    final previous = (task['lockedAcquisition'] ?? '').toString();
    task['lockedAcquisition'] = value;
    task['lockedFailStreak'] = 0;
    task['sniffEmptyScrolls'] = 0;
    task['lastSuccessAcquisition'] = value;
    _touchSmartProgressMarker(task);
    _applyAcquisitionLockPrefs(task, value);
    final label = _smartAcquisitionLabel(value);
    task['matchStage'] = '沿用 · $label';
    if (announce && previous != value) {
      _showSmartOperation(
        previous.isEmpty ? '已锁定本任务方式：$label（成功前不再换）' : '改沿用方式：$label',
      );
    }
  }

  void _applySiteDefaultAcquisition(Map<String, dynamic> task) {
    final siteProfile = (task['siteProfile'] ?? '').toString();
    task['lockedAcquisition'] = '';
    task['lockedFailStreak'] = 0;
    task['sniffEmptyScrolls'] = 0;
    if (_smartUsesLegacyPriorityPipeline(siteProfile)) {
      // X/91：只复位获取偏好，绝不改写 gestureMode / FSM，避免打乱原可靠管线。
      final acq = siteProfile == 'x' ? 'legacy_x' : 'legacy_91';
      _applyAcquisitionLockPrefs(task, acq);
      task['preferSniffFirst'] = false;
      task['skipSniffAcquire'] = true;
    } else if (_smartUsesFacebookPipeline(siteProfile)) {
      // Facebook：下载引擎绑当前 reel + stub 闸门；编排默认已改为动作套路循环。
      _applyAcquisitionLockPrefs(task, 'legacy_facebook');
      task['preferSniffFirst'] = false;
      task['skipSniffAcquire'] = true;
      task['gestureMode'] = true;
      task['protectVisibleGestureFlow'] = true;
      task['facebookPipeline'] = true;
      task['allowBroadenDiscovery'] = false;
    } else {
      task['preferSniffFirst'] = true;
      task['skipSniffAcquire'] = false;
      task['gestureMode'] = true;
      task['protectVisibleGestureFlow'] = true;
    }
  }

  void _touchSmartProgressMarker(Map<String, dynamic> task) {
    final seen = task['seenMediaUrls'];
    final seenLen = seen is Set ? seen.length : 0;
    final marker =
        '${task['success']}|${task['failed']}|$seenLen|${task['lockedAcquisition']}|${task['strategyLayer']}';
    if ((task['lastProgressMarker'] ?? '').toString() != marker) {
      task['lastProgressMarker'] = marker;
      task['lastProgressAt'] = DateTime.now();
    }
  }

  void _clearSmartTaskAcquisitionLock(
    Map<String, dynamic> task, {
    required String reason,
  }) {
    if ((task['lockedAcquisition'] ?? '').toString().isEmpty) {
      _showSmartOperation(reason);
      return;
    }
    task['lockedAcquisition'] = '';
    task['lockedFailStreak'] = 0;
    task['sniffEmptyScrolls'] = 0;
    _applySiteDefaultAcquisition(task);
    task['matchStage'] = '沿用失败 · 尝试其他方式';
    _showSmartOperation(reason);
  }

  Future<void> _scrollPageForLockedSniff(Map<String, dynamic> task) async {
    if (!identical(_smartDownloadTask, task) || _controller == null) return;
    final emptyScrolls = ((task['sniffEmptyScrolls'] as int?) ?? 0) + 1;
    task['sniffEmptyScrolls'] = emptyScrolls;
    // 连续多轮「直链空转+滚动」视为该方式无进展，计入失败并可能解锁。
    if (emptyScrolls >= 5) {
      task['sniffEmptyScrolls'] = 0;
      _noteSmartTaskAcquisitionFailure(task);
      if ((task['lockedAcquisition'] ?? '').toString() != 'sniff') {
        Future<void>.delayed(const Duration(milliseconds: 200), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
    }
    try {
      await _controller!.evaluateJavascript(
        source: '''
(() => {
  const dy = Math.max(240, Math.floor((window.innerHeight || 640) * 0.7));
  const root = document.scrollingElement || document.documentElement || document.body;
  if (root) root.scrollBy(0, dy);
  else window.scrollBy(0, dy);
  return true;
})()
''',
      );
    } catch (_) {}
    task['matchStage'] = '沿用直链 · 滚动寻找（${task['sniffEmptyScrolls']}/5）';
    Future<void>.delayed(const Duration(milliseconds: 450), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_advanceSmartDownload(_currentUrl));
      }
    });
  }

  Map<String, dynamic> _builtInPreferredRecipe({
    required String host,
    required String pageType,
    required String siteProfile,
  }) {
    if (_smartUsesLegacyPriorityPipeline(siteProfile)) {
      final acquisition = siteProfile == 'x' ? 'legacy_x' : 'legacy_91';
      final recipe = <String, dynamic>{
        'host': host,
        'pageType': pageType,
        'acquisition': acquisition,
        'traversal': 'nearby',
        'scrollBetween': false,
        'successes': 0,
        'updatedAt': DateTime.now().toIso8601String(),
        'nameCustom': true,
      };
      recipe['name'] = siteProfile == 'x' ? 'X·原智能（已验证）' : '91·原智能（已验证）';
      return recipe;
    }
    if (_smartUsesFacebookPipeline(siteProfile)) {
      return <String, dynamic>{
        'host': host,
        'pageType': pageType,
        // 仅保留下载引擎策略画像；操作步骤完全由用户动作编排提供。
        'acquisition': 'action_recipe',
        'traversal': 'nearby',
        'scrollBetween': true,
        'successes': 0,
        'updatedAt': DateTime.now().toIso8601String(),
        'nameCustom': true,
        'name': 'Facebook·动作编排',
      };
    }
    final recipe = <String, dynamic>{
      'host': host,
      'pageType': pageType,
      'acquisition': 'sniff',
      'traversal': pageType == 'search' ? 'list' : 'nearby',
      'scrollBetween': false,
      'successes': 0,
      'updatedAt': DateTime.now().toIso8601String(),
      'nameCustom': true,
    };
    recipe['name'] = '${_smartStrategyDisplaySite(host)}·通用套路';
    return recipe;
  }

  /// 自动方式用尽且数量未满时，请求用户示范一次；学会后继续自动。
  Future<bool> _tryEnterSmartDemoAfterExhaustion(
    Map<String, dynamic> task,
    String reason,
  ) async {
    if (!identical(_smartDownloadTask, task)) return false;
    if (task['allowAutoDemo'] != true) return false;
    if (task['autoDemoRequested'] == true) return false;
    if (task['demoPhase'] == 'demo') return false;
    final success = (task['success'] as int?) ?? 0;
    final target = (task['target'] as int?) ?? 0;
    if (success >= target) return false;

    task['autoDemoRequested'] = true;
    task['demoPhase'] = 'demo';
    // 冷启动多示范 1 次以便推断「详情/滚动」；已有成功时再示范 1 次即可。
    final needExtra = success <= 0 ? 2 : 1;
    task['demoRequired'] = success + needExtra;
    task['demoCompleted'] = success;
    task['gestureMode'] = false;
    task['protectVisibleGestureFlow'] = false;
    task['lockedAcquisition'] = '';
    task['lockedFailStreak'] = 0;
    task['skipSniffAcquire'] = true;
    task['preferSniffFirst'] = false;
    task['allowLegacyAlternateAcquire'] = false;
    task['matchStage'] = '请示范 · 自动尝试已尽力';
    _showSmartOperation(
      needExtra > 1
          ? '自动方式暂时不够用（$reason）。请手动长按成功下载 $needExtra 个，学会后继续自动'
          : '自动方式暂时不够用（$reason）。请手动长按成功下载 1 个，学会后继续自动完成剩余',
    );
    _updateSmartDiscoveryProgress(task, 'demo_after_exhaustion');
    debugPrint('Smart demo requested after auto exhaustion: $reason');
    return true;
  }

  void _bindSmartStrategyToTask(
    Map<String, dynamic> task,
    Map<String, dynamic> recipe, {
    required String strategyKey,
    required bool manualPick,
  }) {
    final bound = Map<String, dynamic>.from(recipe);
    _ensureSmartStrategyName(bound);
    var acquisition = _normalizeSmartAcquisition(
      (bound['acquisition'] ?? 'longpress_inplace').toString(),
    );
    final siteProfile = (task['siteProfile'] ?? '').toString();
    // 同站已验证经验（含示范学会的直链）应原样优先；勿强行改回原智能。
    if (_smartUsesLegacyPriorityPipeline(siteProfile) &&
        (acquisition == 'sniff' || acquisition == 'site_address')) {
      task['allowLegacyAlternateAcquire'] = true;
    }
    task['learnedRecipe'] = bound;
    task['preferredStrategyKey'] = strategyKey;
    task['preferredAcquisition'] = acquisition;
    task['strategyManualPick'] = manualPick;
    task['strategyLayer'] = 'preferred';
    task['strategyFailStreak'] = 0;
    // 把可执行字段真正应用到任务（不再只当标签）。
    final traversal = (bound['traversal'] ?? '').toString();
    if (traversal == 'list' ||
        traversal == 'nearby' ||
        traversal == 'nearby_scroll') {
      task['smartRunMode'] = traversal == 'list' ? 'list' : 'nearby';
      task['preferScrollBetween'] =
          traversal == 'nearby_scroll' || bound['scrollBetween'] == true;
    } else if (bound['scrollBetween'] == true) {
      task['preferScrollBetween'] = true;
    }
    // 策略只决定「优先尝试」；真正锁定发生在本任务首次成功之后。
    _applyAcquisitionLockPrefs(task, acquisition);
    task['lockedAcquisition'] = '';
    task['lockedFailStreak'] = 0;
    final isBuiltin = strategyKey.startsWith('__builtin__');
    task['matchStage'] =
        isBuiltin ? '内置默认 · ${bound['name']}' : '成功经验优先 · ${bound['name']}';
  }

  void _noteSmartTaskAcquisitionFailure(Map<String, dynamic> task) {
    if (!identical(_smartDownloadTask, task)) return;
    final locked = (task['lockedAcquisition'] ?? '').toString();
    if (locked.isEmpty) {
      _noteSmartStrategyProgress(task, success: false);
      return;
    }
    final streak = ((task['lockedFailStreak'] as int?) ?? 0) + 1;
    task['lockedFailStreak'] = streak;
    // 连续 3 次该方式失败才解锁，避免偶发失败就乱换。
    if (streak < 3) {
      task['matchStage'] =
          '沿用 · ${_smartAcquisitionLabel(locked)}（失败 $streak/3）';
      return;
    }
    _clearSmartTaskAcquisitionLock(task, reason: '沿用方式连续失败，开始尝试其他下载方式');
    _noteSmartStrategyProgress(task, success: false);
  }

  void _noteSmartStrategyProgress(
    Map<String, dynamic> task, {
    required bool success,
  }) {
    if (!identical(_smartDownloadTask, task)) return;
    if (success) {
      task['strategyFailStreak'] = 0;
      _touchSmartProgressMarker(task);
      return;
    }
    final streak = ((task['strategyFailStreak'] as int?) ?? 0) + 1;
    task['strategyFailStreak'] = streak;
    final layer = (task['strategyLayer'] ?? 'preferred').toString();
    final siteProfile = (task['siteProfile'] ?? '').toString();
    // 91 关键词模式：不升层到嗅探/扩大探索，只在搜索页按卡片顺序继续。
    if (task['strict91KeywordMode'] == true) {
      task['matchStage'] = '关键词搜索 · 当前方式未成功（$streak）';
      return;
    }
    if (layer == 'preferred' && streak >= 4) {
      task['strategyLayer'] = 'default';
      task['strategyFailStreak'] = 0;
      _clearSmartTaskAcquisitionLock(task, reason: '当前成功经验暂未奏效，改用本站默认可靠方式继续');
      _applySiteDefaultAcquisition(task);
      // X/91 默认可靠方式就是原智能管线。
      if (_smartUsesLegacyPriorityPipeline(siteProfile)) {
        task['skipSniffAcquire'] = true;
        task['preferSniffFirst'] = false;
        task['allowLegacyAlternateAcquire'] = false;
      }
      task['matchStage'] = '经验未奏效 · 切换本站默认方式';
      return;
    }
    if (layer == 'default' && streak >= 6) {
      task['strategyLayer'] = 'fallback';
      task['strategyFailStreak'] = 0;
      _clearSmartTaskAcquisitionLock(task, reason: '默认方式受阻，正在启用更多尝试以继续完成数量');
      if (_smartUsesLegacyPriorityPipeline(siteProfile)) {
        // X/91：原管线之外再开放直链等备用获取，仍保留扩大探索。
        task['allowLegacyAlternateAcquire'] = true;
        task['skipSniffAcquire'] = false;
        task['preferSniffFirst'] = true;
        task['matchStage'] = '原智能受阻 · 尝试更多下载方式';
        _showSmartOperation('原可靠方式受阻，正在尝试其他下载方式');
        if (task['allowBroadenDiscovery'] == true) {
          _broadenSmartDiscovery(task, '默认管线受阻，扩大探索并启用备用获取');
        } else {
          Future<void>.delayed(const Duration(milliseconds: 120), () {
            if (identical(_smartDownloadTask, task)) {
              unawaited(_advanceSmartDownload(_currentUrl));
            }
          });
        }
        return;
      }
      if (task['allowBroadenDiscovery'] == true) {
        _applySiteDefaultAcquisition(task);
        task['matchStage'] = '默认受阻 · 扩大站内探索';
        _broadenSmartDiscovery(task, '默认管线受阻，扩大探索');
      } else {
        // 通用站兜底：先开有限扩大探索，再不行才请示范。
        task['allowBroadenDiscovery'] = true;
        task['gestureMode'] = false;
        task['phase'] = 'collecting_site_results';
        task['lockedAcquisition'] = 'site_address';
        task['lockedFailStreak'] = 0;
        _applyAcquisitionLockPrefs(task, 'site_address');
        task['matchStage'] = '默认受阻 · 站内地址 + 扩大探索';
        _broadenSmartDiscovery(task, '默认管线受阻，启用站内探索兜底');
      }
      return;
    }
    if (layer == 'fallback' && streak >= 5) {
      unawaited(_tryEnterSmartDemoAfterExhaustion(task, '多种自动方式连续未成功'));
    }
  }

  Future<void> _renameSmartStrategy(String key, String newName) async {
    final recipe = _smartDemoRecipes[key];
    if (recipe == null) return;
    final trimmed = newName.trim();
    if (trimmed.isEmpty) {
      recipe['nameCustom'] = false;
      _ensureSmartStrategyName(recipe);
    } else {
      recipe['name'] = trimmed;
      recipe['nameCustom'] = true;
    }
    recipe['updatedAt'] = DateTime.now().toIso8601String();
    await _saveSmartDemoRecipes();
  }

  Future<void> _deleteSmartStrategy(String key) async {
    if (!_smartDemoRecipes.containsKey(key)) return;
    _smartDemoRecipes.remove(key);
    await _saveSmartDemoRecipes();
  }

  Future<void> _promptRenameSmartStrategy(
    BuildContext dialogContext,
    String key,
    VoidCallback onChanged,
  ) async {
    final recipe = _smartDemoRecipes[key];
    if (recipe == null) return;
    final controller = TextEditingController(
      text: (recipe['name'] ?? '').toString(),
    );
    final ok = await showDialog<bool>(
      context: dialogContext,
      builder:
          (ctx) => AlertDialog(
            title: const Text('重命名策略'),
            content: TextField(
              controller: controller,
              autofocus: true,
              decoration: const InputDecoration(
                labelText: '策略名称',
                hintText: '例如：91·详情·长按',
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx, false),
                child: const Text('取消'),
              ),
              TextButton(
                onPressed: () => Navigator.pop(ctx, true),
                child: const Text('保存'),
              ),
            ],
          ),
    );
    if (ok == true) {
      await _renameSmartStrategy(key, controller.text);
      onChanged();
    }
    controller.dispose();
  }

  bool _isSmartDemoLearningActive([Map<String, dynamic>? task]) {
    final active = task ?? _smartDownloadTask;
    return active != null && active['demoPhase'] == 'demo';
  }

  Future<double> _readSmartPageScrollY() async {
    final controller = _controller;
    if (controller == null) return 0;
    try {
      final result = await controller.evaluateJavascript(
        source:
            '(function(){const r=document.scrollingElement||document.documentElement;return r?r.scrollTop:0;})()',
      );
      if (result is num) return result.toDouble();
      return double.tryParse(result?.toString() ?? '') ?? 0;
    } catch (_) {
      return 0;
    }
  }

  Future<void> _recordSmartDemoStep(Map<String, dynamic> task) async {
    final steps = task['demoSteps'];
    if (steps is! List) return;
    final scrollY = await _readSmartPageScrollY();
    steps.add(<String, dynamic>{
      'pageUrl': _currentUrl,
      'scrollY': scrollY,
      'at': DateTime.now().toIso8601String(),
    });
  }

  Map<String, dynamic> _inferSmartDemoRecipe(Map<String, dynamic> task) {
    final steps = (task['demoSteps'] as List?) ?? const [];
    final siteProfile = (task['siteProfile'] ?? '').toString();
    final lastAcq = (task['lastSuccessAcquisition'] ?? '').toString();
    var acquisition = 'longpress_inplace';
    var traversal = (task['smartRunMode'] == 'list') ? 'list' : 'nearby';
    var scrollBetween = false;
    if (lastAcq.isNotEmpty) {
      acquisition = lastAcq;
    } else if (_smartUsesLegacyPriorityPipeline(siteProfile) && steps.isEmpty) {
      acquisition = siteProfile == 'x' ? 'legacy_x' : 'legacy_91';
    }
    if (steps.length >= 2) {
      final a = Map<String, dynamic>.from(steps[steps.length - 2] as Map);
      final b = Map<String, dynamic>.from(steps[steps.length - 1] as Map);
      final urlA = (a['pageUrl'] ?? '').toString();
      final urlB = (b['pageUrl'] ?? '').toString();
      final yA = (a['scrollY'] as num?)?.toDouble() ?? 0;
      final yB = (b['scrollY'] as num?)?.toDouble() ?? 0;
      if (!_isSameLoadedDocument(urlA, urlB)) {
        if (lastAcq.isEmpty) acquisition = 'detail_longpress';
      }
      if ((yB - yA).abs() > 120) {
        scrollBetween = true;
        traversal = 'nearby_scroll';
      }
    }
    return <String, dynamic>{
      'acquisition': acquisition,
      'traversal': traversal,
      'scrollBetween': scrollBetween,
      'updatedAt': DateTime.now().toIso8601String(),
      'demoCount': (task['demoRequired'] as int?) ?? 2,
    };
  }

  Future<void> _persistSmartDemoRecipe(
    Map<String, dynamic> task, {
    bool allowRewrite = false,
  }) async {
    await _loadSmartDemoRecipes();
    final host = (task['host'] ?? '').toString();
    final pageType = (task['demoPageType'] ?? 'feed').toString();
    if (host.isEmpty) return;
    final key = _smartDemoRecipeKey(host: host, pageType: pageType);
    final previous = _smartDemoRecipes[key];
    // 自动收尾只累计成功次数，避免浅层推断覆盖示范学到的强经验。
    if (previous != null && !allowRewrite) {
      final prevAcq = _normalizeSmartAcquisition(
        (previous['acquisition'] ?? '').toString(),
      );
      final lastAcq = _normalizeSmartAcquisition(
        (task['lastSuccessAcquisition'] ?? '').toString(),
      );
      final bump = 1;
      previous['successes'] = ((previous['successes'] as int?) ?? 0) + bump;
      previous['updatedAt'] = DateTime.now().toIso8601String();
      final isUserDemo =
          previous['source'] == 'user_demo' || previous['demoTaught'] == true;
      // 用户示范经验：自动阶段不得改写 acquisition。
      if (!isUserDemo &&
          lastAcq.isNotEmpty &&
          prevAcq.isNotEmpty &&
          lastAcq != prevAcq &&
          (task['demoPhase'] == 'auto')) {
        previous['acquisition'] = lastAcq;
        if (previous['nameCustom'] != true) {
          previous['nameCustom'] = false;
          _ensureSmartStrategyName(previous);
        }
      }
      _smartDemoRecipes[key] = previous;
      await _saveSmartDemoRecipes();
      task['learnedRecipe'] = previous;
      debugPrint('智能下载策略已累计: $key -> ${previous['name']} +$bump');
      return;
    }
    final recipe = _inferSmartDemoRecipe(task);
    recipe['host'] = host;
    recipe['pageType'] = pageType;
    recipe['successes'] = ((previous?['successes'] as int?) ?? 0) + 1;
    if (allowRewrite ||
        task['demoPhase'] == 'demo' ||
        task['userRequestedDemo'] == true) {
      recipe['source'] = 'user_demo';
      recipe['demoTaught'] = true;
    } else if (previous != null &&
        (previous['source'] == 'user_demo' || previous['demoTaught'] == true)) {
      recipe['source'] = 'user_demo';
      recipe['demoTaught'] = true;
    } else {
      recipe['source'] = previous?['source'] ?? 'auto';
      recipe['demoTaught'] = previous?['demoTaught'] == true;
    }
    if (previous != null && previous['nameCustom'] == true) {
      recipe['name'] = previous['name'];
      recipe['nameCustom'] = true;
    } else {
      recipe['nameCustom'] = false;
      _ensureSmartStrategyName(recipe);
    }
    _smartDemoRecipes[key] = recipe;
    await _saveSmartDemoRecipes();
    task['learnedRecipe'] = recipe;
    debugPrint('智能下载策略已保存: $key -> ${recipe['name']} $recipe');
  }

  /// 动作编排真实入库成功后：写入全局可借用成功列表，并设为本站默认。
  Future<void> _persistSiteSuccessActionRecipe(
    Map<String, dynamic> task,
  ) async {
    try {
      final host = _normalizeSmartHost((task['host'] ?? '').toString());
      if (host.isEmpty) return;
      final raw = task['actionRecipeJson'];
      if (raw is! Map) return;
      // 保留套路来源 host；本站默认指针用 defaultForHost=当前站。
      final recipe = SmartActionRecipe.fromJson(Map<String, dynamic>.from(raw));
      if (recipe.steps.isEmpty) return;
      final axis = (task['advanceAxisHint'] ?? '').toString().trim();
      final mode = (task['advanceMode'] ?? '').toString().trim();
      await SmartActionRecipeStore.markLastSuccess(
        recipe,
        advanceAxisHint: axis,
        advanceMode: mode,
        defaultForHost: host,
      );
      debugPrint(
        '成功动作套路已保存(全局可借用/本站默认): $host -> ${recipe.name} '
        'axis=$axis mode=$mode steps=${recipe.steps.length}',
      );
    } catch (e) {
      debugPrint('保存本站成功动作套路失败: $e');
    }
  }

  Future<void> _finishSmartDemoLearning(Map<String, dynamic> task) async {
    if (!identical(_smartDownloadTask, task)) return;
    final siteProfile = (task['siteProfile'] ?? '').toString();
    // 用示范结束时的真实页面类型落盘，便于下次同场景复用。
    task['demoPageType'] = _smartDemoPageType(
      url: _currentUrl,
      siteProfile: siteProfile,
      keyword: (task['keyword'] ?? '').toString(),
      smartRunMode: (task['smartRunMode'] ?? 'nearby').toString(),
    );
    await _persistSmartDemoRecipe(task, allowRewrite: true);
    task['demoPhase'] = 'auto';
    final isLegacy = _smartUsesLegacyPriorityPipeline(siteProfile);
    final learned = task['learnedRecipe'];
    final learnedAcq =
        learned is Map
            ? _normalizeSmartAcquisition(
              (learned['acquisition'] ?? '').toString(),
            )
            : '';
    // 新学会的方式立刻成为本任务优先成功经验，并已持久化供下次复用。
    if (learned is Map) {
      final host = (task['host'] ?? '').toString();
      final pageType = (task['demoPageType'] ?? 'feed').toString();
      final key = _smartDemoRecipeKey(host: host, pageType: pageType);
      _bindSmartStrategyToTask(
        task,
        Map<String, dynamic>.from(learned),
        strategyKey: key,
        manualPick: false,
      );
    }
    if (isLegacy) {
      final startedFromCurrent = task['startedFromCurrentPage'] == true;
      final keywordFirst91 = task['strict91KeywordMode'] == true;
      // 91 专有套路不启用手势引擎（与 a00c4bd 一致）。
      task['gestureMode'] =
          startedFromCurrent && !keywordFirst91 && siteProfile != '91';
      task['protectVisibleGestureFlow'] = task['gestureMode'] == true;
      task['allowBroadenDiscovery'] = true;
      if (learnedAcq == 'sniff' || learnedAcq == 'site_address') {
        task['allowLegacyAlternateAcquire'] = true;
      }
    } else if (_smartUsesFacebookPipeline(siteProfile)) {
      task['gestureMode'] = true;
      task['protectVisibleGestureFlow'] = true;
      task['facebookPipeline'] = true;
      task['allowBroadenDiscovery'] = false;
      if (learnedAcq == 'sniff' || learnedAcq == 'site_address') {
        task['allowLegacyAlternateAcquire'] = true;
      }
    } else {
      task['gestureMode'] = true;
      task['protectVisibleGestureFlow'] = true;
    }
    final fallbackAcq =
        isLegacy
            ? (siteProfile == 'x' ? 'legacy_x' : 'legacy_91')
            : _smartUsesFacebookPipeline(siteProfile)
            ? 'legacy_facebook'
            : 'longpress_inplace';
    _lockSmartTaskAcquisition(
      task,
      learnedAcq.isNotEmpty ? learnedAcq : fallbackAcq,
      announce: false,
    );
    task['matchStage'] = '示范完成 · 沿用新成功经验';
    _showSmartOperation('已学会并保存成功经验，将优先沿用继续下载剩余媒体');
    _updateSmartDiscoveryProgress(task, 'demo_learning_done');
    if ((task['success'] as int) >= (task['target'] as int)) {
      await _finishSmartDownload();
      return;
    }
    Future<void>.delayed(const Duration(milliseconds: 400), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_advanceSmartDownload(_currentUrl));
      }
    });
  }

  bool _isSmartHardStopReason(String reason) {
    return reason.contains('用户已停止') ||
        reason.contains('5 小时') ||
        reason.contains('写入媒体库失败') ||
        reason.contains('地址无效');
  }

  Future<bool> _tryV1SmartSniffAcquire(Map<String, dynamic> task) async {
    if (!identical(_smartDownloadTask, task) || _controller == null) {
      return false;
    }
    if (task['gestureDownloadPending'] == true) return false;
    final lastAt = task['v1LastSniffAt'] as DateTime?;
    if (lastAt != null &&
        DateTime.now().difference(lastAt) < const Duration(milliseconds: 900)) {
      return false;
    }
    task['v1LastSniffAt'] = DateTime.now();

    final allowMixed = task['allowMixedMedia'] == true;
    final mediaType = task['mediaType'] as MediaType;
    final seen = task['seenMediaUrls'] as Set<String>;
    final urls = await _collectV1SmartPageMediaUrls(
      imagesOnly: !allowMixed && mediaType == MediaType.image,
      videosOnly: !allowMixed && mediaType == MediaType.video,
      preferVideo: allowMixed || mediaType == MediaType.video,
    );
    if (urls.isEmpty) {
      // 空直链也算本轮无进展，推动升层/解锁，避免只靠看门狗。
      final empty = ((task['sniffEmptyScrolls'] as int?) ?? 0) + 1;
      task['sniffEmptyScrolls'] = empty;
      if (empty >= 3) {
        task['sniffEmptyScrolls'] = 0;
        _noteSmartTaskAcquisitionFailure(task);
      }
      return false;
    }

    for (final rawUrl in urls) {
      if (!identical(_smartDownloadTask, task)) return false;
      final url = rawUrl.trim();
      if (url.isEmpty) continue;
      final norm = _normalizeVideoSourceUrl(url);
      if (seen.contains(url) || (norm.isNotEmpty && seen.contains(norm))) {
        continue;
      }
      seen.add(url);
      if (norm.isNotEmpty) seen.add(norm);

      final looksImage = RegExp(
        r'\.(jpg|jpeg|png|gif|webp|bmp)(\?|#|$)',
        caseSensitive: false,
      ).hasMatch(url);
      final looksVideo =
          RegExp(
            r'\.(mp4|webm|mov|m3u8|m3u|mpd)(\?|#|$)',
            caseSensitive: false,
          ).hasMatch(url) ||
          url.toLowerCase().contains('m3u8') ||
          url.toLowerCase().contains('/video');
      if (!allowMixed && mediaType == MediaType.image && looksVideo) continue;
      if (!allowMixed &&
          mediaType == MediaType.video &&
          looksImage &&
          !looksVideo) {
        continue;
      }
      final downloadType =
          looksVideo
              ? MediaType.video
              : looksImage
              ? MediaType.image
              : (allowMixed ? MediaType.video : mediaType);

      task['phase'] = 'v1_sniff_downloading';
      task['matchStage'] = 'V1 · 优先直链下载';
      _showSmartOperation('发现媒体地址，正在直链保存');
      _updateSmartDiscoveryProgress(task, 'v1_sniff_downloading');

      var failureType = '';
      final ok = await _downloadMediaRobustly(
        item: <String, dynamic>{
          'url': url,
          'pageUrl': _currentUrl,
          'videoUrl': downloadType == MediaType.video ? url : '',
          'candidateUrls': <String>[url],
          'downloadOrigin': 'smart_batch',
          'smartTask': task,
          'title': '',
        },
        showModalDialog: false,
        showResultHint: false,
        onFailureType: (type) => failureType = type,
        minFileBytes: task['effectiveMinVideoBytes'] as int?,
        maxFileBytes: task['effectiveMaxVideoBytes'] as int?,
      );
      if (ok) {
        task['success'] = (task['success'] as int) + 1;
        task['gestureConsecutiveFailures'] = 0;
        _lockSmartTaskAcquisition(task, 'sniff');
        _noteSmartStrategyProgress(task, success: true);
        _updateSmartDiscoveryProgress(task, 'v1_sniff_success');
        if ((task['success'] as int) >= (task['target'] as int)) {
          await _finishSmartDownload();
          return true;
        }
        Future<void>.delayed(const Duration(milliseconds: 350), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return true;
      }
      if (failureType == 'library_save_failed') {
        await _finishSmartDownload('写入媒体库失败，已停止任务；请检查存储空间和数据库状态');
        return true;
      }
      if (<String>{
        'already_in_library',
        'already_in_smart_task',
        'duplicate_name_in_smart_task',
        'already_downloading',
      }.contains(failureType)) {
        continue;
      }
      task['failed'] = (task['failed'] as int) + 1;
      task['lastSniffAttemptedDownload'] = true;
    }
    if (task['lastSniffAttemptedDownload'] == true) {
      task['lastSniffAttemptedDownload'] = false;
      final locked = (task['lockedAcquisition'] ?? '').toString();
      if (locked == 'sniff' || locked.isEmpty) {
        _noteSmartTaskAcquisitionFailure(task);
      }
    }
    return false;
  }

  Future<List<String>> _collectV1SmartPageMediaUrls({
    required bool imagesOnly,
    required bool videosOnly,
    required bool preferVideo,
  }) async {
    final controller = _controller;
    if (controller == null) return const <String>[];
    try {
      final result = await controller.evaluateJavascript(
        source: '''
(() => {
  const out = [];
  const push = (u) => {
    try {
      if (!u) return;
      const abs = new URL(String(u), location.href).toString();
      if (!/^https?:/i.test(abs)) return;
      if (out.includes(abs)) return;
      out.push(abs);
    } catch (_) {}
  };
  const early = window.__appEarlyMediaRequests;
  if (early && typeof early.forEach === 'function') {
    early.forEach((meta, url) => push(url));
  } else if (early && typeof early.entries === 'function') {
    for (const [url] of early.entries()) push(url);
  }
  document.querySelectorAll('video').forEach((el) => {
    push(el.currentSrc || el.src);
    el.querySelectorAll('source[src]').forEach((s) => push(s.src));
  });
  document.querySelectorAll('img[src]').forEach((el) => push(el.currentSrc || el.src));
  document.querySelectorAll('a[href]').forEach((el) => {
    const href = el.href || '';
    if (/\\.(m3u8|mp4|webm|mov)(\\?|#|\$)/i.test(href)) push(href);
  });
  return out.slice(0, 80);
})()
''',
      );
      final raw = <String>[];
      dynamic decoded = result;
      if (decoded is String) {
        final text = decoded.trim();
        if (text.startsWith('[')) {
          try {
            decoded = jsonDecode(text);
          } catch (_) {}
        }
      }
      if (decoded is List) {
        for (final row in decoded) {
          final s = row?.toString().trim() ?? '';
          if (s.isNotEmpty && s != 'null') raw.add(s);
        }
      }
      bool isImage(String u) => RegExp(
        r'\.(jpg|jpeg|png|gif|webp|bmp)(\?|#|$)',
        caseSensitive: false,
      ).hasMatch(u);
      bool isVideo(String u) {
        final lower = u.toLowerCase();
        return RegExp(
              r'\.(mp4|webm|mov|m3u8|m3u|mpd)(\?|#|$)',
              caseSensitive: false,
            ).hasMatch(u) ||
            lower.contains('m3u8') ||
            lower.contains('mpegurl');
      }

      var filtered =
          raw.where((u) {
            if (_isLikelyAdUrl(u)) return false;
            if (imagesOnly) {
              return isImage(u) &&
                  !isVideo(u) &&
                  !_isLikelyPosterOrThumbImageUrl(u);
            }
            if (videosOnly) {
              // 视频任务：只接受真实流，拒绝海报/缩略图冒充。
              return _isSniffVideoStreamUrl(u) ||
                  (isVideo(u) && !_isLikelyPosterOrThumbImageUrl(u));
            }
            if (isImage(u) && _isLikelyPosterOrThumbImageUrl(u)) return false;
            return true;
          }).toList();
      if (preferVideo || videosOnly) {
        filtered = [
          ...filtered.where((u) => _isSniffVideoStreamUrl(u) || isVideo(u)),
          ...filtered.where((u) => !_isSniffVideoStreamUrl(u) && !isVideo(u)),
        ];
      }
      return filtered;
    } catch (e) {
      debugPrint('V1 智能下载直链采集失败: $e');
      return const <String>[];
    }
  }

  String _baiduVideoSearchUrl(String keyword, {int page = 0}) {
    return Uri.https('m.baidu.com', '/s', <String, String>{
      'pd': 'video',
      'sa': 'vs_tab',
      'word': keyword.trim(),
      if (page > 0) 'pn': '${page * 10}',
    }).toString();
  }

  bool _isBaiduVideoResultsUrl(String url) {
    final uri = Uri.tryParse(url);
    return uri != null &&
        _isBaiduHost(uri.host) &&
        uri.path == '/s' &&
        uri.queryParameters['pd'] == 'video';
  }

  bool _isUnsafeBaiduSmartPage(String url) {
    final uri = Uri.tryParse(url);
    if (uri == null) return true;
    final host = uri.host.toLowerCase();
    final value = url.toLowerCase();
    return !_isBaiduHost(host) ||
        host == 'ufo.baidu.com' ||
        host == 'mysearch.pae.baidu.com' ||
        value.contains('sd_privacy_terms') ||
        value.startsWith('chrome-error://');
  }

  Future<bool> _recoverStrictGesturePage(
    Map<String, dynamic> task,
    String reason, {
    bool nextPage = false,
  }) async {
    if (task['strictBaiduVideoMode'] != true) return false;
    final keyword = (task['keyword'] ?? '').toString().trim();
    if (keyword.isEmpty) return false;

    var page = (task['strictBaiduPage'] as int?) ?? 0;
    if (nextPage) page++;
    task['strictBaiduPage'] = page;
    final searchUrl = _baiduVideoSearchUrl(keyword, page: page);
    task['strictBaiduSearchUrl'] = searchUrl;
    task['gestureMode'] = true;
    task['gestureKeywordSubmitted'] = true;
    task['gestureTypeFilterApplied'] = true;
    task['gestureDetailMode'] = false;
    task['gestureReturnUrl'] = '';
    task['gestureDownloadPending'] = false;
    task['gestureWaitCount'] = 0;
    task['gesturePrepareCount'] = 0;
    task['gestureNoMoveCount'] = 0;
    task['gestureEngineFailures'] = 0;
    task['gestureConsecutiveFailures'] = 0;
    task['phase'] = 'baidu_video_search_loading';
    task['matchStage'] = '百度视频结果页 · $reason';
    debugPrint(
      'Smart Baidu video: recover page=$page reason=$reason url=$searchUrl',
    );
    _showSmartOperation('返回“$keyword”视频结果页，继续按顺序查找');
    _loadUrl(searchUrl);
    return true;
  }

  Future<bool> _recoverVisibleGesturePage(
    Map<String, dynamic> task,
    String reason, {
    bool nextPage = false,
  }) async {
    if (await _recoverStrictGesturePage(task, reason, nextPage: nextPage)) {
      return true;
    }
    if (task['strict91KeywordMode'] == true) {
      final searchUrl = (task['strict91SearchUrl'] ?? '').toString();
      if (searchUrl.isEmpty) return false;
      task['gestureMode'] = false;
      task['gestureDownloadPending'] = false;
      task['gestureEngineFailures'] = 0;
      task['gestureConsecutiveFailures'] = 0;
      task['phase'] = 'collecting_search_results';
      task['matchStage'] = '91 关键词结果页 · 按卡片顺序查找';
      debugPrint(
        'Smart 91 strict: leaving generic gesture recovery '
        'reason=$reason url=$searchUrl',
      );
      _showSmartOperation('识别当前关键词结果卡片，按顺序进入下载');
      if (!_isSame91TaskPage(searchUrl, _currentUrl)) {
        _loadUrl(searchUrl);
      } else {
        Future<void>.delayed(const Duration(milliseconds: 120), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
      }
      return true;
    }
    if (task['protectVisibleGestureFlow'] != true) return false;
    if (nextPage && await _returnFromStalledSmartPage(task, reason)) {
      return true;
    }
    if (task['siteProfile'] == 'x' &&
        (task['keyword'] ?? '').toString().trim().isEmpty) {
      task['gestureMode'] = true;
      task['gestureDetailMode'] = false;
      task['gestureReturnUrl'] = '';
      task['gestureDownloadPending'] = false;
      task['gestureEngineFailures'] = 0;
      task['gestureConsecutiveFailures'] = 0;
      task['phase'] = 'scanning_feed';
      task['matchStage'] = 'X 沉浸模式 · 切换下一条媒体';
      debugPrint('Smart X immersive recovery: reason=$reason url=$_currentUrl');
      _continueSmartFeed(task, madeProgress: false);
      return true;
    }

    final taskHost = (task['host'] ?? '').toString();
    final recoveryUrl = <String>[
      (task['gestureReturnUrl'] ?? '').toString(),
      (task['gestureResultUrl'] ?? '').toString(),
      (task['gestureLastSafeUrl'] ?? '').toString(),
      (task['originUrl'] ?? '').toString(),
    ].firstWhere((value) {
      final uri = Uri.tryParse(value);
      return uri != null && uri.hasScheme && _sameSmartSite(uri.host, taskHost);
    }, orElse: () => '');
    if (recoveryUrl.isEmpty) return false;

    final alreadyOnRecoveryPage = _isSameLoadedDocument(
      recoveryUrl,
      _currentUrl,
    );
    if (alreadyOnRecoveryPage && nextPage) return false;
    final recoveryCount = ((task['gestureRecoveryCount'] as int?) ?? 0) + 1;
    if (alreadyOnRecoveryPage && recoveryCount > 3) return false;

    task['gestureRecoveryCount'] = recoveryCount;
    task['gestureMode'] = true;
    task['gestureDetailMode'] = false;
    task['gestureReturnUrl'] = '';
    task['gestureDownloadPending'] = false;
    task['gestureWaitCount'] = 0;
    task['gesturePrepareCount'] = 0;
    task['gestureNoMoveCount'] = 0;
    task['gestureEngineFailures'] = 0;
    task['phase'] = 'gesture_recovering_result';
    task['matchStage'] = '返回媒体结果页 · $reason';
    debugPrint(
      'Smart visible recovery: profile=${task['siteProfile']} '
      'reason=$reason url=$recoveryUrl',
    );
    _showSmartOperation('返回上一层媒体列表，继续查找');
    _loadUrl(recoveryUrl);
    return true;
  }

  Future<String> _readSmartPageMotionSnapshot() async {
    final controller = _controller;
    if (controller == null) return '';
    try {
      final result = await controller.evaluateJavascript(
        source: '''
          (() => {
            const root = document.scrollingElement || document.documentElement;
            const visible = element => {
              const r = element.getBoundingClientRect();
              return r.width > 20 && r.height > 20 &&
                r.bottom > 0 && r.top < innerHeight;
            };
            const scrollables = Array.from(document.querySelectorAll('*'))
              .filter(element => {
                if (!visible(element)) return false;
                const style = getComputedStyle(element);
                return element.scrollHeight > element.clientHeight + 40 &&
                  /(auto|scroll)/.test(style.overflowY);
              })
              .slice(0, 8)
              .map(element => [
                Math.round(element.scrollTop || 0),
                Math.round(element.scrollHeight || 0),
                Math.round(element.clientHeight || 0)
              ].join(':'));
            const media = Array.from(document.querySelectorAll('video, img'))
              .filter(visible)
              .map(element => {
                const r = element.getBoundingClientRect();
                const scope = element.closest(
                  'article, [data-testid="cellInnerDiv"], [role="dialog"]'
                );
                const status = scope?.querySelector('a[href*="/status/"]')?.href || '';
                const source = element.currentSrc || element.src || element.poster || '';
                return [
                  status,
                  String(source).split('?')[0],
                  Math.round(r.top),
                  Math.round(r.height)
                ].join('|');
              })
              .slice(0, 6);
            return JSON.stringify({
              href: location.href,
              rootTop: Math.round(root?.scrollTop || window.scrollY || 0),
              scrollables,
              media
            });
          })()
        ''',
      );
      return result?.toString() ?? '';
    } catch (_) {
      return '';
    }
  }

  Future<bool> _returnFromStalledSmartPage(
    Map<String, dynamic> task,
    String reason,
  ) async {
    final controller = _controller;
    if (controller == null || !identical(_smartDownloadTask, task)) {
      return false;
    }
    final actualUrl = (await controller.getUrl())?.toString() ?? _currentUrl;
    final taskHost = (task['host'] ?? '').toString();
    final knownReturnUrl = <String>[
      (task['xReturnUrl'] ?? '').toString(),
      (task['gestureReturnUrl'] ?? '').toString(),
      (task['cardListUrl'] ?? '').toString(),
      (task['candidateListUrl'] ?? '').toString(),
      (task['gestureResultUrl'] ?? '').toString(),
      (task['originUrl'] ?? '').toString(),
    ].firstWhere((value) {
      final uri = Uri.tryParse(value);
      return uri != null &&
          uri.hasScheme &&
          _sameSmartSite(uri.host, taskHost) &&
          !_isSameLoadedDocument(value, actualUrl);
    }, orElse: () => '');

    final isXDetail =
        task['siteProfile'] == 'x' &&
        (task['xEnteredDetailFromList'] == true ||
            _isXStatusDetailPage(actualUrl) ||
            _isXMediaViewerPage(actualUrl));
    if (isXDetail && (task['xReturnUrl'] ?? '').toString().startsWith('http')) {
      task['feedStalledCount'] = 0;
      task['gestureNoMoveCount'] = 0;
      task['matchStage'] = '当前详情页无法继续 · 返回原信息流';
      _showSmartOperation('当前页面已经到底，返回上一级继续下载');
      await _returnFromXSmartCard(task);
      return true;
    }

    // X's no-keyword immersive viewer keeps transient entries in WebView
    // history. When there is no proven list-page return URL, going back can
    // reopen an already exhausted video and leave the FSM without a next
    // callback. Stay in the viewer and advance to the next item instead.
    if (task['siteProfile'] == 'x' &&
        (task['keyword'] ?? '').toString().trim().isEmpty &&
        knownReturnUrl.isEmpty) {
      task['feedStalledCount'] = 0;
      task['gestureNoMoveCount'] = 0;
      task['gestureDetailMode'] = false;
      task['gestureReturnUrl'] = '';
      task['gestureDownloadPending'] = false;
      task['phase'] = 'scanning_feed';
      task['matchStage'] = 'X 当前视频不可用 · 跳到下一条';
      debugPrint(
        '[SMART_RECOVERY] X exhausted media has no safe return URL; '
        'advance in place current=$actualUrl reason=$reason',
      );
      _showSmartOperation('当前视频无法下载，自动跳到下一条');
      _continueSmartFeed(task, madeProgress: false);
      return true;
    }

    if (knownReturnUrl.isEmpty && !await controller.canGoBack()) return false;
    task['feedStalledCount'] = 0;
    task['gestureNoMoveCount'] = 0;
    task['phase'] = 'gesture_returning';
    task['matchStage'] = '当前页面无法继续 · 返回上一层';
    _showSmartOperation('连续滑动没有变化，返回上一页继续查找');
    debugPrint(
      'Smart stalled page return: reason=$reason '
      'current=$actualUrl target=$knownReturnUrl',
    );
    if (task['siteProfile'] == 'x' && knownReturnUrl.startsWith('http')) {
      task['phase'] = 'x_search_returning';
      task['xReturnExpectedUrl'] = knownReturnUrl;
      task['xReturnAttempts'] = 0;
      _loadUrl(knownReturnUrl);
      return true;
    }
    if (await controller.canGoBack()) {
      await controller.goBack();
      await Future<void>.delayed(const Duration(milliseconds: 280));
    }
    final afterBack = (await controller.getUrl())?.toString() ?? '';
    final afterHost = Uri.tryParse(afterBack)?.host ?? '';
    if (knownReturnUrl.isNotEmpty &&
        !_isSameLoadedDocument(knownReturnUrl, afterBack)) {
      _loadUrl(knownReturnUrl);
    } else if (afterHost.isNotEmpty && !_sameSmartSite(afterHost, taskHost)) {
      final originUrl = (task['originUrl'] ?? '').toString();
      if (originUrl.startsWith('http')) _loadUrl(originUrl);
    }
    Future<void>.delayed(const Duration(milliseconds: 800), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_advanceSmartDownload(_currentUrl));
      }
    });
    return true;
  }

  Future<bool> _advanceVisibleSmartGesture(Map<String, dynamic> task) async {
    if (!identical(_smartDownloadTask, task) || _controller == null) {
      return false;
    }
    if (task['demoPhase'] == 'demo') {
      final need = (task['demoRequired'] as int?) ?? 2;
      final done = (task['success'] as int?) ?? 0;
      task['matchStage'] = '示范学习 · 等待手动长按';
      _showSmartOperation('请手动长按下载第 ${done + 1}/$need 个媒体（示范中）');
      _updateSmartDiscoveryProgress(task, 'demo_waiting_user');
      return true;
    }
    final taskHost = (task['host'] ?? '').toString().toLowerCase();
    final currentHost =
        Uri.tryParse(
          _currentUrl,
        )?.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '') ??
        '';
    final strictBaiduVideoMode = task['strictBaiduVideoMode'] == true;
    if (strictBaiduVideoMode && _isUnsafeBaiduSmartPage(_currentUrl)) {
      return _recoverStrictGesturePage(task, '拦截无关或异常页面');
    }
    final staysOnSite =
        _sameSmartSite(currentHost, taskHost) ||
        (strictBaiduVideoMode && _isBaiduHost(currentHost));
    if (taskHost.isNotEmpty && currentHost.isNotEmpty && !staysOnSite) {
      if (await _recoverVisibleGesturePage(task, '拦截离开当前网站')) {
        return true;
      }
      return false;
    }
    if (!strictBaiduVideoMode || _isBaiduVideoResultsUrl(_currentUrl)) {
      task['gestureLastSafeUrl'] = _currentUrl;
    }
    if (task['gestureDownloadPending'] == true) {
      final startedAt = task['gestureDownloadStartedAt'] as DateTime?;
      if (_smartUsesFacebookPipeline((task['siteProfile'] ?? '').toString()) &&
          startedAt != null &&
          DateTime.now().difference(startedAt) >=
              _kFacebookSmartRoundHardTimeout) {
        _cancelStalledSmartMediaDownloads('profile_grid_media_timeout');
        _longPressVideoDownloadInProgress = false;
        task['lastGestureFailureType'] = 'step_watchdog_timeout';
        await _completeSmartGestureDownload(false);
        return true;
      }
      final hasActiveDownload = _downloadTasks.any(
        (row) =>
            row['isSmartBatchMedia'] == true && row['status'] == 'downloading',
      );
      // HLS 等长视频下载可能远超 20 秒；有在途下载或长按保存进行中时绝不能提前判失败。
      if (hasActiveDownload || _longPressVideoDownloadInProgress) {
        task['matchStage'] = '等待当前视频下载完成';
        return true;
      }
      if (startedAt == null ||
          DateTime.now().difference(startedAt) < const Duration(seconds: 45)) {
        return true;
      }
      // A page may swallow synthetic touch events. Release the stalled
      // candidate and continue with the next visible item.
      await _completeSmartGestureDownload(false);
      return true;
    }

    // V1：非 X/91 优先尝试页面已暴露的直链，失败再走页内长按（不改 X/91 路径）。
    // 本任务若已锁定某方式：只沿用该方式，成功前不改道。
    final siteProfile = (task['siteProfile'] ?? '').toString();
    final lockedAcquisition = _normalizeSmartAcquisition(
      (task['lockedAcquisition'] ?? '').toString(),
    );
    // 通用站：优先直链（或锁定直链）。
    // X/91：默认走原智能；仅在 fallback 备用阶段才开放直链等额外尝试。
    final isLegacy = _smartUsesLegacyPriorityPipeline(siteProfile);
    final allowLegacyAlternate =
        isLegacy && task['allowLegacyAlternateAcquire'] == true;
    final allowSniff =
        (!isLegacy &&
            (lockedAcquisition == 'sniff' ||
                (lockedAcquisition.isEmpty &&
                    task['skipSniffAcquire'] != true))) ||
        (allowLegacyAlternate &&
            (lockedAcquisition == 'sniff' ||
                (lockedAcquisition.isEmpty &&
                    task['skipSniffAcquire'] != true)));
    if (allowSniff) {
      final sniffed = await _tryV1SmartSniffAcquire(task);
      if (sniffed) return true;
      // 已锁定直链：本轮没有可下直链时只滚动寻找，不改去长按。
      if (lockedAcquisition == 'sniff') {
        await _scrollPageForLockedSniff(task);
        return true;
      }
    }

    final phase = (task['phase'] ?? '').toString();
    if (task['xInlineActivationPending'] == true) {
      final activatedAt = task['xInlineActivatedAt'] as DateTime?;
      final elapsed =
          activatedAt == null
              ? const Duration(seconds: 3)
              : DateTime.now().difference(activatedAt);
      if (elapsed < const Duration(milliseconds: 2400)) {
        final remaining = const Duration(milliseconds: 2400) - elapsed;
        Future<void>.delayed(remaining, () {
          if (identical(_smartDownloadTask, task) &&
              task['xInlineActivationPending'] == true) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return true;
      }
      task['xInlineActivationPending'] = false;
      task['xInlineReadyToLongPress'] = true;
      task['phase'] = 'scanning_feed';
    }
    if (phase == 'gesture_opening_card') {
      final returnUrl = (task['gestureReturnUrl'] ?? '').toString();
      final startedAt = task['gestureActionStartedAt'] as DateTime?;
      final elapsed =
          startedAt == null
              ? const Duration(seconds: 3)
              : DateTime.now().difference(startedAt);
      final navigated =
          returnUrl.startsWith('http') &&
          !_isSameLoadedDocument(returnUrl, _currentUrl);
      if (!navigated && elapsed < const Duration(milliseconds: 2600)) {
        Future<void>.delayed(const Duration(milliseconds: 1300), () {
          if (identical(_smartDownloadTask, task) &&
              task['phase'] == 'gesture_opening_card') {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return true;
      }
      // URL changes, same-document modals and SPA route updates are all
      // treated as one detail layer. No second card click is allowed here.
      task['gestureDetailMode'] = true;
      task['phase'] = 'gesture_scanning_detail';
    } else if (phase == 'gesture_returning') {
      task['gestureDetailMode'] = false;
      task['gestureReturnUrl'] = '';
      task['phase'] = 'gesture_scanning_results';
    }
    if (task['gestureDetailMode'] != true &&
        (phase == 'gesture_searching' ||
            phase == 'gesture_filtering_type' ||
            phase == 'gesture_scanning_results' ||
            phase == 'gesture_recovering_result' ||
            phase == 'collecting_search_results' ||
            phase == 'x_search_loading' ||
            phase == 'baidu_video_search_loading') &&
        _currentUrl.startsWith('http')) {
      task['gestureResultUrl'] = _currentUrl;
      task['gestureRecoveryCount'] = 0;
    }

    final keyword = (task['keyword'] ?? '').toString().trim();
    final mediaType = task['mediaType'] as MediaType;
    final allowMixed = task['allowMixedMedia'] == true;
    final attempted = task['gestureAttemptedKeys'] as Set<String>;
    final attemptedJson = jsonEncode(attempted.toList());
    final keywordJson = jsonEncode(keyword.toLowerCase());
    final requestedType =
        allowMixed
            ? 'mixed'
            : mediaType == MediaType.image
            ? 'image'
            : 'video';
    final requestedTypeJson = jsonEncode(requestedType);
    final keywordAlreadySubmitted = task['gestureKeywordSubmitted'] == true;
    final typeFilterApplied = task['gestureTypeFilterApplied'] == true;
    final skipPendingWait = task['gestureSkipPendingWait'] == true;
    final gestureReturnUrl = (task['gestureReturnUrl'] ?? '').toString();
    final hasReturnPage = task['gestureDetailMode'] == true;
    final siteProfileJson = jsonEncode((task['siteProfile'] ?? 'generic'));
    final xInlineFeedMode = task['xInlineFeedMode'] == true;
    final xInlineReadyToLongPress = task['xInlineReadyToLongPress'] == true;

    try {
      final result = await _controller!.evaluateJavascript(
        source: '''
          (() => {
            const keyword = $keywordJson;
            const requestedType = $requestedTypeJson;
            const attempted = new Set($attemptedJson);
            const keywordAlreadySubmitted = $keywordAlreadySubmitted;
            const typeFilterApplied = $typeFilterApplied;
            const skipPendingWait = $skipPendingWait;
            const hasReturnPage = $hasReturnPage;
            const siteProfile = $siteProfileJson;
            const xInlineFeedMode = $xInlineFeedMode;
            const xInlineReadyToLongPress = $xInlineReadyToLongPress;
            const currentSearchInputs = Array.from(document.querySelectorAll(
              'input[type="search"], input[name="q"], input[name="s"], ' +
              'input[name*="search"], input[placeholder*="搜索"], ' +
              'input[placeholder*="关键词"], input[placeholder*="Search" i]'
            ));
            let decodedLocation = String(location.href || '').toLowerCase();
            try { decodedLocation = decodeURIComponent(decodedLocation); } catch (_) {}
            const trustedKeywordResults = !!keyword && (
              keywordAlreadySubmitted ||
              decodedLocation.includes(keyword) ||
              currentSearchInputs.some(input =>
                String(input.value || '').trim().toLowerCase() === keyword
              )
            );
            if (keyword && !keywordAlreadySubmitted) {
              const inputs = currentSearchInputs.filter(input => {
                const r = input.getBoundingClientRect();
                return r.width > 80 && r.height > 20 && r.bottom > 0 &&
                  r.top < innerHeight && !input.disabled;
              });
              const input = inputs[0];
              if (input && String(input.value || '').trim().toLowerCase() !== keyword) {
                input.focus();
                const setter = Object.getOwnPropertyDescriptor(
                  HTMLInputElement.prototype, 'value'
                );
                if (setter && setter.set) setter.set.call(input, keyword);
                else input.value = keyword;
                input.dispatchEvent(new Event('input', {bubbles:true}));
                input.dispatchEvent(new Event('change', {bubbles:true}));
                const form = input.closest('form');
                setTimeout(() => {
                  if (form && typeof form.requestSubmit === 'function') {
                    form.requestSubmit();
                  } else {
                    input.dispatchEvent(new KeyboardEvent('keydown', {
                      key:'Enter', code:'Enter', keyCode:13, which:13,
                      bubbles:true, cancelable:true
                    }));
                    input.dispatchEvent(new KeyboardEvent('keyup', {
                      key:'Enter', code:'Enter', keyCode:13, which:13,
                      bubbles:true, cancelable:true
                    }));
                  }
                }, 120);
                const r = input.getBoundingClientRect();
                return {
                  action:'search', key:'',
                  x:(r.left + r.width / 2) / Math.max(1, innerWidth),
                  y:(r.top + r.height / 2) / Math.max(1, innerHeight)
                };
              }
            }
            const visible = (el) => {
              const r = el.getBoundingClientRect();
              if (r.width < 80 || r.height < 64 ||
                  r.bottom <= 0 || r.top >= innerHeight ||
                  r.right <= 0 || r.left >= innerWidth) return false;
              const style = getComputedStyle(el);
              return style.display !== 'none' && style.visibility !== 'hidden' &&
                Number(style.opacity || 1) > 0.05;
            };
            const mediaKind = (el) => {
              if (el.tagName === 'VIDEO') return 'video';
              if (el.tagName === 'IMG' || el.tagName === 'CANVAS') return 'image';
              const style = String(
                (el.style && el.style.backgroundImage) ||
                getComputedStyle(el).backgroundImage || ''
              );
              const source = String(
                el.getAttribute('data-original') ||
                el.getAttribute('data-src') || ''
              );
              if (style.includes('url(') ||
                  /\\.(jpe?g|png|gif|webp|bmp|avif)(\\?|#|\$)/i.test(source)) {
                return 'image';
              }
              return '';
            };
            const mediaSource = (el) => {
              const direct = String(
                el.getAttribute('data-original') ||
                el.getAttribute('data-src') ||
                el.currentSrc || el.src || el.getAttribute('poster') || ''
              ).trim();
              if (direct) return direct;
              const bg = String(
                (el.style && el.style.backgroundImage) ||
                getComputedStyle(el).backgroundImage || ''
              );
              const match = bg.match(/url\\(['"]?([^'")]+)['"]?\\)/i);
              return match ? match[1] : '';
            };
            const isUsefulMedia = (el) => {
              const kind = mediaKind(el);
              if (!kind) return false;
              const r = el.getBoundingClientRect();
              const source = mediaSource(el).toLowerCase();
              const hint = String(
                (el.className && (el.className.baseVal || el.className)) || ''
              ).toLowerCase() + ' ' +
                String(el.id || '').toLowerCase() + ' ' +
                String(el.alt || '').toLowerCase();
              if (/(avatar|emoji|icon|logo|sprite|badge|qrcode|qr-code|广告|ad[-_])/i
                  .test(source + ' ' + hint)) return false;
              if (kind === 'image') {
                const naturalWidth = Number(el.naturalWidth || el.width || 0);
                const naturalHeight = Number(el.naturalHeight || el.height || 0);
                if (el.tagName === 'IMG' && el.complete &&
                    naturalWidth > 0 && naturalHeight > 0 &&
                    (naturalWidth < 96 || naturalHeight < 72)) return false;
                if (r.width * r.height < 9000) return false;
                if (/^(data:image\\/gif;base64,R0lGODlhAQABA|about:blank)/i.test(source)) {
                  return false;
                }
              }
              return true;
            };
            const bestTouchPoint = (el) => {
              const r = el.getBoundingClientRect();
              const points = [
                [0.5, 0.5], [0.32, 0.5], [0.68, 0.5],
                [0.5, 0.32], [0.5, 0.68]
              ];
              for (const point of points) {
                const x = Math.max(8, Math.min(innerWidth - 8, r.left + r.width * point[0]));
                const y = Math.max(8, Math.min(innerHeight - 8, r.top + r.height * point[1]));
                const stack = document.elementsFromPoint(x, y);
                const hit = stack.find(node =>
                  node === el || el.contains(node) || node.contains(el)
                );
                if (hit) return {x, y, exposed:true};
              }
              return {
                x:Math.max(8, Math.min(innerWidth - 8, r.left + r.width / 2)),
                y:Math.max(8, Math.min(innerHeight - 8, r.top + r.height / 2)),
                exposed:false
              };
            };
            const mediaKey = (el, index) => {
              const src = mediaSource(el);
              if (src) return src;
              const r = el.getBoundingClientRect();
              return location.href + '#smart-' + el.tagName + '-' +
                Math.round(scrollY + r.top) + '-' + Math.round(r.left) + '-' + index;
            };
            const contextText = (el) => {
              const host = el.closest(
                'article, figure, li, [role="article"], [class*="card"], ' +
                '[class*="item"], [class*="post"], [data-testid="tweet"]'
              ) || el.parentElement;
              return String((host && host.innerText) || el.alt || el.title || '')
                .toLowerCase();
            };
            const imageSelector =
              'img, canvas, [style*="background-image"], [data-original], [data-src]';
            const selector = requestedType === 'image' ? imageSelector :
              requestedType === 'video' ? 'video' : 'video, ' + imageSelector;
            const rows = Array.from(document.querySelectorAll(selector))
              .filter(el => visible(el) && isUsefulMedia(el))
              .map((el, index) => {
                const r = el.getBoundingClientRect();
                const key = mediaKey(el, index);
                const point = bestTouchPoint(el);
                const x = point.x;
                const y = point.y;
                const text = contextText(el);
                // Once the site accepted the keyword, every media item on the
                // result page is a candidate. Search engines rarely repeat the
                // query text beside every thumbnail.
                const matches =
                  !keyword || trustedKeywordResults || text.includes(keyword);
                const centerDistance = Math.abs(y - innerHeight / 2) +
                  Math.abs(x - innerWidth / 2) * 0.2;
                const quality =
                  Math.min(r.width * r.height, 1000000) +
                  (point.exposed ? 250000 : -500000) +
                  (el.tagName === 'VIDEO' && !el.paused ? 400000 : 0);
                const activeXSeed = xInlineFeedMode &&
                  (el.matches?.('[data-smart-seed-media="1"]') ||
                   el.closest('[data-app-smart-x-active="1"]') != null);
                return {
                  el, key, x, y, top:r.top, left:r.left, matches,
                  centerDistance, quality, type:mediaKind(el), activeXSeed
                };
              })
              .filter(row => !attempted.has(row.key) && row.matches);
            rows.sort((a, b) => keyword
              ? (a.top - b.top || a.left - b.left || b.quality - a.quality)
              : ((b.activeXSeed ? 1 : 0) - (a.activeXSeed ? 1 : 0) ||
                 a.centerDistance - b.centerDistance || b.quality - a.quality));
            const selected = rows[0];
            if (selected) {
              if (selected.type === 'video') {
                if (xInlineFeedMode && !xInlineReadyToLongPress) {
                  const makeTouchEvent = (name, active) => {
                    const event = new Event(name, {bubbles:true, cancelable:true});
                    const touch = {
                      identifier: Date.now(),
                      target: selected.el,
                      clientX: selected.x,
                      clientY: selected.y,
                      pageX: selected.x + scrollX,
                      pageY: selected.y + scrollY,
                      screenX: selected.x,
                      screenY: selected.y
                    };
                    Object.defineProperty(event, 'touches', {
                      configurable:true, value:active ? [touch] : []
                    });
                    Object.defineProperty(event, 'changedTouches', {
                      configurable:true, value:[touch]
                    });
                    return event;
                  };
                  selected.el.dispatchEvent(makeTouchEvent('touchstart', true));
                  if (typeof PointerEvent === 'function') {
                    selected.el.dispatchEvent(new PointerEvent('pointerdown', {
