                      }));
                    }
                    selected.el.click();
                    try {
                      selected.el.muted = true;
                      selected.el.play().catch(() => {});
                    } catch (_) {}
                  }, 90);
                  return {
                    action:'activate',
                    key:selected.key,
                    type:'video',
                    scrollY:Math.max(0, window.scrollY || 0),
                    x:selected.x / Math.max(1, innerWidth),
                    y:selected.y / Math.max(1, innerHeight)
                  };
                }
