                        location.hostname;
                    } catch (_) { sameHost = false; }
                  }
                  return {el, text, r, sameHost};
                }).filter(row =>
                  row.sameHost && wanted.test(row.text) &&
                  row.r.width > 20 && row.r.height > 16
                );
                const tab = tabs[0];
