      if (action == 'longpress') {
        final lockedForPress = _normalizeSmartAcquisition(
          (task['lockedAcquisition'] ?? '').toString(),
        );
        // 本任务已锁定直链成功经验：不要再改成长按，继续找可直链项。
        if (lockedForPress == 'sniff') {
