      final failures = ((task['gestureEngineFailures'] as int?) ?? 0) + 1;
      task['gestureEngineFailures'] = failures;
      task['failed'] = (task['failed'] as int) + 1;
      if (failures >= 3 && await _recoverVisibleGesturePage(task, '可视识别发生异常')) {
        return true;
      }
      if (failures >= 3) {
        task['gestureMode'] = false;
        task['phase'] = 'collecting_site_results';
        task['matchStage'] = '可视识别连续异常，启用原有站内下载兜底';
      }
      Future<void>.delayed(const Duration(milliseconds: 180), () {
        if (identical(_smartDownloadTask, task)) {
          unawaited(_advanceSmartDownload(_currentUrl));
        }
      });
      return true;
    }
    return false;
  }

  Future<void> _completeSmartGestureDownload(bool success) async {
    final task = _smartDownloadTask;
    if (task == null) return;
    final demoLearning = task['demoPhase'] == 'demo';
    final actionRecipeMode = task['mode'] == 'action_recipe';
    final simpleGenericMode = task['mode'] == 'simple_generic';
    final gridMode = task['instagramGridMode'] == true;
    final libraryGated = _smartUsesLibraryGate(task);
    // 示范学习期允许手动长按回调；自动期仍要求 gestureDownloadPending。
    if (!demoLearning &&
        !actionRecipeMode &&
        !simpleGenericMode &&
        !gridMode &&
        task['gestureDownloadPending'] != true) {
      return;
    }
    if (!demoLearning &&
        libraryGated &&
        task['gestureDownloadPending'] != true &&
        task['actionAwaitingLibrarySave'] != true &&
        task['actionLongPressNeedsConfirm'] != true) {
      // 闸门已关时：仍接受「晚到的真实入库成功」，否则固定等待轮询永远看不到
      // library_saved（常见于噪声 complete(false) 先关闸、后台下载稍后落盘）。
      final alreadySaved =
          task['actionLibrarySaveOk'] == true &&
          (task['actionDownloadOutcome'] ?? '').toString() == 'library_saved';
      if (!(success && libraryGated && !alreadySaved)) {
        return;
      }
    }
    // 失败/跳过类 complete：同一次长按的 already_downloading 绝不能放行。
    // 成功路径仅由「媒体库落盘确认」后的 owner 调用（success 计数 / 入库同一路径）。
    if (!success && libraryGated) {
      final peekFailure = (task['lastGestureFailureType'] ?? '').toString();
      if (_actionRecipeShouldSuppressEarlyComplete(task, peekFailure)) {
        debugPrint(
          'Smart gesture: suppress early complete ($peekFailure); '
          'await library save before advance',
        );
        return;
      }
    }
    task['gestureDownloadPending'] = false;
    task['xInlineActivationPending'] = false;
    task['xInlineReadyToLongPress'] = false;
    if (_smartUsesFacebookPipeline((task['siteProfile'] ?? '').toString())) {
      // Persist stable identity BEFORE clearing the per-press bind — otherwise
      // soft-skip-disabled auto mode re-downloads the same reel forever.
      // (skippedDuplicate is computed below; stash key now, decide after.)
      task['__fbKeyPendingHandled'] =
          (task['expectedFbVideoKey'] ?? '').toString().trim();
      // The CDN identity belongs only to the just-pressed reel. Carrying it
      // into the next action is exactly how a later long press can download
      // the previous/neighbor item.
      task.remove('expectedFbVideoKey');
    }
    final failureType =
        (task.remove('lastGestureFailureType') ?? '').toString();
    // 仅媒体库确认的重复可自动跳过。
    // already_in_smart_task / duplicate_name_in_smart_task 是会话/备案软标记，
    // 绝不能当成「已经处理过」放行切条（否则未入库也会狂滑下一条）。
    final skippedDuplicate = !success && failureType == 'already_in_library';
    final pendingFbKey =
        (task.remove('__fbKeyPendingHandled') ?? '').toString().trim();
    if ((success || skippedDuplicate) && pendingFbKey.isNotEmpty) {
      _rememberHandledFacebookIdentity(task, pendingFbKey);
    }
    final activeKey = (task['gestureActiveKey'] ?? '').toString();
    final actionFailures =
        (task['gestureActionFailures'] as Map<String, int>?) ?? <String, int>{};
    task['gestureActionFailures'] = actionFailures;
    // 重复媒体视为「已处理」，不计入连续失败，避免 X 沉浸模式遇重复后卡死。
    if (success || skippedDuplicate) {
      task['gestureConsecutiveFailures'] = 0;
      task['gestureEngineFailures'] = 0;
      if (success && !actionRecipeMode) {
        final siteProfile = (task['siteProfile'] ?? '').toString();
        String acq;
        if (demoLearning) {
          acq =
              task['gestureDetailMode'] == true
                  ? 'detail_longpress'
                  : 'longpress_inplace';
        } else if (_smartUsesLegacyPriorityPipeline(siteProfile)) {
          acq = siteProfile == 'x' ? 'legacy_x' : 'legacy_91';
        } else {
          final fromRecipe =
              (task['learnedRecipe'] is Map
                      ? (task['learnedRecipe'] as Map)['acquisition']
                      : null)
                  ?.toString();
          acq =
              (fromRecipe != null && fromRecipe.isNotEmpty)
                  ? fromRecipe
                  : (task['gestureDetailMode'] == true
                      ? 'detail_longpress'
                      : 'longpress_inplace');
        }
        _lockSmartTaskAcquisition(task, acq);
        _noteSmartStrategyProgress(task, success: true);
        task['lastSuccessAcquisition'] = acq;
      }
    } else if (!actionRecipeMode) {
      task['gestureConsecutiveFailures'] =
          ((task['gestureConsecutiveFailures'] as int?) ?? 0) + 1;
      if (activeKey.isNotEmpty) {
        actionFailures[activeKey] = (actionFailures[activeKey] ?? 0) + 1;
      }
      _noteSmartTaskAcquisitionFailure(task);
    }
    task['gestureActiveKey'] = '';
    if (success) {
      task['success'] = ((task['success'] as int?) ?? 0) + 1;
      if ((task['lastSuccessAcquisition'] ?? '').toString().isEmpty) {
        task['lastSuccessAcquisition'] = 'longpress_inplace';
      }
      _showSmartOperation('下载成功 ${task['success']}/${task['target']}');
    } else if (skippedDuplicate) {
      // 仅入库后哈希查重 / 内容哈希确认的库内重复可走此文案
      task['matchStage'] =
          actionRecipeMode ? '库内已有，跳过' : '发现重复媒体 · 已自动跳过并切换下一项';
      _showSmartOperation(actionRecipeMode ? '库内已有，跳过' : '当前媒体已经处理过，自动跳过');
    } else {
      task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
      if (failureType == 'already_in_smart_task' ||
          failureType == 'duplicate_name_in_smart_task') {
        debugPrint(
          'Smart gesture: soft-duplicate $failureType ignored as skip '
          '(not library-confirmed)',
        );
      }
      if (actionRecipeMode && _actionRecipeIsInvalidMediaOutcome(failureType)) {
        task['invalidSkipped'] = ((task['invalidSkipped'] as int?) ?? 0) + 1;
        task['matchStage'] = '无效媒体，已跳过';
        _showSmartOperation('无效媒体，已跳过');
      }
    }
    _syncSmartBatchProgress(task);
    // 动作编排：仅入库成功或库内确认重复后写入会话已处理集合
    if (actionRecipeMode && (success || skippedDuplicate)) {
      await _markCurrentMediaHandled(task);
    }
    // 入库闸门：与 success 计数同一路径结束等待；仅此时允许 waitDownload/findNext。
    if (libraryGated) {
      if (success) {
        _actionRecipeFinishAwaitLibrarySave(
          task,
          libraryOk: true,
          outcome: 'library_saved',
        );
      } else if (skippedDuplicate) {
        _actionRecipeFinishAwaitLibrarySave(
          task,
          libraryOk: false,
          outcome: failureType,
        );
        // 库内重复：立刻放行 findNext，勿被残留下载标志卡死
        if (actionRecipeMode || simpleGenericMode) {
          task['actionForceSkipReleased'] = true;
          task['needAdvancePastCurrent'] = true;
        }
      } else {
        _actionRecipeFinishAwaitLibrarySave(
          task,
          libraryOk: false,
          outcome: failureType.isEmpty ? 'failed' : failureType,
        );
        if (actionRecipeMode &&
            _actionRecipeIsInvalidMediaOutcome(failureType)) {
          // 无效媒体：关闸后立刻允许 findNext，并标记当前条避免原地重试
          task['actionForceSkipReleased'] = true;
          task['needAdvancePastCurrent'] = true;
          await _markCurrentMediaHandled(task);
        }
      }
    }
    final pendingCompleter = task.remove('actionDownloadCompleter');
    if (pendingCompleter is Completer<bool> && !pendingCompleter.isCompleted) {
      // Completer true = 媒体库已确认写入；duplicate skip 为 false 但已 finishAwait。
      pendingCompleter.complete(success);
      debugPrint(
        'Smart gesture: completer done success=$success '
        'skippedDuplicate=$skippedDuplicate failureType=$failureType',
      );
    }
    if (actionRecipeMode || simpleGenericMode) {
      // 动作套路 / 通用实测管线由独立循环推进，不进入旧 FSM。
      if (!success && failureType == 'library_save_failed') {
        await _finishSmartDownload('写入媒体库失败，已停止任务；请检查存储空间和数据库状态');
      }
      return;
    }
    if (task['instagramGridMode'] == true) {
      if ((task['success'] as int) >= (task['target'] as int)) {
        await _finishSmartDownload();
        return;
      }
      await _returnFromInstagramGrid(
        task,
        handled: success || skippedDuplicate,
      );
      return;
    }
    _updateSmartDiscoveryProgress(task, 'gesture_download_completed');
    if (!success && failureType == 'library_save_failed') {
      await _finishSmartDownload('写入媒体库失败，已停止任务；请检查存储空间和数据库状态');
      return;
    }
    // V2：示范学习阶段只记步骤，不自动连下；满示范次数后切换自动。
    if (task['demoPhase'] == 'demo') {
      if (success) {
        await _recordSmartDemoStep(task);
        task['demoCompleted'] = (task['success'] as int);
        final need = (task['demoRequired'] as int?) ?? 2;
        final done = task['success'] as int;
        if (done >= need) {
          await _finishSmartDemoLearning(task);
          return;
        }
        task['matchStage'] = '示范学习 · ${done}/$need';
        _showSmartOperation('示范成功 $done/$need，请继续长按下一个未下载媒体');
        _updateSmartDiscoveryProgress(task, 'demo_waiting_user');
        return;
      }
      if (skippedDuplicate) {
        _showSmartOperation('这是重复媒体，请换一个未下载过的进行示范');
        return;
      }
      _showSmartOperation('示范下载未成功，请再试一次长按');
      return;
    }
    if ((task['success'] as int) >= (task['target'] as int)) {
      await _finishSmartDownload();
      return;
    }
    final controller = _controller;
    final actualUrl =
        controller == null
            ? _currentUrl
            : (await controller.getUrl())?.toString() ?? _currentUrl;
    final originUrl = (task['originUrl'] ?? '').toString();
    final xReturnUrl = (task['xReturnUrl'] ?? '').toString();
    final enteredXStatusFromList =
        task['siteProfile'] == 'x' &&
        xReturnUrl.startsWith('http') &&
        (task['xEnteredDetailFromList'] == true ||
            (_isXStatusDetailPage(actualUrl) &&
                !_isSameLoadedDocument(xReturnUrl, actualUrl)));
    if (enteredXStatusFromList) {
      task['gestureDetailMode'] = false;
      task['gestureReturnUrl'] = '';
      task['matchStage'] = 'X 帖子视频已下载 · 返回原信息流';
      _showSmartOperation('当前帖子下载完成，返回原页面继续下一条');
      await _returnFromXSmartCard(task);
      return;
    }
    final enteredXMediaViewer =
        task['siteProfile'] == 'x' &&
        !_isXMediaViewerPage(originUrl) &&
        _isXMediaViewerPage(actualUrl);
    final recordedReturnUrl = (task['gestureReturnUrl'] ?? '').toString();
    final returnUrl =
        recordedReturnUrl.startsWith('http')
            ? recordedReturnUrl
            : enteredXMediaViewer
            ? originUrl
            : '';
    if ((task['gestureDetailMode'] == true || enteredXMediaViewer) &&
        returnUrl.startsWith('http')) {
      task['phase'] = 'gesture_returning';
      task['matchStage'] = 'X 详情媒体已下载 · 返回原列表';
      _showSmartOperation('当前媒体下载完成，返回上一级继续查找');
      var closedXViewer = false;
      if (task['siteProfile'] == 'x') {
        // Never use WebView history for X smart tasks. Its SPA inserts
        // transient about:blank entries that can cause a return loop.
        final xTarget =
            _isSameLoadedDocument(returnUrl, actualUrl) &&
                    originUrl.startsWith('http') &&
                    !_isSameLoadedDocument(originUrl, actualUrl)
                ? originUrl
                : returnUrl;
        task['phase'] = 'x_search_returning';
        task['xReturnUrl'] = xTarget;
        task['xReturnExpectedUrl'] = xTarget;
        task['xReturnAttempts'] = 0;
        _loadUrl(xTarget);
        closedXViewer = true;
      } else if (controller != null && _isXMediaViewerPage(actualUrl)) {
        try {
          final result = await controller.evaluateJavascript(
            source: '''
              (() => {
                const selectors = [
                  '[data-testid="app-bar-back"]',
                  'button[aria-label="Close"]',
                  'button[aria-label="Back"]',
                  '[role="button"][aria-label="Close"]',
                  '[role="button"][aria-label="Back"]'
                ];
                const button = selectors.map(selector =>
                  document.querySelector(selector)
                ).find(element => {
                  if (!element) return false;
                  const rect = element.getBoundingClientRect();
                  return rect.width > 20 && rect.height > 20 &&
                    rect.bottom > 0 && rect.top < innerHeight;
                });
                if (!button) return false;
                button.click();
                return true;
              })()
            ''',
          );
          closedXViewer = result == true || result?.toString() == 'true';
        } catch (_) {}
      }
      if (!closedXViewer &&
          controller != null &&
          await controller.canGoBack()) {
        await controller.goBack();
      } else if (!closedXViewer) {
        _loadUrl(returnUrl);
      }
      Future<void>.delayed(const Duration(milliseconds: 750), () {
        if (identical(_smartDownloadTask, task) &&
            task['phase'] == 'gesture_returning') {
          unawaited(_advanceSmartDownload(_currentUrl));
        }
      });
      return;
    }
    if ((success || skippedDuplicate) &&
        task['siteProfile'] == 'x' &&
        (task['keyword'] ?? '').toString().trim().isEmpty) {
      task['gestureDetailMode'] = false;
      task['gestureReturnUrl'] = '';
      task['phase'] = 'scanning_feed';
      task['matchStage'] =
          skippedDuplicate ? 'X 沉浸模式 · 跳过重复并上滑下一条' : 'X 沉浸模式 · 上滑到下一条视频';
      _continueSmartFeed(task, madeProgress: true);
      return;
    }
    task['gestureDetailMode'] = false;
    task['gestureReturnUrl'] = '';
    if (!success && ((task['gestureConsecutiveFailures'] as int?) ?? 0) >= 6) {
      if (await _recoverVisibleGesturePage(
        task,
        '连续候选无法触发下载',
        nextPage: true,
      )) {
        return;
      }
      task['gestureMode'] = false;
      task['phase'] = 'collecting_site_results';
      task['matchStage'] = '连续多个可见媒体无法下载，启用网络地址兜底';
      Future<void>.delayed(const Duration(milliseconds: 100), () {
        if (identical(_smartDownloadTask, task)) {
          unawaited(_advanceSmartDownload(_currentUrl));
        }
      });
      return;
    }
    task['phase'] = 'gesture_scrolling';
    Future<void>.delayed(const Duration(milliseconds: 350), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_advanceSmartDownload(_currentUrl));
      }
    });
  }

  Future<void> _anchorSmartSeedForType(MediaType mediaType) async {
    final controller = _controller;
    if (controller == null) return;
    final imageMode = mediaType == MediaType.image;
    try {
      await controller.evaluateJavascript(
        source: '''
          (() => {
            const imageMode = $imageMode;
            const selector = imageMode ? 'img' : 'video';
            const candidates = Array.from(document.querySelectorAll(selector))
              .filter(media => {
                const r = media.getBoundingClientRect();
                if (r.width < 100 || r.height < 80 || r.bottom <= 0 || r.top >= innerHeight) {
                  return false;
                }
                if (!imageMode) return true;
                const src = String(media.currentSrc || media.src || '').toLowerCase();
                const width = Math.max(media.naturalWidth || 0, r.width);
                const height = Math.max(media.naturalHeight || 0, r.height);
                return width >= 200 && height >= 160 &&
                  !/(profile_images|profile_banners|emoji|avatar|icon)/.test(src);
              });
            const center = candidates.sort((left, right) => {
              const lr = left.getBoundingClientRect();
              const rr = right.getBoundingClientRect();
              const ld = Math.abs(lr.top + lr.height / 2 - innerHeight / 2) +
                Math.abs(lr.left + lr.width / 2 - innerWidth / 2) * 0.25;
              const rd = Math.abs(rr.top + rr.height / 2 - innerHeight / 2) +
                Math.abs(rr.left + rr.width / 2 - innerWidth / 2) * 0.25;
              return ld - rd;
            })[0];
            if (!center) return false;
            document.querySelectorAll(
              '[data-smart-seed-media], [data-smart-seed-scope], '
              + '[data-app-smart-x-active], [data-app-smart-x-visited]'
            ).forEach(el => {
              el.removeAttribute('data-smart-seed-media');
              el.removeAttribute('data-smart-seed-scope');
              el.removeAttribute('data-app-smart-x-active');
              el.removeAttribute('data-app-smart-x-visited');
            });
            center.setAttribute('data-smart-seed-media', '1');
            const host = location.hostname.toLowerCase().replace(/^www\./, '');
            const isX = host === 'x.com' || host.endsWith('.x.com') ||
              host === 'twitter.com' || host.endsWith('.twitter.com');
            const scope = isX
              // Immersive viewers preload adjacent posts inside one dialog.
              // Bind to the current video's smallest stable container instead.
              ? center.closest('article[data-testid="tweet"], article') ||
                center.parentElement
              : center.closest('article, figure, [class*="card"], [class*="item"], section') ||
                center.parentElement;
            if (scope) {
              scope.setAttribute('data-smart-seed-scope', '1');
              if (isX) scope.setAttribute('data-app-smart-x-active', '1');
            }
            if (!imageMode) {
              Array.from(document.querySelectorAll('video')).forEach(video => {
                if (video !== center) {
                  try { video.pause(); } catch (_) {}
                }
              });
              try { center.muted = true; center.play().catch(() => {}); } catch (_) {}
            }
            center.scrollIntoView({behavior: 'auto', block: 'center'});
            return true;
          })()
        ''',
      );
      _showSmartOperation(
        mediaType == MediaType.image ? '定位屏幕中心图片' : '定位屏幕中心视频',
      );
    } catch (e) {
      debugPrint('智能下载定位中心媒体失败: $e');
    }
  }

  Future<void> _showSmartDownloadDialog(
    Map<String, dynamic> website, {
    String initialKeyword = '',
    MediaType initialMediaType = MediaType.video,
    bool startFromCurrentPage = false,
    List<String> initialVideoUrls = const <String>[],
    double initialVideoDuration = 0,
  }) async {
    if (_smartDownloadTask != null) {
      await _promptStopOrResetSmartDownload();
      return;
    }
    final keywordController = TextEditingController(text: initialKeyword);
    final countController = TextEditingController(text: '50');
    final minVideoSizeController = TextEditingController();
    final maxVideoSizeController = TextEditingController();
    final dialogRawUrl = (website['url'] ?? '').toString().trim();
    final dialogNormalized =
        dialogRawUrl.startsWith('http://') ||
                dialogRawUrl.startsWith('https://')
            ? dialogRawUrl
            : (dialogRawUrl.isEmpty ? _currentUrl : 'https://$dialogRawUrl');
    final dialogHost = _normalizeSmartHost(
      Uri.tryParse(
            startFromCurrentPage ? _currentUrl : dialogNormalized,
          )?.host ??
          '',
    );
    // 所有网站统一三种方式；默认沿用套路。
    var runMode = 'reuse';
    var historyExpanded = false;
    // 分页嗅探：预先选择最多嗅探到哪一层（页数上限）；嗅探中可软停止并保留已结果。
    var selectedSniffMaxPages = _kPaginatedSniffMaxPages;
    // 媒体类型：可改；Facebook 的操作步骤完全由动作编排决定。
    var selectedMediaType = initialMediaType;
    // 沿用套路：本站有专有套路则默认专有；否则默认通用；均可手动改选。
    String selectedPatternId = _defaultConfirmedPatternIdForHost(
      dialogHost,
      mediaType: selectedMediaType,
    );
    final nativePatternId = _defaultConfirmedPatternIdForHost(dialogHost);
    final hostHasDedicated = _hostHasDedicatedSmartPattern(dialogHost);
    SmartActionRecipe? selectedRecipe =
        await SmartActionRecipeStore.loadLastForHost(dialogHost);
    var hostRecipes = List<SmartActionRecipe>.from(
      await SmartActionRecipeStore.loadForHost(dialogHost),
    );
    // 本站默认：供「沿用套路」自动选用；全局成功列表可跨站借用（类似 X/91 芯片）。
    // 可重命名/删除/覆盖；删除后回退内置专有芯片。
    SmartActionRecipe? siteSuccessRecipe =
        await SmartActionRecipeStore.loadLastSuccessForHost(dialogHost);
    var allSuccessRecipes = List<SmartActionRecipe>.from(
      await SmartActionRecipeStore.loadUserActionRecipes(),
    );
    final facebookHost = _smartUsesFacebookPipeline(
      _smartSiteProfile(dialogHost),
    );
    if (facebookHost) {
      const removedBuiltInNames = <String>{
        'Facebook · 视频/Reels · 长按→等完成→上滑',
        'Facebook · 图片 · 长按→等完成→左滑',
      };
      final staleCandidates = <SmartActionRecipe>[
        ...hostRecipes,
        ...allSuccessRecipes,
      ];
      if (selectedRecipe case final recipe?) staleCandidates.add(recipe);
      if (siteSuccessRecipe case final recipe?) staleCandidates.add(recipe);
      final staleIds = <String>{
        for (final recipe in staleCandidates)
          if (removedBuiltInNames.contains(recipe.name)) recipe.id,
      };
      for (final id in staleIds) {
        await SmartActionRecipeStore.deleteById(id);
      }
      if (staleIds.isNotEmpty) {
        final selectedId = selectedRecipe?.id;
        if (selectedId != null && staleIds.contains(selectedId)) {
          selectedRecipe = null;
        }
        final successId = siteSuccessRecipe?.id;
        if (successId != null && staleIds.contains(successId)) {
          siteSuccessRecipe = null;
        }
        hostRecipes.removeWhere((recipe) => staleIds.contains(recipe.id));
        allSuccessRecipes.removeWhere((recipe) => staleIds.contains(recipe.id));
      }
    }
    // Facebook Reels 竖滑走动作编排；个人页媒体网格默认沿用 facebook_grid 专有套路。
    final facebookProfileGrid =
        facebookHost &&
        _isFacebookProfileGridPage(
          startFromCurrentPage ? _currentUrl : dialogNormalized,
        );
    // reuse 子源：action_recipe（用户成功动作，可跨站）或 pattern（X/91/通用管线）。
    var reuseSource = siteSuccessRecipe != null ? 'action_recipe' : 'pattern';
    if (facebookHost) {
      if (facebookProfileGrid) {
        runMode = 'reuse';
        selectedPatternId = 'facebook_grid';
        reuseSource = 'pattern';
      } else {
        runMode = 'action';
      }
    }
    SmartActionRecipe? selectedReuseRecipe = siteSuccessRecipe;
    String axisHintFromRecipe(SmartActionRecipe? recipe) {
      if (recipe == null) return 'up';
      final kinds = recipe.steps.map((s) => s.kind).toSet();
      if (kinds.contains(SmartActionKind.findNextMediaRight) ||
          kinds.contains(SmartActionKind.flickLeft) ||
          kinds.contains(SmartActionKind.scrollPageLeft)) {
        return 'left';
      }
      if (kinds.contains(SmartActionKind.findPrevMedia) ||
          kinds.contains(SmartActionKind.flickDown) ||
          kinds.contains(SmartActionKind.scrollPageDown)) {
        return 'down';
      }
      if (kinds.contains(SmartActionKind.findNextMedia) ||
          kinds.contains(SmartActionKind.flickUp) ||
          kinds.contains(SmartActionKind.scrollPageUp)) {
        return 'up';
      }
      final stored = (recipe.advanceAxisHint ?? '').trim();
      if (stored == 'up' || stored == 'down' || stored == 'left') {
        return stored;
      }
      return 'up';
    }

    String modeFromRecipe(SmartActionRecipe? recipe) {
      final stored = (recipe?.advanceMode ?? '').trim();
      if (stored == 'distance' || stored == 'verify') return stored;
      return 'distance';
    }

    // 用户手选切条方向（上滑/下滑/左滑）；默认按套路零件推断
    var advanceAxisHint = axisHintFromRecipe(
      selectedReuseRecipe ?? selectedRecipe,
    );
    // 切条方式：按距离滑动（默认，更快）/ 确认切到新媒体（指纹校验）
    var advanceMode = modeFromRecipe(selectedReuseRecipe ?? selectedRecipe);
    if (siteSuccessRecipe != null) {
      selectedRecipe = siteSuccessRecipe;
    }
    Future<void> refreshSuccessRecipes() async {
      siteSuccessRecipe = await SmartActionRecipeStore.loadLastSuccessForHost(
        dialogHost,
      );
      allSuccessRecipes = List<SmartActionRecipe>.from(
        await SmartActionRecipeStore.loadUserActionRecipes(),
      );
      hostRecipes = List<SmartActionRecipe>.from(
        await SmartActionRecipeStore.loadForHost(dialogHost),
      );
      if (selectedReuseRecipe != null) {
        final keepId = selectedReuseRecipe!.id;
        SmartActionRecipe? found;
        for (final r in allSuccessRecipes) {
          if (r.id == keepId) {
            found = r;
            break;
          }
        }
        selectedReuseRecipe = found;
        if (found == null && reuseSource == 'action_recipe') {
          if (siteSuccessRecipe != null) {
            selectedReuseRecipe = siteSuccessRecipe;
          } else {
            reuseSource = 'pattern';
          }
        }
      }
    }

    String successRecipeChipLabel(SmartActionRecipe recipe) {
      final origin = SmartActionRecipeStore.keyForHost(recipe.host);
      final current = SmartActionRecipeStore.keyForHost(dialogHost);
      if (origin.isEmpty || origin == current) return recipe.name;
      return '${recipe.name} · $origin';
    }

    // 编辑器在智能下载对话框关闭后打开，避免挡住网页导致「验证零件」看不见效果
