                                  );
                                  if (!dialogContext.mounted) return;
                                  await refreshSuccessRecipes();
                                  if (!dialogContext.mounted) return;
                                  setDialogState(() {
                                    if (selectedReuseRecipe == null) {
                                      reuseSource = 'pattern';
                                      selectedRecipe =
                                          hostRecipes.isEmpty
                                              ? null
                                              : hostRecipes.first;
                                    } else {
                                      selectedRecipe = selectedReuseRecipe;
                                      advanceAxisHint = axisHintFromRecipe(
                                        selectedReuseRecipe,
                                      );
                                      advanceMode = modeFromRecipe(
                                        selectedReuseRecipe,
                                      );
                                    }
                                  });
                                  ScaffoldMessenger.of(
                                    dialogContext,
                                  ).showSnackBar(
                                    const SnackBar(content: Text('已删除成功动作套路')),
                                  );
                                },
                                child: const Text(
                                  '删除',
                                  style: TextStyle(fontSize: 12),
                                ),
                              ),
                              if (siteSuccessRecipe?.id !=
                                  selectedReuseRecipe!.id)
                                TextButton(
                                  onPressed: () async {
                                    await SmartActionRecipeStore.setAsHostDefault(
                                      dialogHost,
                                      selectedReuseRecipe!.id,
                                    );
                                    if (!dialogContext.mounted) return;
                                    await refreshSuccessRecipes();
                                    if (!dialogContext.mounted) return;
                                    setDialogState(() {
                                      reuseSource = 'action_recipe';
                                      selectedReuseRecipe = siteSuccessRecipe;
                                      selectedRecipe = siteSuccessRecipe;
                                      advanceAxisHint = axisHintFromRecipe(
                                        siteSuccessRecipe,
                                      );
                                      advanceMode = modeFromRecipe(
                                        siteSuccessRecipe,
                                      );
                                    });
                                    ScaffoldMessenger.of(
                                      dialogContext,
                                    ).showSnackBar(
                                      SnackBar(
                                        content: Text(
                                          '已设为「${dialogHost.isEmpty ? '当前站' : dialogHost}」默认套路',
                                        ),
                                      ),
                                    );
                                  },
                                  child: const Text(
                                    '设为当前站默认',
                                    style: TextStyle(fontSize: 12),
                                  ),
                                ),
                            ],
                          ),
                        ],
                      ] else ...[
                        const Padding(
                          padding: EdgeInsets.only(top: 6),
                          child: Text(
                            '从近到远分层嗅探真实媒体地址（视频优先）。'
                            '可先选最多嗅探到哪一层；嗅探过程中也可按「停止」中断，'
                            '已嗅探到的结果仍可选择下载。',
                            style: TextStyle(
                              fontSize: 11,
                              color: Colors.black54,
                            ),
                          ),
                        ),
                        const SizedBox(height: 8),
                        const Text(
                          '最多嗅探层级（由近到远）',
                          style: TextStyle(fontSize: 12),
                        ),
                        const SizedBox(height: 6),
                        Wrap(
                          spacing: 6,
                          runSpacing: 4,
                          children: [
                            for (
                              var i = 0;
                              i < _kPaginatedSniffLayerSizes.length;
                              i++
                            )
                              ChoiceChip(
                                label: Text(
                                  i == 0
                                      ? '第1层·当前页'
                                      : (i ==
                                              _kPaginatedSniffLayerSizes
                                                      .length -
                                                  1
                                          ? '全部层级'
                                          : '第${i + 1}层·${_kPaginatedSniffLayerSizes[i]}页'),
                                  style: const TextStyle(fontSize: 11),
                                ),
                                selected:
                                    selectedSniffMaxPages ==
                                    _kPaginatedSniffLayerSizes[i],
                                onSelected: (_) {
                                  setDialogState(() {
                                    selectedSniffMaxPages =
                                        _kPaginatedSniffLayerSizes[i];
                                  });
                                },
                              ),
                          ],
                        ),
                      ],
                      const SizedBox(height: 16),
                      const Text(
                        '2. 关键词',
                        style: TextStyle(fontWeight: FontWeight.w600),
                      ),
                      const SizedBox(height: 6),
                      TextField(
                        controller: keywordController,
                        autofocus: true,
                        textInputAction: TextInputAction.next,
                        decoration: InputDecoration(
                          labelText: '下载关键词',
                          hintText: '可留空：从当前页邻近依次；填写后按搜索/列表顺序',
                          border: const OutlineInputBorder(),
                          isDense: true,
                          suffixIcon:
                              _smartKeywordHistory.isEmpty
                                  ? null
                                  : IconButton(
                                    tooltip:
                                        historyExpanded ? '收起历史关键词' : '展开历史关键词',
                                    onPressed:
                                        () => setDialogState(
                                          () =>
                                              historyExpanded =
                                                  !historyExpanded,
                                        ),
                                    icon: AnimatedRotation(
                                      turns: historyExpanded ? 0.25 : 0,
                                      duration: const Duration(
                                        milliseconds: 160,
                                      ),
                                      child: const Icon(Icons.arrow_right),
                                    ),
                                  ),
                        ),
                      ),
                      if (historyExpanded &&
                          _smartKeywordHistory.isNotEmpty) ...[
                        const SizedBox(height: 10),
                        const Text(
                          '历史关键词（点击使用，删除错误词）',
                          style: TextStyle(fontSize: 12),
                        ),
                        const SizedBox(height: 4),
                        Wrap(
                          spacing: 6,
                          runSpacing: 2,
                          children:
                              List<String>.from(_smartKeywordHistory)
                                  .map(
                                    (value) => InputChip(
                                      label: ConstrainedBox(
                                        constraints: const BoxConstraints(
                                          maxWidth: 180,
                                        ),
                                        child: Text(
                                          value,
                                          overflow: TextOverflow.ellipsis,
                                        ),
                                      ),
                                      onPressed:
                                          () => keywordController.text = value,
                                      onDeleted: () async {
                                        await _removeSmartKeyword(value);
                                        if (dialogContext.mounted) {
                                          setDialogState(() {});
                                        }
                                      },
                                    ),
                                  )
                                  .toList(),
                        ),
                      ],
                      const SizedBox(height: 16),
                      const Text(
                        '3. 下载数量',
                        style: TextStyle(fontWeight: FontWeight.w600),
                      ),
                      const SizedBox(height: 6),
                      TextField(
                        controller: countController,
                        keyboardType: TextInputType.number,
                        inputFormatters: [
                          FilteringTextInputFormatter.digitsOnly,
                        ],
                        decoration: InputDecoration(
                          labelText: runMode == 'sniff' ? '下载数量（可留空）' : '下载数量',
                          hintText: runMode == 'sniff' ? '不限' : '默认 50',
                          helperText:
                              runMode == 'sniff'
                                  ? '留空=所选层级全部（最多 $_kPaginatedSniffSoftMaxTarget）'
                                  : '1～$_kSmartDownloadMaxTarget；留空按 50',
                          border: const OutlineInputBorder(),
                          isDense: true,
                        ),
                      ),
                      const SizedBox(height: 16),
                      const Text(
                        '4. 大小区间',
                        style: TextStyle(fontWeight: FontWeight.w600),
                      ),
                      const SizedBox(height: 6),
                      Row(
                        children: [
                          Expanded(
                            child: TextField(
                              controller: minVideoSizeController,
                              keyboardType: TextInputType.number,
                              inputFormatters: [
                                FilteringTextInputFormatter.digitsOnly,
                              ],
                              decoration: const InputDecoration(
                                labelText: '最小（MB）',
                                hintText: '不限',
                                border: OutlineInputBorder(),
                                isDense: true,
                              ),
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: TextField(
                              controller: maxVideoSizeController,
                              keyboardType: TextInputType.number,
                              inputFormatters: [
                                FilteringTextInputFormatter.digitsOnly,
                              ],
                              decoration: const InputDecoration(
                                labelText: '最大（MB）',
                                hintText: '不限',
                                border: OutlineInputBorder(),
                                isDense: true,
                              ),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                      const Text(
                        '两项留空时，若从当前视频启动，将按约 50%～150% 自动估算；否则不限制。',
                        style: TextStyle(fontSize: 11, color: Colors.grey),
                      ),
                    ],
                  ),
                ),
                actions: [
                  TextButton(
                    onPressed: () => Navigator.pop(dialogContext),
                    child: const Text('取消'),
                  ),
                  FilledButton(
                    onPressed:
                        (runMode == 'reuse' &&
                                reuseSource == 'action_recipe' &&
                                (selectedReuseRecipe == null ||
                                    selectedReuseRecipe!.steps.isEmpty))
                            ? null
                            : () {
                              final rawCount = countController.text.trim();
                              if (runMode == 'sniff') {
                                if (rawCount.isNotEmpty) {
                                  final count = int.tryParse(rawCount);
                                  if (count == null ||
                                      count < 1 ||
                                      count > _kPaginatedSniffSoftMaxTarget) {
                                    ScaffoldMessenger.of(
                                      dialogContext,
                                    ).showSnackBar(
                                      SnackBar(
                                        content: Text(
                                          '请输入 1～$_kPaginatedSniffSoftMaxTarget，或留空表示不限',
                                        ),
                                      ),
                                    );
                                    return;
                                  }
                                }
                              } else {
                                final count = int.tryParse(rawCount) ?? 50;
                                if (count < 1 ||
                                    count > _kSmartDownloadMaxTarget) {
                                  ScaffoldMessenger.of(
                                    dialogContext,
                                  ).showSnackBar(
                                    SnackBar(
                                      content: Text(
                                        '请输入 1～$_kSmartDownloadMaxTarget 的数量',
                                      ),
                                    ),
                                  );
                                  return;
                                }
                              }
                              final minMb = int.tryParse(
                                minVideoSizeController.text.trim(),
                              );
                              final maxMb = int.tryParse(
                                maxVideoSizeController.text.trim(),
                              );
                              if (minMb != null &&
                                  maxMb != null &&
                                  minMb > maxMb) {
                                ScaffoldMessenger.of(
                                  dialogContext,
                                ).showSnackBar(
                                  const SnackBar(content: Text('最小大小不能大于最大大小')),
                                );
                                return;
                              }
                              if (runMode == 'reuse') {
                                if (reuseSource == 'action_recipe') {
                                  if (selectedReuseRecipe == null ||
                                      selectedReuseRecipe!.steps.isEmpty) {
                                    ScaffoldMessenger.of(
                                      dialogContext,
                                    ).showSnackBar(
                                      const SnackBar(
                                        content: Text(
                                          '请选择一套成功动作套路，或先用「动作编排」跑通一次',
                                        ),
                                      ),
                                    );
                                    return;
                                  }
                                } else if (!_confirmedSmartPatternIds.contains(
                                  selectedPatternId,
                                )) {
                                  ScaffoldMessenger.of(
                                    dialogContext,
                                  ).showSnackBar(
                                    const SnackBar(
                                      content: Text('请选择一个网站套路（专有或通用）'),
                                    ),
                                  );
                                  return;
                                }
                              }
                              Navigator.pop(dialogContext, runMode);
                            },
                    child: const Text('开始'),
                  ),
                ],
              );
            },
          ),
    );

    final enteredKeyword = keywordController.text.trim();
    final enteredSniffMaxPages = selectedSniffMaxPages;
    final sniffUnlimitedCount =
        confirmed == 'sniff' && countController.text.trim().isEmpty;
    final enteredCount =
        sniffUnlimitedCount
            ? 0
            : (int.tryParse(countController.text.trim()) ??
                (confirmed == 'sniff' ? 0 : 5));
    final enteredMinVideoMb = int.tryParse(minVideoSizeController.text.trim());
    final enteredMaxVideoMb = int.tryParse(maxVideoSizeController.text.trim());
    await Future<void>.delayed(const Duration(milliseconds: 280));
    if (confirmed == null || !mounted) {
      keywordController.dispose();
      countController.dispose();
      minVideoSizeController.dispose();
      maxVideoSizeController.dispose();
      return;
    }

    if (enteredKeyword.isNotEmpty) {
      await _rememberSmartKeyword(enteredKeyword);
    }

    int? minVideoBytes =
        enteredMinVideoMb != null ? enteredMinVideoMb * 1024 * 1024 : null;
    int? maxVideoBytes =
        enteredMaxVideoMb != null ? enteredMaxVideoMb * 1024 * 1024 : null;
    var autoVideoSizeRange = false;
    // 分页嗅探不用种子视频自动估大小，避免误杀可下媒体。
    if (confirmed != 'sniff' &&
        enteredMinVideoMb == null &&
        enteredMaxVideoMb == null &&
        startFromCurrentPage) {
      final seedBytes = await _estimateSmartSeedVideoBytes(
        initialVideoUrls,
        _currentUrl,
        initialVideoDuration,
      );
      if (seedBytes != null && seedBytes > 0) {
        minVideoBytes = max(1, (seedBytes * 0.5).floor());
        maxVideoBytes = (seedBytes * 1.5).ceil();
        autoVideoSizeRange = true;
      }
    }

    final mediaType = selectedMediaType;

    /// 「沿用套路」：按所选站点固化管线启动。
    /// 专有套路（91 / X / 未来站点）均可手动借用到当前浏览站；默认仍为本站专有或通用。
    /// 91 = 实测独立管线；通用 = simple_generic；
    /// Facebook 视频 = 长按→等完成→上滑；Facebook 图片 = 长按→等完成→左滑；
    /// 其余专有（含 X）= _startSmartDownload。
    Future<void> startReusePattern() async {
      final id = selectedPatternId.trim();
      if (id.isEmpty || !_confirmedSmartPatternIds.contains(id)) {
        if (mounted) {
          ScaffoldMessenger.of(
            context,
          ).showSnackBar(const SnackBar(content: Text('未选择有效的网站套路')));
        }
        return;
      }
      final native = _defaultConfirmedPatternIdForHost(dialogHost);
      final crossSite = _dedicatedSmartPatternIds.contains(id) && id != native;
      // 91：实测独立管线（有关键词走搜索；无关键词从当前列表/详情批量）。
      // 跨站借用时仍走 91 管线，但以当前浏览 origin/host 为站点上下文。
      if (id == '91') {
        await _startSimple91KeywordDownload(
          website: website,
          keyword: enteredKeyword,
          targetCount: enteredCount,
          mediaType: mediaType,
          startFromCurrentPage: startFromCurrentPage,
          minVideoBytes: minVideoBytes,
          maxVideoBytes: maxVideoBytes,
          autoVideoSizeRange: autoVideoSizeRange,
          strategyManualPick: crossSite,
        );
        return;
      }
      // 通用：独立可靠循环（任意站搜索/信息流 → 真实流下载），不走脆弱 FSM。
      if (id == 'generic') {
        await _startSimpleGenericDownload(
          website: website,
          keyword: enteredKeyword,
          targetCount: enteredCount,
          mediaType: mediaType,
          startFromCurrentPage: startFromCurrentPage,
          minVideoBytes: minVideoBytes,
          maxVideoBytes: maxVideoBytes,
          autoVideoSizeRange: autoVideoSizeRange,
        );
        return;
      }
      // 其他专有套路（含 X）：forceSiteProfile 跨站借用，与 91 同一套手动选用机制。
      await _startSmartDownload(
        website: website,
        keyword: enteredKeyword,
        targetCount: enteredCount,
        mediaType: mediaType,
        allowMixedMedia: id == 'instagram_grid' || id == 'facebook_grid',
        startFromCurrentPage: startFromCurrentPage,
        minVideoBytes: minVideoBytes,
        maxVideoBytes: maxVideoBytes,
        autoVideoSizeRange: autoVideoSizeRange,
        demoCount: null,
        preferredStrategyKey: null,
        strategyManualPick: crossSite,
        strategyExplicitNone: true,
        forceSiteProfile: id,
      );
    }

    /// 「分页嗅探」：分层嗅探同站真实地址，再按层一键下载（视频优先）。
    Future<void> startSniff() async {
      await _startPaginatedSniffDownload(
        website: website,
        targetCount: enteredCount,
        unlimitedTarget: sniffUnlimitedCount || enteredCount <= 0,
        mediaType: mediaType,
        startFromCurrentPage: startFromCurrentPage,
        sniffMaxPages: enteredSniffMaxPages,
        minVideoBytes: minVideoBytes,
        maxVideoBytes: maxVideoBytes,
        autoVideoSizeRange: false,
      );
    }

    Future<void> startAction(SmartActionRecipe? recipe) async {
      var next = recipe;
      if (next == null) {
        next = await showSmartActionEditor(
          context: context,
          host: dialogHost.isEmpty ? 'unknown' : dialogHost,
          initial: defaultActionTemplate(),
          onVerifySteps: (steps) => _probeSmartActionSteps(steps),
        );
      }
      if (next != null && mounted) {
        // Explicitly arranged steps are authoritative. Refresh the fallback
        // axis from those steps instead of rewriting them from a stale chip.
        advanceAxisHint = axisHintFromRecipe(next);
        final runRecipe = next.copyWith(
          steps: next.steps.map((s) => s.copyWith()).toList(),
        );
        next.advanceAxisHint = advanceAxisHint;
        next.advanceMode = advanceMode;
        runRecipe.advanceMode = advanceMode;
        await SmartActionRecipeStore.save(next);
        await SmartActionRecipeStore.markUsed(next);
        await _startActionRecipeDownload(
          website: website,
          recipe: runRecipe,
          targetCount: enteredCount,
          mediaType: mediaType,
          allowMixedMedia: false,
          startFromCurrentPage: startFromCurrentPage,
          minVideoBytes: minVideoBytes,
          maxVideoBytes: maxVideoBytes,
          advanceAxisHint: advanceAxisHint,
          advanceMode: advanceMode,
        );
      }
    }

    if (confirmed == 'reuse') {
      if (reuseSource == 'action_recipe') {
        final recipe = selectedReuseRecipe;
        if (recipe == null || recipe.steps.isEmpty) {
          if (mounted) {
            ScaffoldMessenger.of(context).showSnackBar(
              const SnackBar(content: Text('请选择一套成功动作套路，或先用「动作编排」跑通一次')),
            );
          }
        } else {
          final recipeAxis = axisHintFromRecipe(recipe);
          // 用户显式上滑/左滑时对齐步骤；否则按套路推断。
          if (advanceAxisHint != 'up' &&
              advanceAxisHint != 'down' &&
              advanceAxisHint != 'left') {
            advanceAxisHint = recipeAxis;
          }
          advanceMode = modeFromRecipe(recipe);
          await startAction(recipe);
        }
      } else {
        await startReusePattern();
      }
    } else if (confirmed == 'sniff') {
      await startSniff();
    } else if (confirmed == 'action') {
      await startAction(selectedRecipe);
    } else if (confirmed == 'edit_action') {
      if (!mounted) return;
      final edited = await showSmartActionEditor(
        context: context,
        host: dialogHost.isEmpty ? 'unknown' : dialogHost,
        initial: editorSeed ?? selectedRecipe ?? defaultActionTemplate(),
        onVerifySteps: (steps) => _probeSmartActionSteps(steps),
      );
      if (edited != null && mounted) {
        await SmartActionRecipeStore.save(edited);
        await startAction(edited);
      }
    }

    keywordController.dispose();
    countController.dispose();
    minVideoSizeController.dispose();
    maxVideoSizeController.dispose();
  }

  Future<void> _startActionRecipeDownload({
    required Map<String, dynamic> website,
    required SmartActionRecipe recipe,
    required int targetCount,
    required MediaType mediaType,
    bool allowMixedMedia = false,
    bool startFromCurrentPage = false,
    int? minVideoBytes,
    int? maxVideoBytes,
    String? advanceAxisHint,
    String? advanceMode,
  }) async {
    if (_smartDownloadTask != null) return;
    final rawUrl = (website['url'] ?? '').toString().trim();
    final normalized =
        rawUrl.startsWith('http://') || rawUrl.startsWith('https://')
            ? rawUrl
            : (rawUrl.isEmpty ? _currentUrl : 'https://$rawUrl');
    final uri = Uri.tryParse(startFromCurrentPage ? _currentUrl : normalized);
    final host = _normalizeSmartHost(uri?.host ?? recipe.host);
    if (host.isEmpty) return;
    if (!startFromCurrentPage && normalized.startsWith('http')) {
      _loadUrl(normalized);
      await Future<void>.delayed(const Duration(milliseconds: 900));
    }
    final startedAt = DateTime.now();
    final deadlineAt = startedAt.add(const Duration(hours: 5));
    final hintRaw = (advanceAxisHint ?? '').trim();
    final recipeKinds = recipe.steps.map((step) => step.kind).toSet();
    final String resolvedAxisHint;
    if (recipeKinds.contains(SmartActionKind.findNextMediaRight) ||
        recipeKinds.contains(SmartActionKind.flickLeft) ||
        recipeKinds.contains(SmartActionKind.scrollPageLeft)) {
      resolvedAxisHint = 'left';
    } else if (recipeKinds.contains(SmartActionKind.findPrevMedia) ||
        recipeKinds.contains(SmartActionKind.flickDown) ||
        recipeKinds.contains(SmartActionKind.scrollPageDown)) {
      resolvedAxisHint = 'down';
    } else if (recipeKinds.contains(SmartActionKind.findNextMedia) ||
        recipeKinds.contains(SmartActionKind.flickUp) ||
        recipeKinds.contains(SmartActionKind.scrollPageUp)) {
      resolvedAxisHint = 'up';
    } else if (hintRaw == 'up' || hintRaw == 'down' || hintRaw == 'left') {
      resolvedAxisHint = hintRaw;
    } else {
      resolvedAxisHint = 'up';
    }
    final modeRaw = (advanceMode ?? '').trim();
    // 新任务默认按距离滑动；未显式传入时仍走指纹确认（兼容旧调用）
    final resolvedAdvanceMode =
        modeRaw == 'distance'
            ? 'distance'
            : modeRaw == 'verify'
            ? 'verify'
            : (advanceMode == null ? 'verify' : 'distance');
    // Keep explicitly arranged directions intact. The global axis is only a
    // fallback for automatic recovery/advance paths, never a step rewriter.
    final alignedSteps = recipe.steps
        .map((s) => s.copyWith())
        .toList(growable: true);
    final alignedRecipe = recipe.copyWith(steps: alignedSteps);
    final boundRecipe = alignedRecipe.copyWith(
      host: host,
      advanceAxisHint: resolvedAxisHint,
      advanceMode: resolvedAdvanceMode,
    );
    // 从套路里「等待下载完成」步骤带出等待方式（沿用套路 / lastSuccess 会一起恢复）
    var actionWaitMode = 'library';
    var actionWaitSeconds = 30;
    for (final step in boundRecipe.steps) {
      if (step.kind == SmartActionKind.waitDownload) {
        actionWaitMode = step.waitMode;
        actionWaitSeconds = step.waitSeconds;
        break;
      }
    }
    final siteProfile = _smartSiteProfile(host);
    final usesFacebookPipeline = _smartUsesFacebookPipeline(siteProfile);
    // Facebook 视频保留 stub 下限；这是防止黑色视频占位入库的必要校验。
    var resolvedMinVideoBytes = minVideoBytes;
    if (usesFacebookPipeline && mediaType == MediaType.video) {
      resolvedMinVideoBytes = max(
        resolvedMinVideoBytes ?? 0,
        _kMinFacebookSavedVideoBytes,
      );
    }
    final resolvedMaxVideoBytes = maxVideoBytes;
    _smartDownloadTask = <String, dynamic>{
      'mode': 'action_recipe',
      'phase': 'action_running',
      'siteUrl': normalized,
      'host': host,
      'siteProfile': siteProfile,
      'facebookPipeline': usesFacebookPipeline,
      'keyword': '',
      'mediaType': mediaType,
      'allowMixedMedia': allowMixedMedia,
      'target': targetCount.clamp(1, _kSmartDownloadMaxTarget),
      'minVideoBytes': resolvedMinVideoBytes,
      'maxVideoBytes': resolvedMaxVideoBytes,
      'effectiveMinVideoBytes': resolvedMinVideoBytes,
      'effectiveMaxVideoBytes': resolvedMaxVideoBytes,
      'success': 0,
      'failed': 0,
      'matchStage':
          usesFacebookPipeline
              ? 'Facebook · 动作编排 · ${boundRecipe.name}'
              : '动作套路 · ${boundRecipe.name}',
      'demoPhase': 'auto',
      'gestureDownloadPending': false,
      'actionAwaitingLibrarySave': false,
      'actionLibrarySaveOk': false,
      'actionLongPressNeedsConfirm': false,
      'actionFixedWaitReleased': false,
      'actionForceSkipReleased': false,
      'actionWaitMode': actionWaitMode,
      'actionWaitSeconds': actionWaitSeconds,
      'actionDownloadEpoch': 0,
      'startedAt': startedAt,
      'deadlineAt': deadlineAt,
      'originUrl': _currentUrl,
      'startedFromCurrentPage': startFromCurrentPage,
      'seenMediaUrls': <String>{},
      'attemptedVideoContexts': <String>{},
      'duplicateVideoUrlKeys': <String>{},
      'videoMediaStates': <String, String>{},
      'reservedMediaNameKeys': <String>{},
      'reservedMediaTitleKeys': <String>{},
      'allowBroadenDiscovery': false,
      'recipeName': boundRecipe.name,
      'actionRecipeJson': boundRecipe.toJson(),
      'gestureActionFailures': <String, int>{},
      'gestureConsecutiveFailures': 0,
      'gestureEngineFailures': 0,
      'gestureActiveKey': '',
      // 已成功/已跳过的媒体指纹，防止清障后又回到旧条无限重复
      'handledMediaKeys': <String>{},
      'handledMediaSrcs': <String>{},
      // Facebook: stable fbvideo:/reel: ids — hash-only cannot catch re-signed CDN URLs
      // of the same reel across qualities.
      'handledFbVideoIds': <String>{},
      'needAdvancePastCurrent': false,
      'actionAdvanceFailed': false,
      'advancingPastHandled': false,
      'recoveringTrack': false,
      'stallMediaKey': '',
      'stallCount': 0,
      'noSuccessRounds': 0,
      'recoveryCount': 0,
      'advanceAxisHint': resolvedAxisHint,
      'advanceMode': resolvedAdvanceMode,
    };
    final task = _smartDownloadTask!;
    try {
      await WakelockPlus.enable();
      task['screenWakeLockEnabled'] = true;
    } catch (_) {}
    task['deadlineTimer'] = Timer(deadlineAt.difference(DateTime.now()), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_finishSmartDownload('已达到单次任务 5 小时时间上限'));
      }
    });
    final axisLabel = _advanceAxisSpec(task).$3;
    final modeLabel = _advanceModeIsDistance(task) ? '按距离滑动' : '确认切到新媒体';
    _showSmartOperation('开始执行套路「${boundRecipe.name}」· $axisLabel · $modeLabel');
    unawaited(_runActionRecipeLoop(task, boundRecipe));
  }

  Set<String> _handledMediaKeysOf(Map<String, dynamic> task) {
    final raw = task['handledMediaKeys'];
    if (raw is Set<String>) return raw;
    if (raw is Set) {
      final casted = raw.map((e) => e.toString()).toSet();
      task['handledMediaKeys'] = casted;
      return casted;
    }
    final created = <String>{};
    task['handledMediaKeys'] = created;
    return created;
  }

  Set<String> _handledMediaSrcsOf(Map<String, dynamic> task) {
    final raw = task['handledMediaSrcs'];
    if (raw is Set<String>) return raw;
    if (raw is Set) {
      final casted = raw.map((e) => e.toString()).toSet();
      task['handledMediaSrcs'] = casted;
      return casted;
    }
    final created = <String>{};
    task['handledMediaSrcs'] = created;
    return created;
  }

  Set<String> _handledFbVideoIdsOf(Map<String, dynamic> task) {
    final raw = task['handledFbVideoIds'];
    if (raw is Set<String>) return raw;
    if (raw is Set) {
      final casted = raw.map((e) => e.toString()).toSet();
      task['handledFbVideoIds'] = casted;
      return casted;
    }
    final created = <String>{};
    task['handledFbVideoIds'] = created;
    return created;
  }

  void _rememberHandledFacebookIdentity(
    Map<String, dynamic>? task,
    String identity, {
    String? mediaId,
    String? softReelKey,
  }) {
    final key = identity.trim();
    if (key.isEmpty) return;
    if (task != null) {
      final set = _handledFbVideoIdsOf(task);
      set.add(key);
      if (softReelKey != null && softReelKey.trim().isNotEmpty) {
        set.add(softReelKey.trim());
      }
      if (key.startsWith('fbvideo:')) {
        final vid = key.substring('fbvideo:'.length);
        if (vid.isNotEmpty) set.add(vid);
      }
    }
    final mid = (mediaId ?? '').trim();
    if (mid.isNotEmpty) {
      _videoSourceUrlToMediaId[key] = mid;
      if (softReelKey != null && softReelKey.trim().isNotEmpty) {
        _videoSourceUrlToMediaId[softReelKey.trim()] = mid;
      }
      unawaited(_saveVideoSourceUrlMap());
    }
  }

  bool _sessionHasHandledFacebookIdentity(
    Map<String, dynamic>? task,
    String identity,
  ) {
    final key = identity.trim();
    if (key.isEmpty || task == null) return false;
    final set = _handledFbVideoIdsOf(task);
    if (set.contains(key)) return true;
    for (final existing in set) {
      if (facebookIdentitiesMatch(existing, key)) return true;
    }
    return false;
  }

  Future<bool> _libraryConfirmsFacebookIdentity(String identity) async {
    final key = identity.trim();
    if (key.isEmpty) return false;

    Future<bool> rowOk(String? mediaId) async {
      if (mediaId == null || mediaId.isEmpty) return false;
      try {
        final row = await _databaseService.getMediaItemById(mediaId);
        return await _libraryConfirmsExistingMediaRow(row);
      } catch (_) {
        return false;
      }
    }

    // Exact key only — never fuzzy facebookIdentitiesMatch across the whole
    // source map (that caused「库内已有」for videos not actually in library).
    if (await rowOk(_videoSourceUrlToMediaId[key])) {
      debugPrint('FB_DL libraryConfirm EXACT key=$key → true');
      return true;
    }
    if (key.startsWith('fbvideo:')) {
      final bare = key.substring('fbvideo:'.length);
      if (bare.isNotEmpty && await rowOk(_videoSourceUrlToMediaId[bare])) {
        debugPrint('FB_DL libraryConfirm EXACT bare=$bare → true');
        return true;
      }
    } else if (RegExp(r'^\d{6,}$').hasMatch(key)) {
      if (await rowOk(_videoSourceUrlToMediaId['fbvideo:$key'])) {
        debugPrint('FB_DL libraryConfirm EXACT fbvideo:$key → true');
        return true;
      }
    }
    debugPrint('FB_DL libraryConfirm key=$key → false (no exact map)');
    return false;
  }

  /// 指纹必须足够具体：空 src / none 标签 / 仅几何位的 key 不得参与「已处理」判定。
  bool _isReliableActionMediaIdentity(Map<String, dynamic>? identity) {
    if (identity == null) return false;
    final key = (identity['key'] ?? '').toString().trim();
    final src = (identity['src'] ?? '').toString().trim();
    final tag = (identity['tag'] ?? '').toString().trim().toUpperCase();
    if (key.isEmpty || key.startsWith('none|')) return false;
    if (tag == 'NONE') return false;
    if (src.isEmpty ||
        src == 'about:blank' ||
        src == 'null' ||
        src == 'undefined') {
      return false;
    }
    if (src.startsWith('data:') && src.length < 64) return false;
    final parts = key.split('|');
    // key 形如 TAG|src|left|top|… — src 段为空时全屏信息流极易误匹配
    if (parts.length >= 2 && parts[1].trim().isEmpty) return false;
    return true;
  }

  void _clearHandledMediaIdentity(
    Map<String, dynamic> task,
    Map<String, dynamic>? identity,
  ) {
    if (identity == null) return;
    final key = (identity['key'] ?? '').toString();
    final src = (identity['src'] ?? '').toString().trim();
    if (key.isNotEmpty) _handledMediaKeysOf(task).remove(key);
    if (src.isNotEmpty) _handledMediaSrcsOf(task).remove(src);
    if ((task['lastHandledMediaKey'] ?? '').toString() == key) {
      task['lastHandledMediaKey'] = '';
    }
    if ((task['lastHandledMediaSrc'] ?? '').toString() == src) {
      task['lastHandledMediaSrc'] = '';
    }
  }

  Future<bool> _libraryConfirmsMediaSource(String src) async {
    // 仅作提示/清理映射；绝不可单独作为「库内已有」跳过依据。
    final s = src.trim();
    if (s.isEmpty || s.startsWith('blob:') || s.startsWith('data:')) {
      return false;
    }
    final row = await _findExistingVideoBySourceUrl(s);
    return row != null;
  }

  /// 内容哈希命中且库内对应文件仍在磁盘 → 唯一合法的「库内已有」确认。
  Future<bool> _libraryConfirmsFileHash(String fileHash) async {
    final hash = fileHash.trim();
    if (hash.isEmpty) return false;
    try {
      final row = await _databaseService.findDuplicateMediaItem(hash, '');
      return row != null;
    } catch (_) {
      return false;
    }
  }

  Future<bool> _libraryConfirmsExistingMediaRow(
    Map<String, dynamic>? row,
  ) async {
    if (row == null) return false;
    final directory = (row['directory'] ?? '').toString();
    if (directory == 'recycle_bin') return false;
    final path = (row['path'] ?? '').toString();
    if (path.isEmpty) return false;
    try {
      return await File(path).exists();
    } catch (_) {
      return false;
    }
  }

  bool _isHandledMediaIdentity(
    Map<String, dynamic> task,
    Map<String, dynamic>? identity,
  ) {
    if (!_isReliableActionMediaIdentity(identity)) return false;
    final key = (identity!['key'] ?? '').toString();
    final src = (identity['src'] ?? '').toString().trim();
    final keys = _handledMediaKeysOf(task);
    final srcs = _handledMediaSrcsOf(task);
    // 仅精确匹配，避免 src 子串误判「重复」导致健康页狂切
    if (key.isNotEmpty && keys.contains(key)) return true;
    if (src.isNotEmpty && srcs.contains(src)) return true;
    return false;
  }

  /// 会话「已处理」仅作切条辅助；动作编排下载前绝不凭此跳过。
  /// 「库内已有」文案只能由内容哈希路径写入；此处不得用 URL/磁盘二次确认触发跳过。
  Future<bool> _shouldSkipAsHandledMedia(
    Map<String, dynamic> task,
    Map<String, dynamic>? identity,
  ) async {
    // 动作编排：下载前禁用会话已处理跳过。仅在「本轮已入库成功/哈希确认重复」
    // 或看门狗强制跳过且 needAdvancePastCurrent 时，允许卡住补推切条。
    if (_actionRecipeDisablesPreSkip(task)) {
      if (task['needAdvancePastCurrent'] != true) return false;
      final outcome = (task['actionDownloadOutcome'] ?? '').toString();
      final libraryOk = task['actionLibrarySaveOk'] == true;
      final forceSkipped =
          task['actionForceSkipReleased'] == true ||
          outcome == 'already_in_library' ||
          outcome == 'library_saved' ||
          outcome == 'stagnant_timeout' ||
          outcome == 'loop_timeout' ||
          outcome == 'force_skip_timeout' ||
          outcome == 'step_watchdog_timeout' ||
          _actionRecipeIsInvalidMediaOutcome(outcome);
      if (!libraryOk && !forceSkipped && outcome != 'already_in_library') {
        return false;
      }
      // 编排：仅会话身份匹配即可推条；禁止再凭 URL/磁盘「二次确认」
      return _isHandledMediaIdentity(task, identity);
    }
    if (!_isHandledMediaIdentity(task, identity)) return false;
    final src = (identity!['src'] ?? '').toString().trim();
    if (!src.startsWith('blob:') && !src.startsWith('data:')) {
      // 非编排：URL 映射仅用于清掉过期会话标记，不能单独宣称库内已有
      final inLibrary = await _libraryConfirmsMediaSource(src);
      if (!inLibrary) {
        debugPrint(
          'action handled false-positive: src not in library, clear flag',
        );
        _clearHandledMediaIdentity(task, identity);
        return false;
      }
      final row = await _findExistingVideoBySourceUrl(src);
      if (!await _libraryConfirmsExistingMediaRow(row)) {
        debugPrint(
          'action handled false-positive: library row missing file, clear',
        );
        _clearHandledMediaIdentity(task, identity);
        return false;
      }
      return true;
    }
    // blob/data：动作编排仅在真实入库成功后才可凭会话标记切条，不能当下载前跳过
    if (_actionRecipeDisablesPreSkip(task)) {
      return task['actionLibrarySaveOk'] == true ||
          (task['actionDownloadOutcome'] ?? '').toString() ==
              'already_in_library';
    }
    // 非编排：blob/data 仅信任「入库成功 / 哈希确认重复」后写入的会话标记
    return true;
  }

  /// 仅在媒体库落盘成功或库内确认重复后调用；软失败不得写入。
  Future<void> _markCurrentMediaHandled(Map<String, dynamic> task) async {
    final identity = await _actionCaptureMediaIdentity(task);
    task['needAdvancePastCurrent'] = true;
    if (_isReliableActionMediaIdentity(identity)) {
      final key = (identity!['key'] ?? '').toString();
      final src = (identity['src'] ?? '').toString().trim();
      if (key.isNotEmpty) _handledMediaKeysOf(task).add(key);
      if (src.isNotEmpty) _handledMediaSrcsOf(task).add(src);
      task['lastHandledMediaKey'] = key;
      task['lastHandledMediaSrc'] = src;
      debugPrint(
        'action markHandled key=${key.length > 80 ? key.substring(0, 80) : key} src=$src',
      );
    } else {
      debugPrint('action markHandled skipped: unreliable DOM identity');
    }
    if (_smartUsesFacebookPipeline((task['siteProfile'] ?? '').toString()) ||
        task['facebookPipeline'] == true) {
      final fbId = await _actionCaptureFacebookVideoIdentity(task);
      if (fbId.isNotEmpty) {
        _rememberHandledFacebookIdentity(task, fbId);
        debugPrint('action markHandled fbIdentity=$fbId');
      }
    }
  }

  /// 用户选定的切条方向 → (axisHint, preferHorizontal, label, direction)
  (String axis, bool horizontal, String label, String direction)
  _advanceAxisSpec(Map<String, dynamic> task) {
    switch ((task['advanceAxisHint'] ?? 'up').toString()) {
      case 'down':
        return ('down', false, '下滑切上一条', 'prev');
      case 'left':
        return ('left', true, '左滑切下一条', 'next');
      case 'up':
      default:
        return ('up', false, '上滑切下一条', 'next');
    }
  }

  /// 切条方式：`distance` 按距离轻扫；`verify`/缺省为指纹确认切到新媒体。
  bool _advanceModeIsDistance(Map<String, dynamic> task) {
    return (task['advanceMode'] ?? '').toString() == 'distance';
  }

  /// 仅当当前媒体确实在「已处理」集合里时才切走。
  Future<bool> _advancePastHandledMedia(Map<String, dynamic> task) async {
    if (task['advancingPastHandled'] == true) return false;
    if (task['mode'] != 'action_recipe' && task['actionProbe'] != true) {
      return false;
    }
    if (_actionRecipeRequiresSuccessfulVideoSave(task) &&
        !_actionRecipeMayAdvancePastDownload(task)) {
      task['needAdvancePastCurrent'] = false;
      _showSmartOperation('视频尚未成功入库，保持当前视频等待重试');
      return false;
    }
    // 下载进行中绝不切条（避免与 waitDownload / findNext 抢跑）
    // 固定等待 / 强制跳过已放行时允许推走已处理媒体（下载可在后台继续）
    if (_actionRecipeHasDownloadWork(task) &&
        task['actionFixedWaitReleased'] != true &&
        task['actionForceSkipReleased'] != true) {
      return false;
    }
    final identity = await _actionCaptureMediaIdentity(task);
    final identityReliable = _isReliableActionMediaIdentity(identity);
    if (identityReliable && !await _shouldSkipAsHandledMedia(task, identity)) {
      task['needAdvancePastCurrent'] = false;
      task['actionAdvanceFailureCount'] = 0;
      return true;
    }
    if (!identityReliable) {
      debugPrint(
        '[SMART_ADVANCE] current identity is unreliable; '
        'keep advance gate closed and perform bounded swipe retries',
      );
    }
    task['advancingPastHandled'] = true;
    try {
      final spec = _advanceAxisSpec(task);
      // 按距离模式：竖向整屏屏高 fling + 身份未变则偏 X 再甩
      if (_advanceModeIsDistance(task)) {
        _showSmartOperation('已处理过，${spec.$3}', point: const Offset(0.5, 0.5));
        final ok = await _actionDistanceFlickOnly(
          task,
          axisHint: spec.$1,
          label: spec.$3,
          distanceFraction:
              spec.$2
                  ? ((task['actionHorizontalLearnedDistance'] as num?)
                          ?.toDouble() ??
                      0.67)
                  : 0.7,
          durationMs: spec.$2 ? 380 : 600,
          maxAttempts: spec.$2 ? 3 : 4,
        );
        if (ok) {
          task['needAdvancePastCurrent'] = false;
        }
        return ok;
      }
      for (var i = 0; i < 4; i++) {
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          return false;
        }
        final again = await _actionCaptureMediaIdentity(task);
        if (_isReliableActionMediaIdentity(again) &&
            !await _shouldSkipAsHandledMedia(task, again)) {
          task['needAdvancePastCurrent'] = false;
          task['actionAdvanceFailureCount'] = 0;
          return true;
        }
        _showSmartOperation('已处理过，${spec.$3}', point: const Offset(0.5, 0.5));
        await _actionSwitchAdjacentMedia(
          task,
          label: spec.$3,
          preferHorizontal: spec.$2,
          direction: spec.$4,
          axisHintOverride: spec.$1,
          maxAttempts: 2,
          distanceFraction:
              spec.$2
                  ? (0.50 + i * 0.04).clamp(0.48, 0.58)
                  : (0.48 + i * 0.08).clamp(0.42, 0.78),
          durationMs: 380,
        );
        await Future<void>.delayed(const Duration(milliseconds: 240));
      }
      final finalIdentity = await _actionCaptureMediaIdentity(task);
      final advanced =
          _isReliableActionMediaIdentity(finalIdentity) &&
          !await _shouldSkipAsHandledMedia(task, finalIdentity);
      if (advanced) {
        task['needAdvancePastCurrent'] = false;
        task['actionAdvanceFailureCount'] = 0;
        return true;
      }
      final failures = ((task['actionAdvanceFailureCount'] as int?) ?? 0) + 1;
      task['actionAdvanceFailureCount'] = failures;
      task['needAdvancePastCurrent'] = true;
      debugPrint(
        '[SMART_ADVANCE] swipe not verified after bounded retries '
        'failures=$failures; keep current media download-blocked',
      );
      return false;
    } finally {
      task['advancingPastHandled'] = false;
    }
  }

  /// 健康路径：上一轮已成功下载并切走 → 保轨/清障直接空操作。
  /// 与 needAdvancePastCurrent 无关（该标志只表示「等 findNext 切条」）。
  /// 注意：健康路径只跳过清障/保轨，绝不能跳过「等待下载完成」。
  bool _actionRecipeHealthySkipGuard(Map<String, dynamic> task) {
    return task['mode'] == 'action_recipe' &&
        task['actionHealthyStreak'] == true;
  }

  /// 动作编排 / 沿用套路：禁用一切「下载前查重 / 已处理」预跳过。
  /// 策略：先强制尝试入库，再靠文件哈希做库内去重。
  bool _actionRecipeDisablesPreSkip([Map<String, dynamic>? task]) {
    final t = task ?? _smartDownloadTask;
    return t != null && t['mode'] == 'action_recipe';
  }

  /// 固定等待模式：强制下载，彻底关闭 detect-and-skip。
  bool _actionRecipeIsFixedWaitForce([Map<String, dynamic>? task]) {
    final t = task ?? _smartDownloadTask;
    if (t == null || t['mode'] != 'action_recipe') return false;
    return (t['actionWaitMode'] ?? '').toString().toLowerCase() == 'fixed';
  }

  /// Facebook 视频/Reels 必须等真实文件落盘后才能切到下一条。
  /// 图片仍可使用既有等待策略；动作验证也不启用这道严格闸门。
  bool _actionRecipeRequiresSuccessfulVideoSave(Map<String, dynamic> task) {
    if (task['actionProbe'] == true) return false;
    return task['mode'] == 'action_recipe' &&
        task['facebookPipeline'] == true &&
        task['mediaType'] == MediaType.video &&
        (task['advanceAxisHint'] ?? 'up').toString() != 'left';
  }

  /// 严格视频模式下可安全跳过的终态：必须已经明确失败/无效/超时，
  /// 且当前没有任何真实视频下载仍在进行。already_downloading 不属于终态。
  bool _actionRecipeCanSafelySkipStuckVideo(Map<String, dynamic> task) {
    if (task['actionForceSkipReleased'] != true) return false;
    if (_longPressVideoDownloadInProgress ||
        _actionRecipeHasRealSmartDownloading() ||
        _downloadingUrls.isNotEmpty) {
      return false;
    }
    final outcome = (task['actionDownloadOutcome'] ?? '').toString();
    return _actionRecipeIsInvalidMediaOutcome(outcome) ||
        outcome == 'stagnant_timeout' ||
        outcome == 'loop_timeout' ||
        outcome == 'force_skip_timeout' ||
        outcome == 'step_watchdog_timeout';
  }

  /// 旧版曾把 Facebook 的“固定等待”再次解释成最低等待，导致文件已经
  /// 入库后仍强制倒计时。固定等待现在统一由 waitDownload 作为最长时限
  /// 管理；该步骤会在 library_saved 到达时立即唤醒并切条。
  Future<void> _actionWaitStrictVideoMinimum(Map<String, dynamic> task) async {
    return;
  }

  /// 智能手势/稳健下载是否应跳过下载前查重，强制走下载队列。
  bool _smartForceDownloadNoPreSkip([Map<String, dynamic>? task]) {
    final t = task ?? _smartDownloadTask;
    if (t == null) return false;
    // 动作编排和 Facebook 均禁用下载前的 URL/标题/24h 软预约。
    // Facebook 的签名 URL 会跨清晰度、预加载相邻 Reel，只有下载后将
    // 当前绑定身份与真实内容哈希一起校验，才能安全宣称“库内已有”。
    return t['mode'] == 'action_recipe' ||
        _smartUsesFacebookPipeline((t['siteProfile'] ?? '').toString());
  }

  /// 动作套路媒体库等待看门狗（库确认模式）：超时无进展则强制跳过。
  static const Duration _kActionRecipeLibraryWatchdog = Duration(seconds: 21);

  // Facebook DASH is downloaded as separate video/audio tracks and then
  // merged natively. A missing native callback must never block the smart
  // action state machine forever.
  static const Duration _kFacebookSmartRoundHardTimeout = Duration(seconds: 36);

  /// 识别到无效/非媒体后的快速跳过窗口（不应干等到满库确认超时）。
  static const Duration _kActionRecipeInvalidMediaFastSkip = Duration(
    seconds: 3,
  );

  /// 回合级看门狗：同一媒体长时间无进展则强制跳过并切下一条。
  static const Duration _kActionRecipeStepWatchdog = Duration(seconds: 24);

  /// 普通智能下载的第二层停滞保护。
  ///
  /// 单次下载本身已有 2 分钟 inactivityTimeout；这里额外留 30 秒宽限，
  /// 防止底层取消/回调异常时，一个永久 `downloading` 状态锁死整个 50 条任务。
  /// 只按最后一次真实进度变化判断，持续有数据的大视频不会被误杀。
  static const Duration _kSmartMediaNoProgressHardTimeout = Duration(
    seconds: 150,
  );

  bool _isActionRecipePlaceholderRow(Map row) {
    return (row['url']?.toString() ?? '').startsWith('action-recipe://');
  }

  /// 真实智能批量下载（排除 action-recipe:// 占位条）。
  bool _actionRecipeHasRealSmartDownloading() {
    return _downloadTasks.any(
      (row) =>
          row['isSmartBatchMedia'] == true &&
          row['status'] == 'downloading' &&
          !_isActionRecipePlaceholderRow(row),
    );
  }

  void _cancelStalledSmartMediaDownloads(String reason) {
    final ids = <String>[];
    for (final row in _downloadTasks) {
      if (row['isSmartBatchMedia'] != true ||
          row['status'] != 'downloading' ||
          _isActionRecipePlaceholderRow(row)) {
        continue;
      }
      final token = row['cancelToken'];
      if (token is CancelToken && !token.isCancelled) {
        token.cancel(reason);
      }
      final id = (row['id'] ?? '').toString();
      if (id.isNotEmpty) ids.add(id);
    }
    for (final id in ids) {
      _removeDownloadTask(id);
    }
  }

  int _cancelSmartMediaDownloadsWithoutProgress(
    Duration timeout,
    String reason,
  ) {
    final nowMs = DateTime.now().millisecondsSinceEpoch;
    final staleIds = <String>[];
    for (final row in _downloadTasks) {
      if (row['isSmartBatchMedia'] != true ||
          row['status'] != 'downloading' ||
          _isActionRecipePlaceholderRow(row)) {
        continue;
      }
      final lastProgressAtMs =
          (row['lastProgressAtMs'] as num?)?.toInt() ??
          (row['lastSampleAtMs'] as num?)?.toInt() ??
          nowMs;
      final stalledFor = Duration(
        milliseconds: max(0, nowMs - lastProgressAtMs),
      );
      if (stalledFor < timeout) continue;
      final token = row['cancelToken'];
      if (token is CancelToken && !token.isCancelled) {
        token.cancel(reason);
      }
      final id = (row['id'] ?? '').toString();
      if (id.isNotEmpty) staleIds.add(id);
      debugPrint(
        '[SMART_WATCHDOG] cancel stalled media '
        'id=$id stalled=${stalledFor.inSeconds}s '
        'progress=${row['progress']} detail=${row['progressDetail']}',
      );
    }
    for (final id in staleIds) {
      _removeDownloadTask(id);
    }
    return staleIds.length;
  }

  /// 哈希确认的库内重复：闸门已关，允许立刻切条（勿被残留 longPress/进度条挡住）。
  bool _actionRecipeIsLibraryDuplicateReleased(Map<String, dynamic> task) {
    if (task['actionLongPressNeedsConfirm'] == true) return false;
    final outcome = (task['actionDownloadOutcome'] ?? '').toString();
    return outcome == 'already_in_library';
  }

  /// 动作套路：当前是否仍有未完成的手势下载（pending / Completer / 真实在途任务）。
  /// 含 [actionAwaitingLibrarySave] / [actionLongPressNeedsConfirm]：入库确认前绝不视为可切条。
  /// 占位条不算「真实在途」，避免 loop_timeout 后因占位永远挡住 findNext。
  bool _actionRecipeHasDownloadWork(Map<String, dynamic> task) {
    if (task['actionForceSkipReleased'] == true &&
        task['actionLongPressNeedsConfirm'] != true) {
      return false;
    }
    // 真实库内重复已关闸：立刻视为无待办，避免残留下载标志卡死 waitDownload/findNext
    if (_actionRecipeIsLibraryDuplicateReleased(task)) {
      return false;
    }
    if (task['actionLongPressNeedsConfirm'] == true) return true;
    if (task['actionAwaitingLibrarySave'] == true) return true;
    if (task['gestureDownloadPending'] == true) return true;
    final completer = task['actionDownloadCompleter'];
    if (completer is Completer<bool> && !completer.isCompleted) return true;
    if (_longPressVideoDownloadInProgress) return true;
    return _actionRecipeHasRealSmartDownloading();
  }

  bool _hasActiveSmartBatchDownload() {
    return _longPressVideoDownloadInProgress ||
        _downloadingUrls.isNotEmpty ||
        _actionRecipeHasRealSmartDownloading();
  }

  bool _actionRecipeIsInvalidMediaOutcome(String outcome) {
    final o = outcome.trim().toLowerCase();
    return o == 'invalid_smart_media_content' ||
        o == 'fb_stub_rejected' ||
        o == 'fb_identity_unbound' ||
        o == 'fb_video_track_not_captured' ||
        o == 'fb_audio_track_not_captured' ||
        o == 'outside_requested_size_range' ||
        o.contains('invalid_smart_media') ||
        o.contains('stub') ||
        o.contains('不是有效') ||
        o.contains('无效媒体');
  }

  String _actionRecipeForceSkipStatusText(String outcome) {
    if (_actionRecipeIsInvalidMediaOutcome(outcome)) {
      return '无效媒体，已跳过';
    }
    if (outcome == 'stagnant_timeout' ||
        outcome == 'loop_timeout' ||
        outcome == 'force_skip_timeout' ||
        outcome == 'step_watchdog_timeout') {
      return '超时无进展，强制跳过';
    }
    return '已强制跳过，继续下一条';
  }

  /// 仅取消动作编排占位条；不动用户手动下载、也不动其它真实 URL 在途任务。
  void _actionRecipeCancelPlaceholdersOnly(Map<String, dynamic> task) {
    final placeholderId = (task['actionProgressTaskId'] ?? '').toString();
    final ids = <String>{
      if (placeholderId.isNotEmpty) placeholderId,
      ..._downloadTasks
          .where(_isActionRecipePlaceholderRow)
          .map((row) => (row['id'] ?? '').toString())
          .where((id) => id.isNotEmpty),
    };
    for (final id in ids) {
      final idx = _downloadTasks.indexWhere((row) => row['id'] == id);
      if (idx < 0) continue;
      final token = _downloadTasks[idx]['cancelToken'];
      if (token is CancelToken && !token.isCancelled) {
        token.cancel('action_recipe_force_skip');
      }
      _removeDownloadTask(id);
    }
    task.remove('actionProgressTaskId');
  }

  /// 强制跳过当前长按/等待：关闸、清占位、放行 findNext；不取消无关用户下载。
  Future<void> _actionRecipeForceSkipCurrent(
    Map<String, dynamic> task, {
    required String outcome,
    String? statusText,
    bool incrementFailed = true,
  }) async {
    if (!identical(_smartDownloadTask, task) && task['actionProbe'] != true) {
      return;
    }
    final resolved =
        outcome.trim().isEmpty ? 'force_skip_timeout' : outcome.trim();
    final label =
        (statusText != null && statusText.trim().isNotEmpty)
            ? statusText.trim()
            : _actionRecipeForceSkipStatusText(resolved);
    task['gestureDownloadPending'] = false;
    task['actionHealthyStreak'] = false;
    task['actionForceSkipReleased'] = true;
    task['needAdvancePastCurrent'] = true;
    _actionRecipeCancelPlaceholdersOnly(task);
    _actionRecipeFinishAwaitLibrarySave(
      task,
      libraryOk: false,
      outcome: resolved,
    );
    final pendingCompleter = task.remove('actionDownloadCompleter');
    if (pendingCompleter is Completer<bool> && !pendingCompleter.isCompleted) {
      pendingCompleter.complete(false);
    }
    if (incrementFailed) {
      task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
    }
    if (_actionRecipeIsInvalidMediaOutcome(resolved)) {
      task['invalidSkipped'] = ((task['invalidSkipped'] as int?) ?? 0) + 1;
    }
    task['matchStage'] = label;
    _showSmartOperation(label);
    // 尽量标记当前条，便于回合保轨推走；找不到可靠指纹也不阻塞切条
    try {
      await _markCurrentMediaHandled(task);
    } catch (_) {}
    debugPrint(
      'action recipe FORCE-SKIP outcome=$resolved '
      'epoch=${task['actionDownloadEpoch']} label=$label',
    );
  }

  /// 长按会话开始：在媒体库落盘确认前，套路不得 findNext / 切条。
  void _actionRecipeBeginAwaitLibrarySave(Map<String, dynamic> task) {
    task['actionAwaitingLibrarySave'] = true;
    task['actionLongPressNeedsConfirm'] = true;
    task['actionLibrarySaveOk'] = false;
    task['actionDownloadOutcome'] = null;
    task['actionFixedWaitReleased'] = false;
    task['actionForceSkipReleased'] = false;
    task.remove('lastGestureFailureType');
    task['actionDownloadEpoch'] =
        ((task['actionDownloadEpoch'] as int?) ?? 0) + 1;
    // 强制下载立刻出现在进度条，避免「看起来被跳过」且固定等待后仍可追踪
    _actionRecipeEnsureProgressPlaceholder(task);
    debugPrint(
      'action recipe library-gate OPEN epoch=${task['actionDownloadEpoch']} '
      'waitMode=${task['actionWaitMode']}',
    );
  }

  /// 入库成功 / 明确失败或库内重复跳过：结束等待，允许后续 waitDownload/findNext。
  void _actionRecipeFinishAwaitLibrarySave(
    Map<String, dynamic> task, {
    required bool libraryOk,
    String outcome = '',
  }) {
    final resolved =
        outcome.isEmpty ? (libraryOk ? 'library_saved' : 'done') : outcome;
    task['actionAwaitingLibrarySave'] = false;
    task['actionLibrarySaveOk'] = libraryOk;
    task['actionDownloadOutcome'] = resolved;
    // finish = 终态：此后才允许 waitDownload 放行 / findNext 切条
    task['actionLongPressNeedsConfirm'] = false;
    // 占位任务：若真实下载已进队列则只清占位；勿动其它 downloading 任务
    _actionRecipeResolveProgressPlaceholder(
      task,
      libraryOk: libraryOk,
      outcome: resolved,
    );
    debugPrint(
      'action recipe library-gate CLOSE ok=$libraryOk outcome=$resolved',
    );
  }

  /// 固定等待到点：放行切条，不取消在途下载、不要求媒体库确认。
  void _actionRecipeReleaseFixedWait(Map<String, dynamic> task) {
    task['actionFixedWaitReleased'] = true;
    task['actionAwaitingLibrarySave'] = false;
    task['actionLongPressNeedsConfirm'] = false;
    if ((task['actionDownloadOutcome'] ?? '').toString().isEmpty) {
      task['actionDownloadOutcome'] = 'fixed_wait_elapsed';
    }
    // 到点只放行切条：保留进度条中的真实下载与占位（若仍无真实任务）
    final placeholderId = (task['actionProgressTaskId'] ?? '').toString();
    if (placeholderId.isNotEmpty && mounted) {
      final hasReal = _downloadTasks.any(
        (row) =>
            row['isSmartBatchMedia'] == true &&
            row['status'] == 'downloading' &&
            row['id'] != placeholderId &&
            !(row['url']?.toString() ?? '').startsWith('action-recipe://'),
      );
      if (hasReal) {
        _removeDownloadTask(placeholderId);
        task.remove('actionProgressTaskId');
      } else {
        _updateDownloadTask(placeholderId, progressDetail: '固定等待已结束，下载仍在继续…');
      }
    }
    debugPrint(
      'action recipe fixed-wait RELEASE epoch=${task['actionDownloadEpoch']} '
      'seconds=${task['actionWaitSeconds']}',
    );
  }

  void _actionRecipeEnsureProgressPlaceholder(Map<String, dynamic> task) {
    if (!mounted) return;
    final existingId = (task['actionProgressTaskId'] ?? '').toString();
    if (existingId.isNotEmpty &&
        _downloadTasks.any((row) => row['id'] == existingId)) {
      _updateDownloadTask(
        existingId,
        status: 'downloading',
        progress: 0.0,
        progressDetail: '长按已触发，强制下载中…',
      );
      return;
    }
    final id = const Uuid().v4();
    task['actionProgressTaskId'] = id;
    _addDownloadTask(
      id,
      'action-recipe://force-download/$id',
      MediaType.video,
      CancelToken(),
      displayName: '动作编排 · 强制下载',
      isSmartBatchMedia: true,
    );
    _updateDownloadTask(id, progress: 0.0, progressDetail: '长按已触发，强制下载中…');
  }

  void _actionRecipeResolveProgressPlaceholder(
    Map<String, dynamic> task, {
    required bool libraryOk,
    required String outcome,
  }) {
    final id = (task['actionProgressTaskId'] ?? '').toString();
    if (id.isEmpty) return;
    final idx = _downloadTasks.indexWhere((t) => t['id'] == id);
    if (idx < 0) {
      task.remove('actionProgressTaskId');
      return;
    }
    final url = (_downloadTasks[idx]['url'] ?? '').toString();
    final isPlaceholder = url.startsWith('action-recipe://');
    final hasRealDownloading = _downloadTasks.any(
      (t) =>
          t['isSmartBatchMedia'] == true &&
          t['status'] == 'downloading' &&
          t['id'] != id &&
          !(t['url']?.toString() ?? '').startsWith('action-recipe://'),
    );
    // 真实下载已在进度条：去掉占位，让真实任务继续可追踪
    if (hasRealDownloading && isPlaceholder) {
      _removeDownloadTask(id);
      task.remove('actionProgressTaskId');
      return;
    }
    if (!isPlaceholder) return;
    if (libraryOk || outcome == 'library_saved') {
      _updateDownloadTask(
        id,
        status: 'completed',
        progress: 1.0,
        progressDetail: '已保存到媒体库',
      );
      task.remove('actionProgressTaskId');
      return;
    }
    if (outcome == 'already_in_library') {
      _updateDownloadTask(
        id,
        status: 'completed',
        progress: 1.0,
        progressDetail: '库内已有相同文件',
      );
      task.remove('actionProgressTaskId');
      return;
    }
    if (outcome == 'fixed_wait_elapsed') {
      // 固定等待到点：占位保留为 downloading，便于用户看到仍在队列
      _updateDownloadTask(id, progressDetail: '固定等待已结束，下载仍在继续…');
      return;
    }
    if (_actionRecipeIsInvalidMediaOutcome(outcome)) {
      _updateDownloadTask(id, status: 'failed', progressDetail: '无效媒体，已跳过');
      task.remove('actionProgressTaskId');
      return;
    }
    if (outcome == 'stagnant_timeout' ||
        outcome == 'loop_timeout' ||
        outcome == 'force_skip_timeout' ||
        outcome == 'step_watchdog_timeout') {
      _updateDownloadTask(id, status: 'failed', progressDetail: '超时无进展，强制跳过');
      task.remove('actionProgressTaskId');
      return;
    }
    // 明确失败：标记失败但不在切条时清掉其它真实任务
    _updateDownloadTask(
      id,
      status: 'failed',
      progressDetail: outcome.isEmpty ? '下载未完成' : outcome,
    );
    task.remove('actionProgressTaskId');
  }

  /// 真实智能下载任务入队时，清掉动作编排占位条，避免重复显示。
  void _actionRecipePromoteProgressPlaceholder() {
    final task = _smartDownloadTask;
    if (task == null || task['mode'] != 'action_recipe') return;
    final id = (task['actionProgressTaskId'] ?? '').toString();
    if (id.isEmpty) return;
    final idx = _downloadTasks.indexWhere((t) => t['id'] == id);
    if (idx < 0) {
      task.remove('actionProgressTaskId');
      return;
    }
    final url = (_downloadTasks[idx]['url'] ?? '').toString();
    if (url.startsWith('action-recipe://')) {
      _removeDownloadTask(id);
      task.remove('actionProgressTaskId');
    }
  }

  /// 是否允许在长按下载会话之后切条（入库成功 / 明确跳过失败 / 固定等待到点 / 强制跳过）。
  bool _actionRecipeMayAdvancePastDownload(Map<String, dynamic> task) {
    final outcome = (task['actionDownloadOutcome'] ?? '').toString();
    if (task['mediaType'] == MediaType.video &&
        _isInstagramPlatformPage(_currentUrl) &&
        outcome == 'instagram_current_track_not_captured') {
      // No transfer was started. Retry this same Reel a bounded number of
      // times instead of treating a track-readiness miss as permission to
      // swipe away.
      final captureFailures =
          (task['instagramTrackCaptureFailures'] as int?) ?? 0;
      if (captureFailures < 8) return false;
    }
    if (_actionRecipeRequiresSuccessfulVideoSave(task)) {
      // Facebook 视频严格模式：固定等待到点、看门狗跳过、地址已解析等状态
      // 均不能直接放行。只接受真实入库、哈希确认库内已有，或确认没有
      // 真实下载在途的无效/超时终态，避免永久卡在坏视频页面。
      return _actionRecipeDidLibrarySave(task) ||
          _actionRecipeIsLibraryDuplicateReleased(task) ||
          _actionRecipeCanSafelySkipStuckVideo(task);
    }
    // 固定等待已到点：允许切条，即使下载仍在后台进行
    if (task['actionFixedWaitReleased'] == true) return true;
    // 看门狗强制跳过：允许切条；真实下载若仍在途则后台继续，不挡 findNext
    if (task['actionForceSkipReleased'] == true) return true;
    // 哈希确认库内重复：立刻允许上滑切条
    if (_actionRecipeIsLibraryDuplicateReleased(task)) return true;
    if (task['actionLongPressNeedsConfirm'] == true) return false;
    if (_actionRecipeHasDownloadWork(task)) return false;
    return true;
  }

  /// 真实媒体库落盘成功（非软跳过 / already_in_library）。
  bool _actionRecipeDidLibrarySave(Map<String, dynamic> task) {
    return task['actionLibrarySaveOk'] == true &&
        (task['actionDownloadOutcome'] ?? '').toString() == 'library_saved';
  }

  /// 固定等待期间：真实入库成功，或哈希确认的库内重复，均可提前切条。
  /// 软「已处理」不得走此路径；[successAtStart] 捕捉 complete(true) 已加计数的情况。
  bool _actionRecipeFixedWaitShouldEarlyAdvance(
    Map<String, dynamic> task, {
    required int successAtStart,
  }) {
    if (_actionRecipeDidLibrarySave(task)) return true;
    if (_actionRecipeIsLibraryDuplicateReleased(task)) return true;
    final successNow = (task['success'] as int?) ?? 0;
    if (successNow > successAtStart) return true;
    return false;
  }

  /// 库内重复终态：关闸、完成 Completer、放行切条（供 dialog / complete 共用）。
  void _actionRecipeReleaseAlreadyInLibrary(
    Map<String, dynamic> task, {
    String statusText = '库内已有，跳过',
  }) {
    task['duplicateSkipped'] = ((task['duplicateSkipped'] as int?) ?? 0) + 1;
    task['lastGestureFailureType'] = 'already_in_library';
    task['gestureDownloadPending'] = false;
    task['needAdvancePastCurrent'] = true;
    task['actionForceSkipReleased'] = true;
    task['matchStage'] = statusText;
    _actionRecipeFinishAwaitLibrarySave(
      task,
      libraryOk: false,
      outcome: 'already_in_library',
    );
    final pendingCompleter = task.remove('actionDownloadCompleter');
    if (pendingCompleter is Completer<bool> && !pendingCompleter.isCompleted) {
      pendingCompleter.complete(false);
    }
    _showSmartOperation(statusText);
    debugPrint(
      'action recipe already_in_library RELEASE '
      'epoch=${task['actionDownloadEpoch']} status=$statusText',
    );
  }

  /// already_downloading / 尚无直链 等「同一次长按连发」：绝不能放行 Completer / 切条。
  bool _actionRecipeShouldSuppressEarlyComplete(
    Map<String, dynamic> task,
    String failureType,
  ) {
    // 无效媒体必须立刻放行，绝不能当噪声压制（否则闸门永不关 → 卡死）
    if (_actionRecipeIsInvalidMediaOutcome(failureType)) {
      return false;
    }
    final awaiting =
        task['actionAwaitingLibrarySave'] == true ||
        task['actionLongPressNeedsConfirm'] == true ||
        task['gestureDownloadPending'] == true;
    // already_downloading：同一次长按连发，入库确认前绝不能放行。
    if (failureType == 'already_downloading') {
      return awaiting || _hasActiveSmartBatchDownload();
    }
    // 会话/备案软重复：绝不能当「已处理」放行切条；有在途或仍在等入库时一律压制。
    if (failureType == 'already_in_smart_task' ||
        failureType == 'duplicate_name_in_smart_task') {
      return awaiting || _hasActiveSmartBatchDownload();
    }
    // 流引用 / 尚无直链：长按后常先到噪声消息，入库闸门打开时必须继续等真下载。
    if (awaiting && (failureType.isEmpty || failureType == 'no_direct_url')) {
      return true;
    }
    if (awaiting &&
        failureType == 'download_failed_retryable' &&
        (_hasActiveSmartBatchDownload() || _longPressVideoDownloadInProgress)) {
      return true;
    }
    return false;
  }

  /// 轻量保轨：仅卡死/异常时介入。健康路径应跳过本函数。
  /// [allowAdvance]：步骤后/找下一条前应 false，避免与套路 findNext 双切。
  Future<void> _guardActionRecipeTrack(
    Map<String, dynamic> task, {
    String reason = '保轨',
    bool allowHeavy = false,
    bool allowAdvance = true,
    int stallLevel = 0,
  }) async {
    if (task['mode'] != 'action_recipe' && task['actionProbe'] != true) {
      return;
    }
    if (task['recoveringTrack'] == true) return;
    if (!identical(_smartDownloadTask, task) && task['actionProbe'] != true) {
      return;
    }
    // 健康路径：上一轮成功且已切到新媒体 → 不探测、不清障、不自愈
    if (!allowHeavy && stallLevel <= 0 && _actionRecipeHealthySkipGuard(task)) {
      return;
    }
    task['recoveringTrack'] = true;
    try {
      // 1) 先探测：没广告就不清
      final hasBlocker = await _probeSmartBlockersPresent();
      if (hasBlocker) {
        task['matchStage'] = '清障 · $reason';
        _showSmartOperation('发现干扰，正在关闭', point: const Offset(0.5, 0.42));
        await _clearSmartInterruptions(
          task,
          label: '关闭干扰弹层',
          silent: false,
          forceHide: true,
        );
      }

      // 2) 仅当前确是已处理媒体且允许切走时才切（不因标记标志抢先切）
      if (allowAdvance) {
        final identity = await _actionCaptureMediaIdentity(task);
        if (await _shouldSkipAsHandledMedia(task, identity)) {
          await _advancePastHandledMedia(task);
        }
      }

      if (!allowHeavy || stallLevel < 3) return;
      if (_actionRecipeRequiresSuccessfulVideoSave(task) &&
          !_actionRecipeMayAdvancePastDownload(task)) {
        // Facebook 视频失败/未入库时禁止重自愈直接滑走当前页面。
        task['needAdvancePastCurrent'] = false;
        _showSmartOperation('视频尚未成功入库，禁止自愈上滑');
        return;
      }

      // 3) 重自愈：仅空转多次后才升级（未到极高 stall 不标记已处理）
      final spec = _advanceAxisSpec(task);
      task['matchStage'] = '自愈 · $reason';
      _showSmartOperation('自愈：强力${spec.$3}', point: const Offset(0.5, 0.55));
      await _actionFingerFlick(
        task,
        axisHint: spec.$1,
        label: '自愈${spec.$3}',
        distanceFraction: (0.4 + stallLevel * 0.03).clamp(0.36, 0.65),
        durationMs: 300,
      );
      if (await _probeSmartBlockersPresent()) {
        await _clearSmartInterruptions(task, silent: false, forceHide: true);
      }
      // 卡死很久：只强切，绝不无入库确认写入「已处理」（否则假跳过会永久挡住真下载）
      if (stallLevel >= 5) {
        task['needAdvancePastCurrent'] = false;
        await _actionFingerFlick(
          task,
          axisHint: spec.$1,
          label: '自愈强切',
          distanceFraction: (0.45 + stallLevel * 0.02).clamp(0.4, 0.7),
          durationMs: 320,
        );
      }
      if (stallLevel >= 8) {
        final origin = (task['originUrl'] ?? '').toString();
        _showSmartOperation('自愈：回到信息流', point: const Offset(0.5, 0.2));
        if (origin.startsWith('http') && _isWithinSmartDownloadSite(origin)) {
          _loadUrl(origin);
          await Future<void>.delayed(const Duration(milliseconds: 1400));
        }
        task['stallCount'] = 0;
      }
    } finally {
      task['recoveringTrack'] = false;
    }
  }

  /// 兼容旧名。
  Future<void> _recoverActionRecipeTrack(
    Map<String, dynamic> task, {
    String reason = '保轨',
    int level = 0,
    bool light = false,
    bool allowAdvance = true,
  }) {
    return _guardActionRecipeTrack(
      task,
      reason: reason,
      allowHeavy: !light && level >= 3,
      allowAdvance: allowAdvance,
      stallLevel: level,
    );
  }

  Future<void> _startScopeBatchDownload({
    required Map<String, dynamic> website,
    required int targetCount,
    required MediaType mediaType,
    bool allowMixedMedia = true,
    bool startFromCurrentPage = true,
    int scopeDepth = 0,
    int? minVideoBytes,
    int? maxVideoBytes,
  }) async {
    if (_smartDownloadTask != null) return;
    final rawUrl = (website['url'] ?? '').toString().trim();
    final normalized =
        rawUrl.startsWith('http://') || rawUrl.startsWith('https://')
            ? rawUrl
            : (rawUrl.isEmpty ? _currentUrl : 'https://$rawUrl');
    final uri = Uri.tryParse(startFromCurrentPage ? _currentUrl : normalized);
    final host = _normalizeSmartHost(uri?.host ?? '');
    if (host.isEmpty && _currentUrl.isEmpty) return;
    if (!startFromCurrentPage && normalized.startsWith('http')) {
      _loadUrl(normalized);
      await Future<void>.delayed(const Duration(milliseconds: 900));
    }
    final startedAt = DateTime.now();
    final deadlineAt = startedAt.add(const Duration(hours: 5));
    _smartDownloadTask = <String, dynamic>{
      'mode': 'scope_batch',
      'phase': 'scope_batch_running',
      'siteUrl': normalized,
      'host': host,
      'siteProfile': _smartSiteProfile(host),
      'keyword': '',
      'mediaType': mediaType,
      'allowMixedMedia': allowMixedMedia,
      'target': targetCount.clamp(1, _kSmartDownloadMaxTarget),
      'minVideoBytes': minVideoBytes,
      'maxVideoBytes': maxVideoBytes,
      'success': 0,
      'failed': 0,
      'matchStage': '本页同层 · 深度 $scopeDepth',
      'demoPhase': 'auto',
      'gestureDownloadPending': false,
      'startedAt': startedAt,
      'deadlineAt': deadlineAt,
      'originUrl': _currentUrl,
      'startedFromCurrentPage': startFromCurrentPage,
      'scopeDepth': scopeDepth,
      'seenMediaUrls': <String>{},
      'attemptedVideoContexts': <String>{},
      'duplicateVideoUrlKeys': <String>{},
      'videoMediaStates': <String, String>{},
      'reservedMediaNameKeys': <String>{},
      'reservedMediaTitleKeys': <String>{},
      'allowBroadenDiscovery': false,
    };
    final task = _smartDownloadTask!;
    try {
      await WakelockPlus.enable();
      task['screenWakeLockEnabled'] = true;
    } catch (_) {}
    task['deadlineTimer'] = Timer(deadlineAt.difference(DateTime.now()), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_finishSmartDownload('已达到单次任务 5 小时时间上限'));
      }
    });
    _showSmartOperation(
      '本页同层批量 · 深度 $scopeDepth',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );
    unawaited(_runScopeBatchLoop(task));
  }

  Future<void> _runScopeBatchLoop(Map<String, dynamic> task) async {
    final controller = _controller;
    if (controller == null) {
      await _finishSmartDownload('页面未就绪');
      return;
    }
    final depth = (task['scopeDepth'] as int?) ?? 0;
    final target = (task['target'] as int?) ?? 50;
    final remaining = (target - ((task['success'] as int?) ?? 0)).clamp(
      1,
      _kSmartDownloadMaxTarget,
    );
    final allowMixed = task['allowMixedMedia'] == true;
    final mediaType = task['mediaType'] as MediaType?;
    final imagesOnly = !allowMixed && mediaType == MediaType.image;
    final videosOnly = !allowMixed && mediaType == MediaType.video;
    final minBytes = task['minVideoBytes'] as int?;
    final maxBytes = task['maxVideoBytes'] as int?;
    final startedAt =
        task['startedAt'] is DateTime
            ? task['startedAt'] as DateTime
            : DateTime.now().subtract(const Duration(minutes: 5));

    task['matchStage'] = '本页同层 · 预热嗅探';
    _showSmartOperation(
      '预热同层视频并加强嗅探…',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );
    try {
      await controller.evaluateJavascript(
        source: SmartScopeBatchJs.warmScope(depth: depth),
      );
    } catch (e) {
      debugPrint('scope batch warm failed: $e');
    }
    // 给 MediaInterceptor / early sniffer 一点时间抓到流
    await Future<void>.delayed(const Duration(milliseconds: 900));
    if (!identical(_smartDownloadTask, task)) return;

    task['matchStage'] = '本页同层 · 正在收集媒体（视频优先）';
    _showSmartOperation(
      '正在扫描同层媒体（视频优先）…',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );

    Map<String, dynamic>? collected;
    try {
      final raw = await controller.evaluateJavascript(
        source: SmartScopeBatchJs.collectAtDepth(
          depth: depth,
          imagesOnly: imagesOnly,
          videosOnly: videosOnly,
          limit: max(remaining * 2, remaining),
        ),
      );
      collected = _coerceJsMap(raw);
      debugPrint(
        'scope batch collect: videos=${collected?['videoCount']} '
        'images=${collected?['imageCount']} sniffed=${collected?['sniffed']}',
      );
    } catch (e) {
      debugPrint('scope batch collect failed: $e');
    }

    final pageCaptures =
        _recentCapturedMediaCandidates(
              MediaType.video,
              pageUrl: _currentUrl,
              notBefore: startedAt.subtract(const Duration(minutes: 2)),
              limit: 32,
            )
            .where((u) => !_isLikelyAdUrl(u) && _isLikelyDirectMediaUrl(u))
            .toList();

    final itemsRaw = collected?['items'];
    final items = <Map<String, dynamic>>[];
    if (itemsRaw is List) {
      for (final row in itemsRaw) {
        if (row is! Map) continue;
        final map = Map<String, dynamic>.from(row);
        var url = (map['url'] ?? '').toString().trim();
        final kind = (map['kind'] ?? '').toString();
        final candidates = <String>[];
        final rawCandidates = map['candidates'];
        if (rawCandidates is List) {
          for (final c in rawCandidates) {
            final s = c.toString().trim();
            if (s.isNotEmpty && !_isLikelyAdUrl(s)) candidates.add(s);
          }
        }
        // xfree：listing/封面 UUID 升成 full.mp4
        String? upgradeXfree(String raw) {
          final listing = RegExp(
            r'^(https?://cdn\.xfree\.com/xfree-prod/(?:[0-9a-f]/){3}[0-9a-f-]{36}/)listing\d*\.mp4',
            caseSensitive: false,
          ).firstMatch(raw);
          if (listing != null) return '${listing.group(1)}full.mp4';
          final uuid = RegExp(
            r'([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})',
            caseSensitive: false,
          ).firstMatch(raw);
          if (uuid != null &&
              RegExp(
                r'(thumbs\.xfree\.com|cdn\.xfree\.com|xfree\.com)',
                caseSensitive: false,
              ).hasMatch(raw)) {
            final id = uuid.group(1)!.toLowerCase();
            return 'https://cdn.xfree.com/xfree-prod/${id[0]}/${id[1]}/${id[2]}/$id/full.mp4';
          }
          return null;
        }

        void addCandidate(String? u) {
          if (u == null || u.isEmpty || _isLikelyAdUrl(u)) return;
          if (!candidates.contains(u) && u != url) candidates.add(u);
        }

        final upgradedUrl = url.isNotEmpty ? upgradeXfree(url) : null;
        if (upgradedUrl != null) {
          addCandidate(url);
          url = upgradedUrl;
          map['url'] = url;
          map['kind'] = 'video';
        }
        final poster = (map['posterUrl'] ?? '').toString();
        addCandidate(upgradeXfree(poster));
        for (final c in List<String>.from(candidates)) {
          addCandidate(upgradeXfree(c));
        }

        if (kind == 'video' || map['kind'] == 'video') {
          for (final c in pageCaptures) {
            if (!candidates.contains(c) && c != url) candidates.add(c);
          }
          if (url.isEmpty || !_isLikelyDirectMediaUrl(url)) {
            String? better = upgradeXfree(poster);
            if (better == null) {
              for (final c in candidates) {
                if (_isLikelyDirectMediaUrl(c) &&
                    !c.toLowerCase().contains('listing')) {
                  better = c;
                  break;
                }
              }
            }
            better ??= candidates.cast<String?>().firstWhere(
              (c) => c != null && _isLikelyDirectMediaUrl(c),
              orElse: () => null,
            );
            if (better != null && better.isNotEmpty) {
              if (url.isNotEmpty && !candidates.contains(url)) {
                candidates.insert(0, url);
              }
              url = better;
              map['url'] = url;
            }
          }
        }
        // 图片 URL 若其实是视频流，升为视频
        if ((map['kind'] ?? kind) == 'image' && _isLikelyDirectMediaUrl(url)) {
          map['kind'] = 'video';
          map['upgradedFromImage'] = true;
        }
        final effectiveKind = (map['kind'] ?? kind).toString();
        if (url.isEmpty && effectiveKind != 'video') continue;
        if (url.isNotEmpty && _isLikelyAdUrl(url)) continue;
        map['candidates'] = candidates.take(12).toList();
        items.add(map);
      }
    }

    // 视频优先排序，再截断到数量
    items.sort((a, b) {
      final ak = (a['kind'] == 'video') ? 0 : 1;
      final bk = (b['kind'] == 'video') ? 0 : 1;
      if (ak != bk) return ak.compareTo(bk);
      final as_ = (a['score'] as num?)?.toDouble() ?? 0;
      final bs_ = (b['score'] as num?)?.toDouble() ?? 0;
      return bs_.compareTo(as_);
    });

    if (items.isEmpty) {
      await _finishSmartDownload('同层未找到可下载媒体（已过滤广告/过小图）');
      return;
    }

    final seen = task['seenMediaUrls'] as Set<String>;
    final queue = <Map<String, dynamic>>[];
    for (final it in items) {
      if (queue.length >= remaining) break;
      final url = (it['url'] ?? '').toString();
      final kind = (it['kind'] ?? '').toString();
      if (url.isEmpty && kind == 'video') {
        // 仍无主键：用捕获池第一条未用过的流
        final fill = pageCaptures.firstWhere(
          (c) => !seen.contains(c),
          orElse: () => '',
        );
        if (fill.isEmpty) continue;
        it['url'] = fill;
        if (!seen.add(fill)) continue;
        queue.add(it);
        continue;
      }
      if (url.isEmpty) continue;
      if (!seen.add(url)) continue;
      queue.add(it);
    }

    final videoN = queue.where((e) => e['kind'] == 'video').length;
    final imageN = queue.length - videoN;
    task['matchStage'] = '本页同层 · 待下载 ${queue.length}（视频 $videoN / 图片 $imageN）';
    _showSmartOperation(
      '开始批量：视频 $videoN · 图片 $imageN',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );

    for (var start = 0; start < queue.length; start += 3) {
      if (!identical(_smartDownloadTask, task)) return;
      final left = (target - ((task['success'] as int?) ?? 0)).clamp(0, 3);
      if (left <= 0) break;
      final end = min(start + left, queue.length);
      final batch = queue.sublist(start, end);
      final outcomes = await Future.wait(
        batch.map((it) async {
          if (!identical(_smartDownloadTask, task)) {
            return (ok: false, failureType: 'stopped');
          }
          final url = (it['url'] ?? '').toString();
          final kind = (it['kind'] ?? '').toString();
          final isVideo = kind == 'video';
          final pageUrl = _currentUrl;
          final candidateUrls =
              <String>[
                    url,
                    ...((it['candidates'] is List)
                        ? (it['candidates'] as List).map((e) => e.toString())
                        : const <String>[]),
                  ]
                  .where((u) => u.trim().isNotEmpty && !_isLikelyAdUrl(u))
                  .toSet()
                  .toList();
          var failureType = '';
          if (!await _reserveSmartMediaName(task, url, pageUrl: pageUrl)) {
            return (
              ok: false,
              failureType:
                  (task['lastSmartReserveBlockReason'] ?? 'already_in_library')
                      .toString(),
            );
          }
          _showSmartOperation(
            isVideo ? '下载同层视频…' : '下载同层图片…',
            point: const Offset(0.5, 0.1),
            showFinger: false,
          );
          bool ok;
          if (isVideo) {
            ok = await _downloadMediaRobustly(
              item: <String, dynamic>{
                'videoUrl': url,
                'pageUrl': pageUrl,
                'candidateUrls': candidateUrls,
                'downloadOrigin': 'smart_batch',
                'isSmartBatchMedia': true,
                'smartTask': task,
                'mediaType': MediaType.video,
                if (minBytes != null) 'minFileBytes': minBytes,
                if (maxBytes != null) 'maxFileBytes': maxBytes,
              },
              showResultHint: false,
              onFailureType: (type) => failureType = type,
              minFileBytes: minBytes,
              maxFileBytes: maxBytes,
            );
          } else {
            ok = await _performBackgroundDownload(
              url,
              MediaType.image,
              skipFailurePrompt: true,
              showSuccessPrompt: false,
              showDuplicatePrompt: false,
              validateSmartMedia: true,
              isSmartBatchMedia: true,
              smartTask: task,
              smartPageUrl: pageUrl,
              onFailureType: (type) => failureType = type,
              maxRequestAttempts: 3,
              inactivityTimeout: const Duration(minutes: 2),
            );
          }
          if (!ok && failureType != 'already_in_library') {
            _releaseSmartMediaName(task, url, pageUrl: pageUrl);
          }
          return (ok: ok, failureType: failureType);
        }),
      );
      for (final outcome in outcomes) {
        if (!identical(_smartDownloadTask, task)) return;
        final skippedDuplicate =
            !outcome.ok &&
            <String>{
              'already_in_library',
              'already_in_smart_task',
              'duplicate_name_in_smart_task',
              'already_downloading',
            }.contains(outcome.failureType);
        if (outcome.ok) {
          task['success'] = (task['success'] as int) + 1;
        } else if (!skippedDuplicate) {
          task['failed'] = (task['failed'] as int) + 1;
        }
        task['matchStage'] = '本页同层 · 已完成 ${task['success']}/$target';
      }
    }

    if (!identical(_smartDownloadTask, task)) return;
    await _finishSmartDownload('同层批量结束（成功 ${task['success']}/$target）');
  }

  Future<void> _startPaginatedSniffDownload({
    required Map<String, dynamic> website,
    required int targetCount,
    bool unlimitedTarget = false,
    required MediaType mediaType,
    bool startFromCurrentPage = true,
    int sniffMaxPages = 0,
    int? minVideoBytes,
    int? maxVideoBytes,
    bool autoVideoSizeRange = false,
  }) async {
    if (_smartDownloadTask != null) return;
    final rawUrl = (website['url'] ?? '').toString().trim();
    final normalized =
        rawUrl.startsWith('http://') || rawUrl.startsWith('https://')
            ? rawUrl
            : (rawUrl.isEmpty ? _currentUrl : 'https://$rawUrl');
    final uri = Uri.tryParse(startFromCurrentPage ? _currentUrl : normalized);
    final host = _normalizeSmartHost(uri?.host ?? '');
    if (host.isEmpty && _currentUrl.isEmpty) return;
    if (!startFromCurrentPage && normalized.startsWith('http')) {
      _loadUrl(normalized);
      await Future<void>.delayed(const Duration(milliseconds: 900));
    }
    final startedAt = DateTime.now();
    final deadlineAt = startedAt.add(const Duration(hours: 5));
    final resolvedTarget =
        unlimitedTarget || targetCount <= 0
            ? _kPaginatedSniffSoftMaxTarget
            : targetCount.clamp(1, _kPaginatedSniffSoftMaxTarget);
    final resolvedMaxPages =
        sniffMaxPages > 0
            ? sniffMaxPages.clamp(1, _kPaginatedSniffMaxPages)
            : _kPaginatedSniffMaxPages;
    _smartDownloadTask = <String, dynamic>{
      'mode': 'paginated_sniff',
      'phase': 'paginated_sniff_discover',
      'siteUrl': normalized,
      'host': host,
      'siteProfile': _smartSiteProfile(host),
      'keyword': '',
      'mediaType': mediaType,
      'allowMixedMedia': true,
      'target': resolvedTarget,
      'sniffUnlimited': unlimitedTarget || targetCount <= 0,
      'minVideoBytes': minVideoBytes,
      'maxVideoBytes': maxVideoBytes,
      'autoVideoSizeRange': autoVideoSizeRange,
      'success': 0,
      'failed': 0,
      'matchStage': '分页嗅探 · 准备中',
      'demoPhase': 'auto',
      'gestureDownloadPending': false,
      'startedAt': startedAt,
      'deadlineAt': deadlineAt,
      'originUrl': _currentUrl,
      'startedFromCurrentPage': startFromCurrentPage,
      'sniffPageLimit': resolvedMaxPages,
      'sniffAbortRequested': false,
      'seenMediaUrls': <String>{},
      'attemptedVideoContexts': <String>{},
      'duplicateVideoUrlKeys': <String>{},
      'videoMediaStates': <String, String>{},
      'reservedMediaNameKeys': <String>{},
      'reservedMediaTitleKeys': <String>{},
      'allowBroadenDiscovery': false,
    };
    final task = _smartDownloadTask!;
    try {
      await WakelockPlus.enable();
      task['screenWakeLockEnabled'] = true;
    } catch (_) {}
    task['deadlineTimer'] = Timer(deadlineAt.difference(DateTime.now()), () {
      if (identical(_smartDownloadTask, task)) {
        unawaited(_finishSmartDownload('已达到单次任务 5 小时时间上限'));
      }
    });
    _showSmartOperation(
      '分页嗅探 · 分层发现同站页面…',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );
    unawaited(_runPaginatedSniffFlow(task));
  }

  Future<void> _runPaginatedSniffFlow(Map<String, dynamic> task) async {
    final controller = _controller;
    if (controller == null) {
      await _finishSmartDownload('页面未就绪');
      return;
    }
    final host = (task['host'] ?? '').toString();
    final maxPages = ((task['sniffPageLimit'] as int?) ??
            _kPaginatedSniffMaxPages)
        .clamp(1, _kPaginatedSniffMaxPages);
    final originUrl = (task['originUrl'] ?? _currentUrl).toString();
    final mediaType = task['mediaType'] as MediaType? ?? MediaType.video;
    final allowMixed = task['allowMixedMedia'] == true;
    final imagesOnly = !allowMixed && mediaType == MediaType.image;
    final videosOnly = !allowMixed && mediaType == MediaType.video;
    final target = (task['target'] as int?) ?? _kPaginatedSniffSoftMaxTarget;
    final collectLimit = min(80, max(32, target));
    final minBytes = task['minVideoBytes'] as int?;
    final maxBytes = task['maxVideoBytes'] as int?;

    bool sniffAborted() =>
        !identical(_smartDownloadTask, task) ||
        task['sniffAbortRequested'] == true;

    task['phase'] = 'paginated_sniff_discover';
    task['matchStage'] = '分页嗅探 · 分层发现同站页（最多 $maxPages 页）';
    final pageTargets = await _discoverPaginatedSniffPages(
      host: host,
      maxPages: maxPages,
    );
    if (sniffAborted()) {
      // 发现阶段就被停：无结果则直接结束。
      if (!identical(_smartDownloadTask, task)) return;
      await _finishSmartDownload('已停止嗅探（尚未收集到页面）');
      return;
    }
    if (pageTargets.isEmpty) {
      await _finishSmartDownload('未找到可嗅探页面');
      return;
    }
    debugPrint(
      'paginatedSniff: discover pages=${pageTargets.length} maxPages=$maxPages '
      'labels=${pageTargets.take(8).map((e) => e['label']).join(' | ')}',
    );

    final pageResults = <Map<String, dynamic>>[];
    final expandSeen = <String>{
      for (final p in pageTargets) (p['url'] ?? '').toString(),
    };
    // 跨页去重：UI 计数与下载队列共用同一套唯一可下 URL。
    final globalSeenUrls = <String>{};
    var abortedDuringScan = false;

    for (var i = 0; i < pageTargets.length; i++) {
      if (sniffAborted()) {
        abortedDuringScan = identical(_smartDownloadTask, task);
        break;
      }
      if (pageResults.length >= maxPages) break;
      final page = pageTargets[i];
      final pageUrl = (page['url'] ?? '').toString();
      final source = (page['source'] ?? '').toString();
      final label = (page['label'] ?? pageUrl).toString();
      if (_isJunkSniffPage(pageUrl, label)) {
        debugPrint('paginatedSniff: skip junk page label=$label url=$pageUrl');
        continue;
      }
      final layerHint = _paginatedSniffLayerLabelForPageIndex(i);
      task['phase'] = 'paginated_sniff_scanning';
      task['matchStage'] = '分页嗅探 · $layerHint · ${i + 1}/${pageTargets.length}';
      _showSmartOperation(
        '分层嗅探 ${i + 1}/${pageTargets.length}：$label',
        point: const Offset(0.5, 0.1),
        showFinger: false,
      );

      var items = <Map<String, dynamic>>[];
      final onCurrent =
          source == 'current' || _isSameLoadedDocument(pageUrl, _currentUrl);
      if (onCurrent) {
        items = await _sniffCollectPageMediaItems(
          imagesOnly: imagesOnly,
          videosOnly: videosOnly,
          limit: collectLimit,
          pageUrl: _currentUrl,
          notBefore: (task['startedAt'] as DateTime?)?.subtract(
            const Duration(minutes: 30),
          ),
        );
      } else {
        // 仅用同文档捕获预热；不够则导航实嗅，避免把别页流误算进本页。
        items = _harvestCapturedMediaForPage(
          pageUrl: pageUrl,
          imagesOnly: imagesOnly,
          videosOnly: videosOnly,
          limit: min(24, collectLimit),
          requireSameDocument: true,
        );
        final hasSameDocVideo = items.any(
          (e) => e['kind'] == 'video' && _sniffItemLooksDownloadable(e),
        );
        final needsLive = !hasSameDocVideo || items.length < 2;
        if (needsLive) {
          final navigated = await _navigateAndAwaitForSniff(
            task,
            pageUrl,
            settleMs: 1400,
          );
          if (sniffAborted()) {
            abortedDuringScan = identical(_smartDownloadTask, task);
            break;
          }
          if (navigated) {
            final live = await _sniffCollectPageMediaItems(
              imagesOnly: imagesOnly,
              videosOnly: videosOnly,
              limit: collectLimit,
              pageUrl: pageUrl,
              notBefore: DateTime.now().subtract(const Duration(minutes: 2)),
            );
            items = _mergeSniffItems(items, live);
            if (pageTargets.length < maxPages && !sniffAborted()) {
              await _appendDiscoveredSniffPages(
                pageTargets,
                expandSeen,
                host: host,
                maxPages: maxPages,
                source: 'expand',
              );
            }
          }
        }
      }

      if (sniffAborted() && items.isEmpty) {
        abortedDuringScan = identical(_smartDownloadTask, task);
        break;
      }

      items = _normalizeSniffItemsVideoFirst(items);
      final downloadable = <Map<String, dynamic>>[];
      for (final raw in items) {
        if (!_sniffItemLooksDownloadable(raw)) continue;
        final prepared = _prepareSniffQueueItem(raw, pageUrl: pageUrl);
        if (prepared == null) continue;
        final url = (prepared['url'] ?? '').toString();
        final norm = _normalizeVideoSourceUrl(url);
        if (!globalSeenUrls.add(url)) continue;
        if (norm.isNotEmpty && !globalSeenUrls.add('norm:$norm')) continue;
        downloadable.add(prepared);
      }
      final videoCount = downloadable.where((e) => e['kind'] == 'video').length;
      final imageCount = downloadable.length - videoCount;
      debugPrint(
        'paginatedSniff: page#$i label=$label '
        'downloadable=${downloadable.length} video=$videoCount image=$imageCount '
        'sample=${downloadable.take(3).map((e) => e['url']).join(' , ')}',
      );
      pageResults.add({
        'url': pageUrl,
        'label': label,
        'source': source,
        'isCurrent': source == 'current',
        'items': downloadable,
        'videoCount': videoCount,
        'imageCount': imageCount,
      });
    }

    // 硬退出（任务已清空）则不再弹结果。
    if (!identical(_smartDownloadTask, task)) return;

    if (originUrl.startsWith('http') &&
        !_isSameLoadedDocument(originUrl, _currentUrl) &&
        !sniffAborted()) {
      task['matchStage'] = '分页嗅探 · 返回起始页';
      _showSmartOperation(
        '嗅探完成，返回起始页…',
        point: const Offset(0.5, 0.1),
        showFinger: false,
      );
      await _navigateAndAwaitForSniff(task, originUrl, settleMs: 700);
    }
    if (!identical(_smartDownloadTask, task)) return;

    // 软停止后清掉中断标记，便于进入选层下载阶段。
    if (abortedDuringScan || task['sniffAbortRequested'] == true) {
      task['sniffAbortRequested'] = false;
      abortedDuringScan = true;
    }

    final totalVideos = pageResults.fold<int>(
      0,
      (sum, row) => sum + ((row['videoCount'] as int?) ?? 0),
    );
    final totalImages = pageResults.fold<int>(
      0,
      (sum, row) => sum + ((row['imageCount'] as int?) ?? 0),
    );
    debugPrint(
      'paginatedSniff: totals video=$totalVideos image=$totalImages '
      'pages=${pageResults.length} aborted=$abortedDuringScan',
    );
    if (totalVideos + totalImages <= 0) {
      await _finishSmartDownload(
        abortedDuringScan ? '已停止嗅探，尚未收集到可下载媒体' : '未嗅探到可真实下载的媒体（已过滤广告/海报）',
      );
      return;
    }

    task['phase'] = 'paginated_sniff_choose';
    task['matchStage'] =
        abortedDuringScan
            ? '分页嗅探 · 已中断，可选已嗅探结果（视频 $totalVideos / 图片 $totalImages）'
            : '分页嗅探 · 待选层级（视频 $totalVideos / 图片 $totalImages）';
    _showSmartOperation(
      abortedDuringScan ? '嗅探已中断，请选择下载范围' : '分层嗅探完成，请选择下载层级',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );

    final choice = await _showPaginatedSniffScopePicker(
      pageResults: pageResults,
      abortedEarly: abortedDuringScan,
    );
    if (!identical(_smartDownloadTask, task)) return;
    if (choice == null || choice == 'cancel') {
      await _finishSmartDownload('已取消下载（嗅探结果已丢弃）');
      return;
    }

    var takePages = pageResults.length;
    if (choice.startsWith('layer:')) {
      takePages = int.tryParse(choice.substring('layer:'.length)) ?? takePages;
    }
    takePages = takePages.clamp(1, pageResults.length);
    final selectedPages = pageResults.take(takePages).toList();

    // 层内条目已按全局唯一可下 URL 存好；队列再建一次防并发态污染。
    final queue = _buildPaginatedSniffDownloadQueue(
      task: task,
      selectedPages: selectedPages,
      target: _kPaginatedSniffSoftMaxTarget,
    );
    final unlimited = task['sniffUnlimited'] == true;
    final effectiveTarget =
        unlimited
            ? queue.length.clamp(1, _kPaginatedSniffSoftMaxTarget)
            : min(target, queue.length).clamp(1, _kPaginatedSniffSoftMaxTarget);
    task['target'] = effectiveTarget;
    if (queue.length > effectiveTarget) {
      queue.removeRange(effectiveTarget, queue.length);
    }

    debugPrint(
      'paginatedSniff: queue size=${queue.length} target=$effectiveTarget '
      'unlimited=$unlimited '
      'sample=${queue.take(5).map((e) => '${e['kind']}:${e['url']}').join(' | ')}',
    );

    if (queue.isEmpty) {
      await _finishSmartDownload('所选层级没有可真实下载的新媒体');
      return;
    }

    task['phase'] = 'paginated_sniff_downloading';
    final videoN = queue.where((e) => e['kind'] == 'video').length;
    final imageN = queue.length - videoN;
    task['matchStage'] = '分页嗅探 · 下载中（视频 $videoN / 图片 $imageN）';
    _showSmartOperation(
      '开始下载：视频 $videoN · 图片 $imageN',
      point: const Offset(0.5, 0.1),
      showFinger: false,
    );
    await _downloadPaginatedSniffQueue(
      task,
      queue,
      minBytes: minBytes,
      maxBytes: maxBytes,
    );
  }

  String _paginatedSniffLayerLabelForPageIndex(int index) {
    final pageNo = index + 1;
    for (var i = 0; i < _kPaginatedSniffLayerSizes.length; i++) {
      if (pageNo <= _kPaginatedSniffLayerSizes[i]) {
        return '第${i + 1}层';
      }
    }
    return '扩展层';
  }

  Future<List<Map<String, dynamic>>> _discoverPaginatedSniffPages({
    required String host,
    required int maxPages,
  }) async {
    final pages = <Map<String, dynamic>>[];
    final seen = <String>{};

    void add(String rawUrl, String source, {String label = ''}) {
      final url = rawUrl.trim().split('#').first;
      if (url.isEmpty ||
          !(url.startsWith('http://') || url.startsWith('https://'))) {
        return;
      }
      final uri = Uri.tryParse(url);
      final pageHost = _normalizeSmartHost(uri?.host ?? '');
      if (pageHost.isEmpty) return;
      if (host.isNotEmpty && !_sameSmartSite(pageHost, host)) return;
      if (seen.contains(url)) return;
      final resolvedLabel =
          label.isNotEmpty ? label : _shortSniffPageLabel(url);
      // 当前页始终保留；邻近/历史丢掉语言切换与导航垃圾链。
      if (source != 'current' && _isJunkSniffPage(url, resolvedLabel)) {
        return;
      }
      seen.add(url);
      pages.add({'url': url, 'source': source, 'label': resolvedLabel});
    }

    final current = _currentUrl.trim().split('#').first;
    if (current.startsWith('http')) {
      add(current, 'current', label: '当前页');
    }

    for (final row in _sessionPageTrail) {
      if (pages.length >= maxPages) break;
      final url = (row['url'] ?? '').toString();
      final title = (row['title'] ?? '').toString().trim();
      add(
        url,
        'session',
        label: title.isNotEmpty ? title : _shortSniffPageLabel(url),
      );
    }

    if (pages.length < maxPages && _controller != null) {
      await _appendDiscoveredSniffPages(
        pages,
        seen,
        host: host,
        maxPages: maxPages,
        source: 'nearby',
      );
    }

    if (pages.length < maxPages) {
      for (final row in _history) {
        if (pages.length >= maxPages) break;
        final url = (row['url'] ?? '').toString();
        final title = (row['title'] ?? '').toString().trim();
        add(
          url,
          'history',
          label: title.isNotEmpty ? title : _shortSniffPageLabel(url),
        );
      }
    }

    return pages.take(maxPages).toList();
  }

  Future<void> _appendDiscoveredSniffPages(
    List<Map<String, dynamic>> pages,
    Set<String> seen, {
    required String host,
    required int maxPages,
    required String source,
  }) async {
    if (_controller == null || pages.length >= maxPages) return;
    try {
      final raw = await _controller!.evaluateJavascript(
        source: SmartPaginatedSniffJs.discoverNearbyPages(limit: maxPages * 3),
      );
      final map = _coerceJsMap(raw);
      final list = map?['pages'];
      if (list is! List) return;
      for (final row in list) {
        if (pages.length >= maxPages) break;
        if (row is! Map) continue;
        final url = (row['url'] ?? '').toString().trim().split('#').first;
        if (url.isEmpty || seen.contains(url)) continue;
        final label =
            (row['label'] ?? '').toString().trim().isNotEmpty
                ? (row['label'] ?? '').toString()
                : _shortSniffPageLabel(url);
        if (_isJunkSniffPage(url, label)) continue;
        final uri = Uri.tryParse(url);
        final pageHost = _normalizeSmartHost(uri?.host ?? '');
        if (pageHost.isEmpty) continue;
        if (host.isNotEmpty && !_sameSmartSite(pageHost, host)) continue;
        seen.add(url);
        pages.add({'url': url, 'source': source, 'label': label});
      }
    } catch (e) {
      debugPrint('paginatedSniff: expand pages failed: $e');
    }
  }

  bool _isJunkSniffPage(String url, String label) {
    final text = label.replaceAll(RegExp(r'\s+'), ' ').trim();
    if (text.isNotEmpty) {
      final junkLabel = RegExp(
        r'^(?:中文(?:\(简体\)|（简体）)?|简体|繁體|繁体|english|日本語|한국어|hong\s*kong|taiwan|singapore|全部播放列表|播放列表|playlists?|合作伙伴|经纪公司|關於我們|关于我们|隐私|privacy|terms|cookie|登录|登錄|注册|sign\s*in|log\s*in|language|語言|语言)$',
        caseSensitive: false,
      );
      if (junkLabel.hasMatch(text)) return true;
      if (text.length <= 16 &&
          RegExp(
            r'合作|经纪|伙伴|语言|語言|地区|地區|playlist',
            caseSensitive: false,
          ).hasMatch(text)) {
        return true;
      }
    }
    final lower = url.toLowerCase();
    if (RegExp(
      r'/(?:language|lang|locale|i18n|partner|about|privacy|terms|login|signin|register|signup|playlist|playlists)(?:/|$|\?)',
      caseSensitive: false,
    ).hasMatch(lower)) {
      return true;
    }
    if (RegExp(r'[?&](?:lang|locale|language|hl|country)=').hasMatch(lower)) {
      return true;
    }
    if (RegExp(
      r'(?:^|[/?#_-])(?:zh-cn|zh-tw|zh-hk|en-us|en-gb|ja-jp|ko-kr)(?:$|[/?#_])',
      caseSensitive: false,
    ).hasMatch(lower)) {
      return true;
    }
    return false;
  }

  bool _isLikelyPosterOrThumbImageUrl(String url) {
    final s = url.toLowerCase();
    if (s.contains('blob:')) return true;
    const hints = [
      'poster',
      'thumbnail',
      'thumb',
      'cover',
      'sprite',
      'preview',
      'placeholder',
      'loading',
      'spinner',
      'avatar',
      'favicon',
      'banner',
      'ads',
      '/ad/',
    ];
    for (final h in hints) {
      if (s.contains(h)) return true;
    }
    return s.endsWith('.svg') || s.contains('.svg?');
  }

  bool _isSniffVideoStreamUrl(String url) {
    final u = url.trim();
    if (u.isEmpty || u.startsWith('blob:') || u.startsWith('data:')) {
      return false;
    }
    if (_isLikelyAdUrl(u) || _isLikelyPosterOrThumbImageUrl(u)) return false;
    if (!(u.startsWith('http://') || u.startsWith('https://'))) return false;
    return _isLikelyDirectMediaUrl(u) ||
        _isCapturedVideoCandidate(u) ||
        _isTrustedMediaCandidate(u) ||
        u.toLowerCase().contains('.m3u8') ||
        u.toLowerCase().contains('.mpd');
  }

  String? _pickBestSniffDownloadUrl(Map<String, dynamic> item) {
    final kind = (item['kind'] ?? '').toString();
    final primary = (item['url'] ?? '').toString().trim();
    final candidates =
        <String>[
              if (primary.isNotEmpty) primary,
              ...((item['candidates'] is List)
                  ? (item['candidates'] as List).map((e) => e.toString())
                  : const <String>[]),
            ]
            .map((e) => e.trim())
            .where((e) => e.isNotEmpty && !_isLikelyAdUrl(e))
            .toList();
    if (candidates.isEmpty) return null;
    if (kind == 'video' || candidates.any(_isSniffVideoStreamUrl)) {
      String? best;
      var bestScore = -1;
      for (final u in candidates) {
        if (!_isSniffVideoStreamUrl(u)) continue;
        var score = _scoreFavoriteVideoUrl(u);
        if (_isCapturedVideoCandidate(u) || _isTrustedMediaCandidate(u)) {
          score += 500;
        }
        if (score > bestScore) {
          bestScore = score;
          best = u;
        }
      }
      return best;
    }
    for (final u in candidates) {
      if (u.startsWith('http') &&
          !u.startsWith('blob:') &&
          !_isLikelyPosterOrThumbImageUrl(u) &&
          !_isLikelyDirectMediaUrl(u)) {
        return u;
      }
    }
    return null;
  }

  Map<String, dynamic>? _prepareSniffQueueItem(
    Map<String, dynamic> raw, {
    required String pageUrl,
  }) {
    final it = Map<String, dynamic>.from(raw);
    final best = _pickBestSniffDownloadUrl(it);
    if (best == null || best.isEmpty) return null;
    final kind =
        _isSniffVideoStreamUrl(best)
            ? 'video'
            : ((it['kind'] ?? 'image').toString());
    // 视频必须以真实流为主键；海报/页面地址不得进入队列。
    if (kind == 'video' && !_isSniffVideoStreamUrl(best)) return null;
    if (kind == 'image' &&
        (_isLikelyPosterOrThumbImageUrl(best) ||
            _isLikelyDirectMediaUrl(best))) {
      return null;
    }
    final candidates =
        <String>{
          best,
          ...((it['candidates'] is List)
              ? (it['candidates'] as List).map((e) => e.toString())
              : const <String>[]),
          if ((it['url'] ?? '').toString().trim().isNotEmpty)
            (it['url'] ?? '').toString().trim(),
        }.where((u) => u.trim().isNotEmpty && !_isLikelyAdUrl(u)).toList();
    it['url'] = best;
    it['kind'] = kind;
    it['candidates'] = candidates.take(12).toList();
    it['pageUrl'] = pageUrl;
    return it;
  }

  bool _sniffItemLooksDownloadable(Map<String, dynamic> item) {
    return _pickBestSniffDownloadUrl(item) != null;
  }

  List<Map<String, dynamic>> _normalizeSniffItemsVideoFirst(
    List<Map<String, dynamic>> items,
  ) {
    final out = <Map<String, dynamic>>[];
    for (final raw in items) {
      final it = Map<String, dynamic>.from(raw);
      var url = (it['url'] ?? '').toString().trim();
      var kind = (it['kind'] ?? '').toString();
      final candidates =
          <String>[
                if (url.isNotEmpty) url,
                ...((it['candidates'] is List)
                    ? (it['candidates'] as List).map((e) => e.toString())
                    : const <String>[]),
              ]
              .map((e) => e.trim())
              .where((e) => e.isNotEmpty && !_isLikelyAdUrl(e))
              .toSet()
              .toList();

      // 候选里若有真实视频流，升级为 video，避免海报图冒充主媒体。
      String? videoCandidate;
      for (final c in candidates) {
        if (_isLikelyDirectMediaUrl(c) ||
            c.contains('.m3u8') ||
            c.contains('.mpd') ||
            _isCapturedVideoCandidate(c)) {
          videoCandidate = c;
          break;
        }
      }
      if (videoCandidate != null) {
        kind = 'video';
        if (url.isEmpty ||
            !_isLikelyDirectMediaUrl(url) ||
            _isLikelyPosterOrThumbImageUrl(url)) {
          url = videoCandidate;
        }
      } else if (kind == 'image' && _isLikelyDirectMediaUrl(url)) {
        kind = 'video';
      }

      if (kind == 'image' && _isLikelyPosterOrThumbImageUrl(url)) {
        // 无视频候选的纯海报跳过
        if (videoCandidate == null) continue;
      }

      it['url'] = url;
      it['kind'] = kind;
      it['candidates'] = candidates.take(12).toList();
      out.add(it);
    }
    out.sort((a, b) {
      final ak = (a['kind'] == 'video') ? 0 : 1;
      final bk = (b['kind'] == 'video') ? 0 : 1;
      if (ak != bk) return ak.compareTo(bk);
      final as_ = (a['score'] as num?)?.toDouble() ?? 0;
      final bs_ = (b['score'] as num?)?.toDouble() ?? 0;
      return bs_.compareTo(as_);
    });
    return out;
  }

  List<Map<String, dynamic>> _buildPaginatedSniffDownloadQueue({
    required Map<String, dynamic> task,
    required List<Map<String, dynamic>> selectedPages,
    required int target,
  }) {
    final seen = task['seenMediaUrls'] as Set<String>;
    final videos = <Map<String, dynamic>>[];
    final images = <Map<String, dynamic>>[];

    for (final page in selectedPages) {
      final pageUrl = (page['url'] ?? '').toString();
      final items = page['items'];
      if (items is! List) continue;
      final pageVideos = <Map<String, dynamic>>[];
      final pageImages = <Map<String, dynamic>>[];
      for (final raw in items) {
        if (raw is! Map) continue;
        final prepared = _prepareSniffQueueItem(
          Map<String, dynamic>.from(raw),
          pageUrl: pageUrl,
        );
        if (prepared == null) continue;
        final url = (prepared['url'] ?? '').toString().trim();
        if (url.isEmpty || _isLikelyAdUrl(url)) continue;
        if (!seen.add(url)) continue;
        final norm = _normalizeVideoSourceUrl(url);
        if (norm.isNotEmpty && !seen.add('norm:$norm')) continue;
        if (prepared['kind'] == 'video') {
          pageVideos.add(prepared);
        } else {
          pageImages.add(prepared);
        }
      }
      videos.addAll(pageVideos);
      // 同页已有视频时，丢掉海报类图片，避免「只下封面、不下视频」。
      if (pageVideos.isEmpty) {
        images.addAll(pageImages);
      } else {
        images.addAll(
          pageImages.where(
            (e) => !_isLikelyPosterOrThumbImageUrl((e['url'] ?? '').toString()),
          ),
        );
      }
    }

    final queue = <Map<String, dynamic>>[...videos, ...images];
    debugPrint(
      'paginatedSniff: buildQueue videos=${videos.length} '
      'images=${images.length} cappedTarget=$target',
    );
    if (queue.length > target) {
      return queue.take(target).toList(growable: true);
    }
    return queue;
  }

  String _shortSniffPageLabel(String url) {
    final uri = Uri.tryParse(url);
    if (uri == null) return url;
    final path = uri.path.isEmpty || uri.path == '/' ? '' : uri.path;
    final q = uri.query.isEmpty ? '' : '?…';
    final host = uri.host.replaceFirst(RegExp(r'^www\.'), '');
    final label = '$host$path$q';
    return label.length > 42 ? '${label.substring(0, 40)}…' : label;
  }

  List<Map<String, dynamic>> _harvestCapturedMediaForPage({
    required String pageUrl,
    required bool imagesOnly,
    required bool videosOnly,
    required int limit,
    bool requireSameDocument = false,
  }) {
    final pageUri = Uri.tryParse(pageUrl);
    final items = <Map<String, dynamic>>[];
    final seen = <String>{};
    final scored = <(_CapturedWebResource, int, bool)>[];
    for (final resource in _capturedWebResources.values) {
      if (_isLikelyAdUrl(resource.url)) continue;
      final capturedPage = Uri.tryParse(resource.pageUrl);
      if (pageUri != null &&
          capturedPage != null &&
          pageUri.host.isNotEmpty &&
          capturedPage.host.isNotEmpty &&
          !_sameSmartSite(
            _normalizeSmartHost(pageUri.host),
            _normalizeSmartHost(capturedPage.host),
          )) {
        continue;
      }
      final sameDoc =
          pageUri != null &&
          capturedPage != null &&
          _isSameLoadedDocument(pageUrl, resource.pageUrl);
      if (requireSameDocument && !sameDoc) continue;
      final age = DateTime.now().difference(resource.capturedAt);
      // 非同文档仅接受极近捕获，且默认路径已要求同文档，避免跨页重复计数。
      if (!sameDoc && age > const Duration(minutes: 3)) continue;
      final isVideo = _capturedResourceMatchesType(resource, MediaType.video);
      final isImage = _capturedResourceMatchesType(resource, MediaType.image);
      if (imagesOnly && !isImage) continue;
      if (videosOnly && !isVideo) continue;
      if (!imagesOnly && !videosOnly && !isVideo && !isImage) continue;
      if (isVideo && !_isSniffVideoStreamUrl(resource.url)) continue;
      if (isImage &&
          (_isLikelyPosterOrThumbImageUrl(resource.url) ||
              _isLikelyDirectMediaUrl(resource.url))) {
        continue;
      }
      var score = max(0, 2000 - age.inSeconds);
      if (sameDoc) score += 5000;
      if (isVideo) score += 3000;
      scored.add((resource, score, sameDoc));
    }
    scored.sort((a, b) => b.$2.compareTo(a.$2));
    for (final entry in scored) {
      if (items.length >= limit) break;
      final url = entry.$1.url;
      if (!seen.add(url)) continue;
      final isVideo = _capturedResourceMatchesType(entry.$1, MediaType.video);
      items.add({
        'url': url,
        'kind': isVideo ? 'video' : 'image',
        'candidates': <String>[url],
        'score': entry.$2.toDouble(),
        'fromCapture': true,
        'sameDoc': entry.$3,
      });
    }
    return items;
  }

  Future<List<Map<String, dynamic>>> _sniffCollectPageMediaItems({
    required bool imagesOnly,
    required bool videosOnly,
    required int limit,
    required String pageUrl,
    DateTime? notBefore,
  }) async {
    final controller = _controller;
    if (controller == null) return const <Map<String, dynamic>>[];

    // 推荐层级：优先真实 video 较多的一层。
    var depth = 2;
    try {
      final levelsRaw = await controller.evaluateJavascript(
        source: SmartScopeBatchJs.listLevels(
          imagesOnly: imagesOnly,
          videosOnly: videosOnly,
        ),
      );
      final levelsMap = _coerceJsMap(levelsRaw);
      final defaultDepth = (levelsMap?['defaultDepth'] as num?)?.toInt();
      if (defaultDepth != null) depth = defaultDepth.clamp(0, 16);
    } catch (_) {}

    try {
      await controller.evaluateJavascript(
        source: SmartScopeBatchJs.warmScope(depth: depth),
      );
    } catch (_) {}
    await Future<void>.delayed(const Duration(milliseconds: 650));

    Map<String, dynamic>? collected;
    try {
      final raw = await controller.evaluateJavascript(
        source: SmartScopeBatchJs.collectAtDepth(
          depth: depth,
          imagesOnly: imagesOnly,
          videosOnly: videosOnly,
          limit: limit.clamp(1, 100),
        ),
      );
      collected = _coerceJsMap(raw);
    } catch (e) {
      debugPrint('paginated sniff collect failed: $e');
    }

    final pageCaptures =
        _recentCapturedMediaCandidates(
              MediaType.video,
              pageUrl: pageUrl,
              notBefore: notBefore,
              limit: 32,
            )
            .where((u) => !_isLikelyAdUrl(u) && _isLikelyDirectMediaUrl(u))
            .toList();

    final items = <Map<String, dynamic>>[];
    final itemsRaw = collected?['items'];
    if (itemsRaw is List) {
      for (final row in itemsRaw) {
        if (row is! Map) continue;
        final map = Map<String, dynamic>.from(row);
        var url = (map['url'] ?? '').toString().trim();
        final kind = (map['kind'] ?? '').toString();
        final candidates = <String>[];
        final rawCandidates = map['candidates'];
        if (rawCandidates is List) {
          for (final c in rawCandidates) {
            final s = c.toString().trim();
            if (s.isNotEmpty && !_isLikelyAdUrl(s)) candidates.add(s);
          }
        }
        if (kind == 'video' || map['kind'] == 'video') {
          for (final c in pageCaptures) {
            if (!candidates.contains(c) && c != url) candidates.add(c);
          }
          if (url.isEmpty || !_isLikelyDirectMediaUrl(url)) {
            String? better;
            for (final c in candidates) {
              if (_isLikelyDirectMediaUrl(c)) {
                better = c;
                break;
              }
            }
            if (better != null && better.isNotEmpty) {
              if (url.isNotEmpty && !candidates.contains(url)) {
                candidates.insert(0, url);
              }
              url = better;
              map['url'] = url;
            }
          }
        }
        if ((map['kind'] ?? kind) == 'image' && _isLikelyDirectMediaUrl(url)) {
          map['kind'] = 'video';
        }
        final effectiveKind = (map['kind'] ?? kind).toString();
        if (url.isEmpty && effectiveKind != 'video') continue;
        if (url.isNotEmpty && _isLikelyAdUrl(url)) continue;
        map['candidates'] = candidates.take(12).toList();
        items.add(map);
      }
    }

    // 捕获池兜底补齐（仅同文档，避免跨页把同一条流重复算进多层）
    if (items.length < limit) {
      final harvested = _harvestCapturedMediaForPage(
        pageUrl: pageUrl,
        imagesOnly: imagesOnly,
        videosOnly: videosOnly,
        limit: limit,
        requireSameDocument: true,
      );
      final merged = _mergeSniffItems(items, harvested);
      items
        ..clear()
        ..addAll(merged);
    }

    items.sort((a, b) {
      final ak = (a['kind'] == 'video') ? 0 : 1;
      final bk = (b['kind'] == 'video') ? 0 : 1;
      if (ak != bk) return ak.compareTo(bk);
      final as_ = (a['score'] as num?)?.toDouble() ?? 0;
      final bs_ = (b['score'] as num?)?.toDouble() ?? 0;
      return bs_.compareTo(as_);
    });

    final deduped = <Map<String, dynamic>>[];
    final seen = <String>{};
    for (final it in items) {
      final url = (it['url'] ?? '').toString();
      if (url.isEmpty) {
        deduped.add(it);
        continue;
      }
      if (!seen.add(url)) continue;
      deduped.add(it);
      if (deduped.length >= limit) break;
    }
    return deduped;
  }

  List<Map<String, dynamic>> _mergeSniffItems(
    List<Map<String, dynamic>> primary,
    List<Map<String, dynamic>> extra,
  ) {
    final out = <Map<String, dynamic>>[];
    final seen = <String>{};
    for (final list in [primary, extra]) {
      for (final it in list) {
        final url = (it['url'] ?? '').toString();
        if (url.isEmpty) {
          out.add(it);
          continue;
        }
        if (!seen.add(url)) continue;
        out.add(it);
      }
    }
    return out;
  }

  Future<bool> _navigateAndAwaitForSniff(
    Map<String, dynamic> task,
    String url, {
    int settleMs = 1000,
  }) async {
    if (!url.startsWith('http')) return false;
    if (_isSameLoadedDocument(url, _currentUrl)) {
      await Future<void>.delayed(Duration(milliseconds: settleMs ~/ 2));
      return true;
    }
    _loadUrl(url);
    final deadline = DateTime.now().add(const Duration(seconds: 12));
    while (DateTime.now().isBefore(deadline)) {
      if (!identical(_smartDownloadTask, task)) return false;
      await Future<void>.delayed(const Duration(milliseconds: 220));
      if (_isSameLoadedDocument(url, _currentUrl) && !_isLoading) {
        await Future<void>.delayed(Duration(milliseconds: settleMs));
        return true;
      }
    }
    return _isSameLoadedDocument(url, _currentUrl);
  }

  Future<String?> _showPaginatedSniffScopePicker({
    required List<Map<String, dynamic>> pageResults,
    bool abortedEarly = false,
  }) async {
    if (!mounted) return 'cancel';
    final total = pageResults.length;
    final layerSizes = <int>[];
    for (final n in _kPaginatedSniffLayerSizes) {
      if (n <= total) layerSizes.add(n);
    }
    if (layerSizes.isEmpty) layerSizes.add(1);
    if (!layerSizes.contains(total)) layerSizes.add(total);

    Map<String, int> statsFor(int take) {
      final slice = pageResults.take(take.clamp(1, total));
      var v = 0;
      var i = 0;
      for (final row in slice) {
        v += (row['videoCount'] as int?) ?? 0;
        i += (row['imageCount'] as int?) ?? 0;
      }
      return {'v': v, 'i': i, 'pages': take.clamp(1, total)};
    }

    return showDialog<String>(
      context: context,
      barrierDismissible: false,
      builder:
          (ctx) => AlertDialog(
            title: Text(abortedEarly ? '嗅探已中断 · 已有结果' : '分层嗅探结果'),
            content: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Text(
                    abortedEarly
                        ? '已停止继续嗅探。以下为目前已收集到的可下载媒体，请选择范围一键下载。'
                        : '选择下载层级（越大覆盖越多同站页面）。'
                            '数量=该层去重后可真实下载的地址（视频优先，已排除海报/语言导航页）。',
                    style: const TextStyle(fontSize: 12, color: Colors.black54),
                  ),
                  const SizedBox(height: 12),
                  ...List<Widget>.generate(layerSizes.length, (idx) {
                    final n = layerSizes[idx];
                    final st = statsFor(n);
                    final isFirst = n == 1;
                    final title =
                        isFirst
                            ? '第1层 · 当前页'
                            : (n == total
                                ? '全部已嗅探 · $n 页'
                                : '第${idx + 1}层 · 最近 $n 页');
                    return Padding(
                      padding: const EdgeInsets.only(bottom: 8),
                      child: OutlinedButton(
                        onPressed: () => Navigator.pop(ctx, 'layer:$n'),
                        child: Align(
                          alignment: Alignment.centerLeft,
                          child: Text(
                            '$title\n视频 ${st['v']} · 图片 ${st['i']}',
                            style: const TextStyle(height: 1.25),
                          ),
                        ),
                      ),
                    );
                  }),
                  const SizedBox(height: 4),
                  ...pageResults.take(8).map((row) {
                    final label = (row['label'] ?? row['url'] ?? '').toString();
                    final v = (row['videoCount'] as int?) ?? 0;
                    final i = (row['imageCount'] as int?) ?? 0;
                    final tag =
                        row['isCurrent'] == true ? '当前' : (row['source'] ?? '');
                    return Padding(
                      padding: const EdgeInsets.only(bottom: 4),
                      child: Text(
                        '· [$tag] $label  （视频 $v / 图 $i）',
                        style: const TextStyle(
                          fontSize: 12,
                          color: Colors.black87,
                        ),
                        maxLines: 2,
                        overflow: TextOverflow.ellipsis,
                      ),
                    );
                  }),
                ],
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.pop(ctx, 'cancel'),
                child: const Text('取消'),
              ),
            ],
          ),
    );
  }

  Future<void> _downloadPaginatedSniffQueue(
    Map<String, dynamic> task,
    List<Map<String, dynamic>> queue, {
    int? minBytes,
    int? maxBytes,
  }) async {
    final target = (task['target'] as int?) ?? queue.length;
    debugPrint(
      'paginatedSniff: download start queue=${queue.length} target=$target '
      'minBytes=$minBytes maxBytes=$maxBytes (serial)',
    );
    // 串行下载：并行 HLS 易互相抢占/取消，导致「只下一成、其余失败就结束」。
    for (var i = 0; i < queue.length; i++) {
      if (!identical(_smartDownloadTask, task)) return;
      if (task['sniffAbortRequested'] == true) {
        debugPrint('paginatedSniff: download aborted by user at $i');
        break;
      }
      final success = (task['success'] as int?) ?? 0;
      if (success >= target) break;

      final it = queue[i];
      final prepared = _prepareSniffQueueItem(
        it,
        pageUrl: (it['pageUrl'] ?? _currentUrl).toString(),
      );
      if (prepared == null) {
        debugPrint('paginatedSniff: skip undownloadable item=${it['url']}');
        task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
        continue;
      }
      final url = (prepared['url'] ?? '').toString();
      final kind = (prepared['kind'] ?? '').toString();
      final isVideo = kind == 'video';
      final pageUrl = (prepared['pageUrl'] ?? _currentUrl).toString();
      final candidateUrls =
          <String>[
                url,
                ...((prepared['candidates'] is List)
                    ? (prepared['candidates'] as List).map((e) => e.toString())
                    : const <String>[]),
              ]
              .where((u) => u.trim().isNotEmpty && !_isLikelyAdUrl(u))
              .toSet()
              .toList();
      var failureType = '';
      _showSmartOperation(
        isVideo
            ? '分页嗅探 · 下载视频 ${i + 1}/${queue.length}'
            : '分页嗅探 · 下载图片 ${i + 1}/${queue.length}',
        point: const Offset(0.5, 0.1),
        showFinger: false,
      );
      task['matchStage'] =
          '分页嗅探 · 下载 ${i + 1}/${queue.length} · 已成功 $success/$target';

      bool ok;
      try {
        if (isVideo) {
          ok = await _downloadMediaRobustly(
            item: <String, dynamic>{
              'videoUrl': url,
              'pageUrl': pageUrl,
              'candidateUrls': candidateUrls,
              'downloadOrigin': 'smart_batch',
              'isSmartBatchMedia': true,
              'smartTask': task,
              'mediaType': MediaType.video,
              // 列表/多详情页常共用 pageUrl；允许按源地址区分，避免整页被 24h pageKey 误杀。
              'allowSourceUrlReuse': true,
              if (minBytes != null) 'minFileBytes': minBytes,
              if (maxBytes != null) 'maxFileBytes': maxBytes,
            },
            showResultHint: false,
            onFailureType: (type) => failureType = type,
            minFileBytes: minBytes,
            maxFileBytes: maxBytes,
          );
        } else {
          ok = await _performBackgroundDownload(
            url,
            MediaType.image,
            skipFailurePrompt: true,
            showSuccessPrompt: false,
            showDuplicatePrompt: false,
            validateSmartMedia: true,
            isSmartBatchMedia: true,
            smartTask: task,
            smartPageUrl: pageUrl,
            onFailureType: (type) => failureType = type,
            maxRequestAttempts: 3,
            inactivityTimeout: const Duration(minutes: 2),
          );
        }
      } catch (e) {
        ok = false;
        failureType = 'exception';
        debugPrint('paginatedSniff: download exception url=$url err=$e');
      }

      if (!identical(_smartDownloadTask, task)) return;
      final skippedDuplicate =
          !ok &&
          <String>{
            'already_in_library',
            'already_in_smart_task',
            'duplicate_name_in_smart_task',
            'already_downloading',
          }.contains(failureType);
      if (ok) {
        task['success'] = ((task['success'] as int?) ?? 0) + 1;
      } else if (!skippedDuplicate) {
        task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
      }
      debugPrint(
        'paginatedSniff: attempt#$i kind=$kind ok=$ok '
        'failureType=${failureType.isEmpty ? 'none' : failureType} '
        'success=${task['success']}/$target url=$url',
      );
      // 单条失败不退出整批；库写入失败也尽量继续下一条。
    }
    if (!identical(_smartDownloadTask, task)) return;
    debugPrint(
      'paginatedSniff: download done success=${task['success']}/$target '
      'failed=${task['failed']}',
    );
    await _finishSmartDownload('分页嗅探结束（成功 ${task['success']}/$target）');
  }

  Future<void> _runActionRecipeLoop(
    Map<String, dynamic> task,
    SmartActionRecipe recipe,
  ) async {
    var idleRounds = 0;
    // 干净站健康路径：长按→等下载→切条→重复；保轨/清障只在卡住时介入
    var healthyStreak = task['actionHealthyStreak'] == true;
    while (identical(_smartDownloadTask, task)) {
      final success = (task['success'] as int?) ?? 0;
      final target = (task['target'] as int?) ?? 0;
      if (success >= target) {
        await _finishSmartDownload();
        return;
      }
      final deadlineAt = task['deadlineAt'] as DateTime?;
      if (deadlineAt != null && !DateTime.now().isBefore(deadlineAt)) {
        await _finishSmartDownload('已达到单次任务 5 小时时间上限');
        return;
      }

      // 回合开始：健康连胜则跳过保轨；仅首轮/卡住才探测清障
      if (!healthyStreak) {
        await _guardActionRecipeTrack(task, reason: '回合开始', allowAdvance: true);
      } else if (task['needAdvancePastCurrent'] == true) {
        // 上轮已下载但可能未切走：只做廉价已处理检查，不探广告/自愈
        final stuck = await _actionCaptureMediaIdentity(task);
        if (await _shouldSkipAsHandledMedia(task, stuck)) {
          await _advancePastHandledMedia(task);
        } else {
          task['needAdvancePastCurrent'] = false;
        }
      }

      final beforeSuccess = success;
      final beforeIdentity = await _actionCaptureMediaIdentity(task);
      final beforeKey = (beforeIdentity?['key'] ?? '').toString();
      final roundStartedAt = DateTime.now();
      // 本轮已成功下载后：后续步骤（含 findNext）不再保轨，避免成功后再清障/双切
      var roundDownloadOk = false;

      for (var i = 0; i < recipe.steps.length; i++) {
        if (!identical(_smartDownloadTask, task)) return;
        if (((task['success'] as int?) ?? 0) >= target) break;
        final step = recipe.steps[i];
        task['matchStage'] =
            '动作 ${i + 1}/${recipe.steps.length} · ${step.kind.label}';

        // 回合级看门狗：同一媒体长时间无进展 → 强制跳过并继续后续 findNext
        final roundElapsed = DateTime.now().difference(roundStartedAt);
        final successNow = (task['success'] as int?) ?? 0;
        if (roundElapsed >= _kActionRecipeStepWatchdog &&
            successNow <= beforeSuccess &&
            task['actionForceSkipReleased'] != true) {
          await _actionRecipeForceSkipCurrent(
            task,
            outcome: 'step_watchdog_timeout',
            statusText: '超时无进展，强制跳过',
          );
          healthyStreak = false;
          task['actionHealthyStreak'] = false;
          // 跳到找下一条步骤（若后面还有）；否则本轮结束后保轨切条
          final nextFindIdx = recipe.steps.indexWhere(
            (s) =>
                s.kind == SmartActionKind.findNextMedia ||
                s.kind == SmartActionKind.findNextMediaRight,
            i,
          );
          if (nextFindIdx >= 0) {
            i = nextFindIdx - 1;
            continue;
          }
          break;
        }

        // 长按前：仅非健康时保轨（绝不预标记已处理；切条交给 findNext）
        if (step.kind == SmartActionKind.longPressDownload && !healthyStreak) {
          await _guardActionRecipeTrack(
            task,
            reason: '长按前',
            allowAdvance: true,
          );
        }

        try {
          await _executeSmartActionStep(task, step);
        } catch (e) {
          debugPrint('动作零件执行失败 ${step.kind.id}: $e');
          task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
          healthyStreak = false;
          task['actionHealthyStreak'] = false;
          roundDownloadOk = false;
          await _guardActionRecipeTrack(
            task,
            reason: '步骤异常恢复',
            allowAdvance: true,
            allowHeavy: idleRounds >= 2,
            stallLevel: idleRounds,
          );
        }

        if (((task['success'] as int?) ?? 0) > beforeSuccess) {
          roundDownloadOk = true;
        }

        // 健康路径 / 本轮已下载成功：步骤间不保轨（切条零件内部已有短 settle）
        if (!healthyStreak && !roundDownloadOk) {
          await _guardActionRecipeTrack(
            task,
            reason: '步骤后',
            allowAdvance: false,
          );
          await Future<void>.delayed(const Duration(milliseconds: 120));
        }
      }

      final afterSuccess = (task['success'] as int?) ?? 0;
      final afterIdentity = await _actionCaptureMediaIdentity(task);
      final afterKey = (afterIdentity?['key'] ?? '').toString();
      final gotNewDownload = afterSuccess > beforeSuccess;
      final mediaMoved =
          beforeKey.isNotEmpty && afterKey.isNotEmpty && afterKey != beforeKey;
      // 重复跳过也算「本轮有进展」，交给 findNext 切走即可
      final gotProgress =
          gotNewDownload ||
          ((task['duplicateSkipped'] as int?) ?? 0) >
              ((task['duplicateSkippedBeforeRound'] as int?) ?? 0) ||
          task['actionForceSkipReleased'] == true;

      if (gotNewDownload || (gotProgress && mediaMoved)) {
        idleRounds = 0;
        task['noSuccessRounds'] = 0;
        task['stallCount'] = 0;
        // 成功下载后若已切到新媒体 → 下一轮纯长按循环；未切走则下一轮需推走已处理
        healthyStreak = gotNewDownload && mediaMoved;
        task['actionHealthyStreak'] = healthyStreak;
        // 成功路径：不 recover、不二次切条（切条只由套路 findNext 负责）
      } else {
        healthyStreak = false;
        task['actionHealthyStreak'] = false;
        final noSuccess = ((task['noSuccessRounds'] as int?) ?? 0) + 1;
        task['noSuccessRounds'] = noSuccess;
        if (!mediaMoved) {
          idleRounds++;
          // 真·空转才升级重自愈
          await _guardActionRecipeTrack(
            task,
            reason: '空转/疑似死循环',
            allowAdvance: true,
            allowHeavy: idleRounds >= 3,
            stallLevel: idleRounds + 1,
          );
        } else if (!gotNewDownload) {
          // 已切到新媒体但未下载：下一轮直接长按，轻探一次即可
          await _guardActionRecipeTrack(
            task,
            reason: '已切条未下载',
            allowAdvance: false,
          );
        }
        if (idleRounds >= 10 || noSuccess >= 14) {
          await _finishSmartDownload(
            '连续多轮未能稳定下载（成功 $afterSuccess/$target），已停止。'
            '可换模板或先验证「上切/长按」零件',
          );
          return;
        }
      }
      task['duplicateSkippedBeforeRound'] =
          (task['duplicateSkipped'] as int?) ?? 0;
    }
  }

  Future<void> _executeSmartActionStep(
    Map<String, dynamic> task,
    SmartActionStep step,
  ) async {
    switch (step.kind) {
      case SmartActionKind.flickUp:
      case SmartActionKind.flickDown:
      case SmartActionKind.flickLeft:
      case SmartActionKind.flickRight:
        {
          if (task['mode'] == 'action_recipe' && task['actionProbe'] != true) {
            final needsGate =
                task['actionLongPressNeedsConfirm'] == true ||
                _actionRecipeHasDownloadWork(task);
            if (needsGate) {
              await _actionWaitDownload(task);
            }
            await _actionWaitStrictVideoMinimum(task);
            if (!_actionRecipeMayAdvancePastDownload(task)) {
              _showSmartOperation('媒体尚未成功入库，本步不切换');
              debugPrint(
                'action recipe switch BLOCKED flick '
                'outcome=${task['actionDownloadOutcome']} '
                'libraryOk=${task['actionLibrarySaveOk']}',
              );
              break;
            }
          }
          final axis =
              step.kind == SmartActionKind.flickUp
                  ? 'up'
                  : step.kind == SmartActionKind.flickDown
                  ? 'down'
                  : step.kind == SmartActionKind.flickLeft
                  ? 'left'
                  : 'right';
          final horizontal = axis == 'left' || axis == 'right';
          final label =
              axis == 'left'
                  ? '左扫'
                  : axis == 'right'
                  ? '右扫'
                  : axis == 'down'
                  ? '下扫'
                  : '上扫';
          // 横向禁止套用竖向近全屏参数；竖向禁止套用图片 0.50
          final rawDist = step.paramDouble(
            'distanceFraction',
            horizontal ? 0.67 : 0.7,
          );
          final rawDur = step.paramInt('durationMs', horizontal ? 380 : 600);
          final dist =
              horizontal
                  ? rawDist.clamp(0.55, 0.88)
                  : (rawDist < 0.5 ? 0.7 : rawDist.clamp(0.55, 0.92));
          final dur =
              horizontal
                  ? (rawDur >= 500 ? 380 : rawDur.clamp(320, 400))
                  : (rawDur <= 350 && rawDist < 0.5
                      ? 600
                      : rawDur.clamp(240, 600));
          await _actionFingerFlick(
            task,
            axisHint: axis,
            label: label,
            distanceFraction: dist,
            durationMs: dur,
          );
          break;
        }
      case SmartActionKind.scrollPageUp:
        await _actionScreenSwipe(
          task,
          axisHint: 'up',
          label: '向上滚一屏',
          fraction: step.paramDouble('distanceFraction', 0.85),
        );
        break;
      case SmartActionKind.scrollPageDown:
        await _actionScreenSwipe(
          task,
          axisHint: 'down',
          label: '向下滚一屏',
          fraction: step.paramDouble('distanceFraction', 0.85),
        );
        break;
      case SmartActionKind.scrollPageLeft:
        await _actionScreenSwipe(
          task,
          axisHint: 'left',
          label: '向左滚一屏',
          fraction: step.paramDouble('distanceFraction', 0.85),
        );
        break;
      case SmartActionKind.scrollPageRight:
        await _actionScreenSwipe(
          task,
          axisHint: 'right',
          label: '向右滚一屏',
          fraction: step.paramDouble('distanceFraction', 0.85),
        );
        break;
      case SmartActionKind.findNextMedia:
      case SmartActionKind.findNextMediaRight:
        {
          // 入库未确认前禁止切条（健康连胜也不得跳过等待）
          if (task['mode'] == 'action_recipe' && task['actionProbe'] != true) {
            final needsGate =
                task['actionLongPressNeedsConfirm'] == true ||
                _actionRecipeHasDownloadWork(task);
            if (needsGate) {
              await _actionWaitDownload(task);
            }
            await _actionWaitStrictVideoMinimum(task);
            if (!_actionRecipeMayAdvancePastDownload(task)) {
              debugPrint(
                'action recipe switch BLOCKED findNext '
                'needsConfirm=${task['actionLongPressNeedsConfirm']} '
                'awaiting=${task['actionAwaitingLibrarySave']} '
                'outcome=${task['actionDownloadOutcome']} '
                'libraryOk=${task['actionLibrarySaveOk']}',
              );
              _showSmartOperation('下载未入库确认，本步不切条');
              break;
            }
            debugPrint(
              'action recipe switch ALLOWED findNext '
              'outcome=${task['actionDownloadOutcome']} '
              'libraryOk=${task['actionLibrarySaveOk']}',
            );
          }
          final explicitAxis =
              step.kind == SmartActionKind.findNextMediaRight ? 'left' : 'up';
          final horizontal = explicitAxis == 'left';
          final explicitLabel = horizontal ? '左滑切到下一张' : '上滑切到下一条';
          final rawDist = step.paramDouble(
            'distanceFraction',
            horizontal ? 0.67 : 0.7,
          );
          final rawDur = step.paramInt('durationMs', horizontal ? 380 : 600);
          // 竖向：丢掉图片左滑 0.50；横向：丢掉视频近全屏 ≥0.65/600
          final dist =
              horizontal
                  ? rawDist.clamp(0.55, 0.88)
                  : (rawDist < 0.5 ? 0.7 : rawDist.clamp(0.55, 0.92));
          final dur =
              horizontal
                  ? (rawDur >= 500 ? 380 : rawDur.clamp(320, 400))
                  : (rawDur <= 350 && rawDist < 0.5
                      ? 600
                      : rawDur.clamp(240, 600));
          final attempts = step.paramInt('maxAttempts', horizontal ? 1 : 5);
          await _actionSwitchAdjacentMedia(
            task,
            label: explicitLabel,
            preferHorizontal: horizontal,
            direction: 'next',
            axisHintOverride: explicitAxis,
            maxAttempts: horizontal ? attempts.clamp(1, 3) : attempts,
            distanceFraction: dist,
            durationMs: dur,
          );
          break;
        }
      case SmartActionKind.findPrevMedia:
        await _actionSwitchAdjacentMedia(
          task,
          label: '下滑切上一条',
          preferHorizontal: false,
          direction: 'prev',
          axisHintOverride: 'down',
          maxAttempts: step.paramInt('maxAttempts', 4),
          distanceFraction: step.paramDouble('distanceFraction', 0.34),
          durationMs: step.paramInt('durationMs', 280),
        );
        break;
      case SmartActionKind.findPrevMediaLeft:
        await _actionSwitchAdjacentMedia(
          task,
          label: '右滑切一条',
          preferHorizontal: true,
          direction: 'prev',
          axisHintOverride: 'right',
          maxAttempts: step.paramInt('maxAttempts', 1),
          distanceFraction: step.paramDouble('distanceFraction', 0.50),
          durationMs: step.paramInt('durationMs', 380),
        );
        break;
      case SmartActionKind.focusMedia:
        await _actionFocusCenterMedia(task);
        break;
      case SmartActionKind.tapMedia:
        await _actionTapMedia(task);
        break;
      case SmartActionKind.doubleTapMedia:
        await _actionDoubleTapMedia(task);
        break;
      case SmartActionKind.longPressDownload:
        await _actionLongPressDownload(task);
        break;
      case SmartActionKind.clickPlay:
        await _actionClickPlay(task);
        break;
      case SmartActionKind.closeOverlay:
        await _actionClickCloseOverlay(task);
        break;
      case SmartActionKind.goBack:
        await _actionGoBack(task);
        break;
      case SmartActionKind.reloadPage:
        await _actionReloadPage(task);
        break;
      case SmartActionKind.pullRefresh:
        await _actionPullRefresh(task);
        break;
      case SmartActionKind.scrollToTop:
        await _actionScrollEdge(task, toTop: true);
        break;
      case SmartActionKind.waitBrief:
        await _actionWaitMs(task, step.paramInt('ms', 1000), '等待片刻');
        break;
      case SmartActionKind.waitPageSettle:
        await _actionWaitPageSettle(task);
        break;
      case SmartActionKind.waitDownload:
        // 步骤参数覆盖任务级等待方式（同一套路内多处 wait 时以后执行为准）
        task['actionWaitMode'] = step.waitMode;
        task['actionWaitSeconds'] = step.waitSeconds;
        await _actionWaitDownload(task);
        break;
      case SmartActionKind.nextPage:
        await _actionClickTextButton(task, mode: 'next', label: '下一页');
        break;
      case SmartActionKind.loadMore:
        await _actionClickTextButton(task, mode: 'more', label: '加载更多');
        break;
    }
  }

  (bool imagesOnly, bool videosOnly) _actionMediaFilterFlags(
    Map<String, dynamic> task,
  ) {
    final allowMixed = task['allowMixedMedia'] == true;
    final mediaType = task['mediaType'];
    final imagesOnly = !allowMixed && mediaType == MediaType.image;
    final videosOnly = !allowMixed && mediaType == MediaType.video;
    return (imagesOnly, videosOnly);
  }

  Future<void> _actionScrollEdge(
    Map<String, dynamic> task, {
    required bool toTop,
  }) async {
    final controller = _controller;
    if (controller == null) return;
    final label = toTop ? '滚到顶部' : '滚到底部';
    _showSmartOperation(label, point: Offset(0.5, toTop ? 0.2 : 0.85));
    try {
      await controller.evaluateJavascript(
        source: SmartActionJs.scrollEdge(toTop: toTop),
      );
      if (toTop) {
        try {
          await controller.scrollTo(x: 0, y: 0, animated: true);
        } catch (_) {}
      }
    } catch (e) {
      debugPrint('action scrollEdge failed: $e');
    }
    await Future<void>.delayed(const Duration(milliseconds: 700));
  }

  /// 计算轻扫起止点（归一化 0~1），与原生注入 / 手指动画共用。
  /// 竖向大幅度：近全屏（约 85–92% → 8–12%），Reels 慢拖会回弹，必须划满。
  (Offset from, Offset to) _fingerFlickEndpoints(
    String axisHint, {
    double distanceFraction = 0.32,
    double startX = 0.5,
  }) {
    final f = distanceFraction.clamp(0.12, 0.92);
    final x = startX.clamp(0.28, 0.72);
    switch (axisHint) {
      case 'down':
        if (f >= 0.50) {
          // 近顶起手 → 近底松手（几乎一屏）
          final fromY = (0.12 - (f - 0.78) * 0.05).clamp(0.08, 0.15);
          final toY = (fromY + f).clamp(0.85, 0.94);
          return (Offset(x, fromY), Offset(x, toY));
        }
        return (Offset(x, 0.38), Offset(x, (0.38 + f).clamp(0.0, 0.92)));
      case 'left':
        return (Offset(0.72, 0.5), Offset((0.72 - f).clamp(0.06, 1.0), 0.5));
      case 'right':
        return (Offset(0.28, 0.5), Offset((0.28 + f).clamp(0.0, 0.94), 0.5));
      case 'up':
      default:
        if (f >= 0.50) {
          // 近底起手 → 近顶松手（几乎一屏）；避免 0.62 中段慢拖被 Reels 橡皮筋弹回
          final fromY = (0.88 + (f - 0.78) * 0.05).clamp(0.85, 0.92);
          final toY = (fromY - f).clamp(0.08, 0.12);
          return (Offset(x, fromY), Offset(x, toY));
        }
        return (Offset(x, 0.62), Offset(x, (0.62 - f).clamp(0.08, 1.0)));
    }
  }

  /// Reels / 竖向切条专用：近全屏 + 可变起点 X（避开死区）。
  (Offset from, Offset to) _reelsFlingEndpoints(
    String axisHint, {
    double startX = 0.5,
    double fromY = 0.90,
    double toY = 0.10,
  }) {
    final x = startX.clamp(0.28, 0.72);
    if (axisHint == 'down') {
      return (
        Offset(x, fromY.clamp(0.08, 0.15)),
        Offset(x, toY.clamp(0.85, 0.94)),
      );
    }
    return (
      Offset(x, fromY.clamp(0.85, 0.92)),
      Offset(x, toY.clamp(0.08, 0.12)),
    );
  }

  /// Android：向 WebView 注入真实 MotionEvent（站点能响应）。失败时再退回 JS。
  Future<bool> _nativeWebViewFlick({
    required String axisHint,
    double distanceFraction = 0.32,
    int durationMs = 260,
    Offset? from,
    Offset? to,
  }) async {
    if (!Platform.isAndroid) return false;
    try {
      final ends = _fingerFlickEndpoints(
        axisHint,
        distanceFraction: distanceFraction,
      );
      final f = from ?? ends.$1;
      final t = to ?? ends.$2;
      final ok = await const MethodChannel(
        'webview_touch',
      ).invokeMethod<bool>('flick', <String, dynamic>{
        'axisHint': axisHint,
        'distanceFraction': distanceFraction,
        'durationMs': durationMs,
        'fromX': f.dx,
        'fromY': f.dy,
        'toX': t.dx,
        'toY': t.dy,
      });
      debugPrint('native fingerFlick ok=$ok axis=$axisHint');
      return ok == true;
    } catch (e) {
      debugPrint('native fingerFlick failed: $e');
      return false;
    }
  }

  /// 整屏高度竖向 fling：原生用 Display/Window 屏高算 90%→8%，
  /// 经 locationOnScreen 换算进 Facebook WebView（非 WebView 局部比例）。
  Future<bool> _nativeFullScreenVerticalFling({
    required String direction,
    double xNorm = 0.5,
    int durationMs = 180,
    double fromScreenY = 0.90,
    double toScreenY = 0.08,
  }) async {
    if (!Platform.isAndroid) return false;
    try {
      final raw = await const MethodChannel(
        'webview_touch',
      ).invokeMethod<dynamic>('fullScreenVerticalFling', <String, dynamic>{
        'direction': direction,
        'xNorm': xNorm.clamp(0.22, 0.78),
        'durationMs': durationMs.clamp(140, 240),
        'fromScreenY': fromScreenY.clamp(0.78, 0.96),
        'toScreenY': toScreenY.clamp(0.04, 0.18),
      });
      var ok = false;
      if (raw is bool) {
        ok = raw;
      } else if (raw is Map) {
        ok = raw['ok'] == true;
        debugPrint(
          'native fullScreenVerticalFling ok=$ok '
          'screenH=${raw['screenH']} wvH=${raw['webViewH']} '
          'dy=${raw['dy']} fromY=${raw['fromY']} toY=${raw['toY']} '
          'locY=${raw['locY']} x=$xNorm dur=${durationMs}ms',
        );
      }
      if (raw is! Map) {
        debugPrint(
          'native fullScreenVerticalFling ok=$ok dir=$direction x=$xNorm',
        );
      }
      return ok;
    } catch (e) {
      debugPrint('native fullScreenVerticalFling failed: $e');
      return false;
    }
  }

  /// 原生 MotionEvent 点击（关广告「取消」必须用这个，JS click 无效）。
  Future<bool> _nativeWebViewTap(Offset point, {int holdMs = 70}) async {
    if (!Platform.isAndroid) return false;
    try {
      final ok = await const MethodChannel('webview_touch').invokeMethod<bool>(
        'tap',
        <String, dynamic>{
          'x': point.dx.clamp(0.02, 0.98),
          'y': point.dy.clamp(0.02, 0.98),
          'holdMs': holdMs,
        },
      );
      debugPrint('native tap ok=$ok at $point');
      return ok == true;
    } catch (e) {
      debugPrint('native tap failed: $e');
      return false;
    }
  }

  Future<void> _actionFingerFlick(
    Map<String, dynamic> task, {
    required String axisHint,
    required String label,
    double distanceFraction = 0.32,
    int durationMs = 260,
    bool announceDone = true,
    Offset? fromOverride,
    Offset? toOverride,
    double startX = 0.5,
  }) async {
    final controller = _controller;
    if (controller == null) return;
    final ends = _fingerFlickEndpoints(
      axisHint,
      distanceFraction: distanceFraction,
      startX: startX,
    );
    final from = fromOverride ?? ends.$1;
    final to = toOverride ?? ends.$2;
    final waitMs = (durationMs + 80).clamp(160, 900);

    // 先播手指轨迹 UI，同时注入原生触摸（与真人手势同源）
    final flickFuture = _nativeWebViewFlick(
      axisHint: axisHint,
      distanceFraction: distanceFraction,
      durationMs: durationMs,
      from: from,
      to: to,
    );

    final frames = (waitMs / 36).round().clamp(5, 18);
    for (var i = 0; i <= frames; i++) {
      if (!identical(_smartDownloadTask, task)) return;
      final t = i / frames;
      final eased = 1 - (1 - t) * (1 - t) * (1 - t);
      _showSmartOperation(
        label,
        point: Offset(
          from.dx + (to.dx - from.dx) * eased,
          from.dy + (to.dy - from.dy) * eased,
        ),
      );
      await Future<void>.delayed(Duration(milliseconds: waitMs ~/ frames));
    }

    final nativeOk = await flickFuture;
    if (!identical(_smartDownloadTask, task)) return;

    // 原生失败时再走 JS（文档流站点仍可能靠 scrollBy 推进）
    if (!nativeOk) {
      try {
        final raw = await controller.evaluateJavascript(
          source: SmartActionJs.fingerFlick(
            axisHint: axisHint,
            distanceFraction: distanceFraction,
            durationMs: durationMs,
          ),
        );
        debugPrint('action fingerFlick js fallback: $raw');
        await Future<void>.delayed(Duration(milliseconds: durationMs + 60));
      } catch (e) {
        debugPrint('action fingerFlick js failed: $e');
      }
    } else {
      // 给信息流动画一点落地时间
      await Future<void>.delayed(const Duration(milliseconds: 180));
    }

    if (!identical(_smartDownloadTask, task)) return;
    if (announceDone) {
      _showSmartOperation('已$label', point: to);
      await Future<void>.delayed(const Duration(milliseconds: 120));
    }
  }

  Future<void> _actionScreenSwipe(
    Map<String, dynamic> task, {
    required String axisHint,
    required String label,
    double fraction = 0.85,
  }) async {
    final controller = _controller;
    if (controller == null) return;
    _showSmartOperation(
      label,
      point: const Offset(0.5, 0.45),
      showFinger: false,
    );
    // 整屏翻页优先原生滑动（信息流/Swiper）；再辅以 JS scrollBy
    final nativeOk = await _nativeWebViewFlick(
      axisHint: axisHint,
      distanceFraction: fraction.clamp(0.45, 0.9),
      durationMs: 340,
    );
    Map<String, dynamic>? result;
    try {
      final raw = await controller.evaluateJavascript(
        source: SmartActionJs.screenSwipe(
          axisHint: axisHint,
          fraction: fraction,
        ),
      );
      result = _coerceJsMap(raw);
      debugPrint('action screenPage: native=$nativeOk js=$result');
    } catch (e) {
      debugPrint('action screenPage failed: $e');
    }
    final moved = ((result?['moved'] as num?)?.toDouble() ?? 0);
    final waitMs = ((result?['scheduledMs'] as num?)?.toInt() ?? 480).clamp(
      350,
      800,
    );
    await Future<void>.delayed(Duration(milliseconds: waitMs));
    if (!identical(_smartDownloadTask, task)) return;
    _showSmartOperation(
      (nativeOk || moved > 2) ? '已$label' : '已执行 · $label',
      point: const Offset(0.5, 0.45),
      showFinger: false,
    );
    await Future<void>.delayed(const Duration(milliseconds: 180));
  }

  Map<String, dynamic>? _coerceJsMap(dynamic raw) {
    if (raw is Map) return Map<String, dynamic>.from(raw);
    if (raw is String) {
      final s = raw.trim();
      if (s.isEmpty || s == 'null' || s == 'undefined') return null;
      try {
        final decoded = jsonDecode(s);
        if (decoded is Map) return Map<String, dynamic>.from(decoded);
      } catch (_) {}
    }
    return null;
  }

  Future<Map<String, dynamic>?> _actionCaptureMediaIdentity(
    Map<String, dynamic> task,
  ) async {
    final controller = _controller;
    if (controller == null) return null;
    final filter = _actionMediaFilterFlags(task);
    try {
      final raw = await controller.evaluateJavascript(
        source: SmartActionJs.mediaIdentity(
          imagesOnly: filter.$1,
          videosOnly: filter.$2,
        ),
      );
      return _coerceJsMap(raw);
    } catch (e) {
      debugPrint('mediaIdentity failed: $e');
      return null;
    }
  }

  /// Stable Facebook reel/video identity for session skip (not DOM geometry).
  Future<String> _actionCaptureFacebookVideoIdentity(
    Map<String, dynamic> task,
  ) async {
    final fromTask = (task['expectedFbVideoKey'] ?? '').toString().trim();
    if (_isFacebookCdnIdentity(fromTask) || fromTask.startsWith('reel:')) {
      return fromTask;
    }
    final controller = _controller;
    if (controller == null) return '';
    try {
      final raw = await controller.evaluateJavascript(
        source: r'''
(() => {
  const facebookMediaKey = (u) => {
    const raw = String(u || '').trim();
    if (!raw || raw.startsWith('blob:') || raw.startsWith('data:')) return '';
    try {
      const lower = raw.toLowerCase();
      const reel = lower.match(/(?:facebook\.com|fb\.watch)\/(?:reel|reels|videos?)\/(\d{6,})/);
      if (reel) return 'reel:' + reel[1];
      const parsed = new URL(raw, location.href);
      const encodedEfg = parsed.searchParams.get('efg') || '';
      if (encodedEfg) {
        try {
          const normalized = decodeURIComponent(encodedEfg)
            .replace(/-/g, '+').replace(/_/g, '/');
          const padded = normalized + '='.repeat((4 - normalized.length % 4) % 4);
          const metadata = JSON.parse(atob(padded));
          const videoId = String(metadata.video_id || '').trim();
          if (videoId) return 'fbvideo:' + videoId.toLowerCase();
        } catch (_) {}
      }
    } catch (_) {}
    return '';
  };
  const vw = window.innerWidth || 1, vh = window.innerHeight || 1;
  const cx = vw / 2, cy = vh / 2;
  const videos = Array.from(document.querySelectorAll('video'));
  let best = null, bestScore = -1e18;
  for (const video of videos) {
    const r = video.getBoundingClientRect();
    const area = Math.max(0, Math.min(r.right, vw) - Math.max(r.left, 0)) *
      Math.max(0, Math.min(r.bottom, vh) - Math.max(r.top, 0));
    if (area < 4096) continue;
    const contains = r.left <= cx && r.right >= cx && r.top <= cy && r.bottom >= cy;
    let score = area;
    if (contains) score += 1e12;
    if (!video.paused && !video.ended) score += 1e11;
    if (score > bestScore) { bestScore = score; best = video; }
  }
  if (!best) return { key: facebookMediaKey(location.href) || '' };
  let key = facebookMediaKey(best.currentSrc || best.src || '');
  if (!key || String(key).startsWith('reel:')) {
    try {
      const link = best.closest && best.closest('a[href*="/reel/"], a[href*="/reels/"], a[href*="/videos/"]');
      if (link && link.href) {
        const rk = facebookMediaKey(link.href);
        if (rk) key = rk;
      }
    } catch (_) {}
  }
  if (!key || String(key).startsWith('reel:')) {
    try {
      let node = best;
      for (let d = 0; node && d < 10; d++, node = node.parentElement) {
        const attr = node.getAttribute && (
          node.getAttribute('data-video-id') ||
          node.getAttribute('data-id') ||
          node.getAttribute('data-reel-id')
        );
        if (attr && /^\d{6,}$/.test(String(attr))) {
          key = 'reel:' + attr;
          break;
        }
      }
    } catch (_) {}
  }
  if (!key) key = facebookMediaKey(location.href) || '';
  return { key: key || '' };
})()
''',
      );
      final map = _coerceJsMap(raw);
      return (map?['key'] ?? '').toString().trim();
    } catch (e) {
      debugPrint('FB action identity capture failed: $e');
      return '';
    }
  }

  /// 媒体身份是否已相对 [before] 变化（key / src / 中心点 / 滚动弱判定）。
  /// 横向相邻图常只改 src 或中心 X，key 全等时也要能检出。
  Future<bool> _actionMediaIdentityChanged(
    Map<String, dynamic> task,
    Map<String, dynamic>? before,
  ) async {
    final after = await _actionCaptureMediaIdentity(task);
    if (_smartUsesFacebookPipeline((task['siteProfile'] ?? '').toString())) {
      final beforeSrc = (before?['src'] ?? '').toString().trim();
      final afterSrc = (after?['src'] ?? '').toString().trim();
      final beforePage = (before?['pageUrl'] ?? '').toString().trim();
      final afterPage = (after?['pageUrl'] ?? '').toString().trim();
      final beforePageId =
          RegExp(
            r'/reel/(\d+)',
            caseSensitive: false,
          ).firstMatch(beforePage)?.group(1) ??
          '';
      final afterPageId =
          RegExp(
            r'/reel/(\d+)',
            caseSensitive: false,
          ).firstMatch(afterPage)?.group(1) ??
          '';
      if (beforePageId.isNotEmpty &&
          afterPageId.isNotEmpty &&
          beforePageId != afterPageId) {
        return true;
      }
      // Facebook changes scroll position and video geometry during the same
      // Reel. Those are not proof of switching and previously caused the next
      // long press to download the same Reel again.
      return beforeSrc.isNotEmpty &&
          afterSrc.isNotEmpty &&
          beforeSrc != afterSrc;
    }
    final beforeKey = (before?['key'] ?? '').toString();
    final afterKey = (after?['key'] ?? '').toString();
    if (beforeKey.isNotEmpty && afterKey.isNotEmpty && afterKey != beforeKey) {
      return true;
    }
    final bSrc = (before?['src'] ?? '').toString();
    final aSrc = (after?['src'] ?? '').toString();
    if (aSrc.isNotEmpty && bSrc.isNotEmpty && aSrc != bSrc) {
      return true;
    }
    final bX = (before?['x'] as num?)?.toDouble();
    final aX = (after?['x'] as num?)?.toDouble();
    final bY = (before?['y'] as num?)?.toDouble();
    final aY = (after?['y'] as num?)?.toDouble();
    if (bX != null && aX != null && (aX - bX).abs() > 0.08) {
      return true;
    }
    if (bY != null && aY != null && (aY - bY).abs() > 0.08) {
      return true;
    }
    final bScrollY = (before?['scrollTop'] as num?)?.toInt() ?? 0;
    final aScrollY = (after?['scrollTop'] as num?)?.toInt() ?? 0;
    final bScrollX = (before?['scrollLeft'] as num?)?.toInt() ?? 0;
    final aScrollX = (after?['scrollLeft'] as num?)?.toInt() ?? 0;
    return (aSrc.isNotEmpty && aSrc != bSrc) ||
        (aScrollY - bScrollY).abs() > 40 ||
        (aScrollX - bScrollX).abs() > 40;
  }

  /// 按距离轻扫：竖向（Reels）优先整屏屏高 fling + 身份校验；
  /// 横向从基础幅度开始智能加大，并记住本任务已成功的幅度。
  /// 返回是否确认切到新媒体。失败时保留 [needAdvancePastCurrent]，禁止长按同条。
  Future<bool> _actionDistanceFlickOnly(
    Map<String, dynamic> task, {
    required String axisHint,
    required String label,
    double distanceFraction = 0.50,
    int durationMs = 280,
    int maxAttempts = 5,
  }) async {
    // 下载未完成时禁止切条：先等到成功/失败落定
    if (task['mode'] == 'action_recipe' && task['actionProbe'] != true) {
      final needsGate =
          task['actionLongPressNeedsConfirm'] == true ||
          _actionRecipeHasDownloadWork(task);
      if (needsGate) {
        _showSmartOperation('下载进行中，等待完成后再切条');
        await _actionWaitDownload(task);
      }
      await _actionWaitStrictVideoMinimum(task);
      if (!_actionRecipeMayAdvancePastDownload(task)) {
        debugPrint(
          'action recipe switch BLOCKED distanceFlick '
          'needsConfirm=${task['actionLongPressNeedsConfirm']} '
          'outcome=${task['actionDownloadOutcome']}',
        );
        _showSmartOperation('下载仍在进行，本步暂不切条');
        return false;
      }
      debugPrint(
        'action recipe switch ALLOWED distanceFlick '
        'outcome=${task['actionDownloadOutcome']} '
        'libraryOk=${task['actionLibrarySaveOk']}',
      );
    }
    if (!identical(_smartDownloadTask, task) && task['actionProbe'] != true) {
      return false;
    }

    final vertical = axisHint == 'up' || axisHint == 'down';
    final prevMixed = task['allowMixedMedia'];
    if (vertical) task['allowMixedMedia'] = true;

    var switched = false;

    if (vertical) {
      // 竖向：编辑器近上限（距离≥0.55 且时长>240）时走原生 flick，完整尊重
      // distanceFraction + durationMs（fullScreenVerticalFling 会被 Kotlin 截到 ≤240ms）。
      // 较短默认仍用整屏屏高 fling。
      final before = await _actionCaptureMediaIdentity(task);
      final attempts = maxAttempts.clamp(2, 4);
      const xOffsets = <double>[0.50, 0.42, 0.58, 0.46];
      final preferParamFlick = distanceFraction >= 0.55 && durationMs > 240;
      final instagramVerticalFlick =
          _isInstagramPlatformPage(_currentUrl) && vertical;

      for (var i = 0; i < attempts; i++) {
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        final startX = xOffsets[i % xOffsets.length];
        if (preferParamFlick) {
          final dist =
              instagramVerticalFlick
                  ? (max(distanceFraction, 0.78) + i * 0.045).clamp(0.78, 0.92)
                  : distanceFraction.clamp(0.55, 0.92);
          // 略加重试：后几轮略加长，但不低于配方值、不超过编辑器上限
          final dur =
              instagramVerticalFlick
                  ? (190 - i * 15).clamp(140, 190)
                  : (durationMs + i * 20).clamp(durationMs, 600);
          final status =
              i == 0
                  ? label
                  : (axisHint == 'up'
                      ? '上滑切条（轻扫重试 ${i + 1}/$attempts）'
                      : '$label（轻扫重试 ${i + 1}/$attempts）');
          final ends = _fingerFlickEndpoints(
            axisHint,
            distanceFraction: dist,
            startX: startX,
          );
          _showSmartOperation(status, point: ends.$1);
          debugPrint(
            'action distanceFlick PARAM-FLICK attempt=${i + 1}/$attempts '
            'axis=$axisHint dist=$dist dur=${dur}ms x=$startX',
          );
          await _actionFingerFlick(
            task,
            axisHint: axisHint,
            label: status,
            distanceFraction: dist,
            durationMs: dur,
            announceDone: false,
            fromOverride: ends.$1,
            toOverride: ends.$2,
            startX: startX,
          );
          if (!identical(_smartDownloadTask, task) &&
              task['actionProbe'] != true) {
            break;
          }
          final settleMs = (550 + i * 40).clamp(500, 700);
          await Future<void>.delayed(Duration(milliseconds: settleMs));
          if (!identical(_smartDownloadTask, task) &&
              task['actionProbe'] != true) {
            break;
          }
          if (await _actionMediaIdentityChanged(task, before)) {
            switched = true;
            debugPrint(
              'action distanceFlick switched on param-flick attempt ${i + 1}',
            );
            break;
          }
          // 未切：同轮再轻扫一次（略偏 X）
          // A successful channel call only proves that MotionEvents were
          // injected. If Instagram did not actually change the visible Reel,
          // escalate to a screen-coordinate fling that mirrors a manual
          // bottom-to-top swipe.
          if (instagramVerticalFlick) {
            final fullScreenX = xOffsets[(i + 1) % xOffsets.length];
            final fullScreenDuration = (210 - i * 12).clamp(150, 210);
            debugPrint(
              '[IG_SWIPE_ESCALATE] param gesture produced no media change; '
              'fullscreen attempt=${i + 1}/$attempts '
              'x=$fullScreenX dur=${fullScreenDuration}ms',
            );
            _showSmartOperation(
              axisHint == 'up' ? '轻扫未切换，改用整屏上滑' : '$label（整屏重试）',
              point: Offset(fullScreenX, axisHint == 'up' ? 0.90 : 0.08),
            );
            await _nativeFullScreenVerticalFling(
              direction: axisHint,
              xNorm: fullScreenX,
              durationMs: fullScreenDuration,
              fromScreenY: 0.92,
              toScreenY: 0.06,
            );
            await Future<void>.delayed(
              Duration(milliseconds: (settleMs + 120).clamp(620, 820)),
            );
            if (!identical(_smartDownloadTask, task) &&
                task['actionProbe'] != true) {
              break;
            }
            if (await _actionMediaIdentityChanged(task, before)) {
              switched = true;
              debugPrint(
                '[IG_SWIPE_ESCALATE] switched on fullscreen '
                'attempt ${i + 1}',
              );
              break;
            }
            debugPrint(
              '[IG_SWIPE_ESCALATE] fullscreen gesture still did not '
              'change media on attempt ${i + 1}',
            );
          }
          final retryX = (startX + 0.06).clamp(0.28, 0.72);
          final retryEnds = _fingerFlickEndpoints(
            axisHint,
            distanceFraction: dist,
            startX: retryX,
          );
          debugPrint(
            'action distanceFlick PARAM-FLICK retry-alt-x '
            'x=$retryX dur=${dur}ms after attempt ${i + 1}',
          );
          _showSmartOperation(
            axisHint == 'up' ? '上滑切条（轻扫二次）' : '$label（轻扫二次）',
            point: retryEnds.$1,
          );
          await _actionFingerFlick(
            task,
            axisHint: axisHint,
            label: axisHint == 'up' ? '上滑切条（轻扫二次）' : '$label（轻扫二次）',
            distanceFraction: dist,
            durationMs: dur,
            announceDone: false,
            fromOverride: retryEnds.$1,
            toOverride: retryEnds.$2,
            startX: retryX,
          );
          await Future<void>.delayed(
            Duration(milliseconds: (settleMs - 40).clamp(500, 680)),
          );
          if (!identical(_smartDownloadTask, task) &&
              task['actionProbe'] != true) {
            break;
          }
          if (await _actionMediaIdentityChanged(task, before)) {
            switched = true;
            debugPrint(
              'action distanceFlick switched on param-flick retry of attempt ${i + 1}',
            );
            break;
          }
          debugPrint(
            'action distanceFlick still same after param-flick double of attempt ${i + 1}',
          );
          continue;
        }

        // 较短默认：整屏高度原生 fling（屏坐标 90%→8%）
        final dur = durationMs.clamp(140, 240);
        final attemptDur = (dur - i * 12).clamp(140, dur);
        final status =
            i == 0
                ? label
                : (axisHint == 'up'
                    ? '上滑切条（整屏重试 ${i + 1}/$attempts）'
                    : '$label（整屏重试 ${i + 1}/$attempts）');
        final fingerFrom =
            axisHint == 'up' ? Offset(startX, 0.90) : Offset(startX, 0.08);
        final fingerTo =
            axisHint == 'up' ? Offset(startX, 0.08) : Offset(startX, 0.90);
        _showSmartOperation(status, point: fingerFrom);
        debugPrint(
          'action distanceFlick FULLSCREEN attempt=${i + 1}/$attempts '
          'axis=$axisHint x=$startX dur=${attemptDur}ms',
        );
        // 手指 UI 与原生整屏甩并行
        final flingFuture = _nativeFullScreenVerticalFling(
          direction: axisHint,
          xNorm: startX,
          durationMs: attemptDur,
          fromScreenY: 0.90,
          toScreenY: 0.08,
        );
        final frames = (attemptDur / 36).round().clamp(4, 10);
        for (var f = 0; f <= frames; f++) {
          if (!identical(_smartDownloadTask, task) &&
              task['actionProbe'] != true) {
            break;
          }
          final t = f / frames;
          _showSmartOperation(
            status,
            point: Offset(
              fingerFrom.dx + (fingerTo.dx - fingerFrom.dx) * t,
              fingerFrom.dy + (fingerTo.dy - fingerFrom.dy) * t,
            ),
          );
          await Future<void>.delayed(
            Duration(milliseconds: attemptDur ~/ frames),
          );
        }
        final flingOk = await flingFuture;
        debugPrint(
          'action distanceFlick FULLSCREEN attempt=${i + 1} nativeOk=$flingOk',
        );
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }

        // 落地结算 500–700ms 再验身份
        final settleMs = (550 + i * 40).clamp(500, 700);
        await Future<void>.delayed(Duration(milliseconds: settleMs));
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        if (await _actionMediaIdentityChanged(task, before)) {
          switched = true;
          debugPrint(
            'action distanceFlick switched on fullscreen attempt ${i + 1}',
          );
          break;
        }

        // 未切：同轮再整屏甩一次（略偏 X）
        final retryX = (startX + 0.06).clamp(0.28, 0.72);
        final retryDur = (attemptDur - 20).clamp(140, attemptDur);
        debugPrint(
          'action distanceFlick FULLSCREEN retry-alt-x '
          'x=$retryX dur=${retryDur}ms after attempt ${i + 1}',
        );
        _showSmartOperation(
          axisHint == 'up' ? '上滑切条（整屏二次）' : '$label（整屏二次）',
          point: Offset(retryX, axisHint == 'up' ? 0.90 : 0.08),
        );
        await _nativeFullScreenVerticalFling(
          direction: axisHint,
          xNorm: retryX,
          durationMs: retryDur,
          fromScreenY: 0.91,
          toScreenY: 0.07,
        );
        await Future<void>.delayed(
          Duration(milliseconds: (settleMs - 40).clamp(500, 680)),
        );
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        if (await _actionMediaIdentityChanged(task, before)) {
          switched = true;
          debugPrint(
            'action distanceFlick switched on fullscreen retry of attempt ${i + 1}',
          );
          break;
        }
        debugPrint(
          'action distanceFlick still same after fullscreen double of attempt ${i + 1}',
        );
      }
    } else {
      // 横向相册：基础 0.67（旧 0.50 的约 4/3），身份未变时逐级加大。
      // 某档成功后写入任务，后续图片直接从该档开始，避免反复试小幅度。
      final before = await _actionCaptureMediaIdentity(task);
      final attempts = maxAttempts.clamp(1, 3);
      final remembered =
          (task['actionHorizontalLearnedDistance'] as num?)?.toDouble();
      final baseDist = (remembered ?? distanceFraction).clamp(0.55, 0.88);
      final rememberedDuration =
          (task['actionHorizontalLearnedDurationMs'] as num?)?.toInt();
      final dur = (rememberedDuration ?? durationMs).clamp(320, 440);
      for (var i = 0; i < attempts; i++) {
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        final dist = (baseDist + i * 0.08).clamp(0.55, 0.88);
        final attemptDur = (dur + i * 20).clamp(320, 440);
        final startX = <double>[0.50, 0.54, 0.46][i];
        final status = i == 0 ? label : '$label（加大 ${i + 1}/$attempts）';
        final ends = _fingerFlickEndpoints(
          axisHint,
          distanceFraction: dist,
          startX: startX,
        );
        _showSmartOperation(status, point: ends.$1);
        debugPrint(
          'action distanceFlick horizontal '
          'attempt=${i + 1}/$attempts axis=$axisHint dist=$dist '
          'dur=${attemptDur}ms',
        );
        await _actionFingerFlick(
          task,
          axisHint: axisHint,
          label: status,
          distanceFraction: dist,
          durationMs: attemptDur,
          announceDone: false,
          fromOverride: ends.$1,
          toOverride: ends.$2,
          startX: startX,
        );
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        await Future<void>.delayed(
          Duration(milliseconds: (attemptDur + 120).clamp(320, 520)),
        );
        if (!identical(_smartDownloadTask, task) &&
            task['actionProbe'] != true) {
          break;
        }
        if (await _actionMediaIdentityChanged(task, before)) {
          switched = true;
          task['actionHorizontalLearnedDistance'] = dist;
          task['actionHorizontalLearnedDurationMs'] = attemptDur;
          debugPrint(
            'action distanceFlick horizontal switched on attempt ${i + 1}; '
            'learned dist=$dist dur=${attemptDur}ms',
          );
          break;
        }
        debugPrint(
          'action distanceFlick horizontal identity unchanged '
          'after attempt ${i + 1}',
        );
      }
    }

    if (prevMixed != null) {
      task['allowMixedMedia'] = prevMixed;
    } else {
      task.remove('allowMixedMedia');
    }
    if (!identical(_smartDownloadTask, task) && task['actionProbe'] != true) {
      return switched;
    }
    await Future<void>.delayed(const Duration(milliseconds: 120));
    if (!identical(_smartDownloadTask, task) && task['actionProbe'] != true) {
      return switched;
    }

    if (switched) {
      task['actionAdvanceFailed'] = false;
      task['needAdvancePastCurrent'] = false;
      task['instagramTrackCaptureFailures'] = 0;
      _showSmartOperation('已$label', point: const Offset(0.5, 0.5));
    } else if (vertical) {
      // 身份未变：保留待切标志，后续长按不得再下同条
      task['actionAdvanceFailed'] = true;
      task['needAdvancePastCurrent'] = true;
      debugPrint(
        'action distanceFlick FAILED axis=$axisHint — '
        'identity unchanged after fullscreen flings',
      );
      _showSmartOperation(
        axisHint == 'up' ? '切条失败，重试上滑' : '切条失败，请重试',
        point: const Offset(0.5, 0.5),
      );
    } else {
      // 横向：身份未变也标失败，避免误报「已切」后继续长按同图
      task['actionAdvanceFailed'] = true;
      task['needAdvancePastCurrent'] = true;
      debugPrint(
        'action distanceFlick FAILED axis=$axisHint — '
        'identity unchanged after horizontal flick(s)',
      );
      _showSmartOperation('切图失败，请重试', point: const Offset(0.5, 0.5));
    }
    return switched;
  }

  /// 真正切到相邻媒体：目标是「换了一条」，不是「滑了某段距离」。
  /// 流程：记指纹 → DOM 定位 → 不成则原生轻扫并加重距离重试，直到指纹变化。
  /// 若 task.advanceMode == 'distance'：改走 [_actionDistanceFlickOnly]，不做指纹环。
  Future<void> _actionSwitchAdjacentMedia(
    Map<String, dynamic> task, {
    required String label,
    required bool preferHorizontal,
    required String direction,
    String? axisHintOverride,
    int maxAttempts = 4,
    double distanceFraction = 0.50,
    int durationMs = 280,
  }) async {
    final controller = _controller;
    if (controller == null) return;
    // 下载未完成时禁止切条：先等到成功/失败落定，再由套路继续
    if (task['mode'] == 'action_recipe' && task['actionProbe'] != true) {
      final needsGate =
          task['actionLongPressNeedsConfirm'] == true ||
          _actionRecipeHasDownloadWork(task);
      if (needsGate) {
        _showSmartOperation('下载进行中，等待完成后再切条');
        await _actionWaitDownload(task);
      }
      await _actionWaitStrictVideoMinimum(task);
      if (!_actionRecipeMayAdvancePastDownload(task)) {
        debugPrint(
          'action recipe switch BLOCKED switchAdjacent '
          'needsConfirm=${task['actionLongPressNeedsConfirm']} '
          'outcome=${task['actionDownloadOutcome']}',
        );
        _showSmartOperation('下载仍在进行，本步暂不切条');
        return;
      }
      debugPrint(
        'action recipe switch ALLOWED switchAdjacent '
        'outcome=${task['actionDownloadOutcome']} '
        'libraryOk=${task['actionLibrarySaveOk']}',
      );
    }
    final goNext = direction != 'prev';
    final axisHint =
        (axisHintOverride != null && axisHintOverride.isNotEmpty)
            ? axisHintOverride
            : (preferHorizontal
                ? (goNext ? 'left' : 'right')
                : (goNext ? 'up' : 'down'));
    // 按距离模式：身份未变时加大重试；横向会记住成功幅度。
    if (_advanceModeIsDistance(task)) {
      await _actionDistanceFlickOnly(
        task,
        axisHint: axisHint,
        label: label,
        distanceFraction: distanceFraction,
        durationMs: durationMs,
        maxAttempts: maxAttempts,
      );
      return;
    }
    final horizontal = axisHint == 'left' || axisHint == 'right';
    // 横向相册最多三档加幅；一旦身份变化立即停止，避免多滑一张。
    final attempts =
        horizontal ? maxAttempts.clamp(1, 2) : maxAttempts.clamp(1, 8);
    // 切换前混合识别，便于指纹覆盖图/视频
    // Preserve the requested media filter while switching. Mixing poster
    // images into a video task makes switch verification unreliable.
    final prevMixed = task['allowMixedMedia'];
    final filter = _actionMediaFilterFlags(task);

    // 健康连胜，或刚下载成功正交给 findNext：首刀不探广告
    final skipInitialClear =
        _actionRecipeHealthySkipGuard(task) ||
        (task['mode'] == 'action_recipe' &&
            task['needAdvancePastCurrent'] == true &&
            task['gestureDownloadPending'] != true);
    Future<void> clearIfNeeded({bool force = false}) async {
      if (skipInitialClear && !force) return;
      if (await _probeSmartBlockersPresent()) {
        await _clearSmartInterruptions(task, forceHide: true);
      }
    }

    // 干净站：直接记指纹切条，首刀不探广告
    if (!skipInitialClear) await clearIfNeeded();
    final before = await _actionCaptureMediaIdentity(task);
    _showSmartOperation(label, point: const Offset(0.5, 0.5));

    Future<bool> changed() => _actionMediaIdentityChanged(task, before);

    void markSwitched() {
      // 切条成功：清除「待推走」标志，避免下一轮误判再切一次
      task['needAdvancePastCurrent'] = false;
    }

    // 1) 先尝试 DOM 空间相邻定位
    try {
      final raw = await controller.evaluateJavascript(
        source: SmartActionJs.fingerSwipe(
          dxNorm: horizontal ? (goNext ? -1.0 : 1.0) : 0,
          dyNorm: horizontal ? 0 : (goNext ? -1.0 : 1.0),
          imagesOnly: filter.$1,
          videosOnly: filter.$2,
          preferHorizontal: horizontal,
          directionOverride: direction,
          axisHint: axisHint,
        ),
      );
      final result = _coerceJsMap(raw);
      debugPrint('action switchMedia locate: $result');
      if (result?['foundNext'] == true) {
        await Future<void>.delayed(const Duration(milliseconds: 520));
        if (!identical(_smartDownloadTask, task)) return;
        if (await changed()) {
          markSwitched();
          _showSmartOperation('已$label', point: const Offset(0.5, 0.5));
          if (prevMixed != null) {
            task['allowMixedMedia'] = prevMixed;
          } else {
            task.remove('allowMixedMedia');
          }
          await Future<void>.delayed(const Duration(milliseconds: 160));
          return;
        }
      }
    } catch (e) {
      debugPrint('action switchMedia locate failed: $e');
    }

    // 2) 原生轻扫 + 校验；竖向用近全屏快扫，直到切走
    final rememberedHorizontal =
        (task['actionHorizontalLearnedDistance'] as num?)?.toDouble();
    final baseDist =
        horizontal
            ? (rememberedHorizontal ?? distanceFraction).clamp(0.55, 0.88)
            : distanceFraction.clamp(0.78, 0.88);
    const xOffsets = <double>[0.50, 0.42, 0.58, 0.46, 0.54];
    for (var i = 0; i < attempts; i++) {
      if (!identical(_smartDownloadTask, task)) return;
      // 首刀失败后的重试才允许探广告
      await clearIfNeeded(force: i > 0);
      final startX = xOffsets[i % xOffsets.length];
      final dist =
          horizontal
              ? (baseDist + i * 0.08).clamp(0.55, 0.88)
              : (baseDist + i * 0.02).clamp(0.78, 0.88);
      // 竖向：越重试越快；横向加幅时略延长，增强 Facebook 相册接手概率。
      final dur =
          horizontal
              ? (durationMs + i * 20).clamp(320, 440)
              : (240 - i * 14).clamp(180, 280);
      final status =
          i == 0
              ? '$label · 第${i + 1}/$attempts 次'
              : (axisHint == 'up'
                  ? '上滑切条（快扫重试）'
                  : '$label · 补扫 ${i + 1}/$attempts');
      late final Offset from;
      late final Offset to;
      if (horizontal) {
        final ends = _fingerFlickEndpoints(
          axisHint,
          distanceFraction: dist,
          startX: startX,
        );
        from = ends.$1;
        to = ends.$2;
      } else {
        final ends = _reelsFlingEndpoints(
          axisHint,
          startX: startX,
          fromY: axisHint == 'up' ? (0.90 - i * 0.01).clamp(0.85, 0.92) : 0.10,
          toY:
              axisHint == 'up'
                  ? 0.10
                  : (0.90 - (i % 3) * 0.01).clamp(0.88, 0.92),
        );
        from = ends.$1;
        to = ends.$2;
      }
      _showSmartOperation(status, point: from);
      await _actionFingerFlick(
        task,
        axisHint: axisHint,
        label: status,
        distanceFraction: dist,
        durationMs: dur,
        announceDone: false,
        fromOverride: from,
        toOverride: to,
        startX: startX,
      );
      if (!identical(_smartDownloadTask, task)) return;
      await Future<void>.delayed(
        Duration(
          milliseconds: horizontal ? 420 : (440 + i * 30).clamp(400, 600),
        ),
      );
      if (await changed()) {
        markSwitched();
        task['actionAdvanceFailed'] = false;
        if (horizontal) {
          task['actionHorizontalLearnedDistance'] = dist;
          task['actionHorizontalLearnedDurationMs'] = dur;
        }
        _showSmartOperation('已$label', point: const Offset(0.5, 0.5));
        if (prevMixed != null) {
          task['allowMixedMedia'] = prevMixed;
        } else {
          task.remove('allowMixedMedia');
        }
        await Future<void>.delayed(const Duration(milliseconds: 160));
        return;
      }
      // 竖向：再试一次 DOM 定位（有的站滑一下才渲染下一条节点）
      // 横向相册禁止二次 DOM 手势，避免首扫已切图却因身份滞后再滑一张
      if (horizontal) continue;
      try {
        await controller.evaluateJavascript(
          source: SmartActionJs.fingerSwipe(
            dxNorm: 0,
            dyNorm: goNext ? -1.0 : 1.0,
            imagesOnly: filter.$1,
            videosOnly: filter.$2,
            preferHorizontal: false,
            directionOverride: direction,
            axisHint: axisHint,
          ),
        );
        await Future<void>.delayed(const Duration(milliseconds: 360));
        if (await changed()) {
          markSwitched();
          task['actionAdvanceFailed'] = false;
          _showSmartOperation('已$label', point: const Offset(0.5, 0.5));
          if (prevMixed != null) {
            task['allowMixedMedia'] = prevMixed;
          } else {
            task.remove('allowMixedMedia');
          }
          return;
        }
      } catch (_) {}
    }

    if (prevMixed != null) {
      task['allowMixedMedia'] = prevMixed;
    } else {
      task.remove('allowMixedMedia');
    }
    if (!horizontal) {
      task['actionAdvanceFailed'] = true;
      task['needAdvancePastCurrent'] = true;
      _showSmartOperation(axisHint == 'up' ? '切条失败，重试上滑' : '切条失败，请重试');
    } else {
      task['actionAdvanceFailed'] = true;
      task['needAdvancePastCurrent'] = true;
      _showSmartOperation('切图失败，请重试');
    }
    await Future<void>.delayed(const Duration(milliseconds: 200));
  }

  /// 兼容旧调用名。
  Future<void> _actionFingerSwipe(
    Map<String, dynamic> task, {
    double dx = 0,
    double dy = 0,
    required String label,
    bool? preferHorizontal,
    String? direction,
  }) {
    final goNext =
        direction == 'next'
            ? true
            : direction == 'prev'
            ? false
            : (dy < 0 || dx < 0);
    final horizontal = preferHorizontal == true || dx.abs() > dy.abs();
    return _actionSwitchAdjacentMedia(
      task,
      label: label,
      preferHorizontal: horizontal,
      direction: goNext ? 'next' : 'prev',
    );
  }

  Future<void> _actionPullRefresh(Map<String, dynamic> task) async {
    final controller = _controller;
    if (controller == null) return;
    _showSmartOperation('下拉刷新', point: const Offset(0.5, 0.15));
    try {
      await controller.evaluateJavascript(source: SmartActionJs.pullRefresh());
    } catch (e) {
      debugPrint('action pullRefresh failed: $e');
    }
    const frames = 10;
    for (var i = 1; i <= frames; i++) {
      if (!identical(_smartDownloadTask, task)) return;
      final t = i / frames;
      _showSmartOperation('下拉刷新', point: Offset(0.5, 0.15 + 0.28 * t));
      await Future<void>.delayed(const Duration(milliseconds: 42));
    }
    await Future<void>.delayed(const Duration(milliseconds: 600));
  }

