  Future<void> _actionLongPressDownload(Map<String, dynamic> task) async {
    final probe = task['actionProbe'] == true;
    final healthy = !probe && _actionRecipeHealthySkipGuard(task);
    final disablePreSkip = !probe && _actionRecipeDisablesPreSkip(task);
    final fixedForce = !probe && _actionRecipeIsFixedWaitForce(task);
    final currentPath = Uri.tryParse(_currentUrl)?.path.toLowerCase() ?? '';
    if (!probe &&
        task['mediaType'] == MediaType.image &&
        _isInstagramPlatformPage(_currentUrl) &&
        currentPath.contains('/reel')) {
      debugPrint(
        'action Instagram Reels: correcting poster-detected task image->video',
      );
      task['mediaType'] = MediaType.video;
    }
    // Facebook 视频一旦在本任务中成功入库或确认重复，就不得再次长按下载。
    // 页面回弹/循环回到旧视频时，先切走再处理新的当前视频。
    if (!probe && _actionRecipeRequiresSuccessfulVideoSave(task)) {
      // Prefer stable fbvideo:/reel: over fragile DOM blob geometry keys.
      final fbIdNow = await _actionCaptureFacebookVideoIdentity(task);
      if (fbIdNow.isNotEmpty &&
          (_sessionHasHandledFacebookIdentity(task, fbIdNow) ||
              await _libraryConfirmsFacebookIdentity(fbIdNow))) {
        _rememberHandledFacebookIdentity(task, fbIdNow);
        task['needAdvancePastCurrent'] = true;
        final advanced = await _advancePastHandledMedia(task);
        if (!advanced) {
          task['actionAdvanceFailed'] = true;
          _showSmartOperation('当前视频已下载，正在重试切到下一条');
          return;
        }
        task['actionAdvanceFailed'] = false;
        await Future<void>.delayed(const Duration(milliseconds: 420));
      } else {
        final currentIdentity = await _actionCaptureMediaIdentity(task);
        if (_isHandledMediaIdentity(task, currentIdentity)) {
          task['needAdvancePastCurrent'] = true;
          final advanced = await _advancePastHandledMedia(task);
          if (!advanced) {
            task['actionAdvanceFailed'] = true;
            _showSmartOperation('当前视频已下载，正在重试切到下一条');
            return;
          }
          task['actionAdvanceFailed'] = false;
          await Future<void>.delayed(const Duration(milliseconds: 420));
        }
      }
    }
    // 切条失败后：身份仍是已处理条时禁止再长按同条（否则 Reels 会反复下同一视频）
    if (!probe &&
        task['mode'] == 'action_recipe' &&
        (task['actionAdvanceFailed'] == true ||
            task['needAdvancePastCurrent'] == true)) {
      final stuck = await _actionCaptureMediaIdentity(task);
      if (await _shouldSkipAsHandledMedia(task, stuck)) {
        _showSmartOperation('切条失败，重试上滑', point: const Offset(0.5, 0.5));
        final advanced = await _advancePastHandledMedia(task);
        final stillStuck = await _shouldSkipAsHandledMedia(
          task,
          await _actionCaptureMediaIdentity(task),
        );
        if (!advanced || stillStuck) {
          debugPrint(
            'action longPressDownload BLOCKED: advance failed, '
            'same media still on screen',
          );
          _showSmartOperation('切条失败，重试上滑', point: const Offset(0.5, 0.5));
          task['actionAdvanceFailed'] = true;
          task['needAdvancePastCurrent'] = true;
          task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
          return;
        }
        task['actionAdvanceFailed'] = false;
      } else {
        task['actionAdvanceFailed'] = false;
        task['needAdvancePastCurrent'] = false;
      }
    }
    // 健康路径：跳过清障/已处理探测，直接长按当前新媒体
    // 动作编排（含固定等待）：长按前绝不「已处理」预跳过，强制触发下载
    if (!healthy) {
      if (await _probeSmartBlockersPresent()) {
        await _clearSmartInterruptions(task, forceHide: true);
      }
      if (!probe && task['mode'] == 'action_recipe' && !disablePreSkip) {
        final identity = await _actionCaptureMediaIdentity(task);
        if (await _shouldSkipAsHandledMedia(task, identity)) {
          await _advancePastHandledMedia(task);
        }
      }
    }
    if (disablePreSkip || fixedForce) {
      debugPrint(
        'action longPressDownload: force download '
        'fixedWait=$fixedForce disablePreSkip=$disablePreSkip',
      );
    }
    // 验证/编排时混合识别，优先屏幕中心大媒体，避免右下角小图
    final prevMixed = task['allowMixedMedia'];
    // Only template probing may inspect mixed media. A real video recipe must
    // not select a poster IMG and count its WebP/JPG save as video success.
    if (probe) {
      task['allowMixedMedia'] = true;
    }
    var hit = await _actionFindCenterMedia(task);
    // 若中心仍是已处理媒体（全屏信息流只有一条 DOM），再切一次
    // 动作编排禁用预跳过：不再因会话已处理集合切走，直接长按中心媒体
    if (!healthy &&
        !probe &&
        !disablePreSkip &&
        task['mode'] == 'action_recipe' &&
        hit != null &&
        hit['found'] != false) {
      final identity = await _actionCaptureMediaIdentity(task);
      if (await _shouldSkipAsHandledMedia(task, identity)) {
        await _advancePastHandledMedia(task);
        hit = await _actionFindCenterMedia(task);
      }
    }
    if (prevMixed != null) {
      task['allowMixedMedia'] = prevMixed;
    } else {
      task.remove('allowMixedMedia');
    }
    if (hit == null) {
      _showSmartOperation('未找到可长按媒体', point: const Offset(0.5, 0.5));
      task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
      return;
    }
    // 视觉手指：媒体中心；找不到媒体时屏幕正中
    final point = Offset(
      ((hit['x'] as num?)?.toDouble() ?? 0.5).clamp(0.12, 0.88),
      ((hit['y'] as num?)?.toDouble() ?? 0.5).clamp(0.12, 0.88),
    );
    var cx = (hit['clientX'] as num?)?.toDouble() ?? 0;
    var cy = (hit['clientY'] as num?)?.toDouble() ?? 0;
    // client 坐标无效时，用屏幕中心像素（由 JS 内再算）
    final useJsCenter = !(cx.isFinite && cy.isFinite && cx > 0 && cy > 0);
    if (!probe &&
        task['mediaType'] == MediaType.video &&
        _isInstagramPlatformPage(_currentUrl)) {
      // A freshly-swiped Reel can be mounted but paused at t=0. In that state
      // the hook runs without Instagram requesting the current DASH track.
      try {
        // Retry state belongs to one visible video. Instagram can replace the
        // Reel while this loop is waiting; never carry an old video's failure
        // count (and its controlled seeks) into the newly visible video.
        final retryIdentity = await _actionCaptureMediaIdentity(task);
        final retrySrc = (retryIdentity?['src'] ?? '').toString().trim();
        final previousRetrySrc =
            (task['instagramTrackRetryMediaSrc'] ?? '').toString().trim();
        if (retrySrc.isNotEmpty &&
            previousRetrySrc.isNotEmpty &&
            retrySrc != previousRetrySrc) {
          debugPrint(
            '[IG_RETRY_IDENTITY_RESET] visible video changed during retry; '
            'old=${previousRetrySrc.substring(max(0, previousRetrySrc.length - 48))} '
            'new=${retrySrc.substring(max(0, retrySrc.length - 48))}',
          );
          task['instagramTrackCaptureFailures'] = 0;
        }
        if (retrySrc.isNotEmpty) {
          task['instagramTrackRetryMediaSrc'] = retrySrc;
        }
        final captureFailures =
            (task['instagramTrackCaptureFailures'] as int?) ?? 0;
        // Mirror a patient manual retry: each "track not captured" result
        // keeps us on the same Reel and increases the playback wait before the
        // next identical long press. Only the fourth press may seek.
        final minimumWarmupAttempts =
            captureFailures <= 0
                ? 2
                : captureFailures == 1
                ? 4
                : captureFailures == 2
                ? 6
                : 8;
        Map<String, dynamic>? warmup;
        String warmupMediaSrc = '';
        for (var warmupAttempt = 1; warmupAttempt <= 8; warmupAttempt++) {
          if (!identical(_smartDownloadTask, task)) return;
          final warmupRaw = await _controller?.evaluateJavascript(
            source: '''
(() => {
  const w = window.innerWidth || 360;
  const h = window.innerHeight || 640;
  const x = $useJsCenter ? (w * ${point.dx}) : $cx;
  const y = $useJsCenter ? (h * ${point.dy}) : $cy;
  const stack = document.elementsFromPoint(x, y);
  let video = stack.find(el =>
    String(el && el.tagName || '').toLowerCase() === 'video');
  if (!video) {
    video = Array.from(document.querySelectorAll('video')).find(el => {
      const r = el.getBoundingClientRect();
      return r.width > 80 && r.height > 80 &&
        r.bottom > 0 && r.top < innerHeight &&
        x >= r.left && x <= r.right && y >= r.top && y <= r.bottom;
    });
  }
  if (!video) return {ok:false, reason:'video_not_mounted'};
  let seeked = false;
  try {
    video.__appWarmupStartedAtMs =
      Number(video.__appWarmupStartedAtMs || 0) || Date.now();
    video.muted = true;
    // Instagram often reuses a MediaSource whose first video segment was
    // fetched before our sniffer was attached. Audio may therefore be visible
    // to Dart while the current asset's video track is still missing. Nudge
    // this exact visible video early (once per retry round) to force a fresh
    // video-segment request instead of wasting several complete long-press
    // rounds before the old late recovery seek runs.
    const captureSeekRound = $captureFailures;
    const captureNudgeReady =
      ($warmupAttempt >= 2 || captureSeekRound > 0) &&
      Number(video.currentTime || 0) < 0.65;
    if (captureNudgeReady &&
        Number.isFinite(video.duration) &&
        video.duration > 3 &&
        Number(video.__appManualRetryCaptureSeekRound ?? -1) !== captureSeekRound) {
      // Begin gently so the user does not see a large jump on the first try;
      // later failed rounds probe different DASH segments with a bounded set.
      const seekFractions = [0.12, 0.28, 0.45, 0.62, 0.78, 0.35, 0.88, 0.18];
      const seekIndex = Math.min(
        seekFractions.length - 1,
        Math.max(0, captureSeekRound)
      );
      const seekTarget = Math.min(
        Math.max(0.75, video.duration * seekFractions[seekIndex]),
        video.duration - 0.5
      );
      video.__appManualRetryCaptureSeekRound = captureSeekRound;
      video.currentTime = seekTarget;
      seeked = true;
    }
    const promise = video.play();
    if (promise && promise.catch) promise.catch(() => {});
  } catch (_) {}
  return {
    ok:true,
    paused:!!video.paused,
    seeked:seeked,
    time:Number(video.currentTime || 0),
    duration:Number(video.duration || 0),
    src:String(video.currentSrc || video.src || '').slice(-48)
  };
})()
''',
          );
          warmup = _coerceJsMap(warmupRaw);
          final observedWarmupSrc = (warmup?['src'] ?? '').toString().trim();
          if (observedWarmupSrc.isNotEmpty) {
            if (warmupMediaSrc.isEmpty) {
              warmupMediaSrc = observedWarmupSrc;
            } else if (observedWarmupSrc != warmupMediaSrc) {
              debugPrint(
                '[IG_RETRY_TARGET_CHANGED] visible video source changed '
                'inside warmup attempt=$warmupAttempt; cancel this press and '
                'restart retry state on the new video',
              );
              task['instagramTrackCaptureFailures'] = 0;
              task.remove('instagramTrackRetryMediaSrc');
              _showSmartOperation('检测到视频已切换，重新从当前视频开始');
              return;
            }
          }
          final playedFor = (warmup?['time'] as num?)?.toDouble() ?? 0.0;
          debugPrint(
            'action Instagram video warmup: attempt=$warmupAttempt/8 '
            '$warmup',
          );
          // Do not use a fixed delay as proof of readiness. Some Reels remain
          // at t=0 for several seconds while their MSE/DASH source is mounted.
          if (warmup?['seeked'] == true) {
            await Future<void>.delayed(const Duration(milliseconds: 900));
            continue;
          }
          if (warmupAttempt >= minimumWarmupAttempts &&
              warmup?['ok'] == true &&
              playedFor >= 0.35) {
            break;
          }
          await Future<void>.delayed(const Duration(milliseconds: 600));
        }
      } catch (e) {
        debugPrint('action Instagram video warmup failed: $e');
      }
    }
    task['gestureDownloadPending'] = true;
    task['gestureDownloadStartedAt'] = DateTime.now();
    // 入库闸门：仅媒体库确认成功（或库内重复/明确失败）后才允许切下一条
    if (!probe && task['mode'] == 'action_recipe') {
      _actionRecipeBeginAwaitLibrarySave(task);
    }
    final completer = Completer<bool>();
    task['actionDownloadCompleter'] = completer;
    final found = hit['found'] != false && hit['type'] != 'none';
    for (var i = 0; i < 5; i++) {
      if (!identical(_smartDownloadTask, task)) {
        task['gestureDownloadPending'] = false;
        if (!probe) {
          _actionRecipeFinishAwaitLibrarySave(
            task,
            libraryOk: false,
            outcome: 'task_replaced',
          );
        }
        task.remove('actionDownloadCompleter');
        if (!completer.isCompleted) completer.complete(false);
        return;
      }
      _showSmartOperation(found ? '长按媒体中心…' : '长按屏幕中心…', point: point);
      await Future<void>.delayed(const Duration(milliseconds: 90));
    }
    _showSmartOperation(found ? '长按媒体中心，触发下载' : '长按屏幕中心，触发下载', point: point);
    try {
      final raw = await _controller?.evaluateJavascript(
        source: '''
(() => {
  if (typeof window.__appTriggerSmartLongPress !== 'function') {
    return {ok:false, reason:'hook_missing'};
  }
  const w = window.innerWidth || 360;
  const h = window.innerHeight || 640;
  const useCenter = $useJsCenter;
  const cx = useCenter ? (w * ${point.dx}) : $cx;
  const cy = useCenter ? (h * ${point.dy}) : $cy;
  return window.__appTriggerSmartLongPress(cx, cy);
})()
''',
      );
      final parsed =
          _coerceJsMap(raw) ??
          (raw is Map ? Map<String, dynamic>.from(raw) : null);
      debugPrint('action longPressDownload: $parsed');
      if (parsed != null && parsed['ok'] == false) {
        _showSmartOperation(
          '长按下载未触发：${parsed['reason'] ?? 'unknown'}',
          point: point,
        );
        task['gestureDownloadPending'] = false;
        if (!probe && task['mode'] == 'action_recipe') {
          _actionRecipeFinishAwaitLibrarySave(
            task,
            libraryOk: false,
            outcome: 'longpress_not_triggered',
          );
        }
        task.remove('actionDownloadCompleter');
        task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
        if (!completer.isCompleted) completer.complete(false);
        return;
      }
    } catch (e) {
      debugPrint('action longPressDownload failed: $e');
      task['gestureDownloadPending'] = false;
      if (!probe && task['mode'] == 'action_recipe') {
        _actionRecipeFinishAwaitLibrarySave(
          task,
          libraryOk: false,
          outcome: 'longpress_exception',
        );
      }
      task.remove('actionDownloadCompleter');
      task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
      if (!completer.isCompleted) completer.complete(false);
      return;
    }
    if (probe) {
      // 验证模式：只确认能触发，不卡死等完整下载
      await Future<void>.delayed(const Duration(milliseconds: 1600));
      task['gestureDownloadPending'] = false;
      task.remove('actionDownloadCompleter');
      if (!completer.isCompleted) completer.complete(true);
      _showSmartOperation('验证：长按已触发', point: point);
      return;
    }
    // 硬等待交给 waitDownload：长按步骤只负责触发并保持入库闸门。
    // 若在此 await Completer，waitDownload 会变成「文案闪一下就放行」，findNext 抢跑。
    await Future<void>.delayed(const Duration(milliseconds: 480));
    if (task['actionAwaitingLibrarySave'] != true &&
        task['actionLongPressNeedsConfirm'] == true) {
      task['actionAwaitingLibrarySave'] = true;
    }
    debugPrint(
      'action longPressDownload: trigger done, defer hard wait '
      'needsConfirm=${task['actionLongPressNeedsConfirm']} '
      'awaiting=${task['actionAwaitingLibrarySave']} '
      'pending=${task['gestureDownloadPending']} '
      'activeDownload=${_hasActiveSmartBatchDownload()}',
    );
  }

  Future<void> _actionWaitDownload(Map<String, dynamic> task) async {
    if (task['actionProbe'] == true) {
      _showSmartOperation('验证：跳过久等下载');
      await Future<void>.delayed(const Duration(milliseconds: 400));
      return;
    }
    final configuredWaitMode =
        (task['actionWaitMode'] ?? 'library').toString().toLowerCase() ==
                'fixed'
            ? 'fixed'
            : 'library';
    final strictVideoSave = _actionRecipeRequiresSuccessfulVideoSave(task);
    // 严格视频校验只负责阻止无效文件入库，不能覆盖用户编排的等待方式。
    // 固定等待是最长时限；时限内真实入库成功仍会立即结束等待。
    // Facebook video must never advance merely because a fixed timer elapsed.
    // A completed media-library write (or a verified duplicate/explicit hard
    // timeout) is the only release signal.
    final waitMode = strictVideoSave ? 'library' : configuredWaitMode;
    final waitSeconds = ((task['actionWaitSeconds'] as num?)?.toInt() ?? 30)
        .clamp(1, 600);
    final epoch = task['actionDownloadEpoch'];
    final needsConfirmAtEnter = task['actionLongPressNeedsConfirm'] == true;
    final hasWorkAtEnter = _actionRecipeHasDownloadWork(task);
    debugPrint(
      'action waitDownload: ENTER epoch=$epoch mode=$waitMode '
      'configuredMode=$configuredWaitMode strictVideo=$strictVideoSave '
      'seconds=$waitSeconds needsConfirm=$needsConfirmAtEnter '
      'hasWork=$hasWorkAtEnter outcome=${task['actionDownloadOutcome']} '
      'libraryOk=${task['actionLibrarySaveOk']} '
      'fixedReleased=${task['actionFixedWaitReleased']} '
      'forceSkipReleased=${task['actionForceSkipReleased']}',
    );

    // 看门狗已放行：不再因残留真实下载重新卡住
    if (task['actionForceSkipReleased'] == true &&
        task['actionLongPressNeedsConfirm'] != true) {
      debugPrint(
        'action waitDownload: EXIT reason=force_skip_already_released',
      );
      return;
    }

    // —— 模式 2：固定等待 —— 时长为上限；真实入库成功 / 库内重复均可提前切条；禁用软 detect-and-skip
    if (waitMode == 'fixed') {
      if (task['actionFixedWaitReleased'] == true) {
        debugPrint('action waitDownload: EXIT reason=fixed_already_released');
        return;
      }
      // 本轮从未长按/无在途工作：无需假装等待
      if (!needsConfirmAtEnter && !hasWorkAtEnter) {
        // 进入时若已真实入库或库内重复，直接放行（不必空等满时长）
        if (_actionRecipeDidLibrarySave(task) ||
            _actionRecipeIsLibraryDuplicateReleased(task)) {
          task['actionFixedWaitReleased'] = true;
          _showSmartOperation(
            _actionRecipeIsLibraryDuplicateReleased(task)
                ? '库内已有，跳过'
                : '已入库，提前继续',
          );
          debugPrint(
            'action waitDownload: EXIT reason=library_ok_at_enter(fixed)',
          );
          return;
        }
        debugPrint('action waitDownload: EXIT reason=no_pending_work(fixed)');
        return;
      }
      // 固定等待 = 最大等待：library_saved / 哈希确认 already_in_library 可提前结束；
      // 软「已处理」绝不提前放行；到点不取消进度条在途任务。
      final started = DateTime.now();
      final deadline = started.add(Duration(seconds: waitSeconds));
      final successAtStart = (task['success'] as int?) ?? 0;
      var invalidSeenAt = DateTime.fromMillisecondsSinceEpoch(0);
      while (identical(_smartDownloadTask, task) &&
          DateTime.now().isBefore(deadline)) {
        // 固定模式：挂起在 wait 开始前 / 无效媒体路径时仍可看门狗强制跳过
        final peekOutcome = (task['actionDownloadOutcome'] ?? '').toString();
        final peekFailure = (task['lastGestureFailureType'] ?? '').toString();
        if (_actionRecipeIsInvalidMediaOutcome(peekOutcome) ||
            _actionRecipeIsInvalidMediaOutcome(peekFailure)) {
          if (invalidSeenAt.millisecondsSinceEpoch <= 0) {
            invalidSeenAt = DateTime.now();
          }
          if (DateTime.now().difference(invalidSeenAt) >=
              _kActionRecipeInvalidMediaFastSkip) {
            await _actionRecipeForceSkipCurrent(
              task,
              outcome: 'invalid_smart_media_content',
              statusText: '无效媒体，已跳过',
              incrementFailed: peekOutcome.isEmpty,
            );
            debugPrint(
              'action waitDownload: EXIT reason=invalid_media_fast_skip(fixed)',
            );
            return;
          }
        } else {
          invalidSeenAt = DateTime.fromMillisecondsSinceEpoch(0);
        }
        // 固定等待开始前若整轮卡住超过看门狗：强制跳过（仍保留 library_saved / 库内重复提前退出）
        if (DateTime.now().difference(started) >=
                _kActionRecipeLibraryWatchdog &&
            !_actionRecipeFixedWaitShouldEarlyAdvance(
              task,
              successAtStart: successAtStart,
            ) &&
            !_actionRecipeHasRealSmartDownloading() &&
            !_longPressVideoDownloadInProgress) {
          await _actionRecipeForceSkipCurrent(
            task,
            outcome: 'force_skip_timeout',
            statusText: '超时无进展，强制跳过',
          );
          debugPrint(
            'action waitDownload: EXIT reason=watchdog_before_progress(fixed)',
          );
          return;
        }
        if (_actionRecipeFixedWaitShouldEarlyAdvance(
          task,
          successAtStart: successAtStart,
        )) {
          final isDup = _actionRecipeIsLibraryDuplicateReleased(task);
          // 补齐闸门终态，避免 findNext 仍被 needsConfirm 挡住
          if (!isDup &&
              !_actionRecipeDidLibrarySave(task) &&
              ((task['success'] as int?) ?? 0) > successAtStart) {
            _actionRecipeFinishAwaitLibrarySave(
              task,
              libraryOk: true,
              outcome: 'library_saved',
            );
          }
          task['actionFixedWaitReleased'] = true;
          task['actionLongPressNeedsConfirm'] = false;
          task['actionAwaitingLibrarySave'] = false;
          if (isDup) {
            task['actionForceSkipReleased'] = true;
          }
          debugPrint(
            'action waitDownload: EXIT reason=library_ok_during_fixed '
            'outcome=${task['actionDownloadOutcome']} '
            'success=${task['success']}/$successAtStart',
          );
          _showSmartOperation(isDup ? '库内已有，跳过' : '已入库，提前继续');
          return;
        }
        final leftMs = deadline.difference(DateTime.now()).inMilliseconds;
        if (leftMs <= 0) break;
        final leftSec = (leftMs / 1000).ceil().clamp(0, waitSeconds);
        final activeCount =
            _downloadTasks
                .where(
                  (row) =>
                      row['isSmartBatchMedia'] == true &&
                      row['status'] == 'downloading' &&
                      !_isActionRecipePlaceholderRow(row),
                )
                .length;
        _showSmartOperation(
          activeCount > 0
              ? '固定等待切条 · 还剩 ${leftSec}s · 下载中 $activeCount'
              : '固定等待切条 · 还剩 ${leftSec}s',
        );
        // 优先挂起在入库 Completer 上，落盘成功立刻醒来；否则最多睡 1s 再轮询
        final completer = task['actionDownloadCompleter'];
        final sliceMs = leftMs < 1000 ? leftMs : 1000;
        if (completer is Completer<bool> && !completer.isCompleted) {
          try {
            await completer.future.timeout(Duration(milliseconds: sliceMs));
          } on TimeoutException {
            // 继续 while：检查 library_saved / 倒计时
          }
        } else {
          await Future<void>.delayed(Duration(milliseconds: sliceMs));
        }
      }
      if (!identical(_smartDownloadTask, task)) {
        debugPrint('action waitDownload: EXIT reason=task_replaced(fixed)');
        return;
      }
      // 循环结束前再看一眼：刚好在 deadline 附近入库 / 库内重复
      if (_actionRecipeFixedWaitShouldEarlyAdvance(
        task,
        successAtStart: successAtStart,
      )) {
        final isDup = _actionRecipeIsLibraryDuplicateReleased(task);
        if (!isDup &&
            !_actionRecipeDidLibrarySave(task) &&
            ((task['success'] as int?) ?? 0) > successAtStart) {
          _actionRecipeFinishAwaitLibrarySave(
            task,
            libraryOk: true,
            outcome: 'library_saved',
          );
        }
        task['actionFixedWaitReleased'] = true;
        task['actionLongPressNeedsConfirm'] = false;
        task['actionAwaitingLibrarySave'] = false;
        if (isDup) {
          task['actionForceSkipReleased'] = true;
        }
        _showSmartOperation(isDup ? '库内已有，跳过' : '已入库，提前继续');
        debugPrint(
          'action waitDownload: EXIT reason=library_ok_at_deadline(fixed)',
        );
        return;
      }
      // 到点放行切条：不取消进度条中的在途下载，任务继续后台完成
      _actionRecipeReleaseFixedWait(task);
      final lingering =
          _downloadTasks
              .where(
                (row) =>
                    row['isSmartBatchMedia'] == true &&
                    row['status'] == 'downloading' &&
                    !_isActionRecipePlaceholderRow(row),
              )
              .length;
      _showSmartOperation(
        lingering > 0 ? '固定等待结束，继续切条（$lingering 个下载仍在进度条）' : '固定等待结束，继续切条',
      );
      debugPrint(
        'action waitDownload: EXIT reason=fixed_elapsed lingering=$lingering',
      );
      return;
    }

    // —— 模式 1：媒体库确认（默认，保持原硬闸门 + 看门狗）——
    // 本轮从未长按/无在途工作：无需假装等待
    if (!needsConfirmAtEnter && !hasWorkAtEnter) {
      debugPrint('action waitDownload: EXIT reason=no_pending_work');
      return;
    }
    // 进入时已是无效媒体终态：立刻放行
    final enterOutcome = (task['actionDownloadOutcome'] ?? '').toString();
    if (_actionRecipeIsInvalidMediaOutcome(enterOutcome) &&
        task['actionLongPressNeedsConfirm'] != true) {
      _showSmartOperation('无效媒体，已跳过');
      task['actionForceSkipReleased'] = true;
      debugPrint('action waitDownload: EXIT reason=invalid_already_finished');
      return;
    }
    // 进入时已是哈希确认库内重复：立刻放行，绝不干等
    if (_actionRecipeIsLibraryDuplicateReleased(task)) {
      task['actionForceSkipReleased'] = true;
      _showSmartOperation('库内已有，跳过');
      debugPrint(
        'action waitDownload: EXIT reason=already_in_library_at_enter',
      );
      return;
    }
    _showSmartOperation('等待下载完成（媒体库确认）');

    // 主路径：若长按创建的 Completer 仍在，必须先 await（健康连胜也绝不跳过）
    // 但加上看门狗上限，避免无效媒体被 suppress 后干等 6 分钟
    final existingCompleter = task['actionDownloadCompleter'];
    if (existingCompleter is Completer<bool> &&
        !existingCompleter.isCompleted) {
      try {
        // Polling below owns the hard deadline; do not hide inside one long
        // await while the UI appears frozen.
        await existingCompleter.future.timeout(const Duration(seconds: 8));
      } on TimeoutException {
        debugPrint('action waitDownload: completer timeout, continue poll');
      }
    }

    final started = DateTime.now();
    final taskDeadline = task['deadlineAt'] as DateTime?;
    final strictWaitLimit =
        taskDeadline != null && taskDeadline.isAfter(started)
            ? taskDeadline.difference(started)
            : const Duration(hours: 5);
    final waitLimit =
        strictVideoSave ? strictWaitLimit : _kActionRecipeLibraryWatchdog;
    var lastClearAt = DateTime.fromMillisecondsSinceEpoch(0);
    var stagnantSince = DateTime.now();
    var lastHadWork = true;
    var quietRounds = 0;
    var invalidSeenAt = DateTime.fromMillisecondsSinceEpoch(0);
    var lastProgressFingerprint = '';
    var progressSince = DateTime.now();
    final healthy = _actionRecipeHealthySkipGuard(task);
    while (identical(_smartDownloadTask, task) &&
        DateTime.now().difference(started) < waitLimit) {
      if (task['actionForceSkipReleased'] == true &&
          task['actionLongPressNeedsConfirm'] != true) {
        debugPrint('action waitDownload: EXIT reason=force_skip_released');
        return;
      }
      // 哈希确认库内重复：立刻退出，勿被残留下载标志拖住
      if (_actionRecipeIsLibraryDuplicateReleased(task)) {
        task['actionForceSkipReleased'] = true;
        _showSmartOperation('库内已有，跳过');
        debugPrint(
          'action waitDownload: EXIT reason=already_in_library_terminal',
        );
        return;
      }
      final needsConfirm = task['actionLongPressNeedsConfirm'] == true;
      final awaitingLibrary = task['actionAwaitingLibrarySave'] == true;
      final pending = task['gestureDownloadPending'] == true;
      final completer = task['actionDownloadCompleter'];
      final completerPending =
          completer is Completer<bool> && !completer.isCompleted;
      final downloading = _actionRecipeHasRealSmartDownloading();
      final longPressBusy = _longPressVideoDownloadInProgress;
      final urlInFlight = _downloadingUrls.isNotEmpty;
      final activelyDownloading = downloading || longPressBusy || urlInFlight;
      if (strictVideoSave &&
          DateTime.now().difference(started) >=
              _kFacebookSmartRoundHardTimeout) {
        debugPrint(
          'action waitDownload: Facebook hard timeout; cancel current media '
          'and release the round',
        );
        _cancelStalledSmartMediaDownloads('facebook_smart_round_timeout');
        _longPressVideoDownloadInProgress = false;
        await _actionRecipeForceSkipCurrent(
          task,
          outcome: 'step_watchdog_timeout',
          statusText: 'Facebook 下载超时，已跳过当前视频',
        );
        return;
      }
      final outcomeNow = (task['actionDownloadOutcome'] ?? '').toString();
      final failurePeek = (task['lastGestureFailureType'] ?? '').toString();
      // 无效媒体：数秒内强制跳过，绝不干等满看门狗
      if (_actionRecipeIsInvalidMediaOutcome(outcomeNow) ||
          _actionRecipeIsInvalidMediaOutcome(failurePeek)) {
        if (invalidSeenAt.millisecondsSinceEpoch <= 0) {
          invalidSeenAt = DateTime.now();
          _showSmartOperation('无效媒体，准备跳过…');
        }
        if (!needsConfirm &&
            !awaitingLibrary &&
            _actionRecipeIsInvalidMediaOutcome(outcomeNow)) {
          task['actionForceSkipReleased'] = true;
          _showSmartOperation('无效媒体，已跳过');
          debugPrint('action waitDownload: EXIT reason=invalid_media_terminal');
          return;
        }
        if (DateTime.now().difference(invalidSeenAt) >=
            _kActionRecipeInvalidMediaFastSkip) {
          await _actionRecipeForceSkipCurrent(
            task,
            outcome: 'invalid_smart_media_content',
            statusText: '无效媒体，已跳过',
            incrementFailed: !_actionRecipeIsInvalidMediaOutcome(outcomeNow),
          );
          debugPrint(
            'action waitDownload: EXIT reason=invalid_media_fast_skip',
          );
          return;
        }
      } else {
        invalidSeenAt = DateTime.fromMillisecondsSinceEpoch(0);
      }
      // 入库闸门未落定前一律视为有工作（健康连胜也不得跳过）
      final hasWork =
          needsConfirm ||
          awaitingLibrary ||
          pending ||
          completerPending ||
          activelyDownloading;
      // 进度指纹：真实下载数 / URL 在途 / 闸门 / outcome，变则刷新看门狗
      final progressFingerprint =
          '${activelyDownloading ? 1 : 0}|${_downloadingUrls.length}|'
          '${needsConfirm ? 1 : 0}|$awaitingLibrary|$pending|'
          '$completerPending|$outcomeNow|${task['success']}';
      if (progressFingerprint != lastProgressFingerprint) {
        lastProgressFingerprint = progressFingerprint;
        progressSince = DateTime.now();
      }
      if (!hasWork) {
        // 仅在长按会话已 finish（needsConfirm=false）后才允许 quiet 放行
        quietRounds++;
        if (quietRounds >= 3) {
          final outcome = (task['actionDownloadOutcome'] ?? '').toString();
          final libraryOk = task['actionLibrarySaveOk'] == true;
          if (_actionRecipeIsInvalidMediaOutcome(outcome)) {
            task['actionForceSkipReleased'] = true;
            _showSmartOperation('无效媒体，已跳过');
          }
          debugPrint(
            'action waitDownload: EXIT reason=quiet_after_terminal '
            'outcome=$outcome libraryOk=$libraryOk',
          );
          return;
        }
        await Future<void>.delayed(const Duration(milliseconds: 220));
        continue;
      }
      quietRounds = 0;
      // 标志被误清但仍需确认：重新拉起闸门，绝不空转放行
      if (needsConfirm &&
          !awaitingLibrary &&
          !pending &&
          !completerPending &&
          !activelyDownloading) {
        debugPrint(
          'action waitDownload: re-assert gate (needsConfirm without flags)',
        );
        task['actionAwaitingLibrarySave'] = true;
        if (task['gestureDownloadPending'] != true) {
          task['gestureDownloadPending'] = true;
        }
      }
      if (hasWork != lastHadWork) {
        stagnantSince = DateTime.now();
        lastHadWork = hasWork;
      }
      // 真实下载进行中：绝不探广告、绝不切条。健康路径只放宽清障频率，不停等下载
      final stagnantMs =
          DateTime.now().difference(stagnantSince).inMilliseconds;
      final shouldProbeClear =
          !activelyDownloading &&
          !completerPending &&
          !awaitingLibrary &&
          !needsConfirm &&
          ((!healthy && stagnantMs > 1600) || stagnantMs > 4000);
      if (shouldProbeClear &&
          DateTime.now().difference(lastClearAt) >
              const Duration(milliseconds: 2000)) {
        lastClearAt = DateTime.now();
        if (await _probeSmartBlockersPresent()) {
          final cleared = await _clearSmartInterruptions(task, forceHide: true);
          if (cleared) {
            _showSmartOperation('等待下载·已关掉干扰弹窗');
            // 仅在确认没有在途下载时，才允许推走已处理媒体
            if (task['mode'] == 'action_recipe' &&
                _actionRecipeMayAdvancePastDownload(task)) {
              final identity = await _actionCaptureMediaIdentity(task);
              if (await _shouldSkipAsHandledMedia(task, identity)) {
                await _advancePastHandledMedia(task);
              }
            }
          }
        }
      }
      // pending/Completer 一直为 true、却没有任何真实下载任务：多半点到广告或未触发
      // 占位条不再算 activelyDownloading，避免假「在下」导致干等满看门狗
      final stagnantLimit =
          (awaitingLibrary || needsConfirm) && activelyDownloading
              ? _kActionRecipeLibraryWatchdog
              : ((awaitingLibrary || needsConfirm)
                  ? const Duration(seconds: 45)
                  : const Duration(seconds: 12));
      if ((pending || completerPending || awaitingLibrary || needsConfirm) &&
          !activelyDownloading &&
          DateTime.now().difference(stagnantSince) > stagnantLimit) {
        await _actionRecipeForceSkipCurrent(
          task,
          outcome: 'stagnant_timeout',
          statusText: '超时无进展，强制跳过',
        );
        await _clearSmartInterruptions(task, silent: false, label: '跳过前清障');
        debugPrint('action waitDownload: EXIT reason=stagnant_timeout');
        return;
      }
      // 有真实下载但长时间无指纹变化：看门狗强制跳过
      if (!strictVideoSave &&
          (awaitingLibrary || needsConfirm) &&
          DateTime.now().difference(progressSince) >
              _kActionRecipeLibraryWatchdog) {
        await _actionRecipeForceSkipCurrent(
          task,
          outcome: 'force_skip_timeout',
          statusText: '超时无进展，强制跳过',
        );
        debugPrint('action waitDownload: EXIT reason=progress_watchdog');
        return;
      }
      // 终态已至（finish 清掉 needsConfirm）且无在途：可以退出
      if (!needsConfirm &&
          !awaitingLibrary &&
          !pending &&
          !completerPending &&
          !activelyDownloading) {
        if (_actionRecipeIsInvalidMediaOutcome(outcomeNow)) {
          task['actionForceSkipReleased'] = true;
          _showSmartOperation('无效媒体，已跳过');
        }
        debugPrint(
          'action waitDownload: EXIT reason=terminal '
          'outcome=${task['actionDownloadOutcome']} '
          'libraryOk=${task['actionLibrarySaveOk']}',
        );
        return;
      }
      // 有 Completer 未完成时优先挂起在 future 上，避免空转轮询抢跑
      if (completerPending && completer is Completer<bool>) {
        try {
          await completer.future.timeout(const Duration(seconds: 8));
        } on TimeoutException {
          // 继续 while 检查在途任务 / 入库闸门
        }
        continue;
      }
      await Future<void>.delayed(const Duration(milliseconds: 350));
    }
    // 审计缺口修复：loop_timeout 必须关闸 + 清占位，否则 findNext 永久被挡
    if (identical(_smartDownloadTask, task)) {
      await _actionRecipeForceSkipCurrent(
        task,
        outcome: 'loop_timeout',
        statusText: '超时无进展，强制跳过',
      );
    }
    debugPrint('action waitDownload: EXIT reason=loop_timeout');
  }

  /// 零件验证：在当前页单独跑一步/一类动作，便于定位哪一步无效。
  Future<String> _probeSmartActionSteps(
    List<SmartActionStep> steps, {
    String? title,
  }) async {
    if (steps.isEmpty) return '没有可验证的动作';
    if (_controller == null) return '浏览器尚未就绪';
    if (_smartDownloadTask != null &&
        _smartDownloadTask!['mode'] != 'action_probe') {
      return '请先停止当前智能下载任务，再验证零件';
    }
    final probeTask = <String, dynamic>{
      'mode': 'action_probe',
      'actionProbe': true,
      'phase': 'probing',
      'mediaType': MediaType.video,
      'allowMixedMedia': true,
      'success': 0,
      'target': 1,
      'failed': 0,
      'host': _normalizeSmartHost(Uri.tryParse(_currentUrl)?.host ?? ''),
    };
    final previous = _smartDownloadTask;
    _smartDownloadTask = probeTask;
    if (mounted) setState(() {});
    final notes = <String>[];
    try {
      for (var i = 0; i < steps.length; i++) {
        if (!identical(_smartDownloadTask, probeTask)) {
          notes.add('验证被中断');
          break;
        }
        final step = steps[i];
        final prefix =
            title == null
                ? '${i + 1}/${steps.length}'
                : '$title ${i + 1}/${steps.length}';
        probeTask['matchStage'] = '验证 $prefix · ${step.kind.label}';
        _showSmartOperation('验证：${step.kind.label}');
        await _clearSmartInterruptions(probeTask);
        final failedBefore = (probeTask['failed'] as int?) ?? 0;
        try {
          await _executeSmartActionStep(probeTask, step);
        } catch (e) {
          notes.add('${step.kind.label} 异常：$e');
          continue;
        }
        final failedAfter = (probeTask['failed'] as int?) ?? 0;
        final op = _smartOperationLabel.trim();
        if (failedAfter > failedBefore) {
          notes.add('${step.kind.label} → 未成功（$op）');
        } else {
          notes.add('${step.kind.label} → 已执行${op.isEmpty ? '' : '（$op）'}');
        }
        await Future<void>.delayed(const Duration(milliseconds: 420));
      }
    } finally {
      if (identical(_smartDownloadTask, probeTask)) {
        _smartDownloadTask = previous;
        if (previous == null && mounted) {
          setState(() {
            _smartOperationPoint = null;
            _smartOperationLabel = '';
            _smartOperationShowFinger = false;
          });
        } else if (mounted) {
          setState(() {});
        }
      }
    }
    return notes.join('\n');
  }

  Future<void> _actionGoBack(Map<String, dynamic> task) async {
    _showSmartOperation('返回', point: const Offset(0.12, 0.18));
    final controller = _controller;
    if (controller == null) return;
    if (await controller.canGoBack()) {
      await controller.goBack();
      await Future<void>.delayed(const Duration(milliseconds: 800));
      return;
    }
    final origin = (task['originUrl'] ?? '').toString();
    if (origin.startsWith('http') && _isWithinSmartDownloadSite(origin)) {
      _loadUrl(origin);
      await Future<void>.delayed(const Duration(milliseconds: 800));
    }
  }

  Future<void> _startSmartDownload({
    required Map<String, dynamic> website,
    required String keyword,
    required int targetCount,
    required MediaType mediaType,
    bool allowMixedMedia = false,
    bool startFromCurrentPage = false,
    int? minVideoBytes,
    int? maxVideoBytes,
    bool autoVideoSizeRange = false,
    int? demoCount,
    String? preferredStrategyKey,
    bool strategyManualPick = false,
    bool strategyExplicitNone = false,

    /// 「沿用套路」手动指定的站点管线（如 x）。仅用户显式选择时传入；
    /// 默认不会自动把专有套路套到其他站；手动借用时配合 strategyManualPick。
    String? forceSiteProfile,
  }) async {
    final rawUrl = (website['url'] ?? '').toString().trim();
    final normalized =
        rawUrl.startsWith('http://') || rawUrl.startsWith('https://')
            ? rawUrl
            : 'https://$rawUrl';
    final uri = Uri.tryParse(normalized);
    if (uri == null || uri.host.isEmpty) return;
    final normalizedHost = uri.host.toLowerCase().replaceFirst(
      RegExp(r'^www\.'),
      '',
    );
    final currentHost =
        Uri.tryParse(
          _currentUrl,
        )?.host.toLowerCase().replaceFirst(RegExp(r'^www\.'), '') ??
        '';
    final currentUri = Uri.tryParse(_currentUrl);
    final effectiveHost =
        startFromCurrentPage && currentHost.isNotEmpty
            ? currentHost
            : normalizedHost;
    final effectiveUri =
        startFromCurrentPage && currentUri != null && currentUri.host.isNotEmpty
            ? currentUri
            : uri;
    final nativeSiteProfile = _smartSiteProfile(effectiveHost);
    final forcedProfile = (forceSiteProfile ?? '').trim();
    final siteProfile =
        forcedProfile.isNotEmpty ? forcedProfile : nativeSiteProfile;
    // Facebook dedicated floor: reject init stubs even when UI min is empty.
    var resolvedMinVideoBytes = minVideoBytes;
    if (_smartUsesFacebookPipeline(siteProfile)) {
      resolvedMinVideoBytes = max(
        resolvedMinVideoBytes ?? 0,
        _kMinFacebookSavedVideoBytes,
      );
    }
    final keywordFirstOn91 =
        startFromCurrentPage &&
        keyword.trim().isNotEmpty &&
        (effectiveHost == '91cg1.com' || effectiveHost.endsWith('.91cg1.com'));
    final strictXFeedMode =
        startFromCurrentPage &&
        (effectiveHost == 'x.com' ||
            effectiveHost.endsWith('.x.com') ||
            effectiveHost == 'twitter.com' ||
            effectiveHost.endsWith('.twitter.com'));
    final keywordFirstOnX = strictXFeedMode && keyword.trim().isNotEmpty;
    final xInlineFeedMode =
        strictXFeedMode &&
        keyword.trim().isEmpty &&
        !_isXStatusDetailPage(_currentUrl) &&
        !_isXMediaViewerPage(_currentUrl);
    final strictBaiduVideoMode =
        startFromCurrentPage &&
        keyword.trim().isNotEmpty &&
        !allowMixedMedia &&
        mediaType == MediaType.video &&
        _isBaiduHost(effectiveHost);
    await _loadSmartDownload24hRegistry();
    await _loadSmartStrategyProfiles();
    await _loadSmartDemoRecipes();
    final startedAt = DateTime.now();
    final deadlineAt = startedAt.add(const Duration(hours: 5));
    final strict91SearchUrl =
        keywordFirstOn91
            ? '${effectiveUri.origin}/search/${Uri.encodeComponent(keyword.trim())}/'
            : '';
    final strictXSearchUrl =
        keywordFirstOnX
            ? '${effectiveUri.origin}/search?q=${Uri.encodeQueryComponent(keyword.trim())}&src=typed_query&f=media'
            : '';
    final strictBaiduSearchUrl =
        strictBaiduVideoMode ? _baiduVideoSearchUrl(keyword) : '';
    if (startFromCurrentPage &&
        keyword.trim().isEmpty &&
        siteProfile != '91' &&
        !_smartUsesProfileGridPipeline(siteProfile)) {
      await _anchorSmartSeedForType(mediaType);
    }
    _smartDownloadTask = <String, dynamic>{
      'phase':
          keywordFirstOn91
              ? 'collecting_search_results'
              : keywordFirstOnX
              ? 'x_search_loading'
              : strictBaiduVideoMode
              ? 'baidu_video_search_loading'
              : startFromCurrentPage
              ? 'visiting_seed'
              : 'opening_site',
      'siteUrl': normalized,
      'host': effectiveHost,
      'siteProfile': siteProfile,
      // 手动借用专有套路到非本站时标记；默认仍不会自动跨站。
      'strategyManualPick': strategyManualPick,
      'crossSiteBorrow':
          strategyManualPick &&
          forcedProfile.isNotEmpty &&
          forcedProfile != nativeSiteProfile,
      'keyword': keyword,
      'mediaType': mediaType,
      'allowMixedMedia': allowMixedMedia,
      'target': targetCount,
      'minVideoBytes': resolvedMinVideoBytes,
      'maxVideoBytes': maxVideoBytes,
      'autoVideoSizeRange': autoVideoSizeRange,
      'effectiveMinVideoBytes': resolvedMinVideoBytes,
      'effectiveMaxVideoBytes': maxVideoBytes,
      'facebookPipeline': _smartUsesFacebookPipeline(siteProfile),
      'matchStage':
          keywordFirstOn91
              ? '关键词优先 · 站内搜索'
              : siteProfile == '91' && keyword.trim().isEmpty
              ? '无关键词 · 邻近媒体查找'
              : _smartUsesFacebookPipeline(siteProfile)
              ? 'Facebook · Reels长按绑定'
              : keyword.isEmpty
              ? '模式A · 中心起点 · 邻近依次'
              : _smartUsesLegacyPriorityPipeline(siteProfile)
              ? '关键词优先 · 站内搜索'
              : '模式B · 列表顺序',
      'smartRunMode': keyword.trim().isEmpty ? 'nearby' : 'list',
      // 91 关键词模式：严禁 broaden 乱逛；无关键词 X/91 仍可扩大探索。
      // Facebook：禁止 broaden，只靠长按绑定当前 Reels。
      'allowBroadenDiscovery':
          _smartUsesLegacyPriorityPipeline(siteProfile) && !keywordFirstOn91,
      'demoPageType': _smartDemoPageType(
        url: _currentUrl,
        siteProfile: siteProfile,
        keyword: keyword,
        smartRunMode: keyword.trim().isEmpty ? 'nearby' : 'list',
      ),
      'demoRequired': 0,
      'demoCompleted': 0,
      'demoPhase': 'auto',
      'demoSteps': <Map<String, dynamic>>[],
      'success': 0,
      'failed': 0,
      'index': 0,
      'candidates': <Map<String, String>>[],
      'seenMediaUrls': <String>{},
      'attemptedVideoContexts': <String>{},
      'duplicateVideoUrlKeys': <String>{},
      'videoMediaStates': <String, String>{},
      'reservedMediaNameKeys': <String>{},
      'reservedMediaTitleKeys': <String>{},
      'clickedSmartCardKeys': <String>{},
      'exploratoryClickedKeys': <String>{},
      'feedScans': 0,
      'feedNoNew': 0,
      'feedDirection': 1,
      'feedMotionSnapshot': '',
      'feedStalledCount': 0,
      'discoveryRound': 0,
      'searchCycle': 0,
      'strategyStats': <String, dynamic>{},
      'startedAt': startedAt,
      'deadlineAt': deadlineAt,
      'lastAdvanceAt': startedAt,
      'visitedPageUrls': <String>{},
      'discoveryPageQueue': <String>[],
      'queuedDiscoveryUrls': <String>{},
      'visitedDiscoveryUrls': <String>{},
      'syntheticRouteFailures': 0,
      'disableSyntheticRoutes': false,
      'preheatedVideoCandidates': <String, List<String>>{},
      'startedFromCurrentPage': startFromCurrentPage,
      // 91 专有套路（a00c4bd）：关键词走 ordered-card FSM；无关键词走邻近/信息流，
      // 不与通用手势引擎混用，避免回归。
      'gestureMode':
          startFromCurrentPage && !keywordFirstOn91 && siteProfile != '91',
      'gestureAttemptedKeys': <String>{},
      'gestureDownloadPending': false,
      'gestureKeywordSubmitted':
          keywordFirstOn91 || keywordFirstOnX || strictBaiduVideoMode,
      'gestureTypeFilterApplied': strictBaiduVideoMode,
      'gestureDetailMode': false,
      'gestureConsecutiveFailures': 0,
      'gestureActionFailures': <String, int>{},
      'gestureWaitCount': 0,
      'gesturePrepareCount': 0,
      'gestureNoMoveCount': 0,
      'gestureLastScrollY': -1.0,
      'gestureSkipPendingWait': false,
      'gestureEngineFailures': 0,
      'gestureActiveKey': '',
      'gestureLastSafeUrl': _currentUrl,
      'gestureResultUrl': _currentUrl,
      'gestureRecoveryCount': 0,
      'protectVisibleGestureFlow':
          startFromCurrentPage && !keywordFirstOn91 && siteProfile != '91',
      'originUrl': _currentUrl,
      'strict91KeywordMode': keywordFirstOn91,
      'strict91SearchUrl': strict91SearchUrl,
      'strict91SearchPage': 1,
      'strict91QueueReady': false,
      'strict91ActiveCardUrl': '',
      'strict91ReturnAttempts': 0,
      'strictXFeedMode': strictXFeedMode,
      'xInlineFeedMode': xInlineFeedMode,
      'xInlineActivationPending': false,
      'xInlineReadyToLongPress': false,
      'strictXSearchUrl': strictXSearchUrl,
      'xVisitedStatusIds': <String>{},
      'xEnteredDetailFromList': false,
      'xReturnExpectedUrl': '',
      'xReturnAttempts': 0,
      'strictBaiduVideoMode': strictBaiduVideoMode,
      'strictBaiduSearchUrl': strictBaiduSearchUrl,
      'strictBaiduPage': 0,
      // Instagram profile grids expose stable post/reel shortcodes.  Keep
      // navigation state separate from generic feed gestures so a three-column
      // grid is traversed exactly once in DOM order.
      'instagramGridMode':
          _smartUsesProfileGridPipeline(siteProfile) &&
          startFromCurrentPage &&
          keyword.trim().isEmpty,
      'profileGridSite':
          siteProfile == 'facebook_grid' ? 'Facebook' : 'Instagram',
      'instagramGridUrl': _currentUrl,
      'instagramGridScrollY': 0.0,
      'instagramGridProcessedKeys': <String>{},
      'instagramGridRetryCounts': <String, int>{},
      'instagramGridNoNewScans': 0,
      'instagramGridMediaWaits': 0,
      'instagramGridActiveHref': '',
      'instagramGridActiveKey': '',
    };
    final activeTask = _smartDownloadTask!;
    final isLegacySite = _smartUsesLegacyPriorityPipeline(siteProfile);
    activeTask['strategyLayer'] = 'default';
    activeTask['strategyFailStreak'] = 0;
    activeTask['lockedAcquisition'] = '';
    activeTask['lockedFailStreak'] = 0;
    activeTask['sniffEmptyScrolls'] = 0;
    activeTask['lastProgressMarker'] = '';
    activeTask['lastProgressAt'] = startedAt;
    activeTask['allowLegacyAlternateAcquire'] = false;
    // 留空＝允许自动穷尽后再请示范；显式填 0＝禁止中途示范。
    activeTask['allowAutoDemo'] = demoCount == null;
    activeTask['autoDemoRequested'] = false;
    // X/91 默认跳过嗅探；备用阶段或学到直链后再开。
    activeTask['skipSniffAcquire'] = isLegacySite;
    activeTask['preferSniffFirst'] = !isLegacySite;
    if (activeTask['instagramGridMode'] == true) {
      // A profile grid can contain legitimate very short clips. A generic
      // minimum-byte filter rejects those before the MP4/content validation
      // (for example a valid 1.7 s reel of about 150 KB).
      activeTask['effectiveMinVideoBytes'] = null;
      activeTask['gestureMode'] = false;
      activeTask['protectVisibleGestureFlow'] = false;
      activeTask['skipSniffAcquire'] = true;
      activeTask['preferSniffFirst'] = false;
      activeTask['allowBroadenDiscovery'] = false;
      if (siteProfile == 'facebook_grid') {
        activeTask['allowMixedMedia'] = true;
      }
      final gridSite =
          siteProfile == 'facebook_grid' ? 'Facebook' : 'Instagram';
      activeTask['phase'] = 'instagram_grid_scanning';
      activeTask['matchStage'] = '$gridSite 网格 · 逐项打开下载';
    }
    // 全局：优先同站成功经验（含 X/91 原智能内置经验）；无记忆则用内置默认。
    Map<String, dynamic>? selectedRecipe;
    var selectedKey = '';
    var selectedManual = false;
    if (!strategyExplicitNone) {
      final canUsePreferred =
          preferredStrategyKey != null &&
          preferredStrategyKey.isNotEmpty &&
          _smartDemoRecipes.containsKey(preferredStrategyKey);
      if (canUsePreferred) {
        selectedKey = preferredStrategyKey!;
        selectedRecipe = _smartDemoRecipes[preferredStrategyKey];
        selectedManual = strategyManualPick;
      } else {
        final autoKey = _defaultSameHostStrategyKey(
          host: effectiveHost,
          pageType: (activeTask['demoPageType'] ?? 'feed').toString(),
        );
        if (autoKey != null) {
          selectedKey = autoKey;
          selectedRecipe = _smartDemoRecipes[autoKey];
          selectedManual = false;
        }
      }
    }
    if (selectedRecipe != null && selectedKey.isNotEmpty) {
      _bindSmartStrategyToTask(
        activeTask,
        selectedRecipe,
        strategyKey: selectedKey,
        manualPick: selectedManual,
      );
      if (!selectedManual) {
        _showSmartOperation('已自动选用同站成功经验「${selectedRecipe['name']}」');
      } else {
        _showSmartOperation('已选用策略「${selectedRecipe['name']}」');
      }
    } else {
      final pageType = (activeTask['demoPageType'] ?? 'feed').toString();
      final builtIn = _builtInPreferredRecipe(
        host: effectiveHost,
        pageType: pageType,
        siteProfile: siteProfile,
      );
      _bindSmartStrategyToTask(
        activeTask,
        builtIn,
        strategyKey: '__builtin__|$siteProfile|$pageType',
        // 跨站手动借用专有套路时保留 manual 标记（勿被内置经验绑定清掉）。
        manualPick: strategyManualPick,
      );
      if (strategyManualPick) {
        activeTask['crossSiteBorrow'] = true;
      }
      if (isLegacySite) {
        activeTask['matchStage'] =
            keywordFirstOn91
                ? '关键词优先 · 站内搜索'
                : (siteProfile == '91' && keyword.isEmpty
                    ? '无关键词 · 邻近媒体查找'
                    : keyword.isEmpty
                    ? '模式A · 中心起点 · 邻近依次'
                    : '关键词优先 · 站内搜索');
        debugPrint(
          'Smart legacy pipeline: site=$siteProfile '
          'gestureMode=${activeTask['gestureMode']} '
          'strict91=${activeTask['strict91KeywordMode']} '
          'crossSite=${activeTask['crossSiteBorrow']} '
          'url=$_currentUrl',
        );
      }
    }
    // V2 示范学习：默认不打扰。留空/0＝先自动；仅显式填 1–5 才先示范。
    {
      late final int requiredDemos;
      if (demoCount == null || demoCount <= 0) {
        requiredDemos = 0;
      } else {
        requiredDemos = demoCount.clamp(1, 5);
      }
      if (requiredDemos > 0) {
        activeTask['userRequestedDemo'] = true;
        activeTask['demoPhase'] = 'demo';
        activeTask['demoRequired'] = requiredDemos;
        activeTask['demoCompleted'] = 0;
        activeTask['gestureMode'] = false;
        activeTask['protectVisibleGestureFlow'] = false;
        activeTask['lockedAcquisition'] = '';
        activeTask['lockedFailStreak'] = 0;
        activeTask['skipSniffAcquire'] = true;
        activeTask['preferSniffFirst'] = false;
        activeTask['allowLegacyAlternateAcquire'] = false;
        activeTask['matchStage'] = '示范学习 · 请手动长按下载';
        _showSmartOperation('请手动长按下载第 1/$requiredDemos 个媒体（示范学习）');
      }
    }
    try {
      await WakelockPlus.enable();

      activeTask['screenWakeLockEnabled'] = true;
    } catch (e) {
      debugPrint('智能下载保持屏幕常亮失败: $e');
    }
    activeTask['deadlineTimer'] = Timer(
      deadlineAt.difference(DateTime.now()),
      () {
        if (identical(_smartDownloadTask, activeTask)) {
          unawaited(_finishSmartDownload('已达到单次任务 5 小时时间上限'));
        }
      },
    );
    activeTask['watchdogTimer'] = Timer.periodic(const Duration(seconds: 30), (
      _,
    ) {
      if (!identical(_smartDownloadTask, activeTask)) return;
      if (!DateTime.now().isBefore(deadlineAt)) {
        unawaited(_finishSmartDownload('已达到单次任务 5 小时时间上限'));
        return;
      }
      final hasActiveMediaDownload = _downloadTasks.any(
        (row) =>
            row['isSmartBatchMedia'] == true && row['status'] == 'downloading',
      );
      if (_smartDownloadAdvancing) return;
      if (hasActiveMediaDownload) {
        final cancelled = _cancelSmartMediaDownloadsWithoutProgress(
          _kSmartMediaNoProgressHardTimeout,
          'smart_media_no_progress_watchdog',
        );
        if (cancelled == 0) return;
        activeTask['lastGestureFailureType'] = 'step_watchdog_timeout';
        activeTask['lastProgressAt'] = DateTime.now();
        activeTask['lastAdvanceAt'] = DateTime.now();
        _longPressVideoDownloadInProgress = false;
        debugPrint(
          '[SMART_WATCHDOG] released $cancelled stalled media task(s); '
          'completed=${activeTask['success']}/${activeTask['target']}',
        );
        Future<void>.delayed(const Duration(milliseconds: 300), () {
          if (identical(_smartDownloadTask, activeTask)) {
            unawaited(_completeSmartGestureDownload(false));
          }
        });
        return;
      }
      if (activeTask['demoPhase'] == 'demo') return;

      _touchSmartProgressMarker(activeTask);
      final lastProgressAt =
          activeTask['lastProgressAt'] as DateTime? ?? startedAt;
      final noProgressFor = DateTime.now().difference(lastProgressAt);

      // 长时间完全无进展：解除沿用并推进，避免直链空滚等假活跃卡死。
      if (noProgressFor >= const Duration(seconds: 90)) {
        if ((activeTask['lockedAcquisition'] ?? '').toString().isNotEmpty) {
          _clearSmartTaskAcquisitionLock(
            activeTask,
            reason: '长时间无下载进展，解除沿用并尝试其他方式',
          );
        } else {
          _noteSmartStrategyProgress(activeTask, success: false);
        }
        activeTask['lastProgressAt'] = DateTime.now();
        activeTask['lastAdvanceAt'] = DateTime.now();
        unawaited(_advanceSmartDownload(_currentUrl));
        return;
      }

      final lastAdvance = activeTask['lastAdvanceAt'] as DateTime? ?? startedAt;
      if (DateTime.now().difference(lastAdvance) <
          const Duration(seconds: 60)) {
        return;
      }
      activeTask['lastAdvanceAt'] = DateTime.now();
      if (activeTask['phase'] == 'resolving_candidate_background') {
        _visitNextSmartCandidate(activeTask);
      } else {
        unawaited(_advanceSmartDownload(_currentUrl));
      }
    });
    final discoveryQueue =
        _smartDownloadTask!['discoveryPageQueue'] as List<String>;
    final queuedDiscoveryUrls =
        _smartDownloadTask!['queuedDiscoveryUrls'] as Set<String>;
    void enqueueDiscoveryPage(String value) {
      final candidateUri = Uri.tryParse(value);
      if (candidateUri == null ||
          !_isWithinSmartDownloadSite(value) ||
          value == _currentUrl ||
          !queuedDiscoveryUrls.add(value)) {
        return;
      }
      discoveryQueue.add(value);
    }

    final seedUri = Uri.tryParse(
      startFromCurrentPage ? _currentUrl : normalized,
    );
    if (!keywordFirstOn91 && seedUri != null && seedUri.host.isNotEmpty) {
      final segments =
          seedUri.pathSegments.where((part) => part.isNotEmpty).toList();
      while (segments.isNotEmpty) {
        segments.removeLast();
        enqueueDiscoveryPage(
          seedUri
              .replace(pathSegments: segments, query: '', fragment: '')
              .toString(),
        );
      }
    }
    final discoveryTaskId = const Uuid().v4();
    final discoveryCancelToken = CancelToken();
    _smartDownloadTask!['discoveryTaskId'] = discoveryTaskId;
    _smartDownloadTask!['discoveryCancelToken'] = discoveryCancelToken;
    if (mounted) {
      _addDownloadTask(
        discoveryTaskId,
        'smart://${keyword.isEmpty ? 'nearby-media' : keyword}',
        mediaType,
        discoveryCancelToken,
        displayName: '智能采集：${keyword.isEmpty ? '当前媒体附近' : keyword}',
        isSmartDiscovery: true,
      );
      _updateDownloadTask(
        discoveryTaskId,
        progress: 0.02,
        progressDetail: '正在解析当前页面媒体地址...',
      );
    }
    // 91 专有套路（a00c4bd）：不要显示「定位屏幕中心媒体」——那是后来通用/X 邻近模式的文案。
    if (keywordFirstOn91) {
      _showSmartOperation('91 关键词搜索 · 按结果卡片顺序进入详情下载');
    } else if (siteProfile == '91') {
      _showSmartOperation(
        keyword.trim().isEmpty ? '91 · 邻近媒体查找' : '91 · 站内搜索下载',
      );
    } else if (_smartUsesProfileGridPipeline(siteProfile)) {
      final gridSite =
          siteProfile == 'facebook_grid' ? 'Facebook' : 'Instagram';
      _showSmartOperation('$gridSite 网格 · 正在识别第一项媒体');
    } else {
      _showSmartOperation(allowMixedMedia ? '正在识别屏幕中心的图片或视频' : '正在定位屏幕中心媒体');
    }
    ScaffoldMessenger.of(context).showSnackBar(
      SnackBar(
        content: Text(
          '智能下载已开始：${allowMixedMedia
              ? '图片+视频'
              : mediaType == MediaType.image
              ? '图片'
              : '视频'} · ${keyword.isEmpty ? '按当前媒体从近到远' : keyword} · $targetCount 个',
        ),
      ),
    );
    if (keywordFirstOn91) {
      _smartDownloadTask!['activeDiscoveryStrategy'] = 'site_search';
      _loadUrl(strict91SearchUrl);
    } else if (keywordFirstOnX) {
      _smartDownloadTask!['activeDiscoveryStrategy'] = 'x_media_search';
      _loadUrl(strictXSearchUrl);
    } else if (strictBaiduVideoMode) {
      _smartDownloadTask!['activeDiscoveryStrategy'] = 'baidu_video_search';
      _loadUrl(strictBaiduSearchUrl);
    } else if (startFromCurrentPage) {
      unawaited(_advanceSmartDownload(_currentUrl));
    } else {
      _loadUrl(normalized);
    }
  }

  bool _isInstagramGridDetailUrl(String value) {
    final uri = Uri.tryParse(value);
    if (uri == null) return false;
    final parts = uri.pathSegments.where((part) => part.isNotEmpty).toList();
    if (parts.length < 2) return false;
    final marker = parts[parts.length - 2].toLowerCase();
    return marker == 'p' || marker == 'reel';
  }

  String _instagramGridDetailKey(String value) {
    final uri = Uri.tryParse(value);
    if (uri == null) return '';
    final parts = uri.pathSegments.where((part) => part.isNotEmpty).toList();
    if (parts.length < 2) return '';
    final marker = parts[parts.length - 2].toLowerCase();
    if (marker != 'p' && marker != 'reel') return '';
    return parts.last;
  }

  /// Grid scan/scroll must never stall on a library gate left from a prior cell.
  bool _profileGridShouldWaitForLibrary(
    Map<String, dynamic> task,
    String phase,
  ) {
    if (task['instagramGridMode'] != true) return false;
    // Scan / scroll / return must never block on a stale gate from the prior cell.
    if (phase == 'instagram_grid_returning' ||
        phase == 'instagram_grid_scanning' ||
        phase == 'instagram_grid_scrolling' ||
        phase == 'visiting_seed') {
      return false;
    }
    if (phase != 'instagram_grid_opening' &&
        phase != 'instagram_grid_waiting_download') {
      return false;
    }
    return task['gestureDownloadPending'] == true ||
        task['actionAwaitingLibrarySave'] == true;
  }

  /// Facebook detail is a same-URL lightbox; do not treat URL drift as detail.
  bool _profileGridIsDetailView({
    required bool nativeInstagram,
    required String actualUrl,
    required String phase,
    required String activeGridKey,
  }) {
    if (phase == 'instagram_grid_returning' ||
        phase == 'instagram_grid_scanning' ||
        phase == 'instagram_grid_scrolling' ||
        phase == 'visiting_seed') {
      return false;
    }
    if (_isInstagramGridDetailUrl(actualUrl)) return true;
    if (nativeInstagram) return false;
    return activeGridKey.isNotEmpty &&
        (phase == 'instagram_grid_opening' ||
            phase == 'instagram_grid_waiting_download');
  }

  void _clearProfileGridLibraryGateForScan(Map<String, dynamic> task) {
    if (task['gestureDownloadPending'] != true &&
        task['actionAwaitingLibrarySave'] != true) {
      return;
    }
    task['gestureDownloadPending'] = false;
    task['gestureActiveKey'] = '';
    _actionRecipeFinishAwaitLibrarySave(
      task,
      libraryOk: false,
      outcome: 'grid_scan_resume',
    );
  }

  Future<void> _returnFromInstagramGrid(
    Map<String, dynamic> task, {
    required bool handled,
  }) async {
    final gridSite = (task['profileGridSite'] ?? 'Instagram').toString();
    final key = (task['instagramGridActiveKey'] ?? '').toString();
    debugPrint(
      '[SMART_GRID] return key=$key handled=$handled '
      'success=${task['success']}/${task['target']}',
    );
    final retries =
        task['instagramGridRetryCounts'] as Map<String, int>? ??
        <String, int>{};
    task['instagramGridRetryCounts'] = retries;
    if (handled) {
      if (key.isNotEmpty) {
        (task['instagramGridProcessedKeys'] as Set<String>).add(key);
      }
    } else if (key.isNotEmpty) {
      final count = (retries[key] ?? 0) + 1;
      retries[key] = count;
      // A transient Instagram player/request failure gets one fresh detail
      // attempt.  The second failure is skipped so one post can never stall
      // the whole profile traversal.
      if (count >= 2) {
        (task['instagramGridProcessedKeys'] as Set<String>).add(key);
      }
    }
    task['gestureDownloadPending'] = false;
    task['instagramGridMediaWaits'] = 0;
    task['phase'] = 'instagram_grid_returning';
    task['matchStage'] =
        handled
            ? '$gridSite 网格 · 当前媒体已处理，返回下一项'
            : '$gridSite 网格 · 当前媒体未成功，返回后重试或跳过';
    _showSmartOperation(handled ? '已处理当前媒体，返回网格' : '返回网格继续处理');

    final gridUrl = (task['instagramGridUrl'] ?? '').toString();
    final controller = _controller;
    if (gridSite == 'Facebook' && controller != null) {
      try {
        await controller.evaluateJavascript(
          source: '''
            (() => {
              const selectors = [
                '[aria-label="Close"][role="button"]',
                '[aria-label="关闭"][role="button"]',
                '[aria-label*="Close"][role="button"]',
                '[aria-label*="关闭"][role="button"]',
                'div[role="dialog"] [aria-label*="Close" i][role="button"]',
                'div[role="dialog"] [aria-label*="关闭"][role="button"]',
              ];
              for (const sel of selectors) {
                const btn = document.querySelector(sel);
                if (!btn) continue;
                const r = btn.getBoundingClientRect();
                if (r.width > 16 && r.height > 16) {
                  btn.click();
                  return true;
                }
              }
              return false;
            })()
          ''',
        );
      } catch (_) {}
    }
    // Instagram's SPA history can contain detail pages from another profile
    // or an older grid run. Going back can therefore jump to an unrelated
    // reel. Restore the exact grid URL captured when this item was opened.
    if (gridSite != 'Facebook' && gridUrl.startsWith('http')) {
      _loadUrl(gridUrl);
    } else if (controller != null && await controller.canGoBack()) {
      await controller.goBack();
    } else if (gridUrl.startsWith('http')) {
      _loadUrl(gridUrl);
    }
    Future<void>.delayed(const Duration(milliseconds: 900), () async {
      if (!identical(_smartDownloadTask, task)) return;
      final current = (await _controller?.getUrl())?.toString() ?? _currentUrl;
      if (gridUrl.startsWith('http') &&
          (_isInstagramGridDetailUrl(current) ||
              !_isSameLoadedDocument(current, gridUrl))) {
        _loadUrl(gridUrl);
        Future<void>.delayed(const Duration(milliseconds: 900), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_returnFromInstagramGridRestorePosition(task));
          }
        });
        return;
      }
      await _returnFromInstagramGridRestorePosition(task);
    });
  }

  Future<void> _returnFromInstagramGridRestorePosition(
    Map<String, dynamic> task,
  ) async {
    if (!identical(_smartDownloadTask, task)) return;
    final current = (await _controller?.getUrl())?.toString() ?? _currentUrl;
    final gridUrl = (task['instagramGridUrl'] ?? '').toString();
    if (_isInstagramGridDetailUrl(current) ||
        (gridUrl.startsWith('http') &&
            !_isSameLoadedDocument(current, gridUrl))) {
      final gridSite = (task['profileGridSite'] ?? 'Instagram').toString();
      await _finishSmartDownload('$gridSite 返回媒体网格失败，已安全停止');
      return;
    }
    final restoreY = (task['instagramGridScrollY'] as num?)?.toDouble() ?? 0.0;
    try {
      await _controller?.evaluateJavascript(
        source: 'window.scrollTo(0, ${restoreY.round()}); true;',
      );
    } catch (_) {}
    if (!identical(_smartDownloadTask, task)) return;
    task['instagramGridActiveKey'] = '';
    task['instagramGridActiveHref'] = '';
    // Only consecutive, settled grid-bottom scans may finish traversal.
    // Transient empty DOMs while returning from a detail must not accumulate.
    task['instagramGridNoNewScans'] = 0;
    _clearProfileGridLibraryGateForScan(task);
    task['phase'] = 'instagram_grid_scanning';
    unawaited(_advanceSmartDownload(_currentUrl));
  }

  Future<void> _advanceInstagramGridDownload(Map<String, dynamic> task) async {
    final controller = _controller;
    if (controller == null || !identical(_smartDownloadTask, task)) return;
    final gridSite = (task['profileGridSite'] ?? 'Instagram').toString();
    // onLoadStop may arrive before the explicit return/scroll restoration
    // timer. Never open another card while that older timer is still pending.
    if (task['phase'] == 'instagram_grid_returning') return;
    if (task['instagramGridAdvancing'] == true) return;
    if ((task['success'] as int) >= (task['target'] as int)) {
      await _finishSmartDownload();
      return;
    }
    final waitPhase = (task['phase'] ?? '').toString();
    if (_profileGridShouldWaitForLibrary(task, waitPhase)) {
      final startedAt = task['gestureDownloadStartedAt'] as DateTime?;
      final outcome = (task['actionDownloadOutcome'] ?? '').toString();
      if (task['actionLibrarySaveOk'] == true ||
          outcome == 'already_in_library' ||
          outcome == 'library_saved') {
        await _completeSmartGestureDownload(outcome != 'already_in_library');
        return;
      }
      if (startedAt != null &&
          DateTime.now().difference(startedAt) >=
              _kFacebookSmartRoundHardTimeout) {
        _cancelStalledSmartMediaDownloads('profile_grid_media_timeout');
        _longPressVideoDownloadInProgress = false;
        task['lastGestureFailureType'] = 'step_watchdog_timeout';
        await _completeSmartGestureDownload(false);
        return;
      }
      final hasActiveDownload = _downloadTasks.any(
        (row) =>
            row['isSmartBatchMedia'] == true && row['status'] == 'downloading',
      );
      if (hasActiveDownload || _longPressVideoDownloadInProgress) {
        task['matchStage'] = '$gridSite 网格 · 等待入库…';
        Future<void>.delayed(const Duration(milliseconds: 450), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
      if (startedAt == null ||
          DateTime.now().difference(startedAt) < const Duration(seconds: 45)) {
        task['matchStage'] = '$gridSite 网格 · 等待入库…';
        Future<void>.delayed(const Duration(milliseconds: 450), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
      task['lastGestureFailureType'] = 'instagram_download_timeout';
      await _completeSmartGestureDownload(false);
      return;
    }

    task['instagramGridAdvancing'] = true;
    try {
      final actualUrl = (await controller.getUrl())?.toString() ?? _currentUrl;
      final phase = (task['phase'] ?? '').toString();
      final activeGridKey = (task['instagramGridActiveKey'] ?? '').toString();
      final nativeInstagram =
          _smartSiteProfile((task['host'] ?? '').toString()) == 'instagram';
      if (nativeInstagram &&
          activeGridKey.isNotEmpty &&
          (phase == 'instagram_grid_opening' ||
              phase == 'instagram_grid_waiting_download')) {
        final actualDetailKey = _instagramGridDetailKey(actualUrl);
        if (actualDetailKey != activeGridKey) {
          final navigationWaits =
              ((task['instagramGridNavigationWaits'] as int?) ?? 0) + 1;
          task['instagramGridNavigationWaits'] = navigationWaits;
          task['matchStage'] = 'Instagram 网格 · 等待指定详情页完成切换';
          debugPrint(
            '[SMART_GRID] wait detail navigation expected=$activeGridKey '
            'actual=$actualDetailKey wait=$navigationWaits url=$actualUrl',
          );
          if (navigationWaits == 8) {
            final activeHref =
                (task['instagramGridActiveHref'] ?? '').toString();
            if (activeHref.startsWith('http')) {
              debugPrint(
                '[SMART_GRID] click navigation delayed; loading exact href '
                '$activeHref',
              );
              _loadUrl(activeHref);
            }
          } else if (navigationWaits >= 20) {
            task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
            await _returnFromInstagramGrid(task, handled: false);
            return;
          }
          Future<void>.delayed(const Duration(milliseconds: 450), () {
            if (identical(_smartDownloadTask, task)) {
              unawaited(_advanceSmartDownload(_currentUrl));
            }
          });
          return;
        }
        task['instagramGridNavigationWaits'] = 0;
      }
      final isDetail = _profileGridIsDetailView(
        nativeInstagram: nativeInstagram,
        actualUrl: actualUrl,
        phase: phase,
        activeGridKey: activeGridKey,
      );
      if (isDetail) {
        if (gridSite == 'Facebook' && phase == 'instagram_grid_opening') {
          final lightboxReady = await controller.evaluateJavascript(
            source: '''
              (() => {
                const dialog = document.querySelector('div[role="dialog"]');
                if (!dialog) return false;
                const media = dialog.querySelector('video, img');
                if (!media) return false;
                const r = media.getBoundingClientRect();
                return r.width >= 120 && r.height >= 120;
              })()
            ''',
          );
          if (lightboxReady != true) {
            task['matchStage'] = '$gridSite 网格 · 等待详情打开';
            _showSmartOperation('等待媒体详情加载');
            Future<void>.delayed(const Duration(milliseconds: 700), () {
              if (identical(_smartDownloadTask, task)) {
                unawaited(_advanceSmartDownload(_currentUrl));
              }
            });
            return;
          }
          task['phase'] = 'instagram_grid_waiting_download';
        }
        final waits = (task['instagramGridMediaWaits'] as int?) ?? 0;
        final requestedType =
            task['allowMixedMedia'] == true
                ? 'mixed'
                : task['mediaType'] == MediaType.video
                ? 'video'
                : 'image';
        // Open the callback gate before dispatching the synthetic long press:
        // a very fast image save can otherwise finish before Dart marks it as
        // pending and its real library confirmation would be ignored.
        task['gestureDownloadPending'] = true;
        task['gestureDownloadStartedAt'] = DateTime.now();
        _actionRecipeBeginAwaitLibrarySave(task);
        task['gestureActiveKey'] =
            (task['instagramGridActiveKey'] ?? '').toString();
        final result = await controller.evaluateJavascript(
          source: '''
            (() => {
              const requested = ${jsonEncode(requestedType)};
              const facebookDetail =
                ${jsonEncode(gridSite)} === 'Facebook';
              const mediaRoot = facebookDetail
                ? (document.querySelector('div[role="dialog"]') || document)
                : document;
              if (facebookDetail &&
                  !document.querySelector('div[role="dialog"]')) {
                return {action:'wait'};
              }
              const visible = (el) => {
                const r = el.getBoundingClientRect();
                if (r.width < 100 || r.height < 100 || r.bottom <= 0 ||
                    r.top >= innerHeight || r.right <= 0 || r.left >= innerWidth) {
                  return false;
                }
                const s = getComputedStyle(el);
                return s.display !== 'none' && s.visibility !== 'hidden' &&
                  Number(s.opacity || 1) > 0.05;
              };
              let media = Array.from(mediaRoot.querySelectorAll('video, img'))
                .filter(el => visible(el))
                .filter(el => {
                  if (requested === 'video') return el.tagName === 'VIDEO';
                  if (requested === 'image') return el.tagName === 'IMG';
                  return true;
                })
                .map(el => {
                  const r = el.getBoundingClientRect();
                  const isVideo = el.tagName === 'VIDEO';
                  const source = String(el.currentSrc || el.src || '');
                  const badImage = !isVideo && (
                    Number(el.naturalWidth || 0) < 240 ||
                    Number(el.naturalHeight || 0) < 240 ||
                    /(avatar|profile|emoji|icon|logo)/i.test(
                      source + ' ' + String(el.alt || '')
                    )
                  );
                  const centerPenalty =
                    Math.abs(r.left + r.width / 2 - innerWidth / 2) * 10;
                  return {
                    el, r, isVideo, badImage,
                    score: r.width * r.height - centerPenalty +
                      (isVideo ? 100000 : 0)
                  };
                })
                .filter(row => !row.badImage)
                .sort((a, b) => b.score - a.score);
              // Reel details contain both the real VIDEO and large poster
              // images. In mixed grid mode, visible video is authoritative.
              if (requested === 'mixed' && media.some(row => row.isVideo)) {
                media = media.filter(row => row.isVideo);
              }
              const row = media[0];
              if (!row) return {action:'wait'};
              if (row.isVideo) {
                try {
                  row.el.muted = true;
                  const play = row.el.play();
                  if (play && typeof play.catch === 'function') play.catch(() => {});
                } catch (_) {}
                const src = String(row.el.currentSrc || row.el.src || '');
                if ((!src && row.el.readyState < 2) ||
                    (!Number.isFinite(row.el.duration) && row.el.readyState < 2)) {
                  return {action:'prepare'};
                }
              }
              const x = Math.max(12, Math.min(innerWidth - 12,
                row.r.left + row.r.width / 2));
              const y = Math.max(12, Math.min(innerHeight - 12,
                row.r.top + row.r.height / 2));
              if (typeof window.__appTriggerSmartLongPress !== 'function') {
                return {action:'wait'};
              }
              const ok = window.__appTriggerSmartLongPress(x, y);
              return {
                action: ok === false ? 'wait' : 'longpress',
                x:x / Math.max(1, innerWidth),
                y:y / Math.max(1, innerHeight),
                video:row.isVideo
              };
            })()
          ''',
        );
        final action =
            result is Map ? (result['action'] ?? '').toString() : 'wait';
        if (action == 'longpress') {
          task['phase'] = 'instagram_grid_waiting_download';
          task['matchStage'] = '$gridSite 网格 · 等待入库…';
          final point =
              result is Map
                  ? Offset(
                    (result['x'] as num?)?.toDouble() ?? 0.5,
                    (result['y'] as num?)?.toDouble() ?? 0.5,
                  )
                  : const Offset(0.5, 0.5);
          _showSmartOperation('长按当前详情媒体并等待下载完成', point: point);
          return;
        }
        task['gestureDownloadPending'] = false;
        task['gestureActiveKey'] = '';
        _actionRecipeFinishAwaitLibrarySave(
          task,
          libraryOk: false,
          outcome: 'media_not_ready',
        );
        final nextWait = waits + 1;
        task['instagramGridMediaWaits'] = nextWait;
        if (nextWait >= 10) {
          task['failed'] = ((task['failed'] as int?) ?? 0) + 1;
          await _returnFromInstagramGrid(task, handled: false);
          return;
        }
        task['matchStage'] =
            action == 'prepare'
                ? '$gridSite 网格 · 播放预热以获取真实视频地址'
                : '$gridSite 网格 · 等待详情媒体加载';
        _showSmartOperation(action == 'prepare' ? '正在播放预热当前视频' : '等待当前媒体加载');
        Future<void>.delayed(const Duration(milliseconds: 700), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }

      // We are on the profile grid. Restore position after SPA/history return,
      // then select by stable shortcode rather than by a screen coordinate.
      final processed =
          task['instagramGridProcessedKeys'] as Set<String>? ?? <String>{};
      task['instagramGridProcessedKeys'] = processed;
      final processedJson = jsonEncode(processed.toList());
      final result = await controller.evaluateJavascript(
        source: '''
          (() => {
            const processed = new Set($processedJson);
            const instagramNative =
              ${jsonEncode(_smartSiteProfile((task['host'] ?? '').toString()))} ===
              'instagram';
            const facebookNative =
              ${jsonEncode((task['profileGridSite'] ?? '').toString())} ===
              'Facebook';
            const requested = ${jsonEncode(task['allowMixedMedia'] == true
            ? 'mixed'
            : task['mediaType'] == MediaType.video
            ? 'video'
            : 'image')};
            let rows;
            if (facebookNative) {
              const junkSrc = (src) =>
                /(avatar|profile_pic|profile_images|profile_banners|emoji|icon|logo|sprite|badge|safe_image|favicon)/i
                  .test(String(src || ''));
              const gridCellSize = (rect) =>
                rect.width >= 56 && rect.height >= 56 &&
                rect.width <= innerWidth * 0.78 &&
                rect.height <= innerHeight * 0.68;
              const findMediaEl = (anchor) => {
                if (!anchor) return null;
                let img = anchor.querySelector('img');
                if (img) return img;
                img = anchor.querySelector('[role="img"] img');
                if (img) return img;
                const roleImg = anchor.querySelector('[role="img"]');
                if (roleImg) return roleImg;
                const bgImg = anchor.querySelector('i[data-visualcompletion], i[style*="background"]');
                if (bgImg) return bgImg;
                return null;
              };
              const stableKey = (anchor, img, rect, ordinal) => {
                const imageId = String(img?.dataset?.imageId || '');
                const actionId = String(anchor?.dataset?.actionId || '');
                const href = String(anchor?.href || anchor?.getAttribute?.('href') || '');
                const aria = String(anchor?.getAttribute?.('aria-label') || '');
                const src = String(img?.currentSrc || img?.src || '');
                const stem = (src.match(/\\/([^/?]+)\\.(?:jpg|jpeg|webp|png)/i) || [])[1] || '';
                const ordinalHint = (aria.match(/(?:第\\s*)?(\\d+)\\s*(?:条|项)?/i) || [])[1] || '';
                let hrefKey = '';
                try {
                  const u = new URL(href, location.href);
                  const m = u.pathname.match(
                    /\\/(?:photo(?:\\/|\\?)|photos\\/|videos\\/|reel\\/|posts\\/|permalink\\/)([^/?]+)/i
                  );
                  if (m) hrefKey = m[1];
                  const fbid = u.searchParams.get('fbid') ||
                    u.searchParams.get('v') || u.searchParams.get('story_fbid');
                  if (fbid) hrefKey = 'fbid:' + fbid;
                } catch (_) {}
                return imageId || actionId || hrefKey || stem ||
                  ('facebook-grid-' + (ordinalHint || ordinal) + '-' +
                    Math.round(scrollY + rect.top) + '-' + Math.round(rect.left));
              };
              const seen = new Set();
              const consider = (anchor) => {
                const img = findMediaEl(anchor);
                if (!anchor || !img) return null;
                const rect = anchor.getBoundingClientRect();
                if (!gridCellSize(rect)) return null;
                const src = String(img.currentSrc || img.src || img.getAttribute?.('src') || '');
                if (junkSrc(src)) return null;
                const aria = String(anchor.getAttribute('aria-label') || '');
                if (/^(Home|Menu|Search|Messenger|Notifications|Settings|Create|Back|Close|Photo profile)/i.test(aria)) {
                  return null;
                }
                const key = stableKey(anchor, img, rect, seen.size);
                if (seen.has(key)) return null;
                seen.add(key);
                const videoHint = /video|reel|播放|观看|views?|次/i.test(aria) ||
                  !!anchor.querySelector('[data-video-id], svg[aria-label*="video" i]');
                if (requested === 'video' && !videoHint &&
                    !/reel/i.test(aria) && !anchor.querySelector('[data-video-id]')) {
                  return null;
                }
                return {
                  anchor, href:String(anchor.href || anchor.getAttribute?.('href') || ''), key,
                  kind: videoHint ? 'reel' : 'photo',
                  top:rect.top, left:rect.left,
                  visible:rect.bottom > 8 && rect.top < innerHeight - 8
                };
              };
              rows = [];
              const selectors = [
                'a[href*="photo"]',
                'a[href*="video"]',
                'a[href*="reel"]',
                'a[href*="permalink"]',
                'a[href*="posts"]',
                'a[href*="fbid"]',
                'a[href*="set=a."]',
                'div[role="button"][tabindex="0"]',
                '[role="link"]',
                '[role="button"]',
              ];
              for (const sel of selectors) {
                for (const anchor of document.querySelectorAll(sel)) {
                  const row = consider(anchor);
                  if (row) rows.push(row);
                }
              }
              rows.sort((a, b) => a.top - b.top || a.left - b.left);
            } else {
              rows = Array.from(document.querySelectorAll('a[href]'))
                .map(anchor => {
                let url;
                try { url = new URL(anchor.href, location.href); }
                catch (_) { return null; }
                const match = url.pathname.match(
                  /^\\/(?:[^/]+\\/)?(p|reel)\\/([^/]+)\\/?\$/
                );
                const rect = anchor.getBoundingClientRect();
                if (rect.width < 70 || rect.height < 70) return null;
                if (!match) {
                  const media = anchor.querySelector('img, video');
                  if (instagramNative || !media ||
                      url.origin !== location.origin ||
                      rect.width > innerWidth * 0.58 ||
                      rect.height > innerHeight * 0.72) {
                    return null;
                  }
                }
                const key = match
                  ? match[2]
                  : (url.pathname + url.search).replace(/\\/\$/, '') ||
                    ('grid-' + Math.round(scrollY + rect.top) + '-' +
                      Math.round(rect.left));
                return {
                  anchor, href:url.href, key,
                  kind:match ? match[1] : 'item',
                  top:rect.top, left:rect.left,
                  visible:rect.bottom > 8 && rect.top < innerHeight - 8
                };
                })
                .filter(Boolean)
                .filter(row =>
                  requested !== 'image' ||
                  row.kind === 'p' ||
                  row.kind === 'item'
                )
                .sort((a, b) => a.top - b.top || a.left - b.left);
            }
            const candidate = rows.find(row =>
              row.visible && !processed.has(row.key)
            );
            if (candidate) {
              candidate.anchor.scrollIntoView({block:'center', inline:'center'});
              const savedY = scrollY;
              const rect = candidate.anchor.getBoundingClientRect();
              let jsClick = false;
              try {
                candidate.anchor.click();
                jsClick = true;
              } catch (_) {}
              return {
                action:'open', href:candidate.href, key:candidate.key,
                kind:candidate.kind, scrollY:savedY, count:rows.length,
                x:(rect.left + rect.width / 2) / Math.max(1, innerWidth),
                y:(rect.top + rect.height / 2) / Math.max(1, innerHeight),
                jsClick
              };
            }
            const remaining = rows.filter(row => !processed.has(row.key));
            if (remaining.length) {
              const nextCard = remaining[0];
              const before = scrollY;
              nextCard.anchor.scrollIntoView({block:'center', inline:'center'});
              return {
                action:'scroll', before, after:scrollY,
                count:rows.length, remaining:remaining.length
              };
            }
            // During Instagram SPA restoration the profile shell can be
            // visible before its grid anchors are mounted. This is not the
            // bottom of the grid and must not consume the end-of-grid budget.
            if (!rows.length) {
              return {action:'wait_dom', count:0};
            }
            const before = scrollY;
            const maxY = Math.max(0,
              document.documentElement.scrollHeight - innerHeight);
            const next = Math.min(maxY, before + innerHeight * 0.82);
            window.scrollTo(0, next);
            return {
              action: Math.abs(next - before) < 3 ? 'end' : 'scroll',
              before, after:next, count:rows.length
            };
          })()
        ''',
      );
      final action =
          result is Map ? (result['action'] ?? '').toString() : 'wait';
      debugPrint(
        '[SMART_GRID] scan action=$action '
        'count=${result is Map ? result['count'] : null} '
        'remaining=${result is Map ? result['remaining'] : null} '
        'success=${task['success']}/${task['target']}',
      );
      if (action == 'open' && result is Map) {
        task['instagramGridNoNewScans'] = 0;
        task['instagramGridEmptyDomScans'] = 0;
        final jsClicked = result['jsClick'] == true;
        var opened = jsClicked;
        if (!opened) {
          opened = await _nativeWebViewTap(
            Offset(
              ((result['x'] as num?)?.toDouble() ?? 0.5).clamp(0.04, 0.96),
              ((result['y'] as num?)?.toDouble() ?? 0.5).clamp(0.04, 0.96),
            ),
            holdMs: 90,
          );
        }
        if (!opened) {
          task['instagramGridEngineFailures'] =
              ((task['instagramGridEngineFailures'] as int?) ?? 0) + 1;
          task['matchStage'] = '$gridSite 网格 · 卡片点击失败，准备重试';
          debugPrint(
            '[SMART_GRID] open failed key=${result['key']} jsClick=$jsClicked',
          );
          Future<void>.delayed(const Duration(milliseconds: 500), () {
            if (identical(_smartDownloadTask, task)) {
              unawaited(_advanceSmartDownload(_currentUrl));
            }
          });
          return;
        }
        task['instagramGridUrl'] = actualUrl;
        task['instagramGridScrollY'] =
            (result['scrollY'] as num?)?.toDouble() ?? 0.0;
        task['instagramGridActiveHref'] = (result['href'] ?? '').toString();
        task['instagramGridActiveKey'] = (result['key'] ?? '').toString();
        task['gestureActiveKey'] = (result['key'] ?? '').toString();
        // The Facebook lite grid exposes image/action IDs, not the playable
        // Reel/CDN video identity. Keep that ID only for grid traversal; the
        // Facebook download pipeline binds the real identity after detail
        // playback starts.
        debugPrint(
          '[SMART_GRID] open key=${task['instagramGridActiveKey']} '
          'href=${task['instagramGridActiveHref']}',
        );
        task['instagramGridMediaWaits'] = 0;
        task['instagramGridNavigationWaits'] = 0;
        task['phase'] = 'instagram_grid_opening';
        task['matchStage'] = '$gridSite 网格 · 打开指定媒体详情';
        _showSmartOperation('打开下一项媒体');
        Future<void>.delayed(const Duration(milliseconds: 1000), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
      if (action == 'scroll') {
        task['instagramGridNoNewScans'] = 0;
        task['instagramGridEmptyDomScans'] = 0;
        task['phase'] = 'instagram_grid_scrolling';
        task['matchStage'] = '$gridSite 网格 · 加载下一行';
        _showSmartOperation('向下浏览下一行网格媒体');
        Future<void>.delayed(const Duration(milliseconds: 850), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
      if (action == 'wait_dom') {
        final emptyScans =
            ((task['instagramGridEmptyDomScans'] as int?) ?? 0) + 1;
        task['instagramGridEmptyDomScans'] = emptyScans;
        task['instagramGridNoNewScans'] = 0;
        debugPrint(
          '[SMART_GRID] grid DOM not mounted yet; wait=$emptyScans/20 '
          'url=$actualUrl',
        );
        if (emptyScans >= 20) {
          await _finishSmartDownload('$gridSite 网格持续无法加载，已安全停止');
          return;
        }
        Future<void>.delayed(const Duration(milliseconds: 1200), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
        return;
      }
      task['instagramGridEmptyDomScans'] = 0;
      final noNew = ((task['instagramGridNoNewScans'] as int?) ?? 0) + 1;
      task['instagramGridNoNewScans'] = noNew;
      // Instagram may need several seconds to append the next virtualized
      // batch at the bottom. A short three-pass window caused false completion.
      if (noNew >= 8) {
        await _finishSmartDownload(
          '$gridSite 网格已遍历完毕（成功 ${task['success']}/${task['target']}）',
        );
        return;
      }
      Future<void>.delayed(const Duration(milliseconds: 1200), () {
        if (identical(_smartDownloadTask, task)) {
          unawaited(_advanceSmartDownload(_currentUrl));
        }
      });
    } catch (e) {
      debugPrint('$gridSite grid pipeline failed: $e');
      final failures = ((task['instagramGridEngineFailures'] as int?) ?? 0) + 1;
      task['instagramGridEngineFailures'] = failures;
      if (failures >= 3) {
        await _finishSmartDownload('$gridSite 网格页面识别连续失败');
      } else {
        Future<void>.delayed(const Duration(milliseconds: 700), () {
          if (identical(_smartDownloadTask, task)) {
            unawaited(_advanceSmartDownload(_currentUrl));
          }
        });
      }
    } finally {
      task['instagramGridAdvancing'] = false;
    }
  }

  Future<void> _advanceSmartDownload(String loadedUrl) async {
    final task = _smartDownloadTask;
    final controller = _controller;
    if (task == null || controller == null) return;
    if (task['instagramGridMode'] == true) {
      await _advanceInstagramGridDownload(task);
      return;
    }
    // 动作套路 / 本页同层批量 / 分页嗅探 / 91·通用实测管线 由独立循环驱动，不进入旧 FSM。
    if (task['mode'] == 'action_recipe' ||
        task['mode'] == 'scope_batch' ||
        task['mode'] == 'paginated_sniff' ||
        task['mode'] == 'simple_91_keyword' ||
        task['mode'] == 'simple_generic') {
      return;
    }
    // 91 a00c4bd 绝对原版管线：整段推进逻辑不走 HEAD 改造版。
    if (task['a00_91_pipeline'] == true) {
      await _advanceSmartDownload91A00(loadedUrl);
      return;
    }
    if (_smartDownloadAdvancing) {
      if (task['advanceRetryScheduled'] != true) {
        task['advanceRetryScheduled'] = true;
        Future<void>.delayed(const Duration(milliseconds: 160), () {
          if (!identical(_smartDownloadTask, task)) return;
          task['advanceRetryScheduled'] = false;
          unawaited(_advanceSmartDownload(_currentUrl));
        });
      }
      return;
    }
    task['advanceRetryScheduled'] = false;
    final discoveryToken = task['discoveryCancelToken'] as CancelToken?;
    if (discoveryToken?.isCancelled == true) {
      await _finishSmartDownload('用户已停止任务');
      return;
    }
    final deadlineAt = task['deadlineAt'] as DateTime?;
    if (deadlineAt != null && !DateTime.now().isBefore(deadlineAt)) {
      await _finishSmartDownload('已达到单次任务 5 小时时间上限');
      return;
    }
    if (task['demoPhase'] == 'demo') {
      final need = (task['demoRequired'] as int?) ?? 2;
      final done = (task['success'] as int?) ?? 0;
      task['matchStage'] = '示范学习 · 等待手动长按';
      _showSmartOperation(
        done >= need ? '示范已完成，正在切换自动下载' : '请手动长按下载第 ${done + 1}/$need 个媒体（示范中）',
      );
      _updateSmartDiscoveryProgress(task, 'demo_waiting_user');
      return;
    }

    _smartDownloadAdvancing = true;
    task['lastAdvanceAt'] = DateTime.now();
    try {
      final phase = task['phase']?.toString() ?? '';
      final taskHost = (task['host'] ?? '').toString();
      final is91Host =
          taskHost == '91cg1.com' || taskHost.endsWith('.91cg1.com');
      final is91KeywordTask =
          (task['strict91KeywordMode'] == true) ||
          (is91Host && (task['keyword'] ?? '').toString().trim().isNotEmpty);
      final is91Dedicated =
          (task['siteProfile'] ?? '').toString() == '91' || is91Host;
      final strict91Mode = task['strict91KeywordMode'] == true;
      final strictXFeedMode = task['strictXFeedMode'] == true;
      final xInlineFeedMode = task['xInlineFeedMode'] == true;
      final strictBaiduVideoMode = task['strictBaiduVideoMode'] == true;
      final strictXSearchUrl = (task['strictXSearchUrl'] ?? '').toString();
      final strict91SearchUrl = (task['strict91SearchUrl'] ?? '').toString();
      final strictBaiduSearchUrl =
          (task['strictBaiduSearchUrl'] ?? '').toString();
      final actualLoadedUrl =
          (await controller.getUrl())?.toString() ?? loadedUrl;
      final actualHost = Uri.tryParse(actualLoadedUrl)?.host ?? '';
      // 全局跨站护栏：任意阶段一旦出站，立即拉回（不只限手势保护模式）。
      if (await _recoverSmartDownloadIfOffsite(task, actualLoadedUrl)) {
        return;
      }
      if (task['protectVisibleGestureFlow'] == true &&
          actualHost.isNotEmpty &&
          taskHost.isNotEmpty &&
          !_sameSmartSite(actualHost, taskHost) &&
          !_isLikelyDirectMediaUrl(actualLoadedUrl)) {
        if (await _recoverVisibleGesturePage(task, '阻止站内兜底跳到其他网站')) {
          return;
        }
      }

      if (task['gestureMode'] == true && strict91Mode) {
        // Tasks created before a hot restart may still carry the old generic
        // gesture flag. Migrate them into the ordered 91 result-card flow.
        task['gestureMode'] = false;
        task['protectVisibleGestureFlow'] = false;
        task['gestureDownloadPending'] = false;
        task['phase'] = 'collecting_search_results';
        if (strict91SearchUrl.isNotEmpty &&
            !_isSame91TaskPage(strict91SearchUrl, actualLoadedUrl)) {
          _loadUrl(strict91SearchUrl);
          return;
        }
      }

      final xReturnInProgress =
          strictXFeedMode &&
          (phase == 'x_search_returning' || phase == 'gesture_returning');
      if (xInlineFeedMode &&
          phase != 'x_search_returning' &&
          task['xInlineActivationPending'] != true &&
          task['xInlineReadyToLongPress'] != true &&
          task['gestureDownloadPending'] != true &&
          (_isXStatusDetailPage(actualLoadedUrl) ||
              _isXMediaViewerPage(actualLoadedUrl))) {
        task['matchStage'] = 'X 信息流直下模式 · 返回原列表';
        _showSmartOperation('已阻止进入详情页，返回信息流继续下载');
        await _returnFromXSmartCard(task);
        return;
      }
      if (task['gestureMode'] == true && !xReturnInProgress) {
        final keyword = (task['keyword'] ?? '').toString().trim();
        final strictSearchStillLoading =
            (strict91Mode &&
                strict91SearchUrl.isNotEmpty &&
                !_isSameLoadedDocument(strict91SearchUrl, actualLoadedUrl)) ||
            (strictXFeedMode &&
                strictXSearchUrl.isNotEmpty &&
                !(Uri.tryParse(actualLoadedUrl)?.path.startsWith('/search') ??
                    false)) ||
            (strictBaiduVideoMode &&
                phase == 'baidu_video_search_loading' &&
                strictBaiduSearchUrl.isNotEmpty &&
                !_isBaiduVideoResultsUrl(actualLoadedUrl));
        if (strictBaiduVideoMode && strictSearchStillLoading) {
          if (_isUnsafeBaiduSmartPage(actualLoadedUrl)) {
            await _recoverStrictGesturePage(task, '搜索页加载异常');
          }
          return;
        }
        if (!strictSearchStillLoading) {
          final handled = await _advanceVisibleSmartGesture(task);
          if (handled) return;
        }
        // If a keyword is not represented on the current page, retain the
        // existing site-search path as a compatibility fallback.
        if (keyword.isEmpty) return;
      }

      if (strictXFeedMode && phase == 'x_search_loading') {
        final actualUri = Uri.tryParse(actualLoadedUrl);
        final onSearchPage =
            actualUri != null &&
            actualUri.pathSegments.isNotEmpty &&
            actualUri.pathSegments.first == 'search';
        if (!onSearchPage) {
          _loadUrl(strictXSearchUrl);
          return;
        }
        await Future<void>.delayed(const Duration(milliseconds: 900));
        task['phase'] = 'scanning_feed';
        _continueSmartFeed(task, madeProgress: false);
        return;
      }

      if (strictXFeedMode && phase == 'x_search_returning') {
        if (strictXSearchUrl.isEmpty) {
          final returnUrl =
              (task['xReturnExpectedUrl'] ?? task['xReturnUrl'] ?? '')
                  .toString()
                  .trim();
          if (_isBlankHistoryUrl(actualLoadedUrl) ||
              !_isXPlatformPage(actualLoadedUrl) ||
              (returnUrl.startsWith('http') &&
                  !_isSameXSmartReturnPage(returnUrl, actualLoadedUrl))) {
            if (returnUrl.startsWith('http')) {
              _loadUrl(returnUrl);
            } else {
              _loadUrl((task['siteUrl'] ?? '').toString());
            }
            return;
          }
          final scrollY = (task['xReturnScrollY'] as num?)?.toDouble();
          if (scrollY != null && scrollY > 0) {
            try {
              await controller.evaluateJavascript(
                source:
                    'window.scrollTo({top: $scrollY, left: 0, behavior: "auto"});',
              );
            } catch (_) {}
          }
          task['xReturnExpectedUrl'] = '';
          task['xReturnAttempts'] = 0;
          task['phase'] = 'scanning_feed';
          _continueSmartFeed(task, madeProgress: false);
          return;
        }
        final actualUri = Uri.tryParse(actualLoadedUrl);
        final onSearchPage =
            actualUri != null &&
            actualUri.pathSegments.isNotEmpty &&
            actualUri.pathSegments.first == 'search';
        if (!onSearchPage) {
          _loadUrl(strictXSearchUrl);
          return;
        }
        task['xReturnExpectedUrl'] = '';
        task['xReturnAttempts'] = 0;
        task['phase'] = 'scanning_feed';
        _continueSmartFeed(task, madeProgress: false);
        return;
      }

      if (strict91Mode && phase == 'strict91_returning') {
        if (_isSame91TaskPage(strict91SearchUrl, actualLoadedUrl)) {
          task['strict91ReturnAttempts'] = 0;
          task['strict91ActiveCardUrl'] = '';
          task.remove('cardEnteredAt');
          task['phase'] = 'visiting_candidate';
          debugPrint('Smart 91 strict: restored remembered search page');
          _visitNextSmartCandidate(task);
          return;
        }
        final attempts = (task['strict91ReturnAttempts'] as int?) ?? 0;
        task['strict91ReturnAttempts'] = attempts + 1;
        if (attempts < 3 && await controller.canGoBack()) {
          debugPrint(
            'Smart 91 strict: backing through intermediate page $actualLoadedUrl',
          );
          await controller.goBack();
        } else {
          debugPrint('Smart 91 strict: restoring $strict91SearchUrl');
          _loadUrl(strict91SearchUrl);
        }
        return;
      }

      if (strict91Mode && phase == 'visiting_clicked_card') {
        final activeCardUrl = (task['strict91ActiveCardUrl'] ?? '').toString();
        if (activeCardUrl.isNotEmpty &&
            !_isSame91TaskPage(activeCardUrl, actualLoadedUrl)) {
          if (_isSame91TaskPage(strict91SearchUrl, actualLoadedUrl)) {
            final clicked = await _clickSmartCandidateLink(activeCardUrl);
            if (!clicked) _loadUrl(activeCardUrl);
          } else {
            _loadUrl(activeCardUrl);
          }
          debugPrint(
            'Smart 91 strict: rejected unrelated page $actualLoadedUrl; expected $activeCardUrl',
          );
          return;
        }
      }
      if (phase == 'returning_candidate_list') {
        task['phase'] = 'visiting_candidate';
        _visitNextSmartCandidate(task);
        return;
      }
      if ((phase == 'scanning_feed' ||
              phase == 'collecting_site_results' ||
              phase == 'collecting_search_results' ||
              phase == 'visiting_candidate') &&
          await _recoverSmartDownloadErrorPage(task, loadedUrl)) {
        return;
      }
      _updateSmartDiscoveryProgress(task, phase);
      if (phase == 'opening_site') {
        await Future<void>.delayed(const Duration(milliseconds: 900));
        if ((task['keyword'] ?? '').toString().trim().isEmpty) {
          task['phase'] = 'scanning_feed';
          Future<void>.delayed(
            const Duration(milliseconds: 120),
            () => unawaited(_advanceSmartDownload(_currentUrl)),
          );
          return;
        }
        task['phase'] = 'collecting_site_results';
        final keywordJson = jsonEncode(task['keyword']);
        final submitted = await controller.evaluateJavascript(
          source: '''
            (() => {
              const keyword = $keywordJson;
              const inputs = Array.from(document.querySelectorAll(
                'input[type="search"], input[name="q"], input[name*="search" i], input[placeholder*="search" i], input[placeholder*="搜索"]'
              ));
              const input = inputs.find(e => e.offsetParent !== null) || inputs[0];
              if (!input) return false;
              input.focus();
              input.value = keyword;
              input.dispatchEvent(new Event('input', {bubbles:true}));
              input.dispatchEvent(new Event('change', {bubbles:true}));
              const form = input.form || input.closest('form');
              if (form) {
                if (form.requestSubmit) form.requestSubmit(); else form.submit();
              } else {
                input.dispatchEvent(new KeyboardEvent('keydown', {key:'Enter', code:'Enter', keyCode:13, bubbles:true}));
              }
              return true;
            })()
          ''',
        );
        final didSubmit = submitted == true || submitted.toString() == 'true';
        if (!didSubmit) {
          Future<void>.delayed(
            const Duration(milliseconds: 200),
            () => unawaited(_advanceSmartDownload(_currentUrl)),
          );
        } else {
          Future<void>.delayed(
            const Duration(seconds: 3),
            () => unawaited(_advanceSmartDownload(_currentUrl)),
          );
        }
        return;
      }

      if (phase == 'collecting_site_results' ||
          phase == 'collecting_search_results') {
        if (strict91Mode) {
          if (!_isSame91TaskPage(strict91SearchUrl, actualLoadedUrl)) {
            _loadUrl(strict91SearchUrl);
            return;
          }
          if (task['strict91QueueReady'] == true &&
              (task['candidates'] as List).isNotEmpty) {
            task['phase'] = 'visiting_candidate';
            _visitNextSmartCandidate(task);
            return;
          }
        }
        await Future<void>.delayed(const Duration(milliseconds: 900));
        final hostJson = jsonEncode(task['host']);
        final keywordJson = jsonEncode(task['keyword']);
        final searchCycleDepth = (task['searchCycle'] as int?) ?? 0;
        final exhaustive = searchCycleDepth > 0;
        final limit = ((task['target'] as int) * 30 + searchCycleDepth * 80)
            .clamp(60, 1000);
        final result = await controller.evaluateJavascript(
          source: '''
            (() => {
              const targetHost = $hostJson;
              const keyword = $keywordJson.toLowerCase();
              const exhaustive = $exhaustive;
              // Avoid backslash escapes in injected regular expressions.
              // Dart string processing can otherwise corrupt the JS source.
              const tokens = keyword.split(' ')
                .map(v => v.trim()).filter(v => v.length >= 2).slice(0, 16);
              const seen = new Set();
              return Array.from(document.querySelectorAll('a[href]')).map((a, order) => {
                try {
                  const u = new URL(a.href, location.href);
                  const host = u.hostname.toLowerCase();
                  const normalizedHost = host.replace(/^www\./, '');
                  if (!(normalizedHost === targetHost || normalizedHost.endsWith('.' + targetHost))) return null;
                  u.hash = '';
                  const url = u.href;
                  if (seen.has(url) || u.pathname === '/' || url === location.href) return null;
                  if (!exhaustive && a.closest('header, nav, footer, aside, [role="navigation"]')) return null;
                  const path = u.pathname.toLowerCase();
                  const directMedia = /[.](m3u8|mp4|webm|mov)(?:\$|[?])/i.test(url);
                  const detailPath = /[/](archives?|posts?|videos?|watch|view|detail|movies?)[/]/i.test(path);
                  const taxonomyPath = /[/](category|categories|tags?|authors?|search|feed|page)[/]/i.test(path);
                  const blockedPath = /[/](login|register|account|logout|cart|checkout|user)[/]/i.test(path);
                  const mediaCard = !!a.querySelector('img, video, picture') ||
                    !!a.closest('article, figure, [class*="card"], [class*="post"], [class*="item"]');
                  if (blockedPath) return null;
                  if (!directMedia && !detailPath && !mediaCard && !taxonomyPath && !exhaustive) return null;
                  seen.add(url);
                  const title = (a.innerText || a.title || a.getAttribute('aria-label') ||
                    (a.querySelector('img') && a.querySelector('img').alt) || '').trim();
                  const haystack = (title + ' ' + url).toLowerCase();
                  const tokenHits = tokens.reduce((sum, token) =>
                    sum + (haystack.includes(token) ? 1 : 0), 0);
                  const exact = keyword.length > 0 && haystack.includes(keyword);
                  const tier = exact ? 2 : (tokenHits > 0 ? 1 : 0);
