                    tokenHits * 5000 +
                    (directMedia ? 80000 : 0) +
                    (detailPath ? 50000 : 0) +
                    (mediaCard ? 20000 : 0) +
                    Math.max(0, 2000 - order);
                  return {url, title: title || document.title || url, score, tier, order,
                    scopeOnly: !directMedia && !detailPath &&
                      (taxonomyPath || (exhaustive && !mediaCard))};
                } catch (_) { return null; }
              }).filter(Boolean).sort((a,b) => b.score - a.score).slice(0, $limit);
