        final exhaustiveCycle = ((task['searchCycle'] as int?) ?? 0) > 0;
        final hasKeyword = (task['keyword'] ?? '').toString().trim().isNotEmpty;
        final loadedUri = Uri.tryParse(loadedUrl);
