                (() => {
                  const step = $prep;
                  const amount = Math.max(420, Math.floor(innerHeight * 0.78));
                  window.scrollBy(0, amount);
                  const videos = Array.from(document.querySelectorAll('video'));
                  const scored = videos.map(v => {
