        }
        if (adLikely) {
          final now = DateTime.now();
          final waitStarted = task['adWaitStartedAt'] as DateTime? ?? now;
          task['adWaitStartedAt'] = waitStarted;
          final waited = now.difference(waitStarted);
          if (waited < const Duration(seconds: 60)) {
