              if (id.isNotEmpty) (grouped[id] ??= <String>[]).add(url);
            }
            if (grouped.isNotEmpty) {
              final ranked =
                  grouped.entries.toList()..sort((left, right) {
                    int score(MapEntry<String, List<String>> entry) {
                      final rows = entry.value;
                      final hasMaster = rows.any(
