                                IconButton(
                                  icon: const Icon(
                                    Icons.delete,
                                    color: Colors.red,
                                  ),
                                  onPressed: () async {
                                    final shouldDelete =
                                        await showDialog<bool>(
                                          context: context,
                                          builder:
                                              (context) => AlertDialog(
                                                title: const Text('删除书签'),
                                                content: Text(
                                                  '确定要删除书签 "$name" 吗？',
                                                ),
                                                actions: [
                                                  TextButton(
                                                    onPressed:
                                                        () => Navigator.pop(
                                                          context,
                                                          false,
                                                        ),
                                                    child: const Text('取消'),
                                                  ),
                                                  TextButton(
                                                    onPressed:
                                                        () => Navigator.pop(
                                                          context,
                                                          true,
                                                        ),
                                                    child: const Text('删除'),
                                                  ),
                                                ],
                                              ),
                                        ) ??
                                        false;
                                    if (shouldDelete) {
                                      modalSetState(() {
                                        _bookmarks.removeAt(index);
                                      });
                                      await _saveBookmarks();
                                    }
                                  },
                                ),
                                IconButton(
                                  icon: const Icon(
                                    Icons.content_copy,
                                    color: Colors.green,
                                  ),
                                  onPressed: () {
                                    if (url.isNotEmpty) {
                                      Clipboard.setData(
                                        ClipboardData(text: url),
