  Future<void> _saveBookmarks() async {
    if (!_bookmarksLoaded) {
      debugPrint('跳过保存书签：尚未完成首次加载');
      return;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      final jsonString = jsonEncode(_bookmarks);
      await prefs.setString('bookmarks', jsonString);
    } catch (e) {
      debugPrint('Error saving bookmarks: $e');
    }
  }

  Future<void> _loadCommonWebsites() async {
    final existing = _commonWebsitesLoadFuture;
    if (existing != null) return existing;
    final future = _loadCommonWebsitesImpl();
    _commonWebsitesLoadFuture = future;
    try {
      await future;
    } finally {
      if (identical(_commonWebsitesLoadFuture, future)) {
        _commonWebsitesLoadFuture = null;
      }
    }
  }

  Future<void> _loadCommonWebsitesImpl() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final commonWebsitesJson = prefs.getString('common_websites');
      if (commonWebsitesJson != null && commonWebsitesJson.isNotEmpty) {
        final decoded = jsonDecode(commonWebsitesJson);
        final List<dynamic> websitesList = decoded is List ? decoded : [];

        if (websitesList.isNotEmpty) {
          var migrated = false;
          final mapped =
              websitesList.map((item) {
                final rawUrl = (item['url'] ?? '').toString();
                var url = rawUrl;
                // Only migrate known dead Google /m; never rewrite user .hk / query URLs.
                if (BrowserService.isDeadGoogleMobileUrl(rawUrl)) {
                  final fixed = BrowserService.normalizeCommonWebsiteUrl(
                    rawUrl,
                  );
                  if (fixed != rawUrl) {
                    url = fixed;
                    migrated = true;
                  }
                }
                return {
                  'name': item['name'],
                  'url': url,
                  'iconCode': Icons.public.codePoint,
                };
              }).toList();
          setState(() {
            _commonWebsites.clear();
            _commonWebsites.addAll(mapped);
          });
          _commonWebsitesLoaded = true;
          debugPrint('从SharedPreferences加载了${_commonWebsites.length}个常用网站');
          if (migrated) {
            await _saveCommonWebsites();
            debugPrint('已迁移旧版 Google /m 常用网站 URL 并写回');
          }
          return;
        }
      }

      // 如果没有从SharedPreferences加载到数据，或者加载的数据为空，则加载默认网站
      setState(() {
        _commonWebsites.clear();
        _commonWebsites.addAll([
          {
            'name': 'Google',
            'url': BrowserService.kGoogleHomeUrl,
            'iconCode': Icons.public.codePoint,
          },
          {
            'name': '百度',
            'url': 'https://www.baidu.com',
            'iconCode': Icons.public.codePoint,
          },
        ]);
      });
      _commonWebsitesLoaded = true;
      debugPrint('加载了默认常用网站');
      await _saveCommonWebsites();
    } catch (e) {
      debugPrint('Error loading common websites: $e');
      // 出错时加载默认网站（不 wipe prefs：避免用户网址被误删）
      setState(() {
        _commonWebsites.clear();
        _commonWebsites.addAll([
          {
            'name': 'Google',
            'url': BrowserService.kGoogleHomeUrl,
            'iconCode': Icons.public.codePoint,
          },
          {
            'name': '百度',
            'url': 'https://www.baidu.com',
            'iconCode': Icons.public.codePoint,
          },
        ]);
      });
      _commonWebsitesLoaded = true;
      debugPrint('加载出错，使用默认常用网站（未清除 prefs）');
    }
  }

  // 2. 加载历史记录
  Future<void> _loadHistory() async {
    final prefs = await SharedPreferences.getInstance();
    final historyString = prefs.getString('browser_history');
    if (historyString != null) {
      var migrated = false;
      final rows = List<Map<String, dynamic>>.from(json.decode(historyString));
      for (final row in rows) {
        final rawUrl = (row['url'] ?? '').toString();
        if (rawUrl.isEmpty) continue;
        if (!BrowserService.isDeadGoogleMobileUrl(rawUrl)) continue;
        final url = BrowserService.normalizeCommonWebsiteUrl(rawUrl);
        if (url != rawUrl) {
          row['url'] = url;
          migrated = true;
        }
      }
      _history = rows;
      if (migrated) {
        await _saveHistory();
        debugPrint('已迁移历史记录中的旧版 Google /m URL');
      }
    }
  }

  // 3. 保存历史记录
  Future<void> _saveHistory() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('browser_history', json.encode(_history));
  }

  // 4. 添加历史记录（在网页加载成功时调用）
  Future<void> _addHistory(String title, String url) async {
    if (url.isEmpty) return;
    // 去重：如果已存在则先移除
    _history.removeWhere((item) => item['url'] == url);
    _history.insert(0, {
      'title': title,
      'url': url,
      'datetime': DateTime.now().toIso8601String(),
    });
    // 限制最大条数
    if (_history.length > 200) _history = _history.sublist(0, 200);
    await _saveHistory();
    _recordSessionPageTrail(title, url);
  }

  void _recordSessionPageTrail(String title, String url) {
    final trimmed = url.trim();
    if (trimmed.isEmpty ||
        !(trimmed.startsWith('http://') || trimmed.startsWith('https://'))) {
      return;
    }
    final key = trimmed.split('#').first;
    _sessionPageTrail.removeWhere(
      (row) => (row['url'] ?? '').toString().split('#').first == key,
    );
    _sessionPageTrail.insert(0, {
      'title': title,
      'url': key,
      'host': _normalizeSmartHost(Uri.tryParse(key)?.host ?? ''),
      'datetime': DateTime.now().toIso8601String(),
    });
    if (_sessionPageTrail.length > _kSessionPageTrailMax) {
      _sessionPageTrail.removeRange(
        _kSessionPageTrailMax,
        _sessionPageTrail.length,
      );
    }
  }

