                  valueListenable: _downloadTasksNotifier,
                  builder: (context, tasks, child) {
                    final activeTasks =
                        tasks
                            .where((t) => t['status'] == 'downloading')
                            .toList();
                    final shouldShow = !_showHomePage || activeTasks.isNotEmpty;
                    if (!shouldShow) return const SizedBox.shrink();
                    final panelW = _downloadPanelExpanded ? 320.0 : 60.0;
                    final panelH =
                        _downloadPanelExpanded
                            ? (_smartDownloadTask == null ? 280.0 : 420.0)
                            : 60.0;
                    final defaultLeft = bodyW - 16 - panelW;
                    final defaultTop = bodyH * 0.75 - panelH / 2;
                    final left = (_downloadPanelPosition?.dx ?? defaultLeft)
                        .clamp(0.0, bodyW - panelW);
                    final top = (_downloadPanelPosition?.dy ?? defaultTop)
                        .clamp(0.0, bodyH - panelH);
                    return Positioned(
                      left: left,
                      top: top,
                      child: GestureDetector(
                        behavior: HitTestBehavior.opaque,
                        onPanUpdate: (details) {
                          setState(() {
                            final dx = (left + details.delta.dx).clamp(
                              0.0,
                              bodyW - panelW,
                            );
                            final dy = (top + details.delta.dy).clamp(
                              0.0,
                              bodyH - panelH,
                            );
                            _downloadPanelPosition = Offset(dx, dy);
                          });
                        },
                        child: _buildDownloadTasksPanel(tasks, activeTasks),
                      ),
                    );
                  },
                ),
              ],
            );
          },
        ),
      ),
    );
  }

  Widget _buildSmartDownloadSummary(Map<String, dynamic> task) {
    final keyword = (task['keyword'] ?? '').toString().trim();
    final mediaType = task['mediaType'] as MediaType?;
    final allowMixedMedia = task['allowMixedMedia'] == true;
    final target = (task['target'] as int?) ?? 0;
    final completed = ((task['success'] as int?) ?? 0).clamp(0, target);
    final remaining = max(0, target - completed);
    final minBytes = task['minVideoBytes'] as int?;
    final maxBytes = task['maxVideoBytes'] as int?;
    final autoSizeRange = task['autoVideoSizeRange'] == true;
    final nextLabel = (task['nextMediaLabel'] ?? '').toString().trim();
    final nextStatus = (task['nextMediaStatus'] ?? '').toString().trim();
    final demoPhase = (task['demoPhase'] ?? '').toString();
    final demoRequired = (task['demoRequired'] as int?) ?? 0;
    final matchStage = (task['matchStage'] ?? '').toString().trim();
    final learned = task['learnedRecipe'];
    final strategyName =
        learned is Map ? (learned['name'] ?? '').toString().trim() : '';
    final strategyLayer = (task['strategyLayer'] ?? '').toString();
    final lockedAcquisition = _normalizeSmartAcquisition(
      (task['lockedAcquisition'] ?? '').toString(),
    );
    String sizeLabel;
    if (mediaType != MediaType.video) {
      sizeLabel = '不限制';
    } else if (minBytes != null && maxBytes != null) {
      sizeLabel =
          '${(minBytes / 1024 / 1024).round()}～${(maxBytes / 1024 / 1024).round()} MB';
    } else if (minBytes != null) {
      sizeLabel = '≥ ${(minBytes / 1024 / 1024).round()} MB';
    } else if (maxBytes != null) {
      sizeLabel = '≤ ${(maxBytes / 1024 / 1024).round()} MB';
    } else {
      sizeLabel = '不限制';
    }
    if (autoSizeRange && sizeLabel != '不限制') {
      sizeLabel = '自动 $sizeLabel';
    }
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 7),
      decoration: BoxDecoration(
        color: Colors.green.withValues(alpha: 0.14),
        borderRadius: BorderRadius.circular(8),
        border: Border.all(color: Colors.green.withValues(alpha: 0.55)),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          if (matchStage.isNotEmpty)
            Text(
              matchStage,
              style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600),
            ),
          if (strategyName.isNotEmpty)
            Text(
              '策略：$strategyName'
              '${strategyLayer == 'preferred'
                  ? ' · 优选中'
                  : strategyLayer == 'default'
                  ? ' · 已切默认'
                  : strategyLayer == 'fallback'
                  ? ' · 兜底中'
                  : ''}',
              style: const TextStyle(fontSize: 12),
            ),
          if (lockedAcquisition.isNotEmpty)
            Text(
              '本任务沿用：${_smartAcquisitionLabel(lockedAcquisition)}'
              '${((task['lockedFailStreak'] as int?) ?? 0) > 0 ? '（失败 ${task['lockedFailStreak']}/3）' : ''}',
              style: const TextStyle(fontSize: 12, color: Colors.teal),
            ),
          if (demoPhase == 'demo' && demoRequired > 0)
            Text(
              '示范学习中：已完成 ${completed.clamp(0, demoRequired)}/$demoRequired 次，请继续手动长按',
              style: const TextStyle(fontSize: 12, color: Colors.orange),
            ),

          Text(
            '智能${allowMixedMedia
                ? '图片+视频'
                : mediaType == MediaType.image
                ? '图片'
                : '视频'} · 关键词：${keyword.isEmpty ? '无（按当前媒体距离）' : keyword}',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
              color: Colors.white,
              fontSize: 12,
              fontWeight: FontWeight.w600,
            ),
          ),
          const SizedBox(height: 3),
          Text(
            '大小：$sizeLabel · 数量：$completed/$target · 待下载：$remaining',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(color: Colors.white70, fontSize: 11),
          ),
          if (nextStatus.isNotEmpty) ...[
            const SizedBox(height: 3),
            Text(
              '下一项：${nextLabel.isEmpty ? '已找到候选媒体' : nextLabel} · $nextStatus',
              maxLines: 1,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                color: Colors.greenAccent,
                fontSize: 11,
                fontWeight: FontWeight.w600,
              ),
            ),
          ],
          const SizedBox(height: 6),
          Row(
            children: [
              Expanded(
                child: OutlinedButton(
                  style: OutlinedButton.styleFrom(
                    foregroundColor: Colors.white,
                    side: const BorderSide(color: Colors.white54),
                    padding: const EdgeInsets.symmetric(vertical: 4),
                    minimumSize: const Size(0, 28),
                    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  ),
                  onPressed: () {
                    final t = _smartDownloadTask;
                    final phase = (t?['phase'] ?? '').toString();
                    final sniffSoft =
                        t != null &&
                        t['mode'] == 'paginated_sniff' &&
                        <String>{
                          'paginated_sniff_scanning',
                          'paginated_sniff_discover',
                          'paginated_sniff_downloading',
                        }.contains(phase);
                    if (sniffSoft) {
                      _requestPaginatedSniffSoftStop();
                    } else {
                      unawaited(_finishSmartDownload('用户已停止任务'));
                    }
                  },
                  child: Text(() {
                    final t = _smartDownloadTask;
                    final phase = (t?['phase'] ?? '').toString();
                    if (t?['mode'] != 'paginated_sniff') return '退出';
                    if (phase == 'paginated_sniff_downloading') {
                      return '停止下载';
                    }
                    if (<String>{
                      'paginated_sniff_scanning',
                      'paginated_sniff_discover',
                    }.contains(phase)) {
                      return '停止嗅探';
                    }
                    return '退出';
                  }(), style: const TextStyle(fontSize: 11)),
                ),
              ),
              const SizedBox(width: 6),
              Expanded(
                child: FilledButton(
                  style: FilledButton.styleFrom(
                    backgroundColor: Colors.orange.shade700,
                    padding: const EdgeInsets.symmetric(vertical: 4),
                    minimumSize: const Size(0, 28),
                    tapTargetSize: MaterialTapTargetSize.shrinkWrap,
                  ),
                  onPressed: () => unawaited(_promptStopOrResetSmartDownload()),
                  child: const Text('停止/重设', style: TextStyle(fontSize: 11)),
                ),
              ),
            ],
          ),
        ],
      ),
    );
  }

