          contextText = (result['contextText'] ?? '').toString();
          elementIdentity = (result['elementIdentity'] ?? '').toString();
          durationSec = (result['duration'] as num?)?.toDouble() ?? 0.0;
          currentTimeSec = (result['currentTime'] as num?)?.toDouble() ?? 0.0;
